; ---- V10 guarded HAM6 Chip allocation ----
; Keep the Exec allocation base immutable and place 64-byte canaries on both
; sides of the actual two-frame HAM6 area. This makes a small overrun visible
; without immediately damaging the Exec memory-list header.
V10_CHIP_GUARD       equ 64
V10_CHIP_ALLOC_BYTES equ T30_CHIP_BYTES+(V10_CHIP_GUARD*2)
V10_GUARD_PRE        equ $A55AA55A
V10_GUARD_POST       equ $5AA55AA5

; ---- TEST61 compact native HAM6 playback ----
; Agnus now fetches exactly the same 192x144x6 planar layout produced in Fast RAM.
T30_PLANE_BYTES equ 3456             ; 24 bytes/row * 144
T30_FRAME_BYTES equ 20736            ; six compact 192x144 1-bit planes (HAM6)
T30_FAST_BYTES  equ 20736            ; legacy helper constant; live scratch is identical
T30_CHIP_BYTES  equ 41472            ; two 20736-byte Chip-RAM HAM6 display buffers
T56_SHADOW_BYTES equ 41472           ; Fast mirrors of both Chip display buffers for 8x-unrolled dirty-copy
