; ====================================================================
; MHI03 engine front-end (external AmigaDOS Process)
; The original BerryMP314 player body remains below and supplies the proven
; BerryCore/Helix + VCHIQ/MMAL HDMI implementation.  This front-end only
; replaces the compressed-byte source with the MHI queue in mhiberry.library.
; ====================================================================
MHI3_OpenLibrary  equ -552
MHI3_CloseLibrary equ -414
MHI3_AllocSignal  equ -330
MHI3_FreeSignal   equ -336
MHI3_FindTask     equ -294
MHI3_Wait         equ -318
MHI3_Signal       equ -324
MHI3_Forbid       equ -132
MHI3_Permit       equ -138

MHI3_B_HANDLE        equ 64
MHI3_H_MAGIC         equ 0
MHI3_H_TASK          equ 4
MHI3_H_SIGMASK       equ 8
MHI3_H_STATUS        equ 12
MHI3_H_PLAYFLAG      equ 13
MHI3_H_STOPREQ       equ 14
MHI3_H_QUIT          equ 15
MHI3_H_QHEAD         equ 16
MHI3_H_QTAIL         equ 18
MHI3_H_QCOUNT        equ 20
MHI3_H_EHEAD         equ 22
MHI3_H_ETAIL         equ 24
MHI3_H_ECOUNT        equ 26
MHI3_H_ENQUEUED      equ 28
MHI3_H_CONSUMED      equ 32
MHI3_H_SIGNALED      equ 36
MHI3_H_VOLUME        equ 44
MHI3_H_QBUFS         equ 64
MHI3_H_QSIZES        equ 128
MHI3_H_EBUFS         equ 192
MHI3_HANDLE_MAGIC    equ $424d4833
MHI3_QUEUE_MASK      equ 15
MHI3_QUEUE_SLOTS     equ 16
MHI3_B_ENGINE_TASK    equ 320
MHI3_B_ENGINE_SIGMASK equ 324
MHI3_B_ENGINE_READY   equ 328
MHI3_B_ENGINE_BUSY    equ 329
MHI3_B_ENGINE_ERROR   equ 330
MHI3_MHIF_PLAYING     equ 0
MHI3_MHIF_STOPPED     equ 1
MHI3_MHIF_OUT_OF_DATA equ 2
MHI3_MHIF_PAUSED      equ 3

        section bss,bss
mhi3_lib_base:       ds.l 1
mhi3_engine_task:    ds.l 1
mhi3_engine_sigmask: ds.l 1
mhi3_engine_signum:  ds.b 1
        even
mhi3_cur_ptr:        ds.l 1
mhi3_cur_size:       ds.l 1
mhi3_cur_pos:        ds.l 1
mhi3_read_total:     ds.l 1
mhi3_session_count:  ds.l 1
mhi3_id3_skip:       ds.l 1
; MHI03g: bounded front-end diagnostics only.  MP314 CPU1/MMAL body unchanged.
mhi3_front_stage:       ds.l 1
mhi3_front_alloc_ptr:   ds.l 1
mhi3_front_read_ret:    ds.l 1
mhi3_front_id3_ret:     ds.l 1
mhi3_front_pre_magic:   ds.l 1
mhi3_front_pre_qcount:  ds.l 1
mhi3_front_pre_qhead:   ds.l 1
mhi3_front_pre_qtail:   ds.l 1
mhi3_front_pre_play:    ds.l 1
mhi3_front_pre_stop:    ds.l 1
mhi3_front_pre_quit:    ds.l 1
mhi3_front_pre_ptr:     ds.l 1
mhi3_front_pre_size:    ds.l 1
mhi3_front_acq_reason:  ds.l 1
mhi3_front_acq_calls:   ds.l 1

        section data,data
mhi3_lib_name:       dc.b "mhiberry.library",0
mhi3_lib_path:       dc.b "LIBS:MHI/mhiberry.library",0
mhi3_engine_banner:  dc.b "mhiberry_engine MHI04 - MP314 RELEASE    ",10,0
mhi4d_dos_name:      dc.b "dos.library",0
mhi4d_diag_path:     dc.b "RAM:mhiberry_engine_diag.txt",0
mhi4d_e_start:       dc.b "ENGINE process start",10,0
mhi4d_e_libok:       dc.b "ENGINE mhiberry.library open OK",10,0
mhi4d_e_ready:       dc.b "ENGINE READY=1",10,0
mhi4d_e_shutdown:    dc.b "ENGINE shutdown entry",10,0
mhi4d_e_clear:       dc.b "ENGINE READY=0/registration cleared",10,0
mhi4d_e_exit:        dc.b "ENGINE exit",10,0
        even

        section code,code
start:
        movem.l d2-d7/a2-a6,-(sp)
        lea     mhi4d_e_start,a0
        bsr     mhi4d_eng_log
        clr.l   mhi3_lib_base
        clr.l   mhi3_engine_task
        clr.l   mhi3_engine_sigmask
        move.b  #-1,mhi3_engine_signum
        clr.l   mhi3_cur_ptr
        clr.l   mhi3_cur_size
        clr.l   mhi3_cur_pos
        clr.l   mhi3_session_count

        move.l  4.w,a4
        ; Prefer an already loaded instance by its internal library name.
        move.l  a4,a6
        lea     mhi3_lib_name,a1
        moveq   #0,d0
        jsr     MHI3_OpenLibrary(a6)
        tst.l   d0
        bne.s   mhi3_engine_lib_ok
        ; If no instance exists yet, load it once from LIBS:MHI/.
        move.l  a4,a6
        lea     mhi3_lib_path,a1
        moveq   #0,d0
        jsr     MHI3_OpenLibrary(a6)
        tst.l   d0
        beq.w   mhi3_engine_exit
mhi3_engine_lib_ok:
        move.l  d0,mhi3_lib_base
        lea     mhi4d_e_libok,a0
        bsr     mhi4d_eng_log

        move.l  a4,a6
        moveq   #-1,d0
        jsr     MHI3_AllocSignal(a6)
        cmpi.b  #-1,d0
        beq.w   mhi3_engine_close_lib
        move.b  d0,mhi3_engine_signum
        andi.l  #$ff,d0
        move.l  d0,d2
        moveq   #1,d3
        lsl.l   d2,d3
        move.l  d3,mhi3_engine_sigmask

        suba.l  a1,a1
        move.l  a4,a6
        jsr     MHI3_FindTask(a6)
        move.l  d0,mhi3_engine_task
        move.l  mhi3_lib_base,a0
        ; MHI04 duplicate-start guard: if an engine became READY while this
        ; process was being spawned (for example a manual start racing the
        ; automatic one), do not overwrite the registered task/signal pair.
        tst.b   MHI3_B_ENGINE_READY(a0)
        bne.w   mhi3_engine_free_sig
        move.l  d0,MHI3_B_ENGINE_TASK(a0)
        move.l  d3,MHI3_B_ENGINE_SIGMASK(a0)
        clr.b   MHI3_B_ENGINE_ERROR(a0)
        clr.b   MHI3_B_ENGINE_BUSY(a0)
        move.b  #1,MHI3_B_ENGINE_READY(a0)
        lea     mhi4d_e_ready,a0
        bsr     mhi4d_eng_log

mhi3_engine_wait:
        move.l  mhi3_engine_sigmask,d0
        ori.l   #SIGBREAKF_CTRL_C,d0
        move.l  a4,a6
        jsr     MHI3_Wait(a6)
        btst    #12,d0
        bne.w   mhi3_engine_shutdown
        move.l  mhi3_lib_base,a0
        lea     MHI3_B_HANDLE(a0),a3
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        bne.w   mhi3_engine_wait
        tst.b   MHI3_H_QUIT(a3)
        bne.w   mhi3_engine_shutdown
        tst.b   MHI3_H_PLAYFLAG(a3)
        beq.s   mhi3_engine_wait
        tst.w   MHI3_H_QCOUNT(a3)
        beq.w   mhi3_engine_no_data

mhi3_engine_start_session:
        move.b  #1,MHI3_B_ENGINE_BUSY(a0)
        clr.b   MHI3_B_ENGINE_ERROR(a0)
        clr.l   mhi3_cur_ptr
        clr.l   mhi3_cur_size
        clr.l   mhi3_cur_pos
        clr.l   mhi3_read_total
        clr.l   mhi3_id3_skip
        clr.l   mhi3_front_stage
        clr.l   mhi3_front_alloc_ptr
        clr.l   mhi3_front_read_ret
        clr.l   mhi3_front_id3_ret
        clr.l   mhi3_front_pre_magic
        clr.l   mhi3_front_pre_qcount
        clr.l   mhi3_front_pre_qhead
        clr.l   mhi3_front_pre_qtail
        clr.l   mhi3_front_pre_play
        clr.l   mhi3_front_pre_stop
        clr.l   mhi3_front_pre_quit
        clr.l   mhi3_front_pre_ptr
        clr.l   mhi3_front_pre_size
        clr.l   mhi3_front_acq_reason
        clr.l   mhi3_front_acq_calls
        addq.l  #1,mhi3_session_count
        moveq   #0,d0
        suba.l  a0,a0
        bsr     h264rgb_main
        ; MHI03d: report actual CPU1/MMAL progress and convert silent internal
        ; failures into an engine error visible to the probe.
        bsr     mhi3_diag_report
        move.l  mhi3_lib_base,a0
        ; MHI03i: BUSY is a hard session fence for MHIStop().  Do not clear
        ; it until the MP314/MMAL body has completed and the engine-owned
        ; current compressed MHI buffer has been returned to the client.
        bsr     mhi3_stream_return_current
        move.l  mhi3_lib_base,a0
        clr.b   MHI3_B_ENGINE_BUSY(a0)
        lea     MHI3_B_HANDLE(a0),a3
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        bne.w   mhi3_engine_wait
        tst.b   MHI3_H_QUIT(a3)
        bne.w   mhi3_engine_shutdown
        tst.b   MHI3_H_STOPREQ(a3)
        bne.s   mhi3_engine_stopped
        move.b  #MHI3_MHIF_OUT_OF_DATA,MHI3_H_STATUS(a3)
        bsr     mhi3_signal_owner
        bra.w   mhi3_engine_wait
mhi3_engine_stopped:
        ; MHI03h: MHIPlay may arrive immediately after MHIStop while the old
        ; session is still BUSY.  In that case PLAYFLAG=1 but STOPREQ remains
        ; asserted deliberately.  The old MP314 session is now fully cleaned,
        ; so acknowledge the stop here and start the new queued title from a
        ; fresh session instead of letting it inherit the old rolling window.
        tst.b   MHI3_H_PLAYFLAG(a3)
        beq.s   .plain_stop
        clr.b   MHI3_H_STOPREQ(a3)
        tst.w   MHI3_H_QCOUNT(a3)
        beq.s   .restart_wait_data
        move.b  #MHI3_MHIF_PLAYING,MHI3_H_STATUS(a3)
        bra.w   mhi3_engine_start_session
.restart_wait_data:
        move.b  #MHI3_MHIF_OUT_OF_DATA,MHI3_H_STATUS(a3)
        bsr     mhi3_signal_owner
        bra.w   mhi3_engine_wait
.plain_stop:
        move.b  #MHI3_MHIF_STOPPED,MHI3_H_STATUS(a3)
        bsr     mhi3_signal_owner
        bra.w   mhi3_engine_wait
mhi3_engine_no_data:
        move.b  #MHI3_MHIF_OUT_OF_DATA,MHI3_H_STATUS(a3)
        bsr     mhi3_signal_owner
        bra.w   mhi3_engine_wait

mhi3_engine_shutdown:
        lea     mhi4d_e_shutdown,a0
        bsr     mhi4d_eng_log
        bsr     mhi3_stream_return_current
        move.l  mhi3_lib_base,a0
        tst.l   a0
        beq.s   mhi3_engine_free_sig
        lea     MHI3_B_HANDLE(a0),a3
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        bne.s   mhi3_engine_clear_reg
        bsr     mhi3_signal_owner
mhi3_engine_clear_reg:
        clr.b   MHI3_B_ENGINE_BUSY(a0)
        clr.b   MHI3_B_ENGINE_READY(a0)
        clr.l   MHI3_B_ENGINE_TASK(a0)
        clr.l   MHI3_B_ENGINE_SIGMASK(a0)
        lea     mhi4d_e_clear,a0
        bsr     mhi4d_eng_log
        ; MHI04E: restore the library base after the diagnostic string used A0.
        ; MHI04D accidentally formed the handle from the log-string address here,
        ; so the final wakeup to MHIFreeDecoder was skipped.
        move.l  mhi3_lib_base,a0
        ; Wake MHIFreeDecoder after READY became zero.
        lea     MHI3_B_HANDLE(a0),a3
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        bne.s   mhi3_engine_free_sig
        bsr     mhi3_signal_owner
mhi3_engine_free_sig:
        moveq   #0,d0
        move.b  mhi3_engine_signum,d0
        cmpi.b  #-1,d0
        beq.s   mhi3_engine_close_lib
        move.l  a4,a6
        jsr     MHI3_FreeSignal(a6)
mhi3_engine_close_lib:
        move.l  mhi3_lib_base,d0
        beq.s   mhi3_engine_exit
        move.l  d0,a1
        move.l  a4,a6
        jsr     MHI3_CloseLibrary(a6)
        clr.l   mhi3_lib_base
mhi3_engine_exit:
        lea     mhi4d_e_exit,a0
        bsr     mhi4d_eng_log
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; MHI04 RELEASE: engine lifecycle logging disabled.
; rts+nop replaces the original 4-byte MOVEM so following code/data keep layout.
mhi4d_eng_log:
        rts
        nop
        ; Unreachable diagnostic implementation retained for source comparison.
        move.l  a0,a3
        move.l  4.w,a6
        lea     mhi4d_dos_name,a1
        moveq   #36,d0
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        beq.s   .out
        move.l  d0,a4
        lea     mhi4d_diag_path,a0
        move.l  a0,d1
        move.l  #MODE_READWRITE,d2
        move.l  a4,a6
        jsr     Open(a6)
        move.l  d0,d4
        bne.s   .opened
        lea     mhi4d_diag_path,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        move.l  d0,d4
        beq.s   .close_dos
.opened:
        move.l  d4,d1
        moveq   #0,d2
        moveq   #OFFSET_END,d3
        jsr     Seek(a6)
        move.l  a3,a0
        moveq   #0,d3
.len:
        tst.b   0(a0,d3.l)
        beq.s   .write
        addq.l  #1,d3
        bra.s   .len
.write:
        move.l  d4,d1
        move.l  a3,d2
        jsr     Write(a6)
        move.l  d4,d1
        jsr     Close(a6)
.close_dos:
        move.l  a4,a1
        move.l  4.w,a6
        jsr     CloseLibrary(a6)
.out:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; Signal MHI client owner. a3=handle.
mhi3_signal_owner:
        movem.l d0/a1/a6,-(sp)
        move.l  MHI3_H_TASK(a3),a1
        move.l  MHI3_H_SIGMASK(a3),d0
        tst.l   a1
        beq.s   .done
        tst.l   d0
        beq.s   .done
        move.l  4.w,a6
        jsr     MHI3_Signal(a6)
        addq.l  #1,MHI3_H_SIGNALED(a3)
.done:  movem.l (sp)+,d0/a1/a6
        rts

; Return the current fully/partly consumed MHI source buffer to the client.
; On controlled stop the buffer may be returned even if only partially copied;
; MHIStop semantics flush ownership back to the caller.
mhi3_stream_return_current:
        movem.l d0-d4/a0-a3/a6,-(sp)
        move.l  mhi3_cur_ptr,d4
        beq.w   .done
        move.l  mhi3_lib_base,a0
        beq.w   .clear
        lea     MHI3_B_HANDLE(a0),a3
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        bne.s   .clear
        move.l  4.w,a6
        jsr     MHI3_Forbid(a6)
        cmpi.w  #MHI3_QUEUE_SLOTS,MHI3_H_ECOUNT(a3)
        bhs.s   .permit_clear
        moveq   #0,d2
        move.w  MHI3_H_ETAIL(a3),d2
        lsl.l   #2,d2
        lea     MHI3_H_EBUFS(a3),a1
        move.l  d4,0(a1,d2.l)
        addq.w  #1,MHI3_H_ETAIL(a3)
        andi.w  #MHI3_QUEUE_MASK,MHI3_H_ETAIL(a3)
        addq.w  #1,MHI3_H_ECOUNT(a3)
        addq.l  #1,MHI3_H_CONSUMED(a3)
.permit_clear:
        jsr     MHI3_Permit(a6)
        bsr     mhi3_signal_owner
.clear:
        clr.l   mhi3_cur_ptr
        clr.l   mhi3_cur_size
        clr.l   mhi3_cur_pos
.done:  movem.l (sp)+,d0-d4/a0-a3/a6
        rts

; Acquire next compressed MHI buffer into mhi3_cur_*.
; D0=1 acquired, D0=0 queue empty/not playable.
mhi3_stream_acquire:
        movem.l d1-d5/a0-a3/a6,-(sp)
        clr.l   d5
        addq.l  #1,mhi3_front_acq_calls
        move.l  #1,mhi3_front_acq_reason       ; entered
        move.l  mhi3_lib_base,a0
        bne.s   .have_lib
        move.l  #2,mhi3_front_acq_reason       ; no library base
        bra.w   .done
.have_lib:
        lea     MHI3_B_HANDLE(a0),a3
        move.l  MHI3_H_MAGIC(a3),mhi3_front_pre_magic
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        beq.s   .magic_ok
        move.l  #3,mhi3_front_acq_reason       ; bad handle magic
        bra.w   .done
.magic_ok:
        tst.b   MHI3_H_STOPREQ(a3)
        beq.s   .stop_ok
        move.l  #4,mhi3_front_acq_reason       ; STOP requested
        bra.w   .done
.stop_ok:
        tst.b   MHI3_H_QUIT(a3)
        beq.s   .quit_ok
        move.l  #5,mhi3_front_acq_reason       ; QUIT requested
        bra.w   .done
.quit_ok:
        move.l  4.w,a6
        jsr     MHI3_Forbid(a6)
        tst.w   MHI3_H_QCOUNT(a3)
        bne.s   .queue_ok
        move.l  #6,mhi3_front_acq_reason       ; queue empty
        bra.s   .permit
.queue_ok:
        moveq   #0,d1
        move.w  MHI3_H_QHEAD(a3),d1
        move.l  d1,d2
        lsl.l   #2,d2
        lea     MHI3_H_QBUFS(a3),a1
        move.l  0(a1,d2.l),d3
        lea     MHI3_H_QSIZES(a3),a1
        move.l  0(a1,d2.l),d4
        addq.w  #1,MHI3_H_QHEAD(a3)
        andi.w  #MHI3_QUEUE_MASK,MHI3_H_QHEAD(a3)
        subq.w  #1,MHI3_H_QCOUNT(a3)
        move.l  d3,mhi3_cur_ptr
        move.l  d4,mhi3_cur_size
        clr.l   mhi3_cur_pos
        move.l  #7,mhi3_front_acq_reason       ; acquired one queue slot
        moveq   #1,d5
.permit:
        jsr     MHI3_Permit(a6)
.done:  move.l  d5,d0
        movem.l (sp)+,d1-d5/a0-a3/a6
        rts

; MHI03g: snapshot the queue state immediately before the first rolling read.
; This is read-only diagnostic state for the preloaded probe test.
mhi3_front_snapshot:
        movem.l d0-d4/a0-a3,-(sp)
        move.l  mhi3_lib_base,a0
        beq.w   .done
        lea     MHI3_B_HANDLE(a0),a3
        move.l  MHI3_H_MAGIC(a3),mhi3_front_pre_magic
        moveq   #0,d0
        move.w  MHI3_H_QCOUNT(a3),d0
        move.l  d0,mhi3_front_pre_qcount
        moveq   #0,d0
        move.w  MHI3_H_QHEAD(a3),d0
        move.l  d0,mhi3_front_pre_qhead
        moveq   #0,d0
        move.w  MHI3_H_QTAIL(a3),d0
        move.l  d0,mhi3_front_pre_qtail
        moveq   #0,d0
        move.b  MHI3_H_PLAYFLAG(a3),d0
        move.l  d0,mhi3_front_pre_play
        moveq   #0,d0
        move.b  MHI3_H_STOPREQ(a3),d0
        move.l  d0,mhi3_front_pre_stop
        moveq   #0,d0
        move.b  MHI3_H_QUIT(a3),d0
        move.l  d0,mhi3_front_pre_quit
        tst.w   MHI3_H_QCOUNT(a3)
        beq.s   .done
        moveq   #0,d1
        move.w  MHI3_H_QHEAD(a3),d1
        lsl.l   #2,d1
        lea     MHI3_H_QBUFS(a3),a1
        move.l  0(a1,d1.l),mhi3_front_pre_ptr
        lea     MHI3_H_QSIZES(a3),a1
        move.l  0(a1,d1.l),mhi3_front_pre_size
.done:
        movem.l (sp)+,d0-d4/a0-a3
        rts

; MHI byte source. Input D2=destination, D3=max bytes. Output D0=count.
; MHI03 intentionally treats an empty queue as end-of-stream; the first test
; therefore uses a short MP3 that is completely preloaded by the client.
mhi3_stream_read:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d2,a3
        move.l  d3,d6
        clr.l   d7
.loop:
        tst.l   d6
        beq.w   .done
        move.l  mhi3_cur_ptr,d0
        bne.s   .have_cur
        bsr     mhi3_stream_acquire
        tst.l   d0
        beq.w   .done
.have_cur:
        move.l  mhi3_cur_size,d4
        sub.l   mhi3_cur_pos,d4
        bne.s   .copy_ready
        bsr     mhi3_stream_return_current
        bra.s   .loop
.copy_ready:
        move.l  d6,d5
        cmp.l   d4,d5
        bls.s   .n_ok
        move.l  d4,d5
.n_ok:
        move.l  mhi3_cur_ptr,a1
        adda.l  mhi3_cur_pos,a1
        move.l  d5,d4
.copy:
        move.b  (a1)+,(a3)+
        subq.l  #1,d4
        bne.s   .copy
        add.l   d5,mhi3_cur_pos
        add.l   d5,d7
        add.l   d5,mhi3_read_total
        sub.l   d5,d6
        move.l  mhi3_cur_pos,d0
        cmp.l   mhi3_cur_size,d0
        bne.s   .loop
        bsr     mhi3_stream_return_current
        bra.s   .loop
.done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3
        rts


; Restore the proven BerryMP306/314 front-end rule for an initial ID3v2 tag.
; Input D0 = staged byte count in v19_aac_buf_ptr. Output D0 = audio bytes
; remaining after an optional leading ID3v2 header/tag has been removed.
mhi3_strip_initial_id3v2:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        clr.l   mhi3_id3_skip
        cmpi.l  #10,d7
        bcs.w   .done
        move.l  v19_aac_buf_ptr,a0
        cmpi.b  #'I',(a0)
        bne.w   .done
        cmpi.b  #'D',1(a0)
        bne.w   .done
        cmpi.b  #'3',2(a0)
        bne.w   .done
        moveq   #0,d1
        move.b  6(a0),d1
        btst    #7,d1
        bne.w   .done
        lsl.l   #7,d1
        moveq   #0,d2
        move.b  7(a0),d2
        btst    #7,d2
        bne.w   .done
        or.l    d2,d1
        lsl.l   #7,d1
        moveq   #0,d2
        move.b  8(a0),d2
        btst    #7,d2
        bne.w   .done
        or.l    d2,d1
        lsl.l   #7,d1
        moveq   #0,d2
        move.b  9(a0),d2
        btst    #7,d2
        bne.w   .done
        or.l    d2,d1
        addq.l  #8,d1
        addq.l  #2,d1
        cmp.l   d7,d1
        bhi.w   .done
        move.l  d1,mhi3_id3_skip
        move.l  d7,d6
        sub.l   d1,d6
        beq.s   .zero
        move.l  a0,a1
        adda.l  d1,a1
        move.l  a0,a2
        move.l  d6,d5
.copy:
        move.b  (a1)+,(a2)+
        subq.l  #1,d5
        bne.s   .copy
        move.l  d6,d7
        bra.s   .done
.zero:
        clr.l   d7
.done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a2
        rts


; MHI03e post-session diagnostic.
; Error codes in library B_ENGINE_ERROR:
;  0 success, 1 no MHI bytes, 2 CPU1 module/init not reached,
;  3 no decoded PCM batch, 4 no renderer chunk submitted,
;  5 no BULK_TX_DONE, 6 no renderer slot returned, 7 MMAL/audio error.
mhi3_diag_report:
        movem.l d0-d7/a0-a6,-(sp)
        move.l  mhi3_lib_base,a0
        tst.l   a0
        beq.w   .print
        clr.b   MHI3_B_ENGINE_ERROR(a0)
        tst.l   mhi3_read_total
        bne.s   .chk_cpu1
        move.b  #1,MHI3_B_ENGINE_ERROR(a0)
        bra.s   .print
.chk_cpu1:
        cmpi.l  #$00000040,vpv302_prepare_stage
        bcc.s   .chk_pcm
        move.b  #2,MHI3_B_ENGINE_ERROR(a0)
        bra.s   .print
.chk_pcm:
        tst.l   vpv48_batch_count
        bne.s   .chk_chunks
        move.b  #3,MHI3_B_ENGINE_ERROR(a0)
        bra.s   .print
.chk_chunks:
        tst.l   vpv53_chunk_count
        bne.s   .chk_bulk
        move.b  #4,MHI3_B_ENGINE_ERROR(a0)
        bra.s   .print
.chk_bulk:
        tst.l   vpv59_audio_bulk_done_count
        bne.s   .chk_return
        move.b  #5,MHI3_B_ENGINE_ERROR(a0)
        bra.s   .print
.chk_return:
        tst.l   vpv59_audio_return_count
        bne.s   .chk_bad
        move.b  #6,MHI3_B_ENGINE_ERROR(a0)
        bra.s   .print
.chk_bad:
        tst.l   vpv39_audio_failed
        bne.s   .audio_bad
        tst.l   vpv59_audio_bad_count
        beq.s   .print
.audio_bad:
        move.b  #7,MHI3_B_ENGINE_ERROR(a0)

.print:
        ; MHI04S SILENT: retain all diagnostic counters/error classification
        ; above, but do not attach to or write to any Shell/console.  The
        ; engine is a transparent background helper for AmiAMP.
        bra.w   .done

        ; Legacy diagnostic printer retained below for source-level debugging,
        ; deliberately unreachable in the silent production build.
        move.l  4.w,a4
        move.l  a4,a6
        lea     dosname,a1
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        beq.w   .done
        move.l  d0,a5
        move.l  a5,a6
        jsr     Output(a6)
        move.l  d0,h264rgb_output_handle

        lea     msg_mhi03d_diag,a1
        move.l  #msg_mhi03d_diag_end-msg_mhi03d_diag,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  mhi3_read_total,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_id3,a1
        move.l  #msg_mhi03d_id3_end-msg_mhi03d_id3,d3
        jsr     print_force
        move.l  mhi3_id3_skip,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_stage,a1
        move.l  #msg_mhi03d_stage_end-msg_mhi03d_stage,d3
        jsr     print_force
        move.l  vpv302_prepare_stage,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_batches,a1
        move.l  #msg_mhi03d_batches_end-msg_mhi03d_batches,d3
        jsr     print_force
        move.l  vpv48_batch_count,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_chunks,a1
        move.l  #msg_mhi03d_chunks_end-msg_mhi03d_chunks,d3
        jsr     print_force
        move.l  vpv53_chunk_count,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_bulk,a1
        move.l  #msg_mhi03d_bulk_end-msg_mhi03d_bulk,d3
        jsr     print_force
        move.l  vpv59_audio_bulk_done_count,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_return,a1
        move.l  #msg_mhi03d_return_end-msg_mhi03d_return,d3
        jsr     print_force
        move.l  vpv59_audio_return_count,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_bad,a1
        move.l  #msg_mhi03d_bad_end-msg_mhi03d_bad,d3
        jsr     print_force
        move.l  vpv59_audio_bad_count,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03d_err,a1
        move.l  #msg_mhi03d_err_end-msg_mhi03d_err,d3
        jsr     print_force
        moveq   #0,d0
        move.l  mhi3_lib_base,a0
        tst.l   a0
        beq.s   .err_ready
        move.b  MHI3_B_ENGINE_ERROR(a0),d0
.err_ready:
        jsr     mhi3_print_hex32_force
        jsr     mhi3_newline_force

        lea     msg_mhi03g_front,a1
        move.l  #msg_mhi03g_front_end-msg_mhi03g_front,d3
        jsr     print_force
        move.l  mhi3_front_stage,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_alloc,a1
        move.l  #msg_mhi03g_alloc_end-msg_mhi03g_alloc,d3
        jsr     print_force
        move.l  mhi3_front_alloc_ptr,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_read,a1
        move.l  #msg_mhi03g_read_end-msg_mhi03g_read,d3
        jsr     print_force
        move.l  mhi3_front_read_ret,d0
        jsr     mhi3_print_hex32_force
