        move.l  #msg_mhi03g_id3ret_end-msg_mhi03g_id3ret,d3
        jsr     print_force
        move.l  mhi3_front_id3_ret,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_magic,a1
        move.l  #msg_mhi03g_magic_end-msg_mhi03g_magic,d3
        jsr     print_force
        move.l  mhi3_front_pre_magic,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_qcount,a1
        move.l  #msg_mhi03g_qcount_end-msg_mhi03g_qcount,d3
        jsr     print_force
        move.l  mhi3_front_pre_qcount,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_head,a1
        move.l  #msg_mhi03g_head_end-msg_mhi03g_head,d3
