        move.l  mhi3_front_pre_qhead,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_tail,a1
        move.l  #msg_mhi03g_tail_end-msg_mhi03g_tail,d3
        jsr     print_force
        move.l  mhi3_front_pre_qtail,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_play,a1
        move.l  #msg_mhi03g_play_end-msg_mhi03g_play,d3
        jsr     print_force
        move.l  mhi3_front_pre_play,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_stop,a1
        move.l  #msg_mhi03g_stop_end-msg_mhi03g_stop,d3
        jsr     print_force
        move.l  mhi3_front_pre_stop,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_quit,a1
        move.l  #msg_mhi03g_quit_end-msg_mhi03g_quit,d3
        jsr     print_force
        move.l  mhi3_front_pre_quit,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_ptr,a1
        move.l  #msg_mhi03g_ptr_end-msg_mhi03g_ptr,d3
        jsr     print_force
        move.l  mhi3_front_pre_ptr,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_size,a1
        move.l  #msg_mhi03g_size_end-msg_mhi03g_size,d3
        jsr     print_force
        move.l  mhi3_front_pre_size,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_acq,a1
        move.l  #msg_mhi03g_acq_end-msg_mhi03g_acq,d3
        jsr     print_force
        move.l  mhi3_front_acq_reason,d0
        jsr     mhi3_print_hex32_force
        lea     msg_mhi03g_calls,a1
        move.l  #msg_mhi03g_calls_end-msg_mhi03g_calls,d3
        jsr     print_force
        move.l  mhi3_front_acq_calls,d0
        jsr     mhi3_print_hex32_force
        jsr     mhi3_newline_force
        clr.l   v41l_force_print

        move.l  a5,a1
        move.l  a4,a6
        jsr     CloseLibrary(a6)
.done:
        movem.l (sp)+,d0-d7/a0-a6
        rts

; MHI03g: each diagnostic hex value must bypass MP314 quiet-output filtering.
mhi3_print_hex32_force:
        move.l  #1,v41l_force_print
        bsr     print_hex32
        clr.l   v41l_force_print
        rts

mhi3_newline_force:
        move.l  #1,v41l_force_print
        bsr     newline
        clr.l   v41l_force_print
        rts

        section data,data
msg_mhi03d_diag:
