        even
        section code,code

mp314_original_start:
        ; V40 keeps the original CLI bytes alive while the player engine may
        ; perform a complete cleanup + restart cycle after a size request.
        move.l  d0,v32r_root_cli_len
        move.l  a0,v32r_root_cli_ptr
        clr.l   v32r_restart_cycle
        clr.l   v32r_restart_armed
        clr.l   v32r_fastforward
        clr.l   v32r_restart_count

v32r_process_loop:
        move.l  v32r_root_cli_len,d0
        move.l  v32r_root_cli_ptr,a0
        bsr     h264rgb_main
        tst.l   v32r_restart_armed
        beq.s   v32r_process_done
        clr.l   v32r_restart_armed
        move.l  #1,v32r_restart_cycle
        addq.l  #1,v32r_restart_count
        bra.w   v32r_process_loop
v32r_process_done:
        rts

; --------------------------------------------------------------------
; h264rgb V1 command-line parser
;
; AmigaDOS CLI entry: D0 = command line length, A0 = command line bytes.
; Copies the first argument into t23_file_name. Quoted paths are accepted.
; Return D0=0 on success, D0=1 if no usable filename was supplied.
; --------------------------------------------------------------------
h264rgb_parse_arg:
        movem.l d1-d3/a0-a1,-(sp)

        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d0
        tst.l   d0
        beq.w   h264rgb_parse_fail

h264rgb_skip_ws:
        tst.l   d0
        beq.w   h264rgb_parse_fail
        move.b  (a0),d1
        cmpi.b  #$20,d1
        beq.s   h264rgb_skip_one
        cmpi.b  #9,d1
        bne.s   h264rgb_arg_begin
h264rgb_skip_one:
        addq.l  #1,a0
        subq.l  #1,d0
        bra.s   h264rgb_skip_ws

h264rgb_arg_begin:
        lea     t23_file_name,a1
        clr.l   d3
        moveq   #0,d2
        cmpi.b  #$22,d1
        bne.s   h264rgb_copy_loop
        moveq   #1,d2
        addq.l  #1,a0
        subq.l  #1,d0

h264rgb_copy_loop:
        tst.l   d0
        beq.s   h264rgb_copy_done
        move.b  (a0)+,d1
        subq.l  #1,d0

        tst.b   d2
        beq.s   h264rgb_check_plain_end
        cmpi.b  #$22,d1
        beq.s   h264rgb_copy_done
        bra.s   h264rgb_store_char

h264rgb_check_plain_end:
        cmpi.b  #$20,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #9,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #10,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #13,d1
        beq.s   h264rgb_copy_done

h264rgb_store_char:
        cmpi.l  #255,d3
        bcc.s   h264rgb_parse_fail
        move.b  d1,(a1)+
        addq.l  #1,d3
        bra.s   h264rgb_copy_loop

h264rgb_copy_done:
        tst.l   d3
        beq.s   h264rgb_parse_fail
        clr.b   (a1)
        moveq   #0,d0
        bra.s   h264rgb_parse_done

h264rgb_parse_fail:
        moveq   #1,d0
h264rgb_parse_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; --------------------------------------------------------------------
; H264RGB4 - find SPS/PPS NAL units in the selected raw Annex-B H264 file.
;
; The probe reads the first 4096 bytes, recognises both 00 00 01 and
; 00 00 00 01 start codes, and extracts the first SPS (NAL type 7) and
; first PPS (NAL type 8), including their original Annex-B start codes.
; The two NAL units are concatenated into h264_file_extradata and the
; actual combined length is sent as MMAL extradata_size (max 128 bytes).
;
; Playback later reopens the same file from byte 0, so the stable live
; streaming path is unchanged.
;
; h264_find_nal input: D0 = wanted NAL type (7=SPS, 8=PPS)
; output: D0=1 found / 0 not found, A0=start-code pointer, D1=NAL bytes
;         through (but excluding) the following Annex-B start code.
; --------------------------------------------------------------------
h264_find_nal:
        movem.l d2-d7/a1-a3,-(sp)
        move.l  d0,d7
        lea     h264_probe_buf,a1
        move.l  h264_probe_read,d6
        move.l  a1,a3
        add.l   d6,a3

h264_find_scan:
        move.l  a3,d0
        sub.l   a1,d0
        cmp.l   #5,d0
        bcs.w   h264_find_not_found

        tst.b   (a1)
        bne.s   h264_find_advance
        tst.b   1(a1)
        bne.s   h264_find_advance
        cmp.b   #1,2(a1)
        beq.s   h264_find_start3
        tst.b   2(a1)
        bne.s   h264_find_advance
        cmp.b   #1,3(a1)
        beq.s   h264_find_start4

h264_find_advance:
        addq.l  #1,a1
        bra.w   h264_find_scan

h264_find_start3:
        moveq   #3,d2
        moveq   #0,d0
        move.b  3(a1),d0
        bra.s   h264_find_check_type

h264_find_start4:
        moveq   #4,d2
        moveq   #0,d0
        move.b  4(a1),d0

h264_find_check_type:
        and.l   #$1F,d0
        cmp.l   d7,d0
        beq.s   h264_find_target

        ; Skip this complete start code and its NAL header so a 4-byte
        ; start code cannot be rediscovered one byte later as a 3-byte code.
        add.l   d2,a1
        addq.l  #1,a1
        bra.w   h264_find_scan

h264_find_target:
        move.l  a1,a0
        move.l  a1,a2
        add.l   d2,a2
        addq.l  #1,a2

        ; Find the next Annex-B start code, which defines the end of this NAL.
h264_find_next:
        move.l  a3,d0
        sub.l   a2,d0
        cmp.l   #3,d0
        bcs.w   h264_find_not_found

        tst.b   (a2)
        bne.s   h264_find_next_advance
        tst.b   1(a2)
        bne.s   h264_find_next_advance
        cmp.b   #1,2(a2)
        beq.s   h264_find_boundary
        cmp.l   #4,d0
        bcs.s   h264_find_next_advance
        tst.b   2(a2)
        bne.s   h264_find_next_advance
        cmp.b   #1,3(a2)
        beq.s   h264_find_boundary

h264_find_next_advance:
        addq.l  #1,a2
        bra.w   h264_find_next

h264_find_boundary:
        move.l  a2,d1
        sub.l   a0,d1
        moveq   #1,d0
        bra.s   h264_find_done

h264_find_not_found:
        moveq   #0,d0
        clr.l   d1

h264_find_done:
        movem.l (sp)+,d2-d7/a1-a3
        rts


h264rgb_load_file_extradata:
        movem.l d1-d7/a0-a3/a6,-(sp)

        clr.l   h264_probe_handle
        clr.l   h264_probe_read
        clr.l   h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   h264rgb_probe_open_fail
        move.l  d0,h264_probe_handle

        move.l  d0,d1
        lea     h264_probe_buf,a0
        move.l  a0,d2
        move.l  #H264_PROBE_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,h264_probe_read

        move.l  h264_probe_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   h264_probe_handle

        move.l  h264_probe_read,d0
        cmp.l   #8,d0
        bcs.w   h264rgb_probe_read_fail

        moveq   #7,d0
        bsr     h264_find_nal
        tst.l   d0
        beq.w   h264rgb_probe_no_sps
        move.l  a0,h264_sps_ptr
        move.l  d1,h264_sps_len

        moveq   #8,d0
        bsr     h264_find_nal
        tst.l   d0
        beq.w   h264rgb_probe_no_pps
        move.l  a0,h264_pps_ptr
        move.l  d1,h264_pps_len

        move.l  h264_sps_len,d0
        add.l   h264_pps_len,d0
        tst.l   d0
        beq.w   h264rgb_probe_no_sps
        move.l  d0,h264_codec_config_len
        cmp.l   #H264_CODEC_CONFIG_MAX,d0
        bhi.w   h264rgb_probe_too_large

        ; Clear max-sized destination then concatenate SPS followed by PPS.
        lea     h264_file_extradata,a0
        moveq   #31,d7
h264rgb_extra_clear:
        clr.l   (a0)+
        dbra    d7,h264rgb_extra_clear

        move.l  h264_sps_ptr,a0
        lea     h264_file_extradata,a1
        move.l  h264_sps_len,d7
        subq.l  #1,d7
h264rgb_copy_sps:
        move.b  (a0)+,(a1)+
        dbra    d7,h264rgb_copy_sps

        move.l  h264_pps_ptr,a0
        move.l  h264_pps_len,d7
        subq.l  #1,d7
h264rgb_copy_pps:
        move.b  (a0)+,(a1)+
        dbra    d7,h264rgb_copy_pps

        lea     msg_hr4_sps,a1
        move.l  #msg_hr4_sps_end-msg_hr4_sps,d3
        jsr     print
        move.l  h264_sps_len,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_hr4_pps,a1
        move.l  #msg_hr4_pps_end-msg_hr4_pps,d3
        jsr     print
        move.l  h264_pps_len,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_hr4_extra,a1
        move.l  #msg_hr4_extra_end-msg_hr4_extra,d3
        jsr     print
        move.l  h264_codec_config_len,d0
        jsr     print_hex32
        jsr     newline

        moveq   #0,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_open_fail:
        lea     e_hr4_probe_open,a1
        move.l  #e_hr4_probe_open_end-e_hr4_probe_open,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_read_fail:
        lea     e_hr4_probe_read,a1
        move.l  #e_hr4_probe_read_end-e_hr4_probe_read,d3
        jsr     print
        move.l  h264_probe_read,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_no_sps:
        lea     e_hr4_no_sps,a1
        move.l  #e_hr4_no_sps_end-e_hr4_no_sps,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_no_pps:
        lea     e_hr4_no_pps,a1
        move.l  #e_hr4_no_pps_end-e_hr4_no_pps,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_too_large:
        lea     e_hr4_too_large,a1
        move.l  #e_hr4_too_large_end-e_hr4_too_large,d3
        jsr     print
        move.l  h264_codec_config_len,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0

h264rgb_probe_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; ====================================================================
; V10 EXTERNAL LUT LOADER
; Keeps the executable small while preserving the exact same Fast-RAM
; lookup access pattern during HAM6 conversion.
; ====================================================================
; Input: D0=size, A0=filename, A1=address of pointer variable
; Output: D0=0 success, D0=1 failure. On failure this allocation is freed.
v9m_load_one_lut:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  d0,d7
        move.l  a0,a2
        move.l  a1,a3
        clr.l   (a3)

        move.l  a4,a6
        move.l  d7,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   v9m_load_one_fail
        move.l  d0,(a3)

        move.l  a5,a6
        move.l  a2,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   v9m_load_one_free_fail
        move.l  d0,d6

        move.l  d6,d1
        move.l  (a3),d2
        move.l  d7,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,d5

        move.l  d6,d1
        move.l  a5,a6
        jsr     Close(a6)

        cmp.l   d7,d5
        bne.s   v9m_load_one_free_fail
        moveq   #0,d0
        bra.s   v9m_load_one_done

v9m_load_one_free_fail:
        move.l  (a3),d0
        beq.s   v9m_load_one_fail
        move.l  d0,a1
        move.l  d7,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   (a3)

v9m_load_one_fail:
        moveq   #1,d0
v9m_load_one_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9m_load_luts:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr

        lea     msg_v9m_lut_start,a1
        move.l  #msg_v9m_lut_start_end-msg_v9m_lut_start,d3
        jsr     print

        lea     v9m_ham_name,a0
        move.l  #V10_HAM_LUT_SIZE,d0
        lea     v9m_ham_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_ham_fail
        lea     msg_v9m_ham_ok,a1
        move.l  #msg_v9m_ham_ok_end-msg_v9m_ham_ok,d3
        jsr     print

        lea     v9m_edge_name,a0
        move.l  #V10_EDGE_LUT_SIZE,d0
        lea     v9m_edge_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_edge_fail
        lea     msg_v9m_edge_ok,a1
        move.l  #msg_v9m_edge_ok_end-msg_v9m_edge_ok,d3
        jsr     print

        lea     v9m_state_name,a0
        move.l  #V10_STATE_LUT_SIZE,d0
        lea     v9m_state_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_state_fail
        lea     msg_v9m_state_ok,a1
        move.l  #msg_v9m_state_ok_end-msg_v9m_state_ok,d3
        jsr     print

        lea     msg_v9m_lut_all_ok,a1
        move.l  #msg_v9m_lut_all_ok_end-msg_v9m_lut_all_ok,d3
        bsr     print
        moveq   #0,d0
        bra.s   v9m_load_luts_done

v9m_load_ham_fail:
        lea     e_v9m_ham,a1
        move.l  #e_v9m_ham_end-e_v9m_ham,d3
        bsr     print
        bra.s   v9m_load_luts_fail
v9m_load_edge_fail:
        lea     e_v9m_edge,a1
        move.l  #e_v9m_edge_end-e_v9m_edge,d3
        bsr     print
        bra.s   v9m_load_luts_fail
v9m_load_state_fail:
        lea     e_v9m_state,a1
        move.l  #e_v9m_state_end-e_v9m_state,d3
        bsr     print
v9m_load_luts_fail:
        jsr     v9m_free_luts
        moveq   #1,d0
v9m_load_luts_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9m_free_luts:
        movem.l d0-d7/a0-a3/a6,-(sp)
        move.l  v9m_ham_lut_ptr,d0
        or.l    v9m_edge_lut_ptr,d0
        or.l    v9m_state_lut_ptr,d0
        beq.w   v9m_free_luts_done

        lea     msg_v9m_lut_free,a1
        move.l  #msg_v9m_lut_free_end-msg_v9m_lut_free,d3
        bsr     print

        move.l  a4,a6
        move.l  v9m_ham_lut_ptr,d0
        beq.s   v9m_free_no_ham
        move.l  d0,a1
        move.l  #V10_HAM_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_ham_lut_ptr
v9m_free_no_ham:
        move.l  v9m_edge_lut_ptr,d0
        beq.s   v9m_free_no_edge
        move.l  d0,a1
        move.l  #V10_EDGE_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_edge_lut_ptr
v9m_free_no_edge:
        move.l  v9m_state_lut_ptr,d0
        beq.s   v9m_free_no_state
        move.l  d0,a1
        move.l  #V10_STATE_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_state_lut_ptr
v9m_free_no_state:
        lea     msg_v9m_lut_free_ok,a1
        move.l  #msg_v9m_lut_free_ok_end-msg_v9m_lut_free_ok,d3
        bsr     print
v9m_free_luts_done:
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts


; --------------------------------------------------------------------
; V10P - Raspberry Pi firmware memory split diagnostic, AFTER the
; already-proven VCHIQ_INIT property transaction.
;
; Reuses the exact property buffer/physical mapping that successfully
; completed VCHIQ_INIT.  Queries are deliberately sent one at a time:
;   0x00010005 GET_ARM_MEMORY -> base,size
;   0x00010006 GET_VC_MEMORY  -> base,size
; For each reply the complete mailbox response word (address+channel)
; must equal the request word.  Failure is non-fatal.
; --------------------------------------------------------------------
v10l_query_firmware_memory_after_init:
        movem.l d0-d7/a0-a3/a6,-(sp)
        clr.l   v10k_arm_base
        clr.l   v10k_arm_size
        clr.l   v10k_vc_base
        clr.l   v10k_vc_size
        clr.l   v10k_query_result

        lea     msg_v10k_mem_start,a1
        move.l  #msg_v10k_mem_start_end-msg_v10k_mem_start,d3
        jsr     print

        ; The normal VCHIQ_INIT path has already proven all three facts below.
        move.l  prop_alloc,d0
        beq.w   v10l_mem_fail_precondition
        move.l  prop_ptr,d0
        beq.w   v10l_mem_fail_precondition
        cmp.l   prop_phys,d0
        bne.w   v10l_mem_fail_precondition

        lea     msg_v10l_reuse,a1
        move.l  #msg_v10l_reuse_end-msg_v10l_reuse,d3
        jsr     print
        move.l  prop_phys,d0
        jsr     print_hex32
        jsr     newline

        ; Query ARM memory first.
        move.l  #$00010005,d0
        jsr     v10l_query_one_memory_tag
        tst.l   d0
        bne.w   v10l_mem_fail_arm
        move.l  d1,v10k_arm_base
        move.l  d2,v10k_arm_size

        ; Query VideoCore memory separately.
        move.l  #$00010006,d0
        jsr     v10l_query_one_memory_tag
        tst.l   d0
        bne.w   v10l_mem_fail_vc
        move.l  d1,v10k_vc_base
        move.l  d2,v10k_vc_size

        lea     msg_v10k_arm,a1
        move.l  #msg_v10k_arm_end-msg_v10k_arm,d3
        jsr     print
        move.l  v10k_arm_base,d0
        jsr     print_hex32
        lea     msg_v10k_sep,a1
        move.l  #msg_v10k_sep_end-msg_v10k_sep,d3
        jsr     print
        move.l  v10k_arm_size,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10k_vc,a1
        move.l  #msg_v10k_vc_end-msg_v10k_vc,d3
        jsr     print
        move.l  v10k_vc_base,d0
        jsr     print_hex32
        lea     msg_v10k_sep,a1
        move.l  #msg_v10k_sep_end-msg_v10k_sep,d3
        jsr     print
        move.l  v10k_vc_size,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10k_vc_mib,a1
        move.l  #msg_v10k_vc_mib_end-msg_v10k_vc_mib,d3
        jsr     print
        move.l  v10k_vc_size,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        jsr     print_hex32
        lea     msg_v10k_mib_suffix,a1
        move.l  #msg_v10k_mib_suffix_end-msg_v10k_mib_suffix,d3
        jsr     print
        moveq   #0,d6
        bra.w   v10l_mem_done

v10l_mem_fail_precondition:
        lea     msg_v10l_mem_precond_fail,a1
        move.l  #msg_v10l_mem_precond_fail_end-msg_v10l_mem_precond_fail,d3
        jsr     print
        moveq   #1,d6
        bra.s   v10l_mem_done
v10l_mem_fail_arm:
        lea     msg_v10l_arm_fail,a1
        move.l  #msg_v10l_arm_fail_end-msg_v10l_arm_fail,d3
        jsr     print
        moveq   #1,d6
        bra.s   v10l_mem_done
v10l_mem_fail_vc:
        lea     msg_v10l_vc_fail,a1
        move.l  #msg_v10l_vc_fail_end-msg_v10l_vc_fail,d3
        jsr     print
        moveq   #1,d6

v10l_mem_done:
        move.l  d6,v10k_query_result
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts

; D0 = property tag. Returns D0=0 success, D1=base, D2=size.
; Returns nonzero on failure. Uses only the already-proven prop_ptr buffer.
v10l_query_one_memory_tag:
        movem.l d3-d7/a0-a2/a6,-(sp)
        move.l  d0,d3                  ; requested tag
        clr.l   d1
        clr.l   d2

        move.l  prop_ptr,a2
        cmpa.l  #0,a2
        beq.w   v10l_q_fail

        ; 32-byte property message with one 8-byte memory tag.
        move.l  a2,a0
        move.l  #32,d0
        jsr     store_le32
        lea     4(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  d3,d0
        jsr     store_le32
        lea     12(a2),a0
        moveq   #8,d0
        jsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     20(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        jsr     store_le32

        ; Same CachePreDMA/physical identity convention as proven VCHIQ_INIT.
        move.l  #32,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,d4                  ; returned physical address
        cmp.l   prop_ptr,d0
        bne.w   v10l_q_post_fail

        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d6                  ; exact request word (phys+channel)

        move.l  #TIMEOUT,d7
v10l_q_tx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.s   v10l_q_tx_ready
        subq.l  #1,d7
        bne.s   v10l_q_tx_wait
        bra.w   v10l_q_post_fail
v10l_q_tx_ready:
        move.l  d6,d0
        jsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
v10l_q_rx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.s   v10l_q_rx_ready
        subq.l  #1,d7
        bne.s   v10l_q_rx_wait
        bra.w   v10l_q_post_fail
v10l_q_rx_ready:
        move.l  MBOX_READ,d0
        jsr     bswap32
        cmp.l   d6,d0                  ; V10P: exact address+channel match
        beq.s   v10l_q_got_exact
        subq.l  #1,d7
        bne.s   v10l_q_rx_wait
        bra.w   v10l_q_post_fail

v10l_q_got_exact:
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a2
        lea     4(a2),a0
        jsr     load_le32
        cmp.l   #$80000000,d0
        bne.s   v10l_q_fail_no_post
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   d3,d0
        bne.s   v10l_q_fail_no_post
        lea     16(a2),a0
        jsr     load_le32
        cmp.l   #$80000008,d0
        bne.s   v10l_q_fail_no_post
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,d1
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,d2
        moveq   #0,d0
        bra.s   v10l_q_done

v10l_q_post_fail:
        ; CachePreDMA has begun: always close the phase before returning.
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
v10l_q_fail_no_post:
v10l_q_fail:
        moveq   #1,d0
v10l_q_done:
        movem.l (sp)+,d3-d7/a0-a2/a6
        rts

; --------------------------------------------------------------------
; V14 - shell-local Ctrl-C stop support.
;
; AmigaDOS sends SIGBREAKF_CTRL_C to the running CLI process.  Poll it with
; Exec SetSignal(0,mask), which returns and clears only the selected break bit.
; No raw keyboard/ESC hook is installed, so Workbench applications keep normal
; keyboard ownership while the film is visible on RGB.
; --------------------------------------------------------------------
v15_clear_ctrl_c:
        movem.l d1/a6,-(sp)
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        movem.l (sp)+,d1/a6
        rts

; Return D0=1 only when a fresh Ctrl-C was observed on this poll.
; The persistent flag remains set until the process finishes its controlled EOS.
v15_poll_ctrl_c:
        movem.l d1-d2/a0/a6,-(sp)
        clr.l   d2
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        and.l   #SIGBREAKF_CTRL_C,d0
        beq.s   v15_poll_ctrl_c_no_shell
        move.l  #1,v15_stop_requested
        moveq   #1,d2
v15_poll_ctrl_c_no_shell:
        ; MHIStop/MHIFreeDecoder is another controlled stop source.
        move.l  mhi3_lib_base,a0
        tst.l   a0
        beq.s   v15_poll_ctrl_c_no_mhi
        lea     MHI3_B_HANDLE(a0),a0
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a0)
        bne.s   v15_poll_ctrl_c_no_mhi
        tst.b   MHI3_H_STOPREQ(a0)
        bne.s   v15_poll_ctrl_c_mhi_stop
        tst.b   MHI3_H_QUIT(a0)
        bne.s   v15_poll_ctrl_c_mhi_stop

        ; MHI03g PAUSE FIX:
        ; MHIPause() already sets H_STATUS=PAUSED and clears H_PLAYFLAG.
        ; The old MP314 body only observed STOPREQ/QUIT while active, so audio
        ; continued despite AmiAMP reporting a paused decoder.  Freeze this
        ; external engine process at its existing cooperative control poll.
        ; MHIPlay(), MHIStop() and MHIFreeDecoder() all signal the engine task,
        ; therefore Wait() sleeps without burning CPU and resumes immediately.
        cmpi.b  #MHI3_MHIF_PAUSED,MHI3_H_STATUS(a0)
        bne.s   v15_poll_ctrl_c_no_mhi
v15_poll_ctrl_c_pause_wait:
        move.l  mhi3_engine_sigmask,d0
        ori.l   #SIGBREAKF_CTRL_C,d0
        move.l  a4,a6
        jsr     MHI3_Wait(a6)
        btst    #12,d0
        bne.s   v15_poll_ctrl_c_pause_ctrl_c
        move.l  mhi3_lib_base,a0
        tst.l   a0
        beq.s   v15_poll_ctrl_c_no_mhi
        lea     MHI3_B_HANDLE(a0),a0
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a0)
        bne.s   v15_poll_ctrl_c_no_mhi
        tst.b   MHI3_H_STOPREQ(a0)
        bne.s   v15_poll_ctrl_c_mhi_stop
        tst.b   MHI3_H_QUIT(a0)
        bne.s   v15_poll_ctrl_c_mhi_stop
        cmpi.b  #MHI3_MHIF_PAUSED,MHI3_H_STATUS(a0)
        beq.s   v15_poll_ctrl_c_pause_wait
        bra.s   v15_poll_ctrl_c_no_mhi
v15_poll_ctrl_c_pause_ctrl_c:
        move.l  #1,v15_stop_requested
        moveq   #1,d2
        bra.s   v15_poll_ctrl_c_no_mhi

v15_poll_ctrl_c_mhi_stop:
        move.l  #1,v15_stop_requested
        moveq   #1,d2
v15_poll_ctrl_c_no_mhi:
        bsr     hdmi_v40o_poll_window_close
        or.l    d0,d2
        move.l  d2,d0
        movem.l (sp)+,d1-d2/a0/a6
        rts

; --------------------------------------------------------------------
; HDMI_v41L - real-time video pacing with ZERO Exec interrupt installation.
;
; v02 used AddIntServer(INTB_VERTB) only as a 50-Hz clock. That was intended
; to be display-neutral, but v04 removes even that variable while diagnosing
; Workbench/RTG ownership. The only Amiga custom-chip access here is READ-ONLY:
; VPOSR/VHPOSR are sampled in a busy wait and vertical raster wrap increments
; a private software tick counter. No Copper, bitplane, DMA or interrupt state
; is changed by the HDMI timing path.
;
; v7_setup_timing has already validated v7_fps_num / v7_fps_den. One frame
; advances by 50*fps_den/fps_num PAL refreshes. Absolute rational deadlines
; retain the v02 cadence (25 fps = 2 ticks; 23.976/30 fps use mixed intervals).
; --------------------------------------------------------------------
v04_timing_reset:
        movem.l d0-d2,-(sp)
        clr.l   v04_clock_started
        clr.l   v04_clock_accum
        clr.l   v04_clock_target
        clr.l   v04_paced_frames
        clr.l   v04_clock_counter
        clr.l   v04_last_raster
        clr.l   hdmi_v40o_dump_count
        clr.l   hdmi_v40o_dump_first_offset
        clr.l   hdmi_v40o_dump_second_offset
        clr.l   hdmi_v40o_merge_count
        clr.l   hdmi_v40o_merge_last_src
        clr.l   hdmi_v40o_merge_fail
        clr.l   hdmi_v40o_merge_retry
        clr.l   hdmi_v40o_slot_a
        clr.l   hdmi_v40o_slot_b
        clr.l   hdmi_v40o_slots_reported
        clr.l   hdmi_v40o_last_patched
        clr.l   hdmi_v40o_live_line_valid
        clr.l   hdmi_v40o_live_last_line
        clr.l   hdmi_v40o_live_shadow_sel
        clr.l   hdmi_v40o_live_switches
        clr.l   hdmi_v40o_live_misses
        clr.l   hdmi_v40o_live_reasserts
        move.l  v7_fps_den,d0
        mulu.w  #50,d0
        move.l  d0,v04_clock_step_num
        move.l  v7_fps_num,d0
        move.l  d0,v04_clock_step_den
        ; Explicit proof that HDMI timing never publishes an RGB display ptr.
        clr.l   t30_active_ptr
        clr.l   t31s_vblank_installed
        bsr     v41e_hr_timing_reset
        movem.l (sp)+,d0-d2
        rts

; Read stable 9-bit PAL raster line into D0 (0..311 typical).
; VPOSR bit 0 is vertical bit 8, VHPOSR high byte carries vertical bits 7..0.
; If vertical bit 8 changes between the two samples, retry to avoid a false
; 255->256 transition looking like a frame wrap.
v04_sample_raster:
        movem.l d1-d3/a0,-(sp)
        lea     CUSTOM_BASE,a0
v04_sample_raster_retry:
        moveq   #0,d1
        move.w  VPOSR(a0),d1
        moveq   #0,d2
        move.w  VHPOSR(a0),d2
        moveq   #0,d3
        move.w  VPOSR(a0),d3
        eor.w   d1,d3
        btst    #0,d3
        bne.s   v04_sample_raster_retry
        andi.w  #$0001,d1
        lsl.w   #8,d1
        lsr.w   #8,d2
        andi.w  #$00ff,d2
        or.w    d2,d1
        moveq   #0,d0
        move.w  d1,d0
        movem.l (sp)+,d1-d3/a0
        rts

; Update passive 50-Hz clock by detecting 311->0 raster wrap.
v04_clock_poll:
        movem.l d1,-(sp)
        bsr     v04_sample_raster
        move.l  v04_last_raster,d1
        cmp.l   d1,d0
        bcc.s   v04_clock_no_wrap
        addq.l  #1,v04_clock_counter
v04_clock_no_wrap:
        move.l  d0,v04_last_raster
        move.l  v04_clock_counter,d0
        movem.l (sp)+,d1
        rts

; D0 <- next interval in 50-Hz ticks, rational remainder retained.
v04_next_interval:
        movem.l d1-d3,-(sp)
        move.l  v04_clock_accum,d0
        add.l   v04_clock_step_num,d0
        move.l  v04_clock_step_den,d1
        tst.l   d1
        beq.s   v04_next_interval_fallback
        divu.w  d1,d0
        move.l  d0,d2
        and.l   #$0000ffff,d0
        swap    d2
        and.l   #$0000ffff,d2
        move.l  d2,v04_clock_accum
        tst.l   d0
        bne.s   v04_next_interval_done
v04_next_interval_fallback:
        moveq   #1,d0
v04_next_interval_done:
        movem.l (sp)+,d1-d3
        rts

; Pace one new container video access unit. First frame is immediate. Later
; frames wait for an absolute passive-raster deadline. Ctrl-C remains sampled.
v04_pace_new_frame:
        ; V41I: hidden restart catch-up must be unpaced in EVERY display style,
        ; including mode 3. V41E/G sent the hidden mode-3 pre-roll at native FPS,
        ; making the cinema switch wait roughly the already-played movie time.
        tst.l   v32r_fastforward
        bne.s   v41i_pace_fastforward
        cmpi.l  #3,v41_display_style
        beq.w   v41e_hr_pace_new_frame
        movem.l d1-d4,-(sp)
        bra.s   v32r_pace_normal
v41i_pace_fastforward:
        movem.l d1-d4,-(sp)
        addq.l  #1,v04_paced_frames
        bsr     v15_poll_ctrl_c
        bra.w   v04_pace_done
v32r_pace_normal:
        jsr     hdmi_v40o_probe_video_dlist
        jsr     hdmi_v40o_live_merge_poll
        move.l  v04_clock_started,d0
        bne.s   v04_pace_wait
        bsr     v04_sample_raster
        move.l  d0,v04_last_raster
        clr.l   v04_clock_counter
        move.l  #1,v04_clock_started
        clr.l   v04_clock_target
        bsr     v04_next_interval
        add.l   d0,v04_clock_target
        addq.l  #1,v04_paced_frames
        bra.s   v04_pace_done

v04_pace_wait:
        move.l  v04_clock_target,d3
v04_pace_wait_loop:
        bsr     v04_clock_poll
        jsr     hdmi_v40o_live_merge_poll
        cmp.l   d3,d0
        bcc.s   v04_pace_reached
        bsr     v15_poll_ctrl_c
        move.l  v15_stop_requested,d0
        tst.l   d0
        bne.s   v04_pace_reached
        bra.s   v04_pace_wait_loop
v04_pace_reached:
        bsr     v04_next_interval
        add.l   d0,v04_clock_target
        addq.l  #1,v04_paced_frames
v04_pace_done:
        movem.l (sp)+,d1-d4
        rts

; --------------------------------------------------------------------
; HDMI_v41L mode 3 high-resolution software pacing.
; The old host feeder advanced only on 50-Hz PAL frame boundaries (20 ms),
; which quantized 29.97/30-fps delivery into visibly uneven 20/40-ms bursts.
; Mode 3 now uses the PAL beam *line* counter as a 15600-Hz monotonic clock
; (312 lines * 50 Hz). This keeps the proven no-interrupt/read-only policy but
; gives ~64-us timing resolution. Modes 1/2 retain the established V41D path.
; --------------------------------------------------------------------
v41e_hr_timing_reset:
        movem.l d0-d1,-(sp)
        clr.l   v41e_hr_started
        clr.l   v41e_hr_base
        clr.l   v41e_hr_last_line
        clr.l   v41e_hr_target
        clr.l   v41e_hr_accum
        move.l  v7_fps_den,d0
        mulu.w  #15600,d0
        move.l  d0,v41e_hr_step_num
        move.l  v7_fps_num,d0
        move.l  d0,v41e_hr_step_den
        movem.l (sp)+,d0-d1
        rts

; D0 <- monotonic PAL beam-line tick (15600 ticks/s nominal).
v41e_hr_clock_poll:
        movem.l d1-d2,-(sp)
        bsr     v04_sample_raster
        move.l  d0,d2
        move.l  v41e_hr_last_line,d1
        cmp.l   d1,d2
        bcc.s   v41e_hr_no_wrap
        add.l   #312,v41e_hr_base
v41e_hr_no_wrap:
        move.l  d2,v41e_hr_last_line
        move.l  v41e_hr_base,d0
        add.l   d2,d0
        movem.l (sp)+,d1-d2
        rts

; D0 <- next native-frame interval in beam-line ticks.
v41e_hr_next_interval:
        movem.l d1-d3,-(sp)
        move.l  v41e_hr_accum,d0
        add.l   v41e_hr_step_num,d0
        move.l  v41e_hr_step_den,d1
        tst.l   d1
        beq.s   v41e_hr_interval_fallback
        divu.w  d1,d0
        move.l  d0,d2
        andi.l  #$0000ffff,d0
        swap    d2
        andi.l  #$0000ffff,d2
        move.l  d2,v41e_hr_accum
        tst.l   d0
        bne.s   v41e_hr_interval_done
v41e_hr_interval_fallback:
        moveq   #1,d0
v41e_hr_interval_done:
        movem.l (sp)+,d1-d3
        rts

; Mode-3 feeder pacing. First visible AU is immediate; later AUs use an
; absolute native-fps timeline with ~64-us granularity. Hidden restart
; fast-forward remains unpaced exactly as in V41D.
v41e_hr_pace_new_frame:
        movem.l d1-d4,-(sp)
        tst.l   v32r_fastforward
        beq.s   v41e_hr_normal
        addq.l  #1,v04_paced_frames
        bsr     v15_poll_ctrl_c
        bra.w   v41e_hr_done
v41e_hr_normal:
        tst.l   v41e_hr_started
        bne.s   v41e_hr_wait
        bsr     v04_sample_raster
        move.l  d0,v41e_hr_last_line
        clr.l   v41e_hr_base
        move.l  d0,v41e_hr_target
        move.l  #1,v41e_hr_started
        bsr     v41e_hr_next_interval
        add.l   d0,v41e_hr_target
        addq.l  #1,v04_paced_frames
        bra.s   v41e_hr_done
v41e_hr_wait:
        move.l  v41e_hr_target,d3
v41e_hr_wait_loop:
        bsr     v41e_hr_clock_poll
        cmp.l   d3,d0
        bcc.s   v41e_hr_reached
        bsr     v15_poll_ctrl_c
        tst.l   v15_stop_requested
        bne.s   v41e_hr_reached
        bra.s   v41e_hr_wait_loop
v41e_hr_reached:
        bsr     v41e_hr_next_interval
        add.l   d0,v41e_hr_target
        addq.l  #1,v04_paced_frames
v41e_hr_done:
        movem.l (sp)+,d1-d4
        rts

; ====================================================================
; VPv21T PRELOG PROOF
; Exact same DOS sequence as the separately hardware-proven WriteTest:
;   Open BerryMP314.log.disabled (MODE_NEWFILE) -> Write -> Flush -> Close.
; This runs before ANY AAC/MMAL/VCHIQ/large-memory setup.  A one-second
; Delay follows Close so the filesystem/device gets time to commit the new
; directory entry before the dangerous A/V path begins.
; ====================================================================
vpv21i_prelog_create:
        movem.l d0-d7/a0-a2/a6,-(sp)
        clr.l   vpv21i_prelog_ok
        move.l  #1,vpv21i_prelog_ok
        bra.w   vpv21i_prelog_done

        move.l  a5,a6
        lea     vpv21f_log_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   vpv21i_prelog_done
        move.l  d0,d5

        move.l  d5,d1
        lea     msg_vpv21i_prelog,a0
        move.l  a0,d2
        move.l  #msg_vpv21i_prelog_end-msg_vpv21i_prelog,d3
        move.l  a5,a6
        jsr     Write(a6)
        cmp.l   #msg_vpv21i_prelog_end-msg_vpv21i_prelog,d0
        bne.s   vpv21i_prelog_close

        move.l  d5,d1
        move.l  a5,a6
        jsr     Flush(a6)
        move.l  #1,vpv21i_prelog_ok

vpv21i_prelog_close:
        move.l  d5,d1
        move.l  a5,a6
        jsr     Close(a6)

        ; Give FFS/device caching time to commit before A/V can crash.
        moveq   #50,d1
        move.l  a5,a6
        jsr     Delay(a6)

vpv21i_prelog_done:
        movem.l (sp)+,d0-d7/a0-a2/a6
        rts

h264rgb_main:
        movem.l d2-d7/a2-a6,-(sp)

        ; Preserve AmigaDOS command line before any library call clobbers D0/A0.
        move.l  d0,h264rgb_cli_len
        move.l  a0,h264rgb_cli_ptr

        move.l  4.w,a4
        move.l  a4,a6
        lea     dosname,a1
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        bne.s   h264rgb_dos_open_ok_v32
        jmp     exit_prog
h264rgb_dos_open_ok_v32:
        move.l  d0,a5

        ; V40: a state file is consumed only by an armed restart cycle.
        ; A normal fresh launch removes any stale file left by a crash/reboot.
        tst.l   v32r_restart_cycle
        bne.s   v32r_keep_restart_state
        jsr     v32r_delete_state
v32r_keep_restart_state:

        ; MHI04S SILENT: an automatically started Workbench/AmigaDOS process
        ; may legitimately have no CLI Output() handle.  HDMI playback must not
        ; depend on a console.  Keep the handle only for legacy code, but never
        ; fail when it is zero.
        move.l  a5,a6
        jsr     Output(a6)
        move.l  d0,d4
        clr.l   h264rgb_output_handle
        ; BerryMP314: all legacy VP file logging is disabled.
        ; No PRELOG, AUTLOG or sparse TRACE file is opened.
        clr.l   vpv21f_log_handle
        clr.l   vpv21i_last_log_ok
        jmp     vpv19_cli_entry

        ; V1 change: filename comes from the AmigaDOS command line.
        bsr     h264rgb_parse_arg
        tst.l   d0
        beq.s   h264rgb_arg_ok

        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force

        ; Nothing has been allocated yet, so usage can exit directly.
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_arg_ok:
        ; V40J: optional start geometry token. Missing token defaults to g50.
        jsr     v40j_parse_size_arg
        tst.l   d0
        beq.s   h264rgb_size_arg_ok
        lea     msg_v40j_bad_size,a1
        move.l  #msg_v40j_bad_size_end-msg_v40j_bad_size,d3
        jsr     print
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        jsr     print_force
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts
h264rgb_size_arg_ok:
        ; V14: discard a stale break from before program start. Any Ctrl-C
        ; received after this point remains pending until the streaming poll sees it.
        clr.l   v15_stop_requested
        bsr     v15_clear_ctrl_c

        ; V10P: bounded-memory live MKV demux.  The V10F metadata probe still
        ; reads only a fixed 2-MiB window to discover Tracks/avcC.  During actual
        ; playback h22_load_frame_data converts only the selected AVC blocks
        ; directly into the 256-KiB MMAL input slot.  No whole-file buffer and
        ; no temporary Annex-B file are created.
        clr.l   v10b_input_is_mkv
        clr.l   v12e_input_is_mp4
        jsr     v12e_is_mp4
        tst.l   d0
        beq.s   h264rgb_check_mkv
        move.l  #1,v12e_input_is_mp4
        jsr     v12e_mp4_probe
        tst.l   d0
        bne.w   h264rgb_mp4_prepare_fail
        lea     msg_v12e_mp4_ready,a1
        move.l  #msg_v12e_mp4_ready_end-msg_v12e_mp4_ready,d3
        jsr     print
        bra.w   h264rgb_have_extradata

h264rgb_check_mkv:
        jsr     v10_is_mkv
        tst.l   d0
        beq.w   h264rgb_raw_prepare
        move.l  #1,v10b_input_is_mkv
        jsr     v10_mkv_probe
        tst.l   v10_h264_found
        beq.w   h264rgb_mkv_prepare_fail
        tst.l   v10_avcc_ok
        beq.w   h264rgb_mkv_prepare_fail
        tst.l   v10_video_track_num
        beq.w   h264rgb_mkv_prepare_fail
        lea     msg_v10b_stream_ready,a1
        move.l  #msg_v10b_stream_ready_end-msg_v10b_stream_ready,d3
        jsr     print
        bra.w   h264rgb_have_extradata

h264rgb_mp4_prepare_fail:
        lea     msg_v12e_mp4_unsupported,a1
        move.l  #msg_v12e_mp4_unsupported_end-msg_v12e_mp4_unsupported,d3
        jsr     print
        jsr     v12e_free_mp4
        move.l  t23_file_handle,d0
        beq.s   h264rgb_mp4_fail_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
h264rgb_mp4_fail_closed:
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_mkv_prepare_fail:
        lea     msg_v10b_prepare_fail,a1
        move.l  #msg_v10b_prepare_fail_end-msg_v10b_prepare_fail,d3
        jsr     print
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; V10P: early unsupported-stream exit. Nothing decoder-related has been
; allocated or started yet, therefore this is a normal shell return and does
; NOT require the persistent-VCHIQ/MMAL cleanup path or a reboot.
h264rgb_unsupported_exit:
        lea     msg_v10p_unsupported,a1
        move.l  #msg_v10p_unsupported_end-msg_v10p_unsupported,d3
        jsr     print
        ; V12E MP4 probing keeps the moov metadata and DOS file open until
        ; playback.  The old V10P unsupported-SPS exit had no such resources.
        ; Release them here as well so an unsupported MP4 returns cleanly.
        jsr     v12e_free_mp4
        move.l  t23_file_handle,d0
        beq.s   h264rgb_unsupported_file_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
h264rgb_unsupported_file_closed:
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_raw_prepare:
        ; Raw Annex-B keeps the hardware-proven V9M/V10F probe unchanged.
        bsr     h264rgb_load_file_extradata
        tst.l   d0
        beq.s   v32r_raw_extradata_ok
        jmp     close_prog
v32r_raw_extradata_ok:

h264rgb_have_extradata:
        ; For MKV, v10_parse_avcc already copied SPS/PPS into the same
        ; h264_file_extradata buffer and set h264_sps_ptr/h264_pps_ptr.
        jsr     v6_parse_sps_geometry
        tst.l   d0
        beq.s   v32r_sps_geometry_ok
        jmp     close_prog
v32r_sps_geometry_ok:
        ; V10P compatibility guard.  The exact SPS used by the known failing
        ; stream has now been hardware-tested through CONFIG removal, full-frame
        ; START|END input, 19 real host output buffers and a DPB-15 experiment.
        ; VideoCore still returns MMAL_ENOSPC before producing frame 0.  Reject
        ; this exact SPS BEFORE LUT allocation, VCHIQ_INIT or MMAL creation so
        ; the CLI returns cleanly and no reboot is required.  The bitstream is
        ; never modified.
        jsr     v10p_check_unsupported_sps
        tst.l   d0
        bne.w   h264rgb_unsupported_exit
        jsr     v7_setup_timing
        tst.l   d0
        beq.s   v40_timing_ok
        jmp     close_prog
v40_timing_ok:
        bsr     v04_timing_reset

vpv01_vchiq_entry:
        ; VPv05 reuses only the hardware-proven VCHIQ/MMAL transport substrate.
        ; No video/HAM6/ISP state is required for this isolated HDMI-audio test.
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr
        lea     msg_hdmi_v40o_no_luts,a1
        move.l  #msg_hdmi_v40o_no_luts_end-msg_hdmi_v40o_no_luts,d3
        jsr     print

        lea     msg_vpv01_start,a1
        move.l  #msg_vpv01_start_end-msg_vpv01_start,d3
        jsr     print_force

        ; V12F: generic MMAL worker helpers default to local VCHIQ port 0.
        clr.l   v12f_local_port
        clr.l   v12f_local_bits

        ; V10: on a second CLI invocation, attach to the persistent VCHIQ
        ; transport and probe a fresh MMAL service on local port 1.
        jsr     v9d_try_attach
        tst.l   d0
        beq.s   v9d_first_start
        cmpi.l  #1,d0
        beq.s   v40c_attach_second
        jmp     v9d_attach_exit
v40c_attach_second:
        jsr     v9d_second_start_probe
        jmp     v9d_attach_exit
v9d_first_start:

        ; HDMI_v41L: pure HDMI path. Do not allocate or touch the legacy HAM6
        ; Chip/Fast display buffers. The VBlank interrupt is used only as a
        ; 50-Hz timebase; t30_active_ptr remains zero, so its ISR never writes
        ; Amiga bitplane registers.
        clr.l   t30_frames_ptr
        clr.l   t30_chip_ptr
        clr.l   v9i_chip_alloc_base
        clr.l   t33_fast_ptr
        clr.l   t56_shadow_ptr
        lea     msg_hdmi_v40o_no_rgb_buffers,a1
        move.l  #msg_hdmi_v40o_no_rgb_buffers_end-msg_hdmi_v40o_no_rgb_buffers,d3
        jsr     print

        clr.l   t31s_display_started
        clr.l   t31s_vblank_installed
        clr.l   t31s_vblank_counter
        clr.l   t31s_pending_ptr
        clr.l   t31s_switch_vblank
        clr.l   t31s_pending_valid
        clr.l   t31s_next_switch_vblank
        clr.l   t8a_isr_late_promote
        clr.l   v7_sched_accum
        clr.l   t31s_missed_deadlines
        clr.l   t31x_slack1
        clr.l   t31x_slack2
        clr.l   t31x_slack3plus
        clr.l   t31x_at_target
        clr.l   t31x_past_target
        move.l  #-1,t31x_miss1_frame
        clr.l   t31x_miss1_target
        clr.l   t31x_miss1_current
        clr.l   t31x_miss1_delta
        move.l  #-1,t31x_miss2_frame
        clr.l   t31x_miss2_target
        clr.l   t31x_miss2_current
        clr.l   t31x_miss2_delta
        clr.l   t31x_max_past_delta
        clr.l   t31u_last_stream_end_vblank
        clr.l   t31u_gap_total
        clr.l   t31u_gap_max
        clr.l   t31u_gap_nonzero
        clr.l   t31u_buffer_total
        clr.l   t31u_buffer_max
        clr.l   t31u_buffer_nonzero
        clr.l   t31u_convert_total
        clr.l   t31u_convert_max
        clr.l   t31u_convert_nonzero
        clr.l   t31w_copy_total
        clr.l   t31w_copy_max
        clr.l   t31w_copy_nonzero
        clr.l   t56_dirty_long_total
        clr.l   t56_dirty_long_max
        clr.l   t57_early_release_total
        clr.l   t61_deferred_total
        clr.l   t61_slot0_frames
        clr.l   t61_slot1_frames
        clr.l   t63_preroll_ptr
        clr.l   t63_preroll_frames
        clr.l   t65_same_vblank_total
        clr.l   t65_same_vblank_late
        clr.l   t65_catchup_debt
        clr.l   t65_debt_added_total
        clr.l   t65_catchup_total
        clr.l   t65_debt_max
        clr.l   t66_current_slack
        clr.l   t66_catchup_deferred
        clr.l   t31u_post_total
        clr.l   t31u_post_max
        clr.l   t31u_post_nonzero
        clr.l   t31u_stage_start_vblank
        clr.l   t31u_run_start_vblank
        clr.l   t30_active_ptr
        clr.l   t30_display_ptr
        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        jsr     print

; --------------------------------------------------------------------
; 1. Allocate and initialize shared VCHIQ memory
; --------------------------------------------------------------------
        lea     msg_alloc,a1
        move.l  #msg_alloc_end-msg_alloc,d3
        jsr     print

        move.l  a4,a6
        move.l  #ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   fail_alloc
        move.l  d0,slot_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,slot_ptr
        move.l  d0,a3

        move.l  a3,d6
        cmp.l   #$3f000000,d6
        bcc.w   fail_range
        or.l    #$c0000000,d6
        move.l  d6,slot_bus

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        jsr     print

        lea     msg_layout,a1
        move.l  #msg_layout_end-msg_layout,d3
        jsr     print

        ; SlotZero header
        move.l  a3,a0
        move.l  #VCHIQ_MAGIC,d0
        jsr     store_le32

        ; version/version_min are u16 fields in little endian.
        ; For v8/min3 this produces bytes 08 00 03 00.
        move.b  #8,4(a3)
        move.b  #0,5(a3)
        move.b  #3,6(a3)
        move.b  #0,7(a3)

        lea     8(a3),a0
        move.l  #SLOTZERO_SIZE,d0
        jsr     store_le32

        lea     12(a3),a0
        move.l  #SLOT_SIZE,d0
        jsr     store_le32

        lea     16(a3),a0
        move.l  #MAX_SLOTS,d0
        jsr     store_le32

        lea     20(a3),a0
        move.l  #MAX_SIDE,d0
        jsr     store_le32

        ; Pi3 fragment area starts directly after the 65 slots.
        move.l  d6,d0
        add.l   #SLOT_MEM_SIZE,d0
        lea     24(a3),a0
        jsr     store_le32

        lea     28(a3),a0
        move.l  #64,d0
        jsr     store_le32

        ; VideoCore/master side: sync 1, data 2..32
        lea     MASTER_FIRST(a3),a0
        move.l  #2,d0
        jsr     store_le32
        lea     MASTER_LAST(a3),a0
        move.l  #32,d0
        jsr     store_le32
        lea     MASTER_SYNC(a3),a0
        move.l  #1,d0
        jsr     store_le32

        ; Host/slave side: sync 33, data 34..64
        lea     SLAVE_FIRST(a3),a0
        move.l  #34,d0
        jsr     store_le32
        lea     SLAVE_LAST(a3),a0
        move.l  #64,d0
        jsr     store_le32
        lea     SLAVE_SYNC(a3),a0
        move.l  #33,d0
        jsr     store_le32

        ; Host slot queue: 34..64
        lea     SLAVE_QUEUE(a3),a2
        move.l  #34,d5
        move.l  #30,d7
queue_init_loop:
        move.l  d5,d0
        jsr     bswap32
        move.l  d0,(a2)+
        addq.l  #1,d5
        dbra    d7,queue_init_loop

        lea     SLAVE_RECYCLEQ(a3),a0
        move.l  #31,d0
        jsr     store_le32

        ; Linux initializes local sync_release.fired = 1.
        lea     SLAVE_SYNCREL_F(a3),a0
        move.l  #1,d0
        jsr     store_le32

        lea     SLAVE_DEBUG0(a3),a0
        move.l  #11,d0
        jsr     store_le32

        ; Local sync slot 33 starts with PADDING. AllocMem CLEAR already
        ; gives msgid=0,size=0, so no extra writes are needed.

        ; Set local initialized last.
        lea     SLAVE_INIT(a3),a0
        move.l  #1,d0
        jsr     store_le32

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        jsr     print

; --------------------------------------------------------------------
; 2. Verify DMA mapping and hand initial shared region to VideoCore
; --------------------------------------------------------------------
        lea     msg_dma,a1
        move.l  #msg_dma_end-msg_dma,d3
        jsr     print

        move.l  #DMA_MEM_SIZE,dma_len
        move.l  a3,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,slot_phys

        move.l  dma_len,d1
        cmp.l   #DMA_MEM_SIZE,d1
        bcs.w   fail_dma_len

        cmp.l   slot_ptr,d0
        bne.w   fail_identity

        lea     msg_phys,a1
        move.l  #msg_phys_end-msg_phys,d3
        jsr     print
        move.l  slot_phys,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_bus,a1
        move.l  #msg_bus_end-msg_bus,d3
        jsr     print
        move.l  slot_bus,d0
        jsr     print_hex32
        jsr     newline

; --------------------------------------------------------------------
; 3. Build firmware property request
; --------------------------------------------------------------------
        lea     msg_prop,a1
        move.l  #msg_prop_end-msg_prop,d3
        jsr     print

        move.l  a4,a6
        move.l  #$200,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   fail_prop_alloc
        move.l  d0,prop_alloc

        add.l   #127,d0
        and.l   #$ffffff80,d0
        move.l  d0,prop_ptr
        move.l  d0,a2

        move.l  a2,a0
        move.l  #28,d0
        bsr     store_le32

        lea     4(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #$00048010,d0
        bsr     store_le32

        lea     12(a2),a0
        moveq   #4,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  slot_bus,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        move.l  #28,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,prop_phys

        cmp.l   prop_ptr,d0
        bne.w   fail_prop_identity

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 4. VCHIQ_INIT via firmware property mailbox
; --------------------------------------------------------------------
        lea     msg_init,a1
        move.l  #msg_init_end-msg_init,d3
        bsr     print

        move.l  prop_phys,d0
        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d5

        move.l  #TIMEOUT,d7
mbox_tx_wait:
        move.l  MBOX_STATUS,d0
        bsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.w   mbox_tx_ready
        subq.l  #1,d7
        bne.w   mbox_tx_wait
        bra.w   fail_tx_timeout

mbox_tx_ready:
        move.l  d5,d0
        bsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
mbox_rx_wait:
        move.l  MBOX_STATUS,d0
        bsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.w   mbox_rx_ready
        subq.l  #1,d7
        bne.w   mbox_rx_wait
        bra.w   fail_rx_timeout

mbox_rx_ready:
        move.l  MBOX_READ,d0
        bsr     bswap32
        move.l  d0,d5

        move.l  d5,d0
        and.l   #$f,d0
        cmp.l   #MBOX_PROPERTY,d0
        beq.w   mbox_got_prop
        subq.l  #1,d7
        bne.w   mbox_rx_wait
        bra.w   fail_rx_timeout

mbox_got_prop:
        move.l  #28,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a0
        move.l  4(a0),d0
        bsr     bswap32
        cmp.l   #$80000000,d0
        bne.w   fail_fw_status

        move.l  20(a0),d0
        bsr     bswap32
        tst.l   d0
        bne.w   fail_channelbase

        lea     msg_init_ok,a1
        move.l  #msg_init_ok_end-msg_init_ok,d3
        bsr     print

        ; V10P: only now, after the exact same property-mailbox path has
        ; demonstrably succeeded, query ARM and VC memory one tag at a time.
        jsr     v10l_query_firmware_memory_after_init

; --------------------------------------------------------------------
; 5. Finish DMA phase, inspect VC/master shared state
; --------------------------------------------------------------------
        ; The shared block has been in a CachePreDMA phase since step 2.
        ; End it so CPU can safely observe VideoCore writes.
        bsr     dma_post_all

        ; Wait briefly for master.initialized if needed.
        move.l  #POLL_COUNT,d7
wait_master_init:
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        tst.l   d0
        bne.w   master_is_ready

        bsr     dma_pre_all
        bsr     short_delay
        bsr     dma_post_all
        subq.l  #1,d7
        bne.w   wait_master_init
        bra.w   fail_master_init

master_is_ready:
        ; First invocation: publish the global VCHIQ slot block through a tiny
        ; persistent Exec resource. It is deliberately never removed/freed;
        ; firmware owns this transport until reboot.
        jsr     v9d_register_resource
        tst.l   d0
        bne.w   fail_v9d_resource

        lea     msg_master,a1
        move.l  #msg_master_end-msg_master,d3
        bsr     print

        lea     msg_master_init,a1
        move.l  #msg_master_init_end-msg_master_init,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_master_tx,a1
        move.l  #msg_master_tx_end-msg_master_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,remote_tx_before
        bsr     print_hex32
        bsr     newline

        lea     msg_master_arm,a1
        move.l  #msg_master_arm_end-msg_master_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,vc_armed
        bsr     print_hex32
        bsr     newline

        lea     msg_master_q0,a1
        move.l  #msg_master_q0_end-msg_master_q0,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 5a. Stabilization window after firmware VCHIQ_INIT.
;
; The sporadic failed boots show that master.initialized=1 and armed=1
; do not always mean that the VideoCore VCHIQ side is fully ready to
; process our CONNECT immediately. Give firmware 25 DOS ticks = 0.5 s.
;
; IMPORTANT: return shared memory to DMA ownership during Delay(), then
; reacquire it and refresh tx_pos / armed / fired before CONNECT.
; --------------------------------------------------------------------
        lea     msg_stabil_start,a1
        move.l  #msg_stabil_start_end-msg_stabil_start,d3
        bsr     print

        bsr     dma_pre_all

        move.l  a5,a6
        move.l  #25,d1
        tst.l   v32r_restart_armed
        beq.s   v40m_close_delay_ready
        ; V40M: a much larger gfull ISP graph is created immediately after this
        ; cleanup. Give firmware two seconds to retire service-owned ISP state.
        move.l  #100,d1
v40m_close_delay_ready:
        jsr     Delay(a6)

        bsr     dma_post_all

        lea     msg_stabil_tx,a1
        move.l  #msg_stabil_tx_end-msg_stabil_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,remote_tx_before
        bsr     print_hex32
        bsr     newline

        lea     msg_stabil_arm,a1
        move.l  #msg_stabil_arm_end-msg_stabil_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,vc_armed
        bsr     print_hex32
        bsr     newline

        lea     msg_stabil_fired,a1
        move.l  #msg_stabil_fired_end-msg_stabil_fired,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        move.l  d0,stabil_fired
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 6. Check whether VideoCore CONNECT is ALREADY present.
; --------------------------------------------------------------------
        clr.l   remote_seen

        lea     msg_precheck,a1
        move.l  #msg_precheck_end-msg_precheck,d3
        bsr     print

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        lea     msg_master_tx,a1
        move.l  #msg_master_tx_end-msg_master_tx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        cmp.l   #8,d5
        bcs.w   pre_no_remote_yet

        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        lea     msg_rxslot,a1
        move.l  #msg_rxslot_end-msg_rxslot,d3
        bsr     print
        move.l  remote_slot0,d0
        bsr     print_hex32
        bsr     newline

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_rx_slot
        cmp.l   #32,d0
        bhi.w   fail_rx_slot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,rx_size

        lea     msg_rxid,a1
        move.l  #msg_rxid_end-msg_rxid,d3
        bsr     print
        move.l  rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_rxsize,a1
        move.l  #msg_rxsize_end-msg_rxsize,d3
        bsr     print
        move.l  rx_size,d0
        bsr     print_hex32
        bsr     newline

        move.l  rx_msgid,d0
        cmp.l   #VCHIQ_MSG_CONNECT,d0
        bne.w   fail_wrong_msg

        move.l  rx_size,d0
        tst.l   d0
        bne.w   fail_wrong_size

        move.l  #1,remote_seen

        lea     msg_remote_ready,a1
        move.l  #msg_remote_ready_end-msg_remote_ready,d3
        bsr     print
        bra.w   queue_our_connect

pre_no_remote_yet:
        lea     msg_remote_later,a1
        move.l  #msg_remote_later_end-msg_remote_later,d3
        bsr     print

; --------------------------------------------------------------------
; 7. Queue OUR CONNECT in host slot 34.
; --------------------------------------------------------------------
queue_our_connect:
        ; One initial notification plus at most two re-notifications.
        ; IMPORTANT: the CONNECT message itself is written only once.
        move.l  #2,connect_retries

        lea     msg_connect,a1
        move.l  #msg_connect_end-msg_connect,d3
        bsr     print

        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  #VCHIQ_MSG_CONNECT,d0
        bsr     store_le32
        lea     4(a0),a0
        moveq   #0,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        moveq   #8,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        bsr     dma_pre_all

        move.l  vc_armed,d0
        tst.l   d0
        beq.w   connect_no_bell_a

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_bell,a1
        move.l  #msg_bell_end-msg_bell,d3
        bsr     print
        bra.w   after_notify_a

connect_no_bell_a:
        lea     msg_nobell,a1
        move.l  #msg_nobell_end-msg_nobell,d3
        bsr     print

after_notify_a:
        bsr     short_delay
        bsr     dma_post_all

        lea     msg_localtx,a1
        move.l  #msg_localtx_end-msg_localtx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_fired_after,a1
        move.l  #msg_fired_after_end-msg_fired_after,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        tst.l   remote_seen
        bne.w   connect_success_a

; --------------------------------------------------------------------
; 8. If VC CONNECT was not present before our send, wait for it.
; --------------------------------------------------------------------
        lea     msg_wait,a1
        move.l  #msg_wait_end-msg_wait,d3
        bsr     print

        bsr     dma_pre_all
        move.l  #POLL_COUNT,d7

connect_poll_loop_a:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   #8,d0
        bcc.w   connect_response_seen_a

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   connect_poll_loop_a
        bra.w   fail_connect_timeout

connect_response_seen_a:
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        lea     msg_rxslot,a1
        move.l  #msg_rxslot_end-msg_rxslot,d3
        bsr     print
        move.l  remote_slot0,d0
        bsr     print_hex32
        bsr     newline

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_rx_slot
        cmp.l   #32,d0
        bhi.w   fail_rx_slot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,rx_size

        lea     msg_rxid,a1
        move.l  #msg_rxid_end-msg_rxid,d3
        bsr     print
        move.l  rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_rxsize,a1
        move.l  #msg_rxsize_end-msg_rxsize,d3
        bsr     print
        move.l  rx_size,d0
        bsr     print_hex32
        bsr     newline

        move.l  rx_msgid,d0
        cmp.l   #VCHIQ_MSG_CONNECT,d0
        bne.w   fail_wrong_msg

        move.l  rx_size,d0
        tst.l   d0
        bne.w   fail_wrong_size

connect_success_a:
        lea     msg_connect_ok,a1
        move.l  #msg_connect_ok_end-msg_connect_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 9. Open the real MMAL control service.
;
; Linux VCHIQ open payload (12 bytes):
;   u32 fourcc, u32 client_id, u16 version, u16 version_min
; Official MMAL values: fourcc 'mmal', version 16, minimum 10.
;
; CONNECT consumed 8 bytes in host slot 34. OPEN stride is 24 bytes,
; so OPEN starts at slot 34 offset 8 and host tx_pos becomes 32.
; --------------------------------------------------------------------
        lea     msg_open,a1
        move.l  #msg_open_end-msg_open,d3
        bsr     print

        ; Slot 34 + offset 8.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #8,a0

        ; Header: OPEN from local port 0, payload size 12.
        move.l  #VCHIQ_MSG_OPEN,d0
        bsr     store_le32
        lea     4(a0),a0
        move.l  #12,d0
        bsr     store_le32

        ; Payload fourcc.
        lea     4(a0),a0              ; now slot+16 = payload start
        move.l  #MMAL_FOURCC,d0
        bsr     store_le32

        ; client_id = 0.
        lea     4(a0),a0
        moveq   #0,d0
        bsr     store_le32

        ; u16 version=16, u16 version_min=10, little endian.
        lea     4(a0),a0
        move.b  #MMAL_VER,(a0)
        clr.b   1(a0)
        move.b  #MMAL_VER_MIN,2(a0)
        clr.b   3(a0)

        ; Publish total host stream position: 8 + 24 = 32.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #32,d0
        bsr     store_le32

        ; Signal VideoCore master trigger.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        ; Read current armed state before giving DMA ownership back.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,open_armed

        lea     msg_open_arm,a1
        move.l  #msg_open_arm_end-msg_open_arm,d3
        bsr     print
        move.l  open_armed,d0
        bsr     print_hex32
        bsr     newline

        bsr     dma_pre_all

        move.l  open_armed,d0
        tst.l   d0
        beq.w   open_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_open_bell,a1
        move.l  #msg_open_bell_end-msg_open_bell,d3
        bsr     print
        bra.w   open_wait_start

open_no_bell:
        lea     msg_open_nobell,a1
        move.l  #msg_open_nobell_end-msg_open_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 10. Wait for next VC message after CONNECT.
; The CONNECT occupies remote stream bytes 0..7. An OPENACK normally
; appears at slot 2 offset 8. RusPiRo shows OPENACK size=2 and the
; resulting remote tx_pos=24. A rejected OPEN may instead return CLOSE.
; --------------------------------------------------------------------
open_wait_start:
        lea     msg_open_wait,a1
        move.l  #msg_open_wait_end-msg_open_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

open_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   #8,d5
        bhi.w   open_response_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   open_poll_loop
        bra.w   fail_open_timeout

open_response_seen:
        lea     msg_open_tx,a1
        move.l  #msg_open_tx_end-msg_open_tx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Use first VC data slot, expected 2, and inspect offset 8.
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_open_rxslot
        cmp.l   #32,d0
        bhi.w   fail_open_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #8,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,open_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,open_size

        lea     msg_open_id,a1
        move.l  #msg_open_id_end-msg_open_id,d3
        bsr     print
        move.l  open_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_open_size,a1
        move.l  #msg_open_size_end-msg_open_size,d3
        bsr     print
        move.l  open_size,d0
        bsr     print_hex32
        bsr     newline

        ; Check message type first.
        move.l  open_msgid,d0
        and.l   #$FF000000,d0
        cmp.l   #VCHIQ_MSG_CLOSE,d0
        beq.w   fail_open_rejected
        cmp.l   #VCHIQ_MSG_OPENACK,d0
        bne.w   fail_open_wrongmsg

        ; OPENACK destination must be our local port 0.
        move.l  open_msgid,d0
        and.l   #$00000FFF,d0
        bne.w   fail_open_dstport

        ; Extract VideoCore remote source port.
        move.l  open_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        move.l  d0,mmal_remote_port

        lea     msg_open_port,a1
        move.l  #msg_open_port_end-msg_open_port,d3
        bsr     print
        move.l  mmal_remote_port,d0
        bsr     print_hex32
        bsr     newline

        ; OPENACK contains at least u16 peer version.
        move.l  open_size,d0
        cmp.l   #2,d0
        bcs.w   fail_open_short

        move.l  a2,a0
        adda.l  #8,a0
        bsr     load_le16
        move.l  d0,mmal_peer_ver

        lea     msg_open_ver,a1
        move.l  #msg_open_ver_end-msg_open_ver,d3
        bsr     print
        move.l  mmal_peer_ver,d0
        bsr     print_hex32
        bsr     newline

        ; We advertised compatibility down to worker version 10.
        move.l  mmal_peer_ver,d0
        cmp.l   #MMAL_VER_MIN,d0
        bcs.w   fail_open_version

        ; Save the current remote stream position. In the successful
        ; TEST11 run this was 0x18: CONNECT (8) + OPENACK (16).
        move.l  d5,mmal_rx_before

        lea     msg_open_success,a1
        move.l  #msg_open_success_end-msg_open_success,d3
        bsr     print

; --------------------------------------------------------------------
; 11. Send MMAL_WORKER_GET_VERSION as VCHIQ DATA.
;
; VCHIQ DATA msgid:
;   type DATA=5
;   source/local port = 0
;   destination/VC port = mmal_remote_port (TEST11 returned 0x55)
;
; MMAL payload is mmal_worker_version, 40 bytes:
;   0  magic          u32 = MMAL_MAGIC
;   4  msgid/type     u32 = GET_VERSION (3)
;   8  control_service u32 = 0
;  12  context/waiter u32 = test cookie
;  16  status         u32 = 0
;  20  dummy/padding  u32 = 0
;  24  flags          u32 = 0
;  28  major          u32 = 0 (reply field)
;  32  minor          u32 = 0 (reply field)
;  36  minimum        u32 = 0 (reply field)
;
; Local stream is currently at 32. DATA header 8 + payload 40 = 48,
; therefore new local tx_pos = 80 (0x50).
; --------------------------------------------------------------------
        lea     msg_getver,a1
        move.l  #msg_getver_end-msg_getver,d3
        bsr     print

        ; Host slot 34, stream offset 32.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #32,a0
        move.l  a0,a2

        ; VCHIQ DATA msgid = 0x05000000 | remote_port.
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        move.l  d0,data_tx_msgid
        bsr     store_le32

        lea     4(a2),a0
        move.l  #40,d0
        bsr     store_le32

        ; MMAL worker payload starts at VCHIQ header + 8.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_GET_VERSION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; control_service

        lea     20(a2),a0
        move.l  #MMAL_TEST_CONTEXT,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; status

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; dummy/padding

        lea     32(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; flags

        lea     36(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; major

        lea     40(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; minor

        lea     44(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; minimum

        lea     msg_data_txid,a1
        move.l  #msg_data_txid_end-msg_data_txid,d3
        bsr     print
        move.l  data_tx_msgid,d0
        bsr     print_hex32
        bsr     newline

        ; Publish local tx_pos 0x50.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #80,d0
        bsr     store_le32

        ; Signal VC.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,data_armed

        lea     msg_data_arm,a1
        move.l  #msg_data_arm_end-msg_data_arm,d3
        bsr     print
        move.l  data_armed,d0
        bsr     print_hex32
        bsr     newline

        ; Flush our DATA message to shared memory.
        bsr     dma_pre_all

        move.l  data_armed,d0
        tst.l   d0
        beq.w   data_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_data_bell,a1
        move.l  #msg_data_bell_end-msg_data_bell,d3
        bsr     print
        bra.w   data_wait_start

data_no_bell:
        lea     msg_data_nobell,a1
        move.l  #msg_data_nobell_end-msg_data_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 12. Wait for MMAL GET_VERSION reply.
; --------------------------------------------------------------------
data_wait_start:
        lea     msg_data_wait,a1
        move.l  #msg_data_wait_end-msg_data_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

data_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   mmal_rx_before,d5
        bhi.w   data_response_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   data_poll_loop
        bra.w   fail_data_timeout

data_response_seen:
        ; This is the start position for the NEXT VideoCore reply.
        move.l  d5,comp_rx_before

        lea     msg_data_rxtx,a1
        move.l  #msg_data_rxtx_end-msg_data_rxtx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Still in first VC data slot for this small test.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_data_rxslot
        cmp.l   #32,d0
        bhi.w   fail_data_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  mmal_rx_before,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; VCHIQ DATA header.
        bsr     load_le32
        move.l  d0,data_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,data_rx_size

        lea     msg_data_rxid,a1
        move.l  #msg_data_rxid_end-msg_data_rxid,d3
        bsr     print
        move.l  data_rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_data_rxsize,a1
        move.l  #msg_data_rxsize_end-msg_data_rxsize,d3
        bsr     print
        move.l  data_rx_size,d0
        bsr     print_hex32
        bsr     newline

        ; Must be DATA.
        move.l  data_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_data_wrongmsg

        ; Destination must be local port 0.
        move.l  data_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   fail_data_dstport

        ; Source must be the VC MMAL service port from OPENACK.
        move.l  data_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_data_srcport

        move.l  data_rx_size,d0
        cmp.l   #40,d0
        bcs.w   fail_data_short

        ; Parse MMAL worker reply.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,worker_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,worker_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,worker_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,worker_status

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,worker_flags

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,worker_major

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,worker_minor

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,worker_minimum

        lea     msg_worker_magic,a1
        move.l  #msg_worker_magic_end-msg_worker_magic,d3
        bsr     print
        move.l  worker_magic,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_type,a1
        move.l  #msg_worker_type_end-msg_worker_type,d3
        bsr     print
        move.l  worker_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_ctx,a1
        move.l  #msg_worker_ctx_end-msg_worker_ctx,d3
        bsr     print
        move.l  worker_context,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_status,a1
        move.l  #msg_worker_status_end-msg_worker_status,d3
        bsr     print
        move.l  worker_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_flags,a1
        move.l  #msg_worker_flags_end-msg_worker_flags,d3
        bsr     print
        move.l  worker_flags,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_major,a1
        move.l  #msg_worker_major_end-msg_worker_major,d3
        bsr     print
        move.l  worker_major,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_minor,a1
        move.l  #msg_worker_minor_end-msg_worker_minor,d3
        bsr     print
        move.l  worker_minor,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_min,a1
        move.l  #msg_worker_min_end-msg_worker_min,d3
        bsr     print
        move.l  worker_minimum,d0
        bsr     print_hex32
        bsr     newline

        ; Validate reply.
        move.l  worker_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_worker_magic

        move.l  worker_type,d0
        cmp.l   #MMAL_GET_VERSION,d0
        bne.w   fail_worker_type

        move.l  worker_context,d0
        cmp.l   #MMAL_TEST_CONTEXT,d0
        bne.w   fail_worker_context

        move.l  worker_status,d0
        tst.l   d0
        bne.w   fail_worker_status

        move.l  worker_major,d0
        cmp.l   #MMAL_VER_MIN,d0
        bcs.w   fail_worker_version

        lea     msg_getver_success,a1
        move.l  #msg_getver_success_end-msg_getver_success,d3
        bsr     print

        ; VPv05: bridge the old fixed-offset first-start bootstrap to the
        ; generic V12A/V12F MMAL helpers used by the audio test.  The legacy
        ; bootstrap has just consumed GET_VERSION logically, but it has not yet
        ; initialised port_tx_pos/port_rx_pos.  Without this bridge the first
        ; audio COMPONENT_CREATE starts at stale stream position 0 and the RX
        ; parser sees an earlier short VCHIQ record (VPv03 stage 4).
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,port_tx_pos           ; expected 0x00000050 after GET_VERSION
        move.l  comp_rx_before,port_rx_pos ; first unread VC record begins here

        ; VPv59 AUDIO-ONLY: GET_VERSION is enough.  Never create ril.video_decode,
        ; ril.isp or any video port.  Run the exact BerryFAAD03/16-KiB double-
        ; buffer scheduler against ril.audio_render only, then return to shell.
        jsr     vpv59_audio_only_run
        jmp     v9d_attach_exit

; --------------------------------------------------------------------
; 13. COMPONENT_CREATE "ril.video_decode" (wire name)
;
; Official MMAL request payload:
;   u32 client_component
;   char name[128]
;   u32 pid
; = 136 bytes.
;
; MMAL header = 24 bytes, therefore MMAL DATA payload = 160 bytes.
; VCHIQ header = 8 bytes -> stream advance 168 bytes.
;
; Host stream before this request = 0x50 (80).
; New host tx_pos = 80 + 168 = 248 = 0xF8.
; --------------------------------------------------------------------
        lea     msg_comp_create,a1
        move.l  #msg_comp_create_end-msg_comp_create,d3
        bsr     print

        ; Host slot 34 + stream offset 0x50.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #80,a0
        move.l  a0,a2

        ; VCHIQ DATA header -> destination MMAL VC port.
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        move.l  d0,comp_tx_msgid
        bsr     store_le32

        lea     4(a2),a0
        move.l  #160,d0
        bsr     store_le32

        ; MMAL worker header (24 bytes).
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; control_service

        lea     20(a2),a0
        move.l  #MMAL_COMP_CONTEXT,d0
        bsr     store_le32              ; synchronous context cookie

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; header status

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; padding

        ; Official host code sends its local MMAL_COMPONENT_T pointer here.
        ; For this bare-metal-style client we use a stable opaque cookie which
        ; VideoCore must only pass back to us in later events/callbacks.
        lea     32(a2),a0
        move.l  #MMAL_CLIENT_COMPONENT,d0
        bsr     store_le32

        ; Explicitly clear the 128-byte component name field.
        lea     36(a2),a0
        move.l  #31,d7
comp_name_clear_loop:
        clr.l   (a0)+
        dbra    d7,comp_name_clear_loop

        ; Copy NUL-terminated ASCII component name.
        lea     36(a2),a0
        lea     comp_name,a1
        move.l  #comp_name_end-comp_name-1,d7
comp_name_copy_loop:
        move.b  (a1)+,(a0)+
        dbra    d7,comp_name_copy_loop

        ; pid = 0
        lea     164(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     msg_comp_txid,a1
        move.l  #msg_comp_txid_end-msg_comp_txid,d3
        bsr     print
        move.l  comp_tx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_localpos,a1
        move.l  #msg_comp_localpos_end-msg_comp_localpos,d3
        bsr     print
        move.l  #$000000F8,d0
        bsr     print_hex32
        bsr     newline

        ; Publish local tx_pos = 0xF8.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #248,d0
        bsr     store_le32

        ; Signal VideoCore event.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,comp_armed

        lea     msg_comp_arm,a1
        move.l  #msg_comp_arm_end-msg_comp_arm,d3
        bsr     print
        move.l  comp_armed,d0
        bsr     print_hex32
        bsr     newline

        ; Flush complete shared-memory region before ringing VC.
        bsr     dma_pre_all

        move.l  comp_armed,d0
        tst.l   d0
        beq.w   comp_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_comp_bell,a1
        move.l  #msg_comp_bell_end-msg_comp_bell,d3
        bsr     print
        bra.w   comp_wait_start

comp_no_bell:
        lea     msg_comp_nobell,a1
        move.l  #msg_comp_nobell_end-msg_comp_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 14. Wait for COMPONENT_CREATE reply.
; --------------------------------------------------------------------
comp_wait_start:
        lea     msg_comp_wait,a1
        move.l  #msg_comp_wait_end-msg_comp_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

comp_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   comp_rx_before,d5
        bhi.w   comp_response_seen

        ; Return shared region to VC before next polling interval.
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   comp_poll_loop
        bra.w   fail_comp_timeout

comp_response_seen:
        ; Start position of the next VideoCore message.
        move.l  d5,port_rx_pos

        lea     msg_comp_rxtx,a1
        move.l  #msg_comp_rxtx_end-msg_comp_rxtx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Response remains in the first VideoCore data slot.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_comp_rxslot
        cmp.l   #32,d0
        bhi.w   fail_comp_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  comp_rx_before,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; VCHIQ header.
        bsr     load_le32
        move.l  d0,comp_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,comp_rx_size

        lea     msg_comp_rxid,a1
        move.l  #msg_comp_rxid_end-msg_comp_rxid,d3
        bsr     print
        move.l  comp_rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_rxsize,a1
        move.l  #msg_comp_rxsize_end-msg_comp_rxsize,d3
        bsr     print
        move.l  comp_rx_size,d0
        bsr     print_hex32
        bsr     newline

        ; Must be VCHIQ DATA.
        move.l  comp_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_comp_wrongmsg

        ; Destination local port must be 0.
        move.l  comp_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   fail_comp_dstport

        ; Source must be our opened VideoCore MMAL port.
        move.l  comp_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_comp_srcport

        ; Reply MMAL body: 24-byte header + 20-byte create_reply.
        move.l  comp_rx_size,d0
        cmp.l   #44,d0
        bcs.w   fail_comp_short

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,comp_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,comp_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,comp_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,comp_hdr_status

        ; component_create_reply payload.
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,comp_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,component_handle

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,component_inputs

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,component_outputs

        lea     48(a2),a0
        bsr     load_le32
        move.l  d0,component_clocks

        ; Diagnostic output.
        lea     msg_comp_magic,a1
        move.l  #msg_comp_magic_end-msg_comp_magic,d3
        bsr     print
        move.l  comp_magic,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_type,a1
        move.l  #msg_comp_type_end-msg_comp_type,d3
        bsr     print
        move.l  comp_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_ctx,a1
        move.l  #msg_comp_ctx_end-msg_comp_ctx,d3
        bsr     print
        move.l  comp_context,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_hstatus,a1
        move.l  #msg_comp_hstatus_end-msg_comp_hstatus,d3
        bsr     print
        move.l  comp_hdr_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_rstatus,a1
        move.l  #msg_comp_rstatus_end-msg_comp_rstatus,d3
        bsr     print
        move.l  comp_reply_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_handle,a1
        move.l  #msg_comp_handle_end-msg_comp_handle,d3
        bsr     print
        move.l  component_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_inputs,a1
        move.l  #msg_comp_inputs_end-msg_comp_inputs,d3
        bsr     print
        move.l  component_inputs,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_outputs,a1
        move.l  #msg_comp_outputs_end-msg_comp_outputs,d3
        bsr     print
        move.l  component_outputs,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_clocks,a1
        move.l  #msg_comp_clocks_end-msg_comp_clocks,d3
        bsr     print
        move.l  component_clocks,d0
        bsr     print_hex32
        bsr     newline

        ; Validate synchronous MMAL reply.
        move.l  comp_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_comp_magic

        move.l  comp_type,d0
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.w   fail_comp_type

        move.l  comp_context,d0
        cmp.l   #MMAL_COMP_CONTEXT,d0
        bne.w   fail_comp_context

        move.l  comp_hdr_status,d0
        tst.l   d0
        bne.w   fail_comp_hdr_status

        move.l  comp_reply_status,d0
        tst.l   d0
        bne.w   fail_comp_reply_status

        move.l  component_handle,d0
        tst.l   d0
        beq.w   fail_comp_handle

        lea     msg_comp_success,a1
        move.l  #msg_comp_success_end-msg_comp_success,d3
        bsr     print

        ; Host stream is at 0xF8 after COMPONENT_CREATE.
        move.l  #248,port_tx_pos

; --------------------------------------------------------------------
; 15. Query all four port classes which the official MMAL host code
;     queries after COMPONENT_CREATE.
; --------------------------------------------------------------------
        lea     msg_ports_start,a1
        move.l  #msg_ports_start_end-msg_ports_start,d3
        bsr     print

        lea     msg_port_control,a1
        move.l  #msg_port_control_end-msg_port_control,d3
        bsr     print
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,control_port_handle

        lea     msg19c_control_enable,a1
        move.l  #msg19c_control_enable_end-msg19c_control_enable,d3
        bsr     print

        bsr     port_enable_control_current
        tst.l   d0
        bne.w   fail_control_enable_main

        lea     msg19c_control_action_ok,a1
        move.l  #msg19c_control_action_ok_end-msg19c_control_action_ok,d3
        bsr     print

        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,control_port_handle
        move.l  port_enabled,d0
        cmp.l   #1,d0
        bne.w   fail_control_enable_verify

        lea     msg19c_control_verify_ok,a1
        move.l  #msg19c_control_verify_ok_end-msg19c_control_verify_ok,d3
        bsr     print

        lea     msg_port_input,a1
        move.l  #msg_port_input_end-msg_port_input,d3
        bsr     print
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,input_port_handle

        move.l  port_buf_num,input_before_buf_num
        move.l  port_buf_size,input_before_buf_size

        lea     msg19c_format_prepare,a1
        move.l  #msg19c_format_prepare_end-msg19c_format_prepare,d3
        bsr     print

        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_H264,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        tst.l   v10b_input_is_mkv
        beq.s   v10g_first_fmt_flags_done
        move.l  #MMAL_ES_FORMAT_FLAG_FRAMED,port_fmt_flags
v10g_first_fmt_flags_done:
        move.l  h264_codec_config_len,d0
        move.l  d0,port_fmt_extra

        move.l  v6_src_aligned_w,port_video_width
        move.l  v6_src_aligned_h,port_video_height
        move.l  v6_src_crop_x,port_crop_x
        move.l  v6_src_crop_y,port_crop_y
        move.l  v6_src_visible_w,port_crop_width
        move.l  v6_src_visible_h,port_crop_height
        move.l  v7_fps_num,port_fps_num
        move.l  v7_fps_den,port_fps_den
        move.l  #1,port_par_num
        move.l  #1,port_par_den
        clr.l   port_color_space

        lea     input_extradata,a1
        moveq   #31,d7
t19c_extra_clear:
        clr.l   (a1)+
        dbra    d7,t19c_extra_clear

        lea     input_extradata,a1
        lea     h264_file_extradata,a0
        move.l  h264_codec_config_len,d7
        subq.l  #1,d7
t19c_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,t19c_extra_copy

        lea     msg19c_format_values,a1
        move.l  #msg19c_format_values_end-msg19c_format_values,d3
        bsr     print

        ; H264RGB4: codec extradata above is parsed SPS+PPS from the selected file.
        ; TEST33: commit the decoder-recommended input geometry instead of
        ; the TEST31D/E minimum 1 x 2048.  VideoCore reported 1 x 0x14000.
        move.l  #INPUT_POOL_COUNT,port_buf_num
        move.l  #INPUT_DATA_SIZE,port_buf_size

        lea     msg_set_start,a1
        move.l  #msg_set_start_end-msg_set_start,d3
        bsr     print

        bsr     port_info_set_input

        lea     msg19c_verify_input,a1
        move.l  #msg19c_verify_input_end-msg19c_verify_input,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   fail_verify_input

        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   fail_verify_h264
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_H264,d0
        bne.w   fail_verify_h264

        move.l  port_fmt_flags,d0
        and.l   #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        tst.l   v10b_input_is_mkv
        beq.s   v10g_first_verify_unframed
        cmpi.l  #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        bne.w   fail_verify_h264
        bra.s   v10g_first_verify_flags_ok
v10g_first_verify_unframed:
        tst.l   d0
        bne.w   fail_verify_h264
v10g_first_verify_flags_ok:

        ; V41I: firmware may normalize aligned geometry/crop/PAR/extradata.
        ; Heidi 956x720 is returned as frame 956x720 although our DMA-side
        ; alignment is 960x720. Identity/encoding/framing/buffer capacity stay strict.
        move.l  port_buf_num,d0
        cmp.l   #INPUT_POOL_COUNT,d0
        bcs.w   fail_verify_input
        move.l  port_buf_size,d0
        cmp.l   #H264_MAX_DATA_LEN,d0
        bcs.w   fail_verify_input

        move.l  port_buf_num,input_before_buf_num
        move.l  port_buf_size,input_before_buf_size
        move.l  port_fmt_extra,input_before_extra

        lea     msg19c_format_verified,a1
        move.l  #msg19c_format_verified_end-msg19c_format_verified,d3
        bsr     print

        lea     msg_port_output,a1
        move.l  #msg_port_output_end-msg_port_output,d3
        bsr     print
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,output_port_handle

        lea     msg_port_clock,a1
        move.l  #msg_port_clock_end-msg_port_clock,d3
        bsr     print
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,clock_port_handle

        lea     msg_ports_summary,a1
        move.l  #msg_ports_summary_end-msg_ports_summary,d3
        bsr     print

        lea     msg_sum_control,a1
        move.l  #msg_sum_control_end-msg_sum_control,d3
        bsr     print
        move.l  control_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_input,a1
        move.l  #msg_sum_input_end-msg_sum_input,d3
        bsr     print
        move.l  input_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_output,a1
        move.l  #msg_sum_output_end-msg_sum_output,d3
        bsr     print
        move.l  output_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_clock,a1
        move.l  #msg_sum_clock_end-msg_sum_clock,d3
        bsr     print
        move.l  clock_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_ports_success,a1
        move.l  #msg_ports_success_end-msg_ports_success,d3
        bsr     print

        ; VPv21T ISOLATION TEST: keep the exact AAC extraction + Helix predecode
        ; and the small PCM allocation, but DO NOT create/configure audio_render.
        ; If HDMI_v41L video is stable here, the host AAC/predecode/memory path is
        ; innocent and the fault begins only when a second MMAL audio component
        ; shares the service/worker RX stream.
        clr.l   vpv21_audio_prepared
        lea     msg_vpv21p_audio_skipped,a1
        move.l  #msg_vpv21p_audio_skipped_end-msg_vpv21p_audio_skipped,d3
        jsr     vpv21n_trace

; --------------------------------------------------------------------
; 18. Re-read INPUT 0 so port_* globals describe exactly this port,
;     then enable it with MMAL PORT_ACTION / ENABLE.
; --------------------------------------------------------------------
        lea     msg_enable_start,a1
        move.l  #msg_enable_start_end-msg_enable_start,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   fail_enable_main

        lea     msg_enable_before,a1
        move.l  #msg_enable_before_end-msg_enable_before,d3
        bsr     print
        move.l  port_enabled,d0
        bsr     print_hex32
        bsr     newline

        bsr     port_enable_current
        tst.l   d0
        bne.w   fail_enable_main

        lea     msg_enable_action_ok,a1
        move.l  #msg_enable_action_ok_end-msg_enable_action_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 19. Verify INPUT 0 reports enabled=1.
; --------------------------------------------------------------------
        lea     msg_enable_verify,a1
        move.l  #msg_enable_verify_end-msg_enable_verify,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_enabled,d0
        cmp.l   #1,d0
        bne.w   fail_enable_verify

        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   fail_enable_verify

        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_H264,d0
        bne.w   fail_enable_verify

        lea     msg_enable_verify_ok,a1
        move.l  #msg_enable_verify_ok_end-msg_enable_verify_ok,d3
        bsr     print

; --------------------------------------------------------------------
; V12A. Decoder OUTPUT is no longer copied to host memory at source size.
; Build a VideoCore-only tunnel:
;   ril.video_decode OUTPUT -> ril.isp INPUT -> 192xN I420 OUTPUT -> host
; The old HAM6 scaler still receives an ordinary small I420 frame.
; --------------------------------------------------------------------
        lea     msg_v12a_graph_start,a1
        move.l  #msg_v12a_graph_start_end-msg_v12a_graph_start,d3
        bsr     print
        lea     msg_vpv21p_graph_before,a1
        move.l  #msg_vpv21p_graph_before_end-msg_vpv21p_graph_before,d3
        jsr     vpv21n_trace
        jsr     v12a_setup_isp_graph
        tst.l   d0
        bne.w   vpv21p_graph_failed
        lea     msg_vpv21p_graph_after_ok,a1
        move.l  #msg_vpv21p_graph_after_ok_end-msg_vpv21p_graph_after_ok,d3
        jsr     vpv21n_trace
        bra.s   vpv21p_graph_return_ok
vpv21p_graph_failed:
        lea     msg_vpv21p_graph_after_fail,a1
        move.l  #msg_vpv21p_graph_after_fail_end-msg_vpv21p_graph_after_fail,d3
        jsr     vpv21n_trace
        bra.w   fail_output_enable_main
vpv21p_graph_return_ok:

        ; HDMI_v41L: no host I420/HAM6 output exists, so the old 192x144
        ; scaler/map preparation is intentionally skipped.

; --------------------------------------------------------------------
; 22. Enable decoder component.
; --------------------------------------------------------------------
        lea     msg_component_enable,a1
        move.l  #msg_component_enable_end-msg_component_enable,d3
        bsr     print

        bsr     component_enable_worker
        tst.l   d0
        bne.w   fail_component_enable_main

        lea     msg_component_enable_ok,a1
        move.l  #msg_component_enable_ok_end-msg_component_enable_ok,d3
        bsr     print

        ; VPv36 isolation stage: prove that a SECOND MMAL component can coexist
        ; on the same already-open MMAL service without configuring any audio
        ; ports and without sending PCM. This is deliberately one step beyond T.
        move.l  component_handle,vpv21_saved_component
        move.l  input_port_handle,vpv21_saved_input
        move.l  port_query_index,vpv21_saved_port_qidx
        move.l  port_buf_size,vpv21_saved_port_buf_size

        lea     msg_vpv21u_create_begin,a1
        move.l  #msg_vpv21u_create_begin_end-msg_vpv21u_create_begin,d3
        jsr     vpv21n_trace
        jsr     vpv01_create_audio_render
        move.l  d0,d7

        ; Restore the live video decoder globals immediately. The audio handle
        ; remains only in vpv01_audio_handle; no audio PORT_INFO_* is executed.
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size

        tst.l   d7
        bne.w   vpv21u_audio_create_failed
        lea     msg_vpv21u_create_ok,a1
        move.l  #msg_vpv21u_create_ok_end-msg_vpv21u_create_ok,d3
        jsr     vpv21n_trace

        ; VPv36: one step beyond VPv21U. Query audio_render CONTROL 0, then INPUT 0.
        ; No PORT_INFO_SET, no enable, no PCM traffic.
        move.l  port_query_type,vpv23_saved_port_qtype
        lea     msg_vpv23_ctrl_get_begin,a1
        move.l  #msg_vpv23_ctrl_get_begin_end-msg_vpv23_ctrl_get_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv23_ctrl_get_fail_local
        move.l  port_last_handle,vpv01_audio_control
        lea     msg_vpv23_ctrl_get_ok,a1
        move.l  #msg_vpv23_ctrl_get_ok_end-msg_vpv23_ctrl_get_ok,d3
        jsr     vpv21n_trace

        ; VPv36: next isolated step - query audio_render INPUT 0 only.
        ; Still no PORT_INFO_SET, enable, HDMI destination or PCM traffic.
        lea     msg_vpv24_input_get_begin,a1
        move.l  #msg_vpv24_input_get_begin_end-msg_vpv24_input_get_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #1,v12a_local_get_active
        jsr     port_info_get
        clr.l   v12a_local_get_active
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv24_input_get_fail_local
        move.l  port_last_handle,vpv01_audio_input
        lea     msg_vpv24_input_get_ok,a1
        move.l  #msg_vpv24_input_get_ok_end-msg_vpv24_input_get_ok,d3
        jsr     vpv21n_trace

        ; VPv36: isolated INPUT0 PORT_INFO_SET using the real Helix PCM format.
        ; No HDMI destination, no audio enable and no PCM buffer traffic yet.
        lea     msg_vpv26_input_set_begin,a1
        move.l  #msg_vpv26_input_set_begin_end-msg_vpv26_input_set_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  v19_pcm_bitrate,d0
        move.l  d0,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v19_pcm_channels,d0
        move.l  d0,port_video_width
        move.l  v19_pcm_rate,d0
        move.l  d0,port_video_height
        move.l  v19_pcm_bits,d0
        move.l  d0,port_crop_x
        move.l  v19_pcm_blockalign,d0
        move.l  d0,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space
        move.l  port_buf_num_min,d0
        tst.l   d0
        bne.s   vpv26_fresh_set_num_ok
        moveq   #1,d0
vpv26_fresh_set_num_ok:
        move.l  d0,port_buf_num
        ; VPv36: use the exact buffer sizing already hardware-proven in VPv20.
        ; VPv25 used the retained PCM byte count (e.g. $BB80), which the
        ; audio renderer rejected. VPv20 commits a 64-KiB input buffer.
        move.l  #$00010000,d0
        cmp.l   port_buf_size_min,d0
        bcc.s   vpv26_fresh_set_size_ok
        move.l  port_buf_size_min,d0
vpv26_fresh_set_size_ok:
        cmp.l   #INPUT_DATA_SIZE,d0
        bhi.w   vpv26_input_set_fail_local
        move.l  d0,port_buf_size
        clr.l   vpv30_skipped
        clr.l   vpv30_async_skipped
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        move.l  d0,d7
        tst.l   vpv30_skipped
        beq.s   vpv30_fresh_no_skip_log
        lea     msg_vpv30_dispatch_skipped,a1
        move.l  #msg_vpv30_dispatch_skipped_end-msg_vpv30_dispatch_skipped,d3
        jsr     vpv21n_trace
        bra.s   vpv30_fresh_skip_log_done
vpv30_fresh_no_skip_log:
        lea     msg_vpv30_dispatch_direct,a1
        move.l  #msg_vpv30_dispatch_direct_end-msg_vpv30_dispatch_direct,d3
        jsr     vpv21n_trace
vpv30_fresh_skip_log_done:
        tst.l   d7
        bne.w   vpv26_input_set_fail_local
        lea     msg_vpv26_input_set_ok,a1
        move.l  #msg_vpv26_input_set_ok_end-msg_vpv26_input_set_ok,d3
        jsr     vpv21n_trace
        ; VPv36: first full audio-render configuration test.  The PCM format SET
        ; is now proven slot-safe in VPv32, so add only destination + INPUT enable
        ; + component enable.  No PCM buffer is queued yet.
        jsr     vpv35_finish_audio_enable
        tst.l   d0
        beq.s   vpv35_fresh_audio_enable_ok
        lea     msg_vpv35_enable_fail_continue,a1
        move.l  #msg_vpv35_enable_fail_continue_end-msg_vpv35_enable_fail_continue,d3
        jsr     vpv21n_trace
        bra.s   vpv35_fresh_audio_enable_done
vpv35_fresh_audio_enable_ok:
        lea     msg_vpv35_enable_ok,a1
        move.l  #msg_vpv35_enable_ok_end-msg_vpv35_enable_ok,d3
        jsr     vpv21n_trace
        ; VPv36: first real combined A/V proof. Queue the already-decoded
        ; short PCM prefix now, while no H264 input buffers are in flight.
        ; The queue helper is slot-safe and waits for BULK_TX_DONE before
        ; restoring the video globals. Audio may then play while video starts.
        jsr     vpv21_queue_audio_prefix
        tst.l   d0
        beq.s   vpv35_fresh_audio_queue_ok
        lea     msg_vpv35_queue_fail_continue,a1
        move.l  #msg_vpv35_queue_fail_continue_end-msg_vpv35_queue_fail_continue,d3
        jsr     vpv21n_trace
        bra.s   vpv35_fresh_audio_enable_done
vpv35_fresh_audio_queue_ok:
        lea     msg_vpv35_queue_proven,a1
        move.l  #msg_vpv35_queue_proven_end-msg_vpv35_queue_proven,d3
        jsr     vpv21n_trace
vpv35_fresh_audio_enable_done:
        moveq   #0,d7
        bra.w   vpv23_ctrl_get_restore
vpv26_input_set_fail_local:
        lea     msg_vpv26_input_set_fail,a1
        move.l  #msg_vpv26_input_set_fail_end-msg_vpv26_input_set_fail,d3
        jsr     vpv21n_trace
        ; VPv36 diagnostic policy: audio SET failure must not suppress video.
        ; Continue with the proven HDMI_v41L stream, with audio still disabled.
        lea     msg_vpv26_set_fail_continue,a1
        move.l  #msg_vpv26_set_fail_continue_end-msg_vpv26_set_fail_continue,d3
        jsr     vpv21n_trace
        moveq   #0,d7
        bra.w   vpv23_ctrl_get_restore
vpv24_input_get_fail_local:
        lea     msg_vpv24_input_get_fail,a1
        move.l  #msg_vpv24_input_get_fail_end-msg_vpv24_input_get_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d7
        bra.w   vpv23_ctrl_get_restore
vpv23_ctrl_get_fail_local:
        lea     msg_vpv23_ctrl_get_fail,a1
        move.l  #msg_vpv23_ctrl_get_fail_end-msg_vpv23_ctrl_get_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d7
vpv23_ctrl_get_restore:
        ; Restore live video globals. TX/RX positions remain advanced because
        ; the CONTROL0 query is a real consumed VCHIQ transaction.
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
        tst.l   d7
        bne.w   fail_buffer_main
        bra.s   vpv21u_audio_create_done
vpv21u_audio_create_failed:
        lea     msg_vpv21u_create_fail,a1
        move.l  #msg_vpv21u_create_fail_end-msg_vpv21u_create_fail,d3
        jsr     vpv21n_trace
        bra.w   fail_buffer_main
vpv21u_audio_create_done:

        ; CONTROL0 and INPUT0 were queried successfully; audio INPUT remains unmodified.
        lea     msg_vpv21p_before_video_stream,a1
        move.l  #msg_vpv21p_before_video_stream_end-msg_vpv21p_before_video_stream,d3
        jsr     vpv21n_trace

; --------------------------------------------------------------------
; 23..28. Queue one empty output buffer, read raw H264 in fixed 65536-byte
; unframed chunks with NO AU knowledge, recycle the same input buffer, and collect:
;   A) an OUTPUT EVENT_TO_HOST (typically format negotiation), or
;   B) an OUTPUT BUFFER_TO_HOST with real data, followed by BULK_RX.
; --------------------------------------------------------------------
        bsr     h264_output_test
        move.l  d0,d6
        lea     msg_vpv21t_h264_returned,a1
        move.l  #msg_vpv21t_h264_returned_end-msg_vpv21t_h264_returned,d3
        jsr     vpv21n_trace
        move.l  d6,d0
        tst.l   d0
        bne.w   fail_buffer_main

        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   v15_first_natural_success
        lea     msg_v15_stop_success,a1
        move.l  #msg_v15_stop_success_end-msg_v15_stop_success,d3
        bsr     print
        bra.s   v15_first_success_done
v15_first_natural_success:
        lea     msg_test19_success,a1
        move.l  #msg_test19_success_end-msg_test19_success,d3
        bsr     print
v15_first_success_done:

        ; V9: close_prog now performs ordered teardown instead of requiring reboot.
        bsr     dma_pre_all
        bra.w   close_prog

fail_control_enable_main:
        lea     e19c_control_enable,a1
        move.l  #e19c_control_enable_end-e19c_control_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_control_enable_verify:
        lea     e19c_control_verify,a1
        move.l  #e19c_control_verify_end-e19c_control_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_enable_main:
        lea     e_enable_main,a1
        move.l  #e_enable_main_end-e_enable_main,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_enable_verify:
        lea     e_enable_verify,a1
        move.l  #e_enable_verify_end-e_enable_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_output_enable_main:
        lea     msg_vpv21p_fail_output_entry,a1
        move.l  #msg_vpv21p_fail_output_entry_end-msg_vpv21p_fail_output_entry,d3
        jsr     vpv21n_trace
        lea     e19_output_enable,a1
        move.l  #e19_output_enable_end-e19_output_enable,d3
        bsr     print
        bsr     dma_pre_all
        lea     msg_vpv21p_fail_output_after_dma,a1
        move.l  #msg_vpv21p_fail_output_after_dma_end-msg_vpv21p_fail_output_after_dma,d3
        jsr     vpv21n_trace
        bra.w   close_prog

fail_output_enable_verify:
        lea     e19_output_verify,a1
        move.l  #e19_output_verify_end-e19_output_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_component_enable_main:
        lea     e_component_enable,a1
        move.l  #e_component_enable_end-e_component_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_buffer_main:
        lea     e_buffer_main,a1
        move.l  #e_buffer_main_end-e_buffer_main,d3
        bsr     print
        ; h264_bulk_test returns with shared VCHIQ RAM CPU-owned.
        bsr     dma_pre_all
        bra.w   close_prog

; --------------------------------------------------------------------
; VPv36 minimal context-aware synchronous RX dispatcher.
;
; This is deliberately the small single-threaded/polled form used by our
; current Amiga player: only ONE synchronous MMAL request is outstanding.
; Every RX record is classified before it can satisfy the waiter.
;
; Expected values:
;   vpv30_expect_type
;   vpv30_expect_context
;
; Return:
;   D0=0, A2 -> matching current RX VCHIQ record, NOT consumed, CPU-owned
;   D0=1 on timeout/map/consume failure, CPU-owned
;
; For VPv36 proof only, unsolicited BUFFER_TO_HOST/EVENT_TO_HOST records seen
; during this pre-stream control transaction are consumed and counted. The
; final A/V implementation will route/queue those events instead of dropping
; them once audio/video buffer traffic is active.
; --------------------------------------------------------------------
vpv30_alloc_context:
        move.l  vpv30_context_counter,d0
        addq.l  #1,d0
        and.l   #$0FFFFFFF,d0
        bne.s   vpv30_ctx_nonzero
        moveq   #1,d0
vpv30_ctx_nonzero:
        move.l  d0,vpv30_context_counter
        or.l    #$30000000,d0
        rts

vpv30_wait_matching:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  #POLL_COUNT,d7

vpv30_wait_loop:
        jsr     short_delay
        jsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv30_wait_have

        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   vpv30_wait_loop

        ; Last iteration left shared memory DMA-owned.
        jsr     dma_post_all
        moveq   #1,d0
        bra.w   vpv30_wait_done

vpv30_wait_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv30_wait_fail

        move.l  a2,a0
        jsr     load_le32
        move.l  d0,vpv30_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv30_rx_size

        ; VCHIQ DATA on the current local MMAL service only.
        move.l  vpv30_rx_msgid,d0
        and.l   #$FF000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   vpv30_wait_skip

        move.l  vpv30_rx_msgid,d0
        and.l   #$00000FFF,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv30_wait_skip

        move.l  vpv30_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv30_wait_skip

        ; Need enough MMAL header bytes to inspect magic/type/context.
        move.l  vpv30_rx_size,d0
        cmp.l   #16,d0
        bcs.w   vpv30_wait_skip

        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv30_wait_skip

        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,d6

        ; Explicitly classify unsolicited messages before context matching.
        cmp.l   #MMAL_BUFFER_TO_HOST,d6
        beq.w   vpv30_wait_skip_async
        cmp.l   #MMAL_EVENT_TO_HOST,d6
        beq.w   vpv30_wait_skip_async

        cmp.l   vpv30_expect_type,d6
        bne.w   vpv30_wait_skip

        lea     20(a2),a0
        jsr     load_le32
        cmp.l   vpv30_expect_context,d0
        bne.w   vpv30_wait_skip

        ; Exact synchronous reply found. Leave it current/unconsumed.
        moveq   #0,d0
        bra.w   vpv30_wait_done

vpv30_wait_skip_async:
        addq.l  #1,vpv30_async_skipped
vpv30_wait_skip:
        addq.l  #1,vpv30_skipped
        move.l  vpv30_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.s   vpv30_wait_fail

        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv30_wait_loop

        jsr     dma_post_all
        moveq   #1,d0
        bra.s   vpv30_wait_done

vpv30_wait_fail:
        moveq   #1,d0
vpv30_wait_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; --------------------------------------------------------------------
; PORT_INFO_GET helper
;
; Inputs via globals:
;   port_query_type
;   port_query_index
;
; On success:
;   port_last_handle and diagnostic fields are updated.
;   Shared memory is CPU-owned on return.
;
; Request = MMAL header 24 + payload 12 = 36 bytes.
; VCHIQ stride = align8(8 + 36) = 48 bytes.
;
; Full firmware reply is normally:
;   MMAL header 24
;   port_info_get_reply 292
; = 316 VCHIQ payload bytes, stride 328.
; We calculate the actual returned stride from RX size.
; --------------------------------------------------------------------
port_info_get:
        ; V14 restart: the existing v9f local-1 PORT_INFO_GET helper has
        ; already been hardware-proven repeatedly during second-decoder setup.
        ; Reuse it for every ISP graph GET instead of the first-run polling path.
        tst.l   v12f_local_port
        beq.s   v12h_port_info_get_first
        jmp     v9f_port_info_get
v12h_port_info_get_first:
        movem.l d2-d7/a2-a3,-(sp)

        ; VPv36: every synchronous request gets a fresh opaque context token.
        ; This follows the reference MMAL client model: reply matching is by
        ; context, never by "next RX message".
        jsr     vpv30_alloc_context
        move.l  d0,port_query_context

        ; V12G restart: absolute TX position must be mapped through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_get_tx_legacy
        move.l  #48,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   fail_port_rxslot
        bra.s   v12g_get_tx_ready
v12g_get_tx_legacy:
        ; Original first-run mapping, intentionally unchanged.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_get_tx_ready:

        ; VCHIQ DATA header, destination = opened VC MMAL port.
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #36,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_INFO_GET,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  port_query_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; port_info_get payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  port_query_type,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  port_query_index,d0
        bsr     store_le32

        ; Advance host stream by one 48-byte VCHIQ stride.
        move.l  port_tx_pos,d0
        add.l   #48,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        ; Signal VC event.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,port_armed

        bsr     dma_pre_all

        move.l  port_armed,d0
        tst.l   d0
        beq.w   port_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

port_no_bell:
        ; VPv36 dispatcher proof: do not assume the next VCHIQ/MMAL record is
        ; our reply. Consume unrelated records until type+context match.
        move.l  #MMAL_PORT_INFO_GET,vpv30_expect_type
        move.l  port_query_context,vpv30_expect_context
        jsr     vpv30_wait_matching
        tst.l   d0
        bne.w   fail_port_timeout
        bra.w   port_reply_seen

        ; Legacy polling loop retained below but no longer entered here.
        move.l  #POLL_COUNT,d7

port_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   port_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   port_poll_loop
        bra.w   fail_port_timeout

port_reply_seen:
        ; V12D: extra ISP setup replies may be in the next MASTER slot.
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   fail_port_rxslot
        move.l  a2,a0

        ; VCHIQ header.
        bsr     load_le32
        move.l  d0,port_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,port_rx_size

        ; DATA type?
        move.l  port_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_port_wrongmsg

        ; Destination local port 0?
        move.l  port_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   fail_port_wrongport

        ; Source is the opened MMAL VC port?
        move.l  port_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_port_wrongport

        ; Need enough bytes through video.color_space.
        move.l  port_rx_size,d0
        cmp.l   #188,d0
        bcs.w   fail_port_short

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_hstatus

        ; port_info_get_reply fixed prefix.
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_component

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_type

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_index

        lea     52(a2),a0
        bsr     load_le32
        move.l  d0,port_last_handle

        ; struct mmal_port begins at message offset 56.
        lea     72(a2),a0
        bsr     load_le32
        move.l  d0,port_enabled

        lea     80(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num_min

        lea     84(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size_min

        lea     88(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_align

        lea     92(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num_rec

        lea     96(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size_rec

        lea     100(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num

        lea     104(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size

        lea     116(a2),a0
        bsr     load_le32
        move.l  d0,port_caps

        ; struct mmal_es_format begins at message offset 120.
        lea     120(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_type

        lea     124(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_encoding

        lea     128(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_variant

        lea     136(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_bitrate

        lea     140(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_flags

        lea     144(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_extra

        ; union mmal_es_specific_format begins at offset 152.
        ; These fields are useful when format type is VIDEO.
        lea     152(a2),a0
        bsr     load_le32
        move.l  d0,port_video_width

        lea     156(a2),a0
        bsr     load_le32
        move.l  d0,port_video_height

        lea     160(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_x

        lea     164(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_y

        lea     168(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_width

        lea     172(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_height

        lea     176(a2),a0
        bsr     load_le32
        move.l  d0,port_fps_num

        lea     180(a2),a0
        bsr     load_le32
        move.l  d0,port_fps_den

        lea     184(a2),a0
        bsr     load_le32
        move.l  d0,port_par_num

        lea     188(a2),a0
        bsr     load_le32
        move.l  d0,port_par_den

        lea     192(a2),a0
        bsr     load_le32
        move.l  d0,port_color_space

        ; Preserve codec extradata only when this reply is INPUT 0.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        bne.w   port_extra_done
        move.l  port_query_index,d0
        tst.l   d0
        bne.w   port_extra_done

        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   fail_port_extradata

        lea     input_extradata,a0
        move.l  #31,d7
port_extra_clear_loop:
        clr.l   (a0)+
        dbra    d7,port_extra_clear_loop

        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.w   port_extra_done
        subq.l  #1,d7
        lea     196(a2),a0
        lea     input_extradata,a1
port_extra_copy_loop:
        move.b  (a0)+,(a1)+
        dbra    d7,port_extra_copy_loop

port_extra_done:
        ; Validate reply identity.
        move.l  port_mmal_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_port_magic

        move.l  port_mmal_type,d0
        cmp.l   #MMAL_PORT_INFO_GET,d0
        bne.w   fail_port_type

        move.l  port_mmal_context,d0
        cmp.l   port_query_context,d0
        bne.w   fail_port_context

        move.l  port_mmal_hstatus,d0
        tst.l   d0
        bne.w   fail_port_status

        move.l  port_reply_status,d0
        tst.l   d0
        bne.w   fail_port_status

        move.l  port_reply_component,d0
        cmp.l   component_handle,d0
        bne.w   fail_port_component

        move.l  port_reply_type,d0
        cmp.l   port_query_type,d0
        bne.w   fail_port_identity

        move.l  port_reply_index,d0
        cmp.l   port_query_index,d0
        bne.w   fail_port_identity

        ; port_handle is opaque. Value 0 is VALID for the MMAL control
        ; port on real Raspberry Pi firmware, so do not reject it.

        ; Print compact but useful port information.
        lea     msg_p_handle,a1
        move.l  #msg_p_handle_end-msg_p_handle,d3
        bsr     print
        move.l  port_last_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_enabled,a1
        move.l  #msg_p_enabled_end-msg_p_enabled,d3
        bsr     print
        move.l  port_enabled,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_min,a1
        move.l  #msg_p_min_end-msg_p_min,d3
        bsr     print
        move.l  port_buf_num_min,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size_min,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_rec,a1
        move.l  #msg_p_rec_end-msg_p_rec,d3
        bsr     print
        move.l  port_buf_num_rec,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size_rec,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_cur,a1
        move.l  #msg_p_cur_end-msg_p_cur,d3
        bsr     print
        move.l  port_buf_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_align,a1
        move.l  #msg_p_align_end-msg_p_align,d3
        bsr     print
        move.l  port_buf_align,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_caps,a1
        move.l  #msg_p_caps_end-msg_p_caps,d3
        bsr     print
        move.l  port_caps,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_format,a1
        move.l  #msg_p_format_end-msg_p_format,d3
        bsr     print
        move.l  port_fmt_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_encoding,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_variant,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_video,a1
        move.l  #msg_p_video_end-msg_p_video,d3
        bsr     print
        move.l  port_video_width,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  port_video_height,d0
        bsr     print_hex32
        lea     msg_crop,a1
        move.l  #msg_crop_end-msg_crop,d3
        bsr     print
        move.l  port_crop_width,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  port_crop_height,d0
        bsr     print_hex32
        bsr     newline

        ; Move to next VC stream message and recycle a crossed MASTER slot.
        move.l  port_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   fail_port_rxslot

        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; PORT_INFO_SET current INPUT 0 state back to VideoCore.
;
; Request layout (wire, 32-bit pointers):
;   MMAL header                     24
;   component/type/index            12
;   mmal_port                       64
;   mmal_es_format                  32
;   mmal_es_specific_format         44
;   extradata                      128
; Total MMAL payload               304
; VCHIQ stride = align8(8+304)     312
;
; Per Linux/RPi implementation, only writable MMAL_PORT fields are sent:
;   buffer_num, buffer_size, userdata.
; Format + ES + extradata are copied from the preceding INPUT GET.
; --------------------------------------------------------------------
port_info_set_input:
        movem.l d2-d7/a2-a3,-(sp)

        ; Sanity before sending.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        beq.s   v12_set_type_ok
        cmp.l   #MMAL_PORT_OUTPUT,d0
        bne.w   fail_set_identity
v12_set_type_ok:
        move.l  port_query_index,d0
        tst.l   d0
        bne.w   fail_set_identity
        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   fail_set_extradata

        ; VPv36: fresh context token for this SET request.
        jsr     vpv30_alloc_context
        move.l  d0,set_context

        ; VPv36: PORT_INFO_SET is a 312-byte VCHIQ record and must NEVER
        ; cross a 4-KiB slot boundary.  The old local-0/first-run path
        ; mapped slot 34 + absolute port_tx_pos directly and therefore
        ; became unsafe after the already large video-graph control traffic.
        ; Local-1 was already using h26a_reserve_tx.  Use the same proven
        ; slot-queue/PADDING reservation for BOTH local services.
        move.l  #312,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   fail_set_rxslot

        ; Clear complete 312-byte VCHIQ message first.
        move.l  a2,a0
        move.l  #77,d7
set_clear_loop:
        clr.l   (a0)+
        dbra    d7,set_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #304,d0
        bsr     store_le32

        ; MMAL worker header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_INFO_SET,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  set_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; mmal_worker_port_info_set fixed prefix.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  port_query_type,d0
        bsr     store_le32

        lea     40(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; mmal_port starts at 44.
        ; Only client-writable fields are meaningful for SET:
        ; buffer_num @ +44, buffer_size @ +48, userdata @ +56
        ; relative to mmal_port, therefore message offsets 88,92,100.
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32

        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32

        lea     100(a2),a0
        move.l  #MMAL_INPUT_USERDATA,d0
        bsr     store_le32

        ; mmal_es_format starts at 108.
        lea     108(a2),a0
        move.l  port_fmt_type,d0
        bsr     store_le32

        lea     112(a2),a0
        move.l  port_fmt_encoding,d0
        bsr     store_le32

        lea     116(a2),a0
        move.l  port_fmt_variant,d0
        bsr     store_le32

        ; es pointer @120 remains zero.

        lea     124(a2),a0
        move.l  port_fmt_bitrate,d0
        bsr     store_le32

        lea     128(a2),a0
        move.l  port_fmt_flags,d0
        bsr     store_le32

        lea     132(a2),a0
        move.l  port_fmt_extra,d0
        bsr     store_le32

        ; extradata pointer @136 remains zero.

        ; mmal_es_specific_format.video starts at 140.
        lea     140(a2),a0
        move.l  port_video_width,d0
        bsr     store_le32

        lea     144(a2),a0
        move.l  port_video_height,d0
        bsr     store_le32

        lea     148(a2),a0
        move.l  port_crop_x,d0
        bsr     store_le32

        lea     152(a2),a0
        move.l  port_crop_y,d0
        bsr     store_le32

        lea     156(a2),a0
        move.l  port_crop_width,d0
        bsr     store_le32

        lea     160(a2),a0
        move.l  port_crop_height,d0
        bsr     store_le32

        lea     164(a2),a0
        move.l  port_fps_num,d0
        bsr     store_le32

        lea     168(a2),a0
        move.l  port_fps_den,d0
        bsr     store_le32

        lea     172(a2),a0
        move.l  port_par_num,d0
        bsr     store_le32

        lea     176(a2),a0
        move.l  port_par_den,d0
        bsr     store_le32

        lea     180(a2),a0
        move.l  port_color_space,d0
        bsr     store_le32

        ; Extradata begins at 184 and is already zeroed.
        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.w   set_extra_done
        subq.l  #1,d7
        lea     input_extradata,a0
        lea     184(a2),a1
set_extra_copy_loop:
        move.b  (a0)+,(a1)+
        dbra    d7,set_extra_copy_loop

set_extra_done:
        lea     msg_set_tx,a1
        move.l  #msg_set_tx_end-msg_set_tx,d3
        bsr     print
        move.l  port_buf_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_set_fmt,a1
        move.l  #msg_set_fmt_end-msg_set_fmt,d3
        bsr     print
        move.l  port_fmt_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_encoding,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_variant,d0
        bsr     print_hex32
        bsr     newline

        ; Advance local stream by 312 bytes and notify VC.
        move.l  port_tx_pos,d0
        add.l   #312,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,set_armed

        bsr     dma_pre_all

        move.l  set_armed,d0
        tst.l   d0
        beq.w   set_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

set_no_bell:
        ; VPv36 dispatcher proof: wait for the exact PORT_INFO_SET context.
        ; Unrelated MMAL traffic is consumed instead of being misread as reply.
        move.l  #MMAL_PORT_INFO_SET,vpv30_expect_type
        move.l  set_context,vpv30_expect_context
        jsr     vpv30_wait_matching
        tst.l   d0
        bne.w   fail_set_timeout
        bra.w   set_reply_seen

        ; Legacy polling loop retained below but no longer entered here.
        move.l  #POLL_COUNT,d7

set_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   set_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   set_poll_loop
        bra.w   fail_set_timeout

set_reply_seen:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   fail_set_rxslot
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,set_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,set_rx_size

        ; VCHIQ DATA and correct remote/local ports.
        move.l  set_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_set_wrongmsg

        move.l  set_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   fail_set_wrongport

        move.l  set_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_set_wrongport

        ; Need at least MMAL header + reply status/component/type/index.
        move.l  set_rx_size,d0
        cmp.l   #40,d0
        bcs.w   fail_set_short

        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,set_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,set_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,set_header_status

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_component

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_port_type

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_index

        lea     msg_set_reply,a1
        move.l  #msg_set_reply_end-msg_set_reply,d3
        bsr     print
        move.l  set_rx_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_set_status,a1
        move.l  #msg_set_status_end-msg_set_status,d3
        bsr     print
        move.l  set_reply_status,d0
        bsr     print_hex32
        bsr     newline

        ; Validate MMAL reply.
        move.l  set_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_set_magic

        move.l  set_type,d0
        cmp.l   #MMAL_PORT_INFO_SET,d0
        bne.w   fail_set_type

        move.l  set_reply_context,d0
        cmp.l   set_context,d0
        bne.w   fail_set_context

        move.l  set_header_status,d0
        tst.l   d0
        bne.w   fail_set_status

        move.l  set_reply_status,d0
        tst.l   d0
        bne.w   fail_set_status

        move.l  set_reply_component,d0
        cmp.l   component_handle,d0
        bne.w   fail_set_identity

        move.l  set_reply_port_type,d0
        cmp.l   port_query_type,d0
        bne.w   fail_set_identity

        move.l  set_reply_index,d0
        tst.l   d0
        bne.w   fail_set_identity

        ; Advance VC stream slot-safely.
        move.l  set_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   fail_set_rxslot

        lea     msg_set_ok,a1
        move.l  #msg_set_ok_end-msg_set_ok,d3
        bsr     print

        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; PORT_ACTION ENABLE helper for the port currently described by port_*.
;
; Request:
;   MMAL header                 24
;   component_handle             4
;   port_handle                  4
;   action                       4
;   struct mmal_port            64
; = MMAL DATA payload          100
; VCHIQ header + payload = 108 -> stride 112.
;
; Reply:
;   MMAL header 24 + status 4 = 28 -> VCHIQ stride 40.
;
; Returns D0=0 success, D0=1 failure.
; Always returns with shared memory CPU-owned.
; --------------------------------------------------------------------
port_enable_current:
        movem.l d2-d7/a2-a3,-(sp)

        move.l  #$16000002,enable_context

        ; VPv36: slot-safe reservation on local-0 as well.  PORT_ACTION is
        ; 112 bytes and, like PORT_INFO_SET, may not cross a 4-KiB VCHIQ slot.
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   enable_bad_reply

        ; Clear complete request area (112 bytes) first.
        move.l  a2,a0
        move.l  #27,d7
enable_clear_loop:
        clr.l   (a0)+
        dbra    d7,enable_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  enable_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; PORT_ACTION payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  input_port_handle,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_ENABLE,d0
        bsr     store_le32

        ; struct mmal_port at offset 44.
        ; priv/name = 0
        lea     52(a2),a0               ; port.type
        move.l  #MMAL_PORT_INPUT,d0
        bsr     store_le32

        ; index/index_all both zero -> packed u16/u16 word remains zero.

        lea     60(a2),a0               ; is_enabled
        move.l  port_enabled,d0
        bsr     store_le32

        ; format pointer field at 64 remains zero.

        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32

        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32

        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32

        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32

        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32

        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32

        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32

        ; component pointer field at 96 remains zero.
        lea     100(a2),a0              ; userdata opaque client cookie
        move.l  #$16000002,d0
        bsr     store_le32

        lea     104(a2),a0              ; capabilities (RO, but harmless)
        move.l  port_caps,d0
        bsr     store_le32

        ; Publish new host tx pos.
        move.l  port_tx_pos,d0
        add.l   #112,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        ; Signal VC.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,enable_armed

        bsr     dma_pre_all

        move.l  enable_armed,d0
        tst.l   d0
        beq.w   enable_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

enable_no_bell:
        move.l  #POLL_COUNT,d7

enable_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   enable_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   enable_poll_loop

        ; timeout: regain CPU ownership before returning
        bsr     dma_post_all
        lea     e_enable_timeout,a1
        move.l  #e_enable_timeout_end-e_enable_timeout,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

enable_reply_seen:
        ; Current tests are still within first VC data slot.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   enable_bad_reply
        cmp.l   #32,d0
        bhi.w   enable_bad_reply

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_rx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2

        bsr     load_le32
        move.l  d0,enable_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,enable_rx_size

        ; VCHIQ DATA / local port 0 / source mmal VC port.
        move.l  enable_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   enable_bad_reply

        move.l  enable_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   enable_bad_reply

        move.l  enable_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   enable_bad_reply

        move.l  enable_rx_size,d0
        cmp.l   #28,d0
        bcs.w   enable_bad_reply

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   enable_bad_reply

        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   enable_bad_reply

        lea     20(a2),a0
        bsr     load_le32
        cmp.l   enable_context,d0
        bne.w   enable_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   enable_bad_reply

        ; port_action_reply.status
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,enable_status

        lea     msg_enable_status,a1
        move.l  #msg_enable_status_end-msg_enable_status,d3
        bsr     print
        move.l  enable_status,d0
        bsr     print_hex32
        bsr     newline

        move.l  enable_status,d0
        tst.l   d0
        bne.w   enable_bad_reply

        ; Advance VC stream by actual VCHIQ stride.
        move.l  enable_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

enable_bad_reply:
        lea     e_enable_reply,a1
        move.l  #e_enable_reply_end-e_enable_reply,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

port_enable_control_current:
        movem.l d2-d7/a2-a3,-(sp)

        move.l  #$19C00001,ctrl_enable_context

        ; Host slot 34 + current tx position.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
