; --------------------------------------------------------------------
; TEST17 - BUFFER_FROM_HOST empty-buffer roundtrip
;
; Official 32-bit worker structure:
;   MMAL header                       24
;   drvbuf                            16
;   drvbuf_ref                        16
;   MMAL_BUFFER_HEADER_T              56
;   type-specific                     40
;   is_zero_copy                       4
;   has_reference                      4
;   payload_in_message                 4
;   short_data                       128
; --------------------------------------
; MMAL payload total                 292 = 0x124
; VCHIQ header + payload             300
; VCHIQ aligned stride               304
;
; For this first buffer test:
;   cmd=0, length=0, offset=0, flags=0
;   payload_in_message=0
;   is_zero_copy=0
;   has_reference=0
;   pts=dts=MMAL_TIME_UNKNOWN
;   NO BULK is submitted.
;
; Return:
;   D0=0 success
;   D0=1 failure
; Shared memory is CPU-owned on return.
; --------------------------------------------------------------------
h264_output_test:
        movem.l d2-d7/a2-a3,-(sp)

        clr.l   v5_wait_stage
        clr.l   v5_wait_timeout_stage
        clr.l   v5_wait_pending
        clr.l   v5_wait_switch
        clr.l   v5_wait_active
        clr.l   v5_wait_display
        clr.l   v5_wait_vblank
        clr.l   v5_wait_raster
        clr.l   bulk_done_seen
        clr.l   eos_sent
        clr.l   eos_pending
        clr.l   eos_bulk_done
        clr.l   eos_return_seen
        clr.l   buffer_seen
        clr.l   event_seen
        clr.l   output_event_seen
        clr.l   v10h_error_seen
        clr.l   v10h_error_status
        clr.l   v10h_last_frame_no
        clr.l   v10h_last_frame_payload
        clr.l   v10h_last_pts_ticks
        clr.l   v10h_last_nal_count
        clr.l   v10h_last_fragment_no
        clr.l   v10h_last_chunk_len
        clr.l   v10h_last_chunk_flags
        clr.l   v10h_last_nal_type
        clr.l   v10h_current_frame_payload
        clr.l   v10h_chunk_fragment_no
        clr.l   output_buffer_seen
        clr.l   output_bulk_queued
        clr.l   output_bulk_done
        clr.l   output_dma_active
        lea     output_dma_active_slots,a0
        moveq   #0,d0
        moveq   #OUTPUT_POOL_MAX-1,d1
v10j_clear_output_dma_slots:
        move.l  d0,(a0)+
        dbra    d1,v10j_clear_output_dma_slots
        clr.l   output_current_idx
        clr.l   output_header_idx
        clr.l   output_empty_idx
        clr.l   output_deferred_count
        clr.l   output_deferred_head
        clr.l   output_deferred_tail
        clr.l   output_eos_seen
        clr.l   output_current_eos
        clr.l   output_pagelist_dma_active
        clr.l   bulk_dma_active
        clr.l   input_return_total
        clr.l   input_bulk_total
        clr.l   input_bulk_pending
        clr.l   input_in_use_count
        clr.l   input_eof_seen
        clr.l   bulk_current_slot
        clr.l   bulk_current_context
        clr.l   output_frame_total
        clr.l   t8c_display_frame_total
        clr.l   t8c_skipped_frames
        clr.l   t8c_late_skipped_frames
        lea     input_slot_state,a0
        moveq   #0,d0
        moveq   #INPUT_POOL_COUNT-1,d1
h31e_clear_input_states:
        move.l  d0,(a0)+
        dbra    d1,h31e_clear_input_states
        move.l  #1,frame_cycle
        move.l  #30,bulk_grace
        clr.l   hdmi_v40o_drain_done
        clr.l   output_alloc_size_saved

        ; HDMI_v41L mode 3 is a pure VideoCore tunnel. No host output pool exists.
        cmpi.l  #3,v41_display_style
        beq.w   v41b_renderer_input_start

        ; Modes 1/2 keep the proven ISP output host-facing.
        lea     msg19_prepare_output,a1
        move.l  #msg19_prepare_output_end-msg19_prepare_output,d3
        bsr     print

        ; ------------------------------------------------------------
        ; V10P: allocate the ACTUAL host I420 output pool requested from MMAL.
        ; V10I proved that merely declaring buffer_num=19 is not enough for
        ; 1.mkv: VideoCore still returned ENOSPC while only two host headers
        ; were offered.  Here each requested buffer gets its own page-aligned
        ; max-size slot. One serialized BULK_RX pagelist remains shared.
        ; ------------------------------------------------------------
        move.l  output_buf_size_saved,d0
        tst.l   d0
        beq.w   h19_bad_local
        cmp.l   #OUTPUT_MAX_DMA,d0
        bhi.w   h19_bad_local

        move.l  v10j_output_req_count,d2
        cmpi.l  #2,d2
        bcs.w   h19_bad_local
        cmpi.l  #OUTPUT_POOL_MAX,d2
        bhi.w   h19_bad_local

        ; pagelist offset = requested_count * OUTPUT_SLOT_STRIDE.
        moveq   #0,d0
        move.l  d2,d3
v10j_output_size_loop:
        add.l   #OUTPUT_SLOT_STRIDE,d0
        subq.l  #1,d3
        bne.s   v10j_output_size_loop
        move.l  d0,output_pagelist_offset_saved
        add.l   #OUTPUT_ALLOC_EXTRA,d0
        move.l  d0,output_alloc_size_saved

        move.l  a4,a6
        move.l  output_alloc_size_saved,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   h19_output_alloc_fail
        move.l  d0,output_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,output_data_ptr0
        move.l  d0,output_data_ptr

        move.l  d0,d1
        add.l   #OUTPUT_SLOT_STRIDE,d1
        move.l  d1,output_data_ptr1

        move.l  d0,d1
        add.l   output_pagelist_offset_saved,d1
        move.l  d1,output_pagelist_ptr

        cmp.l   #$3f000000,d0
        bcc.w   h19_output_map_fail
        cmp.l   #$3f000000,d1
        bcc.w   h19_output_map_fail

        move.l  output_data_ptr,d0
        or.l    #$c0000000,d0
        move.l  d0,output_data_bus
        move.l  output_pagelist_ptr,d0
        or.l    #$c0000000,d0
        move.l  d0,output_pagelist_bus

        ; TEST61: two page-aligned I420 output buffers are offered at once.
        ; VideoCore can decode into one while Emu68 converts the other.
        ; A single shared pagelist is sufficient because host BULK_RX itself
        ; remains serialized; only decoded-buffer ownership is double buffered.

        lea     msg19_output_cpu,a1
        move.l  #msg19_output_cpu_end-msg19_output_cpu,d3
        bsr     print
        move.l  output_data_ptr0,d0
        bsr     print_hex32
        bsr     newline

        lea     msg61_output_cpu1,a1
        move.l  #msg61_output_cpu1_end-msg61_output_cpu1,d3
        bsr     print
        move.l  output_data_ptr1,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_output_bus,a1
        move.l  #msg19_output_bus_end-msg19_output_bus,d3
        bsr     print
        move.l  output_data_ptr0,d0
        or.l    #$c0000000,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_output_size,a1
        move.l  #msg19_output_size_end-msg19_output_size,d3
        bsr     print
        move.l  output_buf_size_saved,d0
        bsr     print_hex32
        bsr     newline
        lea     msg_v10j_pool_info,a1
        move.l  #msg_v10j_pool_info_end-msg_v10j_pool_info,d3
        bsr     print
        move.l  v10j_output_req_count,d0
        bsr     print_hex32
        lea     msg_v10j_pool_info_mid,a1
        move.l  #msg_v10j_pool_info_mid_end-msg_v10j_pool_info_mid,d3
        bsr     print
        move.l  output_alloc_size_saved,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_queue_output,a1
        move.l  #msg19_queue_output_end-msg19_queue_output,d3
        bsr     print

        moveq   #0,d6
v10j_queue_initial_outputs:
        move.l  d6,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h19_bad_reply
        addq.l  #1,d6
        cmp.l   v10j_output_req_count,d6
        bcs.s   v10j_queue_initial_outputs

        lea     msg61_output_queued,a1
        move.l  #msg61_output_queued_end-msg61_output_queued,d3
        bsr     print
        ; V41D: normal ISP/P96 modes must skip the mode-3 input-only label.
        ; V41B accidentally fell through here and cleared the valid host output
        ; handles immediately after queueing them.
        bra.w   v41b_common_input_pool

v41b_renderer_input_start:
        clr.l   output_alloc
        clr.l   output_alloc_size_saved
        clr.l   output_data_ptr
        clr.l   output_data_ptr0
        clr.l   output_data_ptr1
        clr.l   output_port_handle
        clr.l   output_component_handle
        clr.l   v10j_output_req_count
        lea     msg_v41b_renderer_input_only,a1
        move.l  #msg_v41b_renderer_input_only_end-msg_v41b_renderer_input_only,d3
        bsr     print
        bra.s   v41b_common_input_pool

hdmi_v40o_input_only_start:
        lea     msg_hdmi_v40o_input_only,a1
        move.l  #msg_hdmi_v40o_input_only_end-msg_hdmi_v40o_input_only,d3
        bsr     print
v41b_common_input_pool:

        ; ------------------------------------------------------------
        ; TEST33 INPUT POOL
        ; Allocate 1 reusable 64-KiB MMAL input buffer plus one EOS slot.
        ; The data slot owns 20 data pages, one pagelist page and one guard page.
        ; Only one VCHIQ BULK_TX is outstanding at a time, but previously
        ; transferred MMAL buffers may remain owned by VideoCore while the
        ; next free pool slot is filled and sent.
        ; ------------------------------------------------------------
        lea     msg19_prepare_input,a1
        move.l  #msg19_prepare_input_end-msg19_prepare_input,d3
        bsr     print

        move.l  a4,a6
        move.l  #BULK_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   h19_bulk_alloc_fail
        move.l  d0,bulk_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,bulk_pool_base

        ; Entire single-slot pool must remain in the Pi3/Emu68 DMA window.
        move.l  d0,d1
        add.l   #$00083fff,d1
        cmp.l   #$3f000000,d0
        bcc.w   h19_bulk_map_fail
        cmp.l   #$3f000000,d1
        bcc.w   h19_bulk_map_fail

        ; Feed the first block through slot 0.  Further blocks are queued
        ; automatically as BULK_TX_DONE / BUFFER_TO_HOST callbacks arrive.
        bsr     t31s_feed_next_input
        tst.l   d0
        bne.w   h22_resend_fail

        lea     msg19_wait,a1
        move.l  #msg19_wait_end-msg19_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

; ------------------------------------------------------------
; Collect input BULK_TX_DONE, output event/buffer, and if required
; output BULK_RX_DONE.
; ------------------------------------------------------------
h19_poll:
        bsr     short_delay
        bsr     dma_post_all

        ; V14: Ctrl-C belongs only to this CLI process.  On first detection,
        ; stop presenting RGB immediately, but keep the MMAL/VCHIQ engine alive
        ; long enough to send EOS, drain ownership and use the proven cleanup.
        bsr     v15_poll_ctrl_c
        tst.l   d0
        beq.s   h19_check
        move.l  #1,input_eof_seen
        bsr     t31s_display_abort_cleanup

h19_check:
        ; V40: service the bounded two-phase live ISP-output resize here.
        ; dma_post_all has already completed before this point, so CPU-side
        ; VCHIQ state is safe to inspect and, once fully quiescent, to use for
        ; synchronous PORT_ACTION/PORT_INFO_SET.
        jsr     v40_resize_service
        ; V40B: after a successful live ISP-output switch the resize state is
        ; already idle again, but no decoder callback can arrive until a fresh
        ; H264 input block is submitted. Explicitly re-enter the proven feeder
        ; once instead of falling into the generic no-message timeout.
        tst.l   v40_resume_feed_pending
        beq.s   h19_check_after_resize_resume
        clr.l   v40_resume_feed_pending
        bra.w   h25_check_input_recycle
h19_check_after_resize_resume:

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bls.w   h19_no_msg

        ; TEST26C: map absolute RX stream position through MASTER slot_queue.
        ; Low 12 bits are offset within the selected 4-KiB slot.
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.w   h19_bad_reply

        ; TEST26C: h26a_map_rx_current returns the mapped record in A2.
        ; load_le32 reads from A0, so explicitly select the returned header.
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,bulk_rx_size

        jmp     v9g_h19_dispatch
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop

h19_input_bulk_done:
        move.l  bulk_rx_size,d0
        cmp.l   #4,d0
        bcs.w   h19_bad_reply
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,bulk_actual

        ; BerryMP314: audio and video share one MMAL/VCHIQ service. BULK_TX itself
        ; is globally serialized; this flag therefore identifies the current
        ; transport completion without guessing from payload length.
        tst.l   vpv39_audio_bulk_pending
        bne.w   h39_audio_bulk_done

        ; TEST33: after EOS has been published, every further BULK_TX_DONE
        ; belongs to the official 8-byte EOS dummy.  Normal stream bulks are
        ; serialized: only one is outstanding, while up to 20 MMAL buffers
        ; may remain VideoCore-owned.
        move.l  eos_sent,d1
        tst.l   d1
        bne.w   h19a_eos_bulk_done_msg

        move.l  input_bulk_pending,d1
        tst.l   d1
        beq.w   h19_bad_reply
        cmp.l   current_h264_bulk_len,d0
        bne.w   h19_bad_bulk_actual

        clr.l   input_bulk_pending
        move.l  #1,bulk_done_seen
        addq.l  #1,input_bulk_total

        move.l  bulk_dma_active,d0
        tst.l   d0
        beq.w   h19a_after_h264_dma_post
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   bulk_dma_active

h19a_after_h264_dma_post:
        ; The DMA transfer is complete, but this pool slot remains busy until
        ; its unique MMAL BUFFER_TO_HOST context returns.  h19_consume may now
        ; feed another free slot immediately.
        bra.w   h19_consume

h39_audio_bulk_done:
        ; BerryMP314: BULK_TX is still globally serialized, but the renderer can
        ; retain slot0 while slot1 is transferred/queued. Validate against the
        ; exact transport slot and mark only its bulk half complete.
        move.l  vpv47_tx_slot,d1
        cmpi.l  #VPV47_AUDIO_SLOTS,d1
        bcc.w   h19_bad_reply
        move.l  d1,d2
        lsl.l   #2,d2
        lea     vpv47_slot_len,a0
        adda.l  d2,a0
        cmp.l   (a0),d0
        bne.w   h19_bad_reply
        lea     vpv47_slot_bulk_done,a0
        adda.l  d2,a0
        move.l  #1,(a0)
        clr.l   vpv39_audio_bulk_pending
        bra.w   h19_consume

h19a_eos_bulk_done_msg:
        ; After H264, the next BULK_TX_DONE must be the 8-byte dummy
        ; associated with MMAL_WORKER_BUFFER_FROM_HOST_ZEROLEN.
        move.l  eos_sent,d1
        tst.l   d1
        beq.w   h19_bad_reply
        move.l  eos_bulk_done,d1
        tst.l   d1
        bne.w   h19_bad_reply
        cmp.l   #EOS_BULK_LEN,d0
        bne.w   h19a_bad_eos_actual

        move.l  #1,eos_bulk_done

        move.l  bulk_dma_active,d0
        tst.l   d0
        beq.w   h19a_after_eos_dma_post
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   bulk_dma_active

h19a_after_eos_dma_post:
        lea     msg19a_eos_done,a1
        move.l  #msg19a_eos_done_end-msg19a_eos_done,d3
        bsr     print
        bra.w   h19_consume

; ------------------------------------------------------------
; Send the official MMAL >=12.2 zero-length EOS sequence:
;   Worker 24, buffer length=0, flags=EOS
;   immediately followed by an 8-byte dummy VCHIQ BULK_TX.
; Shared VCHIQ memory is CPU-owned on entry.
; ------------------------------------------------------------
h19a_send_eos:
        lea     msg19a_eos_send,a1
        move.l  #msg19a_eos_send_end-msg19a_eos_send,d3
        bsr     print

        ; Use a dedicated 21st pool slot for EOS. Normal input slots may
        ; still be VideoCore-owned here, so reusing the last normal slot would
        ; be unsafe and could recreate the TEST31D end-of-stream deadlock.
        move.l  bulk_pool_base,d0
        add.l   #INPUT_SLOT_STRIDE,d0  ; EOS slot directly after the single data slot
        move.l  d0,bulk_data_ptr
        move.l  d0,d1
        add.l   #INPUT_PAGELIST_OFFSET,d1
        move.l  d1,bulk_pagelist_ptr

        move.l  d0,d2
        or.l    #$c0000000,d2
        move.l  d2,bulk_data_bus
        move.l  d1,d2
        or.l    #$c0000000,d2
        move.l  d2,bulk_pagelist_bus

        ; Dummy payload bytes are irrelevant, but keep them deterministic.
        move.l  bulk_data_ptr,a0
        clr.l   (a0)
        clr.l   4(a0)

        ; Build the dedicated one-page write pagelist for 8 dummy bytes.
        move.l  bulk_pagelist_ptr,a0
        move.l  #EOS_BULK_LEN,d0
        bsr     store_le32
        move.l  bulk_pagelist_ptr,a0
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        lea     8(a0),a0
        move.l  bulk_data_bus,d0
        bsr     store_le32

        ; Enter DMA ownership for the dedicated EOS data + pagelist pages.
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,bulk_phys
        cmp.l   bulk_data_ptr,d0
        bne.w   h19_bulk_dma_fail
        move.l  bulk_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   h19_bulk_dma_fail
        move.l  #1,bulk_dma_active

        ; Host slot 34 + current tx position. 304-byte Worker + 16 bulk.
        move.l  #320,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   h19_bad_reply

        move.l  a2,a0
        move.l  #79,d7
h19a_clear_eos_control:
        clr.l   (a0)+
        dbra    d7,h19a_clear_eos_control

        ; Worker 24 as normal VCHIQ DATA message.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST_ZEROLEN,d0
        bsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  #MMAL_EOS_BUFFER_CONTEXT,d0
        bsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; drvbuf -> decoder input.
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  component_handle,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  input_port_handle,d0
        bsr     store_le32
        lea     44(a2),a0
        move.l  #MMAL_EOS_BUFFER_CONTEXT,d0
        bsr     store_le32

        ; buffer_header.data valid, alloc size valid, length=0, EOS=1.
        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  input_before_buf_size,d0
        bsr     store_le32
        ; length @84 = 0, offset @88 = 0
        lea     92(a2),a0
        move.l  #MMAL_BUFFER_FLAG_EOS,d0
        bsr     store_le32

        ; pts/dts unknown.
        lea     96(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32

        ; payload_in_message remains zero.

        ; Dummy BULK_TX immediately follows Worker 24.
        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        bsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        bsr     store_le32
        lea     12(a3),a0
        move.l  #EOS_BULK_LEN,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #320,d0
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,eos_armed

        move.l  #1,eos_sent

        ; Give VideoCore shared VCHIQ memory back, then ring if armed.
        bsr     dma_pre_all
        move.l  eos_armed,d0
        tst.l   d0
        beq.w   h19a_no_eos_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
h19a_no_eos_bell:
        ; Fresh full observation window after the EOS marker.
        move.l  #POLL_COUNT,d7
        bra.w   h19_poll

h19_output_bulk_done_msg:
        move.l  bulk_rx_size,d0
        cmp.l   #4,d0
        bcs.w   h19_bad_reply
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,output_bulk_actual


        move.l  output_bulk_actual,d0
        cmp.l   output_bulk_len,d0
        bne.w   h19_bad_output_actual

        ; End pagelist DMA phase (VC read it).
        move.l  output_pagelist_dma_active,d0
        tst.l   d0
        beq.w   h19_post_output_data
        move.l  #12,output_pagelist_dma_len
        move.l  output_pagelist_ptr,a0
        lea     output_pagelist_dma_len,a1
        move.l  #DMA_ReadFromRAM,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   output_pagelist_dma_active

h19_post_output_data:
        ; VideoCore wrote the current I420 slot. Return only that slot to CPU.
        move.l  output_current_idx,d0
        bsr     h61_post_output_dma_idx
        tst.l   d0
        bne.w   h19_bad_reply

h19_after_output_post:
        move.l  #1,output_bulk_done

        ; TEST33: only validate the returned I420 frame size here.
        ; The old full Y/U/V byte-sum diagnostics scanned another 115200 bytes
        ; per frame and were useful while proving decoder correctness, but they
        ; are deliberately removed from the live 25-fps path.
        move.l  output_bulk_actual,d0
        cmp.l   output_frame_bytes_expected,d0
        bne.w   h22_bad_frame_size

        ; TEST33 STREAMING:
        ; The current I420 frame is not stored in a movie-sized Fast-RAM array.
        ; Convert selected pictures immediately into the inactive Chip-RAM buffer.
        ; V9 keeps native timing below 25 fps; higher source rates are decoded
        ; completely but rationally reduced to max. 25 fps for RGB/HAM6.
        ; The MMAL output buffer is recycled afterwards,
        ; providing natural back-pressure so decoding cannot run away from video.
        ; H264RGB2: there is no fixed output-frame ceiling. Every complete
        ; I420 payload is accepted until the decoder returns OUTPUT EOS.

        ; TEST33 RGB streaming: convert this I420 frame immediately into
        ; the inactive Chip-RAM display buffer and schedule it from the real
        ; VERTB timebase.  The MMAL output buffer is recycled only afterwards,
        ; so the whole pipeline remains bounded-memory and naturally back-pressured.
        ; V14: after Ctrl-C, keep draining/recycling decoder output but never
        ; restart or update the RGB display that was just restored.
        move.l  v15_stop_requested,d0
        tst.l   d0
        bne.w   h8c_rgb_frame_done

        ; V9 RGB policy for sources above 25 fps:
        ; MMAL still returns and we still count/recycle EVERY decoded picture.
        ; A rational source-frame selector reduces only the classic RGB/HAM6
        ; path to at most 25 pictures/s.  50 fps becomes 1/2, 30 fps becomes
        ; 5/6, 30000/1001 is handled by the same accumulator.
        move.l  t8c_cap25_mode,d0
        tst.l   d0
        beq.s   h8c_selected_rgb_candidate
        move.l  t8c_select_accum,d0
        add.l   t8c_select_step,d0
        cmp.l   v7_fps_num,d0
        bcs.s   h8c_rate_skip_rgb_frame
        sub.l   v7_fps_num,d0
        move.l  d0,t8c_select_accum
        bra.s   h8c_selected_rgb_candidate
h8c_rate_skip_rgb_frame:
        move.l  d0,t8c_select_accum
        addq.l  #1,t8c_skipped_frames
        bra.w   h8c_rgb_frame_done

        ; V8B let lateness move the future timeline and stretched the movie.
        ; V9 keeps an absolute 25-fps grid.  If a selected RGB candidate
        ; reaches us at or after its nominal target, do not spend more time
        ; converting an image whose 40-ms display slot has already started.
        ; Skip it only for RGB and advance the nominal grid by one 40-ms slot.
h8c_selected_rgb_candidate:
        move.l  t8c_cap25_mode,d0
        tst.l   d0
        beq.s   h8c_stream_rgb_frame
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.s   h8c_stream_rgb_frame
        move.l  t31s_next_switch_vblank,d1
        tst.l   d1
        beq.s   h8c_stream_rgb_frame
        move.l  t31s_vblank_counter,d0
        sub.l   d0,d1                     ; d1 = nominal headroom
        tst.l   d1
        bgt.s   h8c_stream_rgb_frame       ; still at least one full VBlank before target
        addq.l  #1,t8c_late_skipped_frames
        addq.l  #2,t31s_next_switch_vblank
        bra.s   h8c_rgb_frame_done

h8c_stream_rgb_frame:
        tst.l   v32r_fastforward
        beq.s   v32r_display_frame_now
        move.l  output_frame_total,d0
        cmp.l   v32r_resume_target,d0
        bcs.w   h8c_rgb_frame_done

        ; Exact decoder-frame catch-up point reached.  The next visible frame
        ; starts a fresh real-time clock; no old pre-roll deadline is reused.
        clr.l   v32r_fastforward
        move.l  #1,v32r_resume_reached
        clr.l   v04_clock_started
        clr.l   v04_clock_accum
        clr.l   v04_clock_target
        clr.l   v04_clock_counter
        clr.l   v04_last_raster

v32r_display_frame_now:
        bsr     t31s_stream_current_frame
        tst.l   d0
        bne.w   h30_store_fail
        addq.l  #1,t8c_display_frame_total
h8c_rgb_frame_done:
        move.l  output_current_idx,d0
        tst.l   d0
        bne.s   h61_count_slot1
        addq.l  #1,t61_slot0_frames
        bra.s   h61_count_slot_done
h61_count_slot1:
        addq.l  #1,t61_slot1_frames
h61_count_slot_done:
        addq.l  #1,output_frame_total

        ; TEST33: absolutely no DOS/console output in the frame-critical
        ; streaming section.  All useful counters remain in memory and are
        ; printed only after success/failure.
        bra.w   h19_consume

h30_store_fail:
        jsr     v40c_report_blit_failure
        lea     e30_store_frame,a1
        move.l  #e30_store_frame_end-e30_store_frame,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        beq.s   h30_store_fail_no_v5
        bsr     v5_print_wait_timeout
h30_store_fail_no_v5:
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

; --------------------------------------------------------------------
; TEST33 - true bounded-memory streaming presentation
;
 ; Current VideoCore I420 output stays in output_data_ptr. Y, U and V are source data.
; A dedicated 20736-byte Fast-RAM color-planar scratch frame is then copied
; into one of the two 20736-byte Chip-RAM display buffers.
; No decoded movie frames are retained after presentation.
;
; Timing:
;   frame 1: start at T0, reload at T1 for its second PAL refresh
;   frame 2: switch at T2, reload at T3
;   frame 3: switch at T4, reload at T5 ...
; This gives 25 video frames/s on a 50 Hz PAL display. The decoder output buffer
; is not recycled until the second refresh has started, which deliberately
; back-pressures MMAL instead of accumulating decoded frames in RAM.
; --------------------------------------------------------------------
; HDMI_v41L: locate the current VideoCore.card/P96 framebuffer from the
; active HVS Workbench plane. VideoCore.card writes 0xC0000000|addr into its
; pointer word, so masking the bus alias restores the normal Amiga CPU address.
; Supports the current scaled 16-word plane and the driver's 7-word unity plane.
hdmi_v40o_capture_wb_fb:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   hdmi_v40o_wb_valid
        clr.l   hdmi_v40o_rtg_frames

        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d6                    ; DWORD list offset
        move.l  #HDMI_V14_HVS_DLIST_BASE,a2
        move.l  d6,d1
        lsl.l   #2,d1
        adda.l  d1,a2

        move.l  a2,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_wb_control
        move.l  d0,d1
        and.l   #$0000000f,d1
        cmpi.l  #7,d1                    ; HVS_PIXEL_FORMAT_RGBA8888
        bne.w   hdmi_v40o_wb_capture_fail

        move.l  d0,d1
        lsr.l   #8,d1
        lsr.l   #8,d1
        lsr.l   #8,d1
        and.l   #$0000003f,d1            ; CONTROL_WORDS
        cmpi.l  #16,d1
        beq.s   hdmi_v40o_wb_scaled
        cmpi.l  #7,d1
        beq.s   hdmi_v40o_wb_unity
        bra.w   hdmi_v40o_wb_capture_fail

hdmi_v40o_wb_scaled:
        lea     12(a2),a0                ; POS2 source size
        jsr     load_le32
        move.l  d0,d2
        and.l   #$00000fff,d2
        move.l  d2,hdmi_v40o_wb_width
        move.l  d0,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        and.l   #$00000fff,d2
        move.l  d2,hdmi_v40o_wb_height
        lea     20(a2),a0                ; framebuffer bus pointer
        jsr     load_le32
        move.l  d0,d3
        lea     28(a2),a0                ; pitch
        jsr     load_le32
        move.l  d0,d4
        bra.s   hdmi_v40o_wb_fields

hdmi_v40o_wb_unity:
        lea     8(a2),a0                 ; POS2 source size
        jsr     load_le32
        move.l  d0,d2
        and.l   #$00000fff,d2
        move.l  d2,hdmi_v40o_wb_width
        move.l  d0,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        and.l   #$00000fff,d2
        move.l  d2,hdmi_v40o_wb_height
        lea     16(a2),a0                ; framebuffer bus pointer
        jsr     load_le32
        move.l  d0,d3
        lea     24(a2),a0                ; pitch
        jsr     load_le32
        move.l  d0,d4

hdmi_v40o_wb_fields:
        and.l   #$3fffffff,d3
        tst.l   d3
        beq.w   hdmi_v40o_wb_capture_fail
        cmp.l   #$1c000000,d3
        bcc.w   hdmi_v40o_wb_capture_fail
        cmpi.l  #$00000400,d4
        bcs.w   hdmi_v40o_wb_capture_fail
        move.l  hdmi_v40o_wb_width,d0
        cmpi.l  #292,d0                  ; x100 + max 192
        bcs.w   hdmi_v40o_wb_capture_fail
        move.l  hdmi_v40o_wb_height,d0
        cmpi.l  #224,d0                  ; y80 + max 144
        bcs.w   hdmi_v40o_wb_capture_fail
        move.l  d3,hdmi_v40o_wb_fb_cpu
        move.l  d4,hdmi_v40o_wb_pitch
        move.l  #1,hdmi_v40o_wb_valid

        lea     msg_hdmi_v40o_wb_fb,a1
        move.l  #msg_hdmi_v40o_wb_fb_end-msg_hdmi_v40o_wb_fb,d3
        jsr     print
        move.l  hdmi_v40o_wb_fb_cpu,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_wb_pitch,a1
        move.l  #msg_hdmi_v40o_wb_pitch_end-msg_hdmi_v40o_wb_pitch,d3
        jsr     print
        move.l  hdmi_v40o_wb_pitch,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_wb_size,a1
        move.l  #msg_hdmi_v40o_wb_size_end-msg_hdmi_v40o_wb_size,d3
        jsr     print
        move.l  hdmi_v40o_wb_width,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  hdmi_v40o_wb_height,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   hdmi_v40o_wb_capture_done

hdmi_v40o_wb_capture_fail:
        lea     msg_hdmi_v40o_wb_fail,a1
        move.l  #msg_hdmi_v40o_wb_fail_end-msg_hdmi_v40o_wb_fail,d3
        jsr     print
        moveq   #1,d0
hdmi_v40o_wb_capture_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; --------------------------------------------------------------------
; HDMI_v41L - real Intuition Window integration.
; The window itself is owned/drawn by AmigaOS. Video pixels still use the
; hardware-proven renderer-free ISP -> P96 path; only the destination follows
; the Window client rectangle. v32 removes free resize and uses two fixed ISP presets.
; Keys 1/2 request a full ISP teardown/rebuild while the H264 decoder stays alive.
; --------------------------------------------------------------------
hdmi_v40o_open_window:
        movem.l d1-d7/a0-a2/a6,-(sp)
        move.l  hdmi_v40o_window_ptr,d0
        tst.l   d0
        bne.w   hdmi_v40o_open_window_ok

        move.l  hdmi_v40o_intuition_base,d0
        tst.l   d0
        bne.s   hdmi_v40o_have_intuition
        move.l  a4,a6
        lea     hdmi_v40o_intuition_name,a1
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        beq.w   hdmi_v40o_open_window_fail
        move.l  d0,hdmi_v40o_intuition_base
hdmi_v40o_have_intuition:
        ; v23: use Picasso96API.library for the final window blit.  Unlike the
        ; direct framebuffer write in v22, p96WritePixelArray targets the
        ; Window RastPort and therefore goes through the window/layer clipping.
        move.l  hdmi_v40o_p96_base,d0
        tst.l   d0
        bne.s   hdmi_v40o_have_p96
        move.l  a4,a6
        lea     hdmi_v40o_p96_name,a1
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        beq.w   hdmi_v40o_open_window_fail
        move.l  d0,hdmi_v40o_p96_base
hdmi_v40o_have_p96:
        jsr     v41_patch_newwindow_style
        move.l  hdmi_v40o_intuition_base,a6
        lea     hdmi_v40o_newwindow,a0
        jsr     IntuiOpenWindow(a6)
        tst.l   d0
        beq.w   hdmi_v40o_open_window_fail
        move.l  d0,hdmi_v40o_window_ptr
        clr.l   hdmi_v40o_close_seen
        clr.l   hdmi_v40o_resize_events
        clr.l   hdmi_v40o_resize_reported
        clr.l   v32_resize_pending
        clr.l   v32_resize_pending_w
        clr.l   v32_resize_pending_h
        clr.l   v32_resize_pending_aw
        clr.l   v32_resize_pending_ah
        clr.l   v32_resize_last_w
        clr.l   v32_resize_last_h
        clr.l   v32_resize_stable
        clr.l   v32_resize_applied
        clr.l   v32_resize_fail
        clr.l   v32_resize_held
        clr.l   v32_pending_mode
        clr.l   v32_switch_requests
        clr.l   v32_last_imsg_class
        clr.l   v32_last_imsg_code

        lea     msg_hdmi_v40o_window_ok,a1
        move.l  #msg_hdmi_v40o_window_ok_end-msg_hdmi_v40o_window_ok,d3
        jsr     print
        move.l  hdmi_v40o_window_ptr,a0
        clr.l   d0
        move.w  WIN_LeftEdge(a0),d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_window_xy,a1
        move.l  #msg_hdmi_v40o_window_xy_end-msg_hdmi_v40o_window_xy,d3
        jsr     print
        clr.l   d0
        move.w  WIN_TopEdge(a0),d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_window_wh,a1
        move.l  #msg_hdmi_v40o_window_wh_end-msg_hdmi_v40o_window_wh,d3
        jsr     print
        clr.l   d0
        move.w  WIN_Width(a0),d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        clr.l   d0
        move.w  WIN_Height(a0),d0
        jsr     print_hex32
        jsr     newline

hdmi_v40o_open_window_ok:
        moveq   #0,d0
        bra.s   hdmi_v40o_open_window_done
hdmi_v40o_open_window_fail:
        lea     msg_hdmi_v40o_window_fail,a1
        move.l  #msg_hdmi_v40o_window_fail_end-msg_hdmi_v40o_window_fail,d3
        jsr     print
        moveq   #1,d0
hdmi_v40o_open_window_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; --------------------------------------------------------------------
; V40 pre-start fixed-size selector.
; The Intuition window already exists, but decoder OUTPUT is still normal
; I420 and ril.isp has NOT been created yet.  Wait for key 1 or 2, compute
; the final aspect-correct ISP target, then return.  No MMAL graph changes
; are made here. D0=0 selected, D0=1 close/Ctrl-C/error.
; --------------------------------------------------------------------
v32_wait_initial_mode:
        movem.l d1-d7/a0-a2/a6,-(sp)

        ; V40K: fresh playback uses the CLI-selected fixed size.
        ; A fullscreen request never live-reconfigures the ISP: after clean EOS
        ; the existing restart/resume path rebuilds MMAL/ISP at gfull and seeks
        ; back to the completed output-frame position.
        tst.l   v32r_restart_cycle
        bne.s   v40k_restart_resume
        jmp     v40j_initial_cli_selector
v40k_restart_resume:

        ; V40 restart/resume: after a size key during playback the previous
        ; run has been fully torn down.  Read the small T: state BEFORE the new
        ; ISP is created, then use the exact same safe fixed-size setup as V31.
        tst.l   v32r_restart_cycle
        beq.w   v32r_manual_selector
        jsr     v32r_load_state
        tst.l   d0
        bne.w   v32r_state_bad
        clr.l   v32r_restart_cycle
        move.l  v32r_state_mode,d7
        move.l  v32r_state_frame,d0
        move.l  d0,v32r_resume_target
        clr.l   v32r_resume_reached
        clr.l   v32r_fastforward
        tst.l   d0
        beq.s   v32r_state_no_ff
        move.l  #1,v32r_fastforward
v32r_state_no_ff:
        lea     msg_v32r_state_loaded,a1
        move.l  #msg_v32r_state_loaded_end-msg_v32r_state_loaded,d3
        jsr     print
        move.l  d7,d0
        jsr     print_hex32
        lea     msg_v32r_state_frame,a1
        move.l  #msg_v32r_state_frame_end-msg_v32r_state_frame,d3
        jsr     print
        move.l  v32r_resume_target,d0
        jsr     print_hex32
        jsr     newline
        jsr     v32r_delete_state
        move.l  d7,d0
        jsr     v41_prepare_restart_style
        tst.l   d0
        bne.w   v32_wait_mode_abort
        bra.w   v32_wait_mode_selected

v32r_state_bad:
        clr.l   v32r_restart_cycle
        clr.l   v32r_fastforward
        clr.l   v32r_resume_target
        jsr     v32r_delete_state
        lea     msg_v32r_state_bad,a1
        move.l  #msg_v32r_state_bad_end-msg_v32r_state_bad,d3
        jsr     print

v32r_manual_selector:
        clr.l   v32r_fastforward
        clr.l   v32r_resume_target
        clr.l   v32r_resume_reached
        lea     msg_v32_choose_size,a1
        move.l  #msg_v32_choose_size_end-msg_v32_choose_size,d3
        jsr     print

v32_wait_mode_loop:
        ; Honor Ctrl-C even before playback begins.
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        and.l   #SIGBREAKF_CTRL_C,d0
        beq.s   v40j_initial_calc_ok
        jmp     v32_wait_mode_abort
v40j_initial_calc_ok:

        move.l  hdmi_v40o_window_ptr,a2
        cmpa.l  #0,a2
        beq.w   v32_wait_mode_abort
        move.l  WIN_UserPort(a2),a0
        cmpa.l  #0,a0
        beq.w   v32_wait_mode_abort

        move.l  a4,a6
        jsr     GetMsg(a6)
        tst.l   d0
        beq.w   v32_wait_mode_idle

        move.l  d0,a1
        move.l  IMSG_Class(a1),d3
        move.l  d3,v32_last_imsg_class
        clr.l   d4
        move.w  IMSG_Code(a1),d4
        move.l  d4,v32_last_imsg_code
        jsr     ReplyMsg(a6)

        move.l  v32_last_imsg_class,d3
        move.l  v32_last_imsg_code,d4
        cmpi.l  #IDCMP_CLOSEWINDOW,d3
        beq.w   v32_wait_mode_abort
        cmpi.l  #IDCMP_VANILLAKEY,d3
        bne.w   v32_wait_mode_loop

        cmpi.w  #$0031,d4
        beq.s   v32_wait_mode_small
        cmpi.w  #$0032,d4
        beq.s   v32_wait_mode_medium
        bra.w   v32_wait_mode_loop

v32_wait_mode_small:
        moveq   #1,d7
        bra.s   v32_wait_mode_selected
v32_wait_mode_medium:
        moveq   #2,d7

v32_wait_mode_selected:
        move.l  d7,d0
        jsr     v40j_calc_mode_dims
        tst.l   d0
        beq.s   v40j_initial_calc_ok2
        jmp     v32_wait_mode_abort
v40j_initial_calc_ok2:
        move.l  d7,v32_fixed_mode
        move.l  v32_calc_w,v12a_target_w
        move.l  v32_calc_h,v12a_target_h
        move.l  v32_calc_aw,v12a_target_aw
        move.l  v32_calc_ah,v12a_target_ah

        lea     msg_v32_size_selected,a1
        move.l  #msg_v32_size_selected_end-msg_v32_size_selected,d3
        jsr     print
        move.l  v32_fixed_mode,d0
        jsr     print_hex32
        lea     msg_v32_size_target,a1
        move.l  #msg_v32_size_target_end-msg_v32_size_target,d3
        jsr     print
        move.l  v12a_target_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_target_h,d0
        jsr     print_hex32
        jsr     newline

        moveq   #0,d0
        bra.s   v32_wait_mode_done

v32_wait_mode_idle:
        ; One DOS tick keeps the pre-start requester effectively idle.
        moveq   #1,d1
        move.l  a5,a6
        jsr     Delay(a6)
        bra.w   v32_wait_mode_loop

v32_wait_mode_abort:
        move.l  #1,v15_stop_requested
        lea     msg_v32_size_abort,a1
        move.l  #msg_v32_size_abort_end-msg_v32_size_abort,d3
        jsr     print
        moveq   #1,d0
v32_wait_mode_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; Poll native Intuition window events during playback.
; V40 accepts fixed size keys during playback; CLOSEWINDOW requests the
; existing controlled EOS path.
hdmi_v40o_poll_window_close:
        movem.l d1-d4/a0-a2/a6,-(sp)
        clr.l   d2
        move.l  hdmi_v40o_window_ptr,a2
        cmpa.l  #0,a2
        beq.w   hdmi_v40o_poll_window_done_events
        move.l  WIN_UserPort(a2),a0
        cmpa.l  #0,a0
        beq.w   hdmi_v40o_poll_window_done_events
        move.l  a4,a6
hdmi_v40o_poll_window_next:
        jsr     GetMsg(a6)
        tst.l   d0
        beq.w   hdmi_v40o_poll_window_done_events
        move.l  d0,a1
        move.l  IMSG_Class(a1),d3
        move.l  d3,v32_last_imsg_class
        clr.l   d4
        move.w  IMSG_Code(a1),d4
        move.l  d4,v32_last_imsg_code
        jsr     ReplyMsg(a6)
        move.l  v32_last_imsg_class,d3
        move.l  v32_last_imsg_code,d4
        cmpi.l  #IDCMP_CLOSEWINDOW,d3
        bne.s   v32f_not_close
        move.l  #1,v15_stop_requested
        moveq   #1,d2
        move.l  hdmi_v40o_close_seen,d0
        tst.l   d0
        bne.w   hdmi_v40o_poll_window_next
        move.l  #1,hdmi_v40o_close_seen
        lea     msg_hdmi_v40o_close,a1
        move.l  #msg_hdmi_v40o_close_end-msg_hdmi_v40o_close,d3
        jsr     print
        bra.w   hdmi_v40o_poll_window_next
v32f_not_close:
        cmpi.l  #IDCMP_VANILLAKEY,d3
        bne.w   hdmi_v40o_poll_window_next
        ; V41 playback controls: exactly ONE mode switch per playback.
        ;   1 = g100 (100% of WB box, capped at source), normal window
        ;   2 = V40R borderless full-area front window
        ;   3 = VideoCore OPQV -> ril.video_render -> HVS fullscreen
        ;   0 = controlled EOS/cleanup, same end path as Ctrl-C.
        cmpi.w  #$0030,d4
        beq.s   v40j_live_key_stop
        ; V41G: Modi 1/2 entfernt; nur direkter VideoCore/HVS-Pfad bleibt.
        cmpi.w  #$0033,d4
        beq.s   v41_live_key_3
        bra.w   hdmi_v40o_poll_window_next
v41_live_key_1:
        move.l  #201,d0
        jsr     v41_request_menu_once
        bra.w   hdmi_v40o_poll_window_next
v41_live_key_2:
        move.l  #202,d0
        jsr     v41_request_menu_once
        bra.w   hdmi_v40o_poll_window_next
v41_live_key_3:
        move.l  #203,d0
        jsr     v41_request_menu_once
        bra.w   hdmi_v40o_poll_window_next
v40j_live_key_stop:
        move.l  #1,v15_stop_requested
        move.l  #1,input_eof_seen
        moveq   #1,d2
        lea     msg_v40j_key0_stop,a1
        move.l  #msg_v40j_key0_stop_end-msg_v40j_key0_stop,d3
        jsr     print
        bra.w   hdmi_v40o_poll_window_next
hdmi_v40o_poll_window_done_events:
        move.l  d2,d0
        movem.l (sp)+,d1-d4/a0-a2/a6
        rts

hdmi_v40o_close_window:
        movem.l a0-a1/a6,-(sp)
        move.l  hdmi_v40o_window_ptr,a0
        cmpa.l  #0,a0
        beq.s   hdmi_v40o_close_window_no_window
        move.l  hdmi_v40o_intuition_base,a6
        cmpa.l  #0,a6
        beq.s   hdmi_v40o_close_window_no_window
        jsr     IntuiCloseWindow(a6)
        clr.l   hdmi_v40o_window_ptr
hdmi_v40o_close_window_no_window:
        move.l  hdmi_v40o_intuition_base,a1
        cmpa.l  #0,a1
        beq.s   hdmi_v40o_close_p96
        move.l  a4,a6
        jsr     CloseLibrary(a6)
        clr.l   hdmi_v40o_intuition_base

hdmi_v40o_close_p96:
        ; v23: release Picasso96API.library independently of Intuition state.
        move.l  hdmi_v40o_p96_base,a1
        cmpa.l  #0,a1
        beq.s   hdmi_v40o_close_window_done
        move.l  a4,a6
        jsr     CloseLibrary(a6)
        clr.l   hdmi_v40o_p96_base
hdmi_v40o_close_window_done:
        movem.l (sp)+,a0-a1/a6
        rts

t31s_stream_current_frame:
        cmpi.l  #3,v41_display_style
        bne.s   v41_blit_via_p96_window
        jsr     v41_direct_fb_blit
        rts
v41_blit_via_p96_window:
        ; HDMI_v41L clipping-safe window path.  The VideoCore ISP returns a
        ; small BGRA8888 frame exactly as in hardware-proven v21/v22.  Instead
        ; of writing the P96 framebuffer directly, hand that linear frame to
        ; Picasso96API.library/p96WritePixelArray() and target Window->RPort.
        ; P96/Intuition can then honor the Window layer ClipRects when another
        ; window overlaps this player.  No HVS display-list register is touched.
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v40c_blit_fail_reason

        move.l  hdmi_v40o_p96_base,a6
        cmpa.l  #0,a6
        bne.s   v40c_blit_p96_ok
        move.l  #1,v40c_blit_fail_reason
        bra.w   hdmi_v40o_rtg_blit_fail
v40c_blit_p96_ok:
        move.l  output_data_ptr,a0
        cmpa.l  #0,a0
        bne.s   v40c_blit_data_ok
        move.l  #2,v40c_blit_fail_reason
        bra.w   hdmi_v40o_rtg_blit_fail
v40c_blit_data_ok:
        move.l  hdmi_v40o_window_ptr,a3
        cmpa.l  #0,a3
        bne.s   v40c_blit_window_ok
        move.l  #3,v40c_blit_fail_reason
        bra.w   hdmi_v40o_rtg_blit_fail
v40c_blit_window_ok:
        move.l  WIN_RPort(a3),a1
        cmpa.l  #0,a1
        bne.s   v40c_blit_rport_ok
        move.l  #4,v40c_blit_fail_reason
        bra.w   hdmi_v40o_rtg_blit_fail
v40c_blit_rport_ok:

        ; v32: fixed ISP preset, no free resize and no CPU scaling.

        ; Source stride = aligned ISP width * 4 bytes.
        move.l  output_width_saved,d4
        lsl.l   #2,d4

        ; Source pointer starts at the visible crop within the aligned BGRA frame.
        move.l  output_crop_x_saved,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        move.l  output_crop_y_saved,d0
        mulu.w  d4,d0
        adda.l  d0,a0

        move.l  output_crop_w_saved,d7
        tst.l   d7
        bne.s   v40c_blit_cropw_ok
        move.l  #5,v40c_blit_fail_reason
        bra.w   hdmi_v40o_rtg_blit_fail
v40c_blit_cropw_ok:
        move.l  output_crop_h_saved,d6
        tst.l   d6
        bne.s   v40c_blit_croph_ok
        move.l  #6,v40c_blit_fail_reason
        bra.w   hdmi_v40o_rtg_blit_fail
v40c_blit_croph_ok:

        ; Destination X is relative to the Window RastPort.  Keep the video
        ; centered inside the client area while respecting the system borders.
        clr.l   d2
        move.w  WIN_Width(a3),d2
        moveq   #0,d0
        move.b  WIN_BorderLeft(a3),d0
        sub.l   d0,d2
        moveq   #0,d1
        move.b  WIN_BorderRight(a3),d1
        sub.l   d1,d2
        cmp.l   d7,d2
        bcc.s   v40c_blit_width_ready
        move.l  #7,v40c_blit_fail_reason
        addq.l  #1,v40c_window_wait_skips
        jsr     v32f_resize_window_fixed
        moveq   #0,d0                    ; transitional frame intentionally not blitted
        bra.w   hdmi_v40o_rtg_blit_done
v40c_blit_width_ready:
        sub.l   d7,d2
        lsr.l   #1,d2
        add.l   d0,d2

        ; Destination Y, likewise relative to Window->RPort.
        clr.l   d3
        move.w  WIN_Height(a3),d3
        moveq   #0,d0
        move.b  WIN_BorderTop(a3),d0
        sub.l   d0,d3
        moveq   #0,d1
        move.b  WIN_BorderBottom(a3),d1
        sub.l   d1,d3
        cmp.l   d6,d3
        bcc.s   v40c_blit_height_ready
        move.l  #8,v40c_blit_fail_reason
        addq.l  #1,v40c_window_wait_skips
        jsr     v32f_resize_window_fixed
        moveq   #0,d0                    ; transitional frame intentionally not blitted
        bra.w   hdmi_v40o_rtg_blit_done
v40c_blit_height_ready:
        sub.l   d6,d3
        lsr.l   #1,d3
        add.l   d0,d3

        ; Build the classic 12-byte P96 RenderInfo for our ISP output.
        lea     hdmi_v40o_renderinfo,a2
        move.l  a0,(a2)                   ; Memory
        move.w  d4,4(a2)                  ; BytesPerRow
        clr.w   6(a2)                     ; pad
        move.l  #RGBFB_B8G8R8A8,8(a2)    ; ISP v21/v22 byte order

        ; p96WritePixelArray(ri,0,0,rp,dstX,dstY,width,height)
        move.l  a2,a0
        moveq   #0,d0                     ; SrcX
        moveq   #0,d1                     ; SrcY
        move.l  d7,d4                     ; SizeX
        move.l  d6,d5                     ; SizeY
        jsr     P96WritePixelArray(a6)

        addq.l  #1,hdmi_v40o_rtg_frames
        moveq   #0,d0
        bra.s   hdmi_v40o_rtg_blit_done
hdmi_v40o_rtg_blit_fail:
        moveq   #1,d0
hdmi_v40o_rtg_blit_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

t31s_stream_schedule:
        move.l  t31s_next_switch_vblank,d6
        move.l  d6,d5                       ; V9: immutable nominal target
        move.l  t31s_vblank_counter,d0

        ; TEST61 deadline/slack profile.  d6 is the absolute desired VBlank,
        ; d0 is the current VBlank after Fast conversion + Chip copy.
        ; Positive d1 = that many complete VBlanks of scheduling headroom.
        move.l  d6,d1
        sub.l   d0,d1
        cmp.l   #1,d1
        beq.w   t31x_slack_one
        cmp.l   #2,d1
        beq.w   t31x_slack_two
        cmp.l   #3,d1
        bge.w   t31x_slack_threeplus
        bra.w   t31x_slack_done
t31x_slack_one:
        addq.l  #1,t31x_slack1
        bra.w   t31x_slack_done
t31x_slack_two:
        addq.l  #1,t31x_slack2
        bra.w   t31x_slack_done
t31x_slack_threeplus:
        addq.l  #1,t31x_slack3plus
t31x_slack_done:
        ; TEST66: remember the current frame's true scheduling headroom.
        ; A 1-refresh catch-up is only safe when this frame arrived at least
        ; two full VBlanks before its target.
        move.l  d1,t66_current_slack

        cmp.l   d6,d0
        bcs.w   t31s_stream_target_ok

        ; TEST66 keeps TEST65's proven raster rescue and debt accounting.  The new part
        ; is below: if a rare miss really needs a later switch, remember the
        ; lost VBlank(s) as timing debt instead of permanently slowing every
        ; following frame.
        beq.w   t65_try_same_vblank
        addq.l  #1,t31x_past_target
        bra.w   t31x_miss_class_done

t65_try_same_vblank:
        lea     CUSTOM_BASE,a0
        moveq   #0,d2
        move.w  VPOSR(a0),d2
        andi.w  #$0001,d2                  ; V8 -> vertical bit 8
        lsl.w   #8,d2
        moveq   #0,d3
        move.w  VHPOSR(a0),d3
        lsr.w   #8,d3                      ; vertical low 8 bits
        or.w    d3,d2                      ; d2 = raster line 0..311
        cmpi.w  #$0052,d2                  ; V9/192x144: stay two lines before PAL VSTART $54
        bcc.w   t65_same_vblank_too_late

        ; Guard against a pathological wrap while the raster registers were
        ; sampled.  We must still be in this exact target VBlank.
        move.l  t31s_vblank_counter,d2
        cmp.l   d6,d2
        bne.w   t65_same_vblank_too_late

        move.l  t30_display_ptr,d2
        move.l  d2,t30_active_ptr
        bsr     t30_set_bpl_ptrs
        addq.l  #1,t65_same_vblank_total
        bra.w   t65_set_next_target

t65_same_vblank_too_late:
        addq.l  #1,t65_same_vblank_late
        addq.l  #1,t31x_at_target
t31x_miss_class_done:
        addq.l  #1,t31s_missed_deadlines

        ; Record the first two misses without any console I/O in the live path.
        move.l  d0,d2
        sub.l   d6,d2                    ; arithmetic lateness in VBlanks
        cmp.l   t31x_max_past_delta,d2
        bls.w   t31x_max_delta_ok
        move.l  d2,t31x_max_past_delta
t31x_max_delta_ok:
        move.l  t31s_missed_deadlines,d1
        cmp.l   #1,d1
        bne.w   t31x_try_miss2
        move.l  t8c_display_frame_total,d1
        addq.l  #1,d1                    ; report human frame number 1..N
        move.l  d1,t31x_miss1_frame
        move.l  d6,t31x_miss1_target
        move.l  d0,t31x_miss1_current
        move.l  d2,t31x_miss1_delta
        bra.w   t31x_miss_record_done
t31x_try_miss2:
        cmp.l   #2,d1
        bne.w   t31x_miss_record_done
        move.l  t8c_display_frame_total,d1
        addq.l  #1,d1
        move.l  d1,t31x_miss2_frame
        move.l  d6,t31x_miss2_target
        move.l  d0,t31x_miss2_current
        move.l  d2,t31x_miss2_delta
t31x_miss_record_done:

        ; Native <=25-fps sources retain TEST66's proven catch-up accounting.
        ; In V9 cap25 mode we deliberately create NO timing debt: the
        ; absolute 25-fps grid must never slide later. Following late RGB
        ; candidates are skipped before conversion until real time is caught up.
        move.l  t8c_cap25_mode,d1
        tst.l   d1
        bne.s   t8c_no_catchup_debt
        move.l  d0,d2
        sub.l   d6,d2
        addq.l  #1,d2
        add.l   d2,t65_catchup_debt
        add.l   d2,t65_debt_added_total
        move.l  t65_catchup_debt,d1
        cmp.l   t65_debt_max,d1
        bls.s   t65_debt_max_ok
        move.l  d1,t65_debt_max
t65_debt_max_ok:
t8c_no_catchup_debt:

        ; Current frame still gets a clean future refresh if same-VBlank rescue
        ; was no longer possible. The next nominal cap25 target is based on d5.
        move.l  d0,d6
        addq.l  #1,d6

t31s_stream_target_ok:
        move.l  t30_display_ptr,d0
        move.l  d0,t31s_pending_ptr
        move.l  d6,t31s_switch_vblank
        move.l  #1,t31s_pending_valid

t65_set_next_target:
        ; V9 cap25 mode uses an ABSOLUTE 25-fps timeline. d5 is the nominal
        ; target that belonged to this RGB candidate before any late rescue.
        ; A late actual switch can therefore never stretch all following frames.
        move.l  t8c_cap25_mode,d1
        tst.l   d1
        beq.s   t8c_native_next_interval
        move.l  d5,d6
        addq.l  #2,d6
        move.l  d6,t31s_next_switch_vblank
        bra.w   t31s_stream_check_final

t8c_native_next_interval:
        ; Native <=25-fps path: V7 rational scheduler remains unchanged.
        jsr     v7_next_interval
        move.l  d0,d3                       ; nominal interval, always >=1

        ; Keep every video frame visible for at least one PAL refresh.
        ; If previous lateness created timing debt, shorten only a nominal
        ; interval of at least 2 VBlanks and only with >=2 VBlanks headroom.
        ; This generalises TEST66 SAFE-CATCHUP without dropping a frame.
        move.l  output_current_eos,d1
        tst.l   d1
        bne.w   v7_next_apply
        move.l  t65_catchup_debt,d1
        tst.l   d1
        beq.w   v7_next_apply
        cmp.l   #2,d3
        bcs.s   v7_catchup_defer
        move.l  t66_current_slack,d2
        cmp.l   #2,d2
        bge.s   v7_catchup_safe
v7_catchup_defer:
        addq.l  #1,t66_catchup_deferred
        bra.s   v7_next_apply

v7_catchup_safe:
        subq.l  #1,d1
        move.l  d1,t65_catchup_debt
        addq.l  #1,t65_catchup_total
        subq.l  #1,d3

v7_next_apply:
        add.l   d3,d6
        move.l  d6,t31s_next_switch_vblank

t31s_stream_check_final:
        ; H264RGB2: the final payload is identified by the decoder's EOS, not
        ; by an expected frame number. If EOS arrived on the other empty slot
        ; while this BULK_RX was active, output_current_eos is also set.
        move.l  output_current_eos,d0
        tst.l   d0
        beq.w   t31s_stream_ok

        move.l  #V5_SPIN_TIMEOUT,d7
t31s_final_wait_pending:
        move.l  t31s_pending_valid,d0
        tst.l   d0
        beq.s   t31s_final_pending_done
        subq.l  #1,d7
        bne.w   t31s_final_wait_pending
        move.l  #3,v5_wait_stage
        bsr     v5_mark_wait_timeout
        bra.w   t31s_stream_fail
t31s_final_pending_done:
        move.l  #3,v5_wait_stage
        bsr     t31s_wait_frame_start
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.w   t31s_stream_fail
        bsr     t30_display_end
        clr.l   t31s_display_started

t31s_stream_ok:
        move.l  t31s_vblank_counter,d0
        move.l  d0,d1
        sub.l   t31u_stage_start_vblank,d1
        add.l   d1,t31u_post_total
        tst.l   d1
        beq.w   t31u_post_no_nonzero
        addq.l  #1,t31u_post_nonzero
t31u_post_no_nonzero:
        cmp.l   t31u_post_max,d1
        bls.w   t31u_post_max_ok
        move.l  d1,t31u_post_max
t31u_post_max_ok:
        move.l  d0,t31u_last_stream_end_vblank

        moveq   #0,d0
        bra.w   t31s_stream_done

t31s_stream_fail:
        moveq   #1,d0

t31s_stream_done:
        movem.l (sp)+,d1-d7/a0-a6
        rts

; --------------------------------------------------------------------
; TEST61 HAM6 scanline encoder: TEST49-equivalent decisions, table accelerated.
; Input: A0=192 Y bytes, A2/A3=96 U/V bytes,
;        A1=current compact plane-0 output row.
; Output: consumes one 192-pixel luma row + one 96-sample chroma row and
;         advances A1 by 24 bytes.  Hardware HAM state starts each line at
;         COLOR00, therefore d6 starts at packed RGB $000 (black).
; --------------------------------------------------------------------
; --------------------------------------------------------------------
; TEST61 HAM6 scanline encoder: TEST49-equivalent adaptive edge reset.
; Expensive per-pixel squared-error comparisons are replaced by:
;   ham.bin   16 MB: exact winner code for targetRGB + heldRGB
;   edge.bin   2 MB: exact TEST49 edge-threshold bitset
;   state.bin 512 KB: exact next Denise held state for heldRGB + code
; The visible HAM code stream is intended to be bit-identical to TEST49.
; Input/output contract is unchanged from TEST49.
; --------------------------------------------------------------------
t44_convert_ham_row:
        movem.l d1-d7/a4-a6,-(sp)
        move.l  v9m_ham_lut_ptr,a5         ; external 16-MiB transition-table base
        moveq   #0,d6                       ; low=held RGB, high=previous target RGB
        clr.b   t56_edge_cooldown
        moveq   #23,d7                      ; 24 groups x 8 pixels = 192

t44_ham_group:
        moveq   #0,d1                       ; accum P4:P5:00:00
        moveq   #0,d2                       ; accum P0:P1:P2:P3
        ; HAM pixel pair 0: one shared I420 U/V sample for two Y pixels.
        moveq   #0,d3
        move.b  (a2)+,d3
        andi.w  #$00F0,d3
        moveq   #0,d0
        move.b  (a3)+,d0
        lsr.b   #4,d0
        or.w    d0,d3
        movea.l d3,a6                     ; preserve UV key across both pixels
        ; t51_p0_0: form 12-bit Y4/U4/V4 key and locate 64-byte target record.
        moveq   #0,d0
        move.b  (a0)+,d0
        andi.w  #$00F0,d0
        lsl.w   #4,d0
        move.l  a6,d3
        or.w    d3,d0
        lsl.l   #6,d0
        lea     t44_target_lut,a4
        adda.l  d0,a4
        moveq   #0,d3
        move.w  56(a4),d3                  ; current target $0RGB
        move.l  60(a4),d4                  ; current target << 12
        ; First visible pixel of the WHOLE scanline only: establish a known direct HAM color.
