        moveq   #0,d5
        move.b  3(a4),d5                   ; direct code, in case edge bit is set
        move.l  d6,d0
        swap    d0
        andi.l  #$00000FFF,d0              ; previous source target $0RGB
        lsl.l   #8,d0
        lsl.l   #4,d0                      ; prev << 12
        or.w    d3,d0                      ; | current target
        lsr.l   #3,d0                      ; bit index -> byte index
        move.l  v9m_edge_lut_ptr,a4
        btst    d3,0(a4,d0.l)              ; memory BTST uses current target low 3 bits
        beq.w   t51_p3_1_transition
        move.b  #3,t56_edge_cooldown
        bra.w   t51_p3_1_chosen
t51_p3_1_transition:
        ; Full TEST49 direct/R/G/B winner is precomputed for target+held state.
        moveq   #0,d0
        move.w  d6,d0                      ; held state is always $000..$FFF
        or.l    d4,d0                      ; (target<<12)|held
        moveq   #0,d5
        move.b  0(a5,d0.l),d5              ; exact 6-bit HAM code
t51_p3_1_chosen:
        ; Update Denise held state through a 4096x64 word table.
        moveq   #0,d0
        move.w  d6,d0
        lsl.l   #7,d0                      ; held * 64 codes * 2 bytes
        moveq   #0,d4
        move.w  d5,d4
        add.w   d4,d4                      ; code * 2
        add.l   d4,d0
        move.l  v9m_state_lut_ptr,a4
        move.w  0(a4,d0.l),d6              ; new held $0RGB
        ; Save current source target in high word, exactly like TEST49.
        swap    d3
        move.w  d6,d3
        move.l  d3,d6
        ; Pair lookup gives two contribution bits for every one of six planes.
        move.l  d7,d0
        swap    d0
        andi.w  #$003F,d0
        lsl.w   #6,d0
        andi.w  #$003F,d5
        or.w    d5,d0
        lsl.w   #3,d0
        lea     t44_pair6_lut,a6
        move.l  4(a6,d0.w),d5              ; P4:P5:00:00 low 2 bits
        move.l  0(a6,d0.w),d0              ; P0:P1:P2:P3 low 2 bits
        lsl.l   #2,d2
        or.l    d0,d2
        lsl.l   #2,d1
        or.l    d5,d1
        ; Store one finished 8-pixel byte in each compact HAM plane.
        move.l  d2,d0
        move.b  d0,T37_FAST_PLANE3_OFF(a1)
        lsr.l   #8,d0
        move.b  d0,T37_FAST_PLANE2_OFF(a1)
        lsr.l   #8,d0
        move.b  d0,T37_FAST_PLANE_BYTES(a1)
        lsr.l   #8,d0
        move.b  d0,(a1)

        move.l  d1,d0
        swap    d0
        move.b  d0,T44_FAST_PLANE5_OFF(a1)
        lsr.w   #8,d0
        move.b  d0,T37_FAST_PLANE4_OFF(a1)
        addq.l  #1,a1
        dbra    d7,t44_ham_group

        movem.l (sp)+,d1-d7/a4-a6
        rts
; --------------------------------------------------------------------
