; --------------------------------------------------------------------
; TEST33 - compact MMAL output header diagnostic.
; Prints only for output #150 onward (or any zero-length output).
; --------------------------------------------------------------------
h31s_log_output_header:
        movem.l d0-d3/a1,-(sp)
        lea     msg31s_hdr,a1
        move.l  #msg31s_hdr_end-msg31s_hdr,d3
        bsr     print
        move.l  output_frame_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_length,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_offset,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_flags,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_cmd,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_pts_hi,d0
        bsr     print_hex32
        move.l  buffer_pts_lo,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_dts_hi,d0
        bsr     print_hex32
        move.l  buffer_dts_lo,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_payload,d0
        bsr     print_hex32
        bsr     newline
        movem.l (sp)+,d0-d3/a1
        rts

h19_mmal_data:
        ; Validate MMAL DATA ports.
        move.l  bulk_rx_msgid,d0
        jsr     v9g_rx_service_match
        tst.l   d0
        bne.w   h19_other_vchiq
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop

        move.l  bulk_rx_size,d0
        cmp.l   #24,d0
        bcs.w   h19_bad_reply

        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   h19_bad_reply
        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,buffer_mmal_type


        move.l  buffer_mmal_type,d0
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        beq.w   h19_buffer_to_host
        cmp.l   #MMAL_EVENT_TO_HOST,d0
        beq.w   h19_event
        bra.w   h19_consume

h19_buffer_to_host:
        ; VPv21T isolation: EXACT HDMI_v41L video BUFFER_TO_HOST path.
        ; No audio component exists in this build, therefore no audio-return
        ; interception is allowed here. This isolates the VPv21 audio hook.
        move.l  bulk_rx_size,d0
        cmp.l   #164,d0
        bcs.w   h19_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   h19_bad_reply
        lea     32(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   h19_bad_reply

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,buffer_drv_port
        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,buffer_drv_context
        lea     72(a2),a0
        bsr     load_le32
        move.l  d0,buffer_cmd
        lea     84(a2),a0
        bsr     load_le32
        move.l  d0,buffer_length
        lea     88(a2),a0
        bsr     load_le32
        move.l  d0,buffer_offset
        lea     92(a2),a0
        bsr     load_le32
        move.l  d0,buffer_flags
        lea     96(a2),a0
        bsr     load_le32
        move.l  d0,buffer_pts_lo
        lea     100(a2),a0
        bsr     load_le32
        move.l  d0,buffer_pts_hi
        lea     104(a2),a0
        bsr     load_le32
        move.l  d0,buffer_dts_lo
        lea     108(a2),a0
        bsr     load_le32
        move.l  d0,buffer_dts_hi
        lea     168(a2),a0
        bsr     load_le32
        move.l  d0,buffer_payload

        ; VPv36 A/V: audio_render INPUT0 and video_decode INPUT0 both use
        ; port handle 1, so port handle alone cannot distinguish callbacks.
        ; The audio buffer uses its own unique context/cookie. Consume that
        ; return here before the video-input ownership checks see it.
        move.l  buffer_drv_context,d0
        ; BerryMP314: two independent audio MMAL input contexts. Mark the exact
        ; renderer-owned slot returned without disturbing the other slot.
        move.l  d0,d1
        sub.l   #VPV47_AUDIO_CONTEXT_BASE,d1
        cmpi.l  #VPV47_AUDIO_SLOTS,d1
        bcc.s   h19_vpv47_not_audio_return
        lsl.l   #2,d1
        lea     vpv47_slot_returned,a0
        adda.l  d1,a0
        move.l  #1,(a0)
        bra.w   h19_consume
h19_vpv47_not_audio_return:
        ; Keep the old single-buffer context recognized for legacy helpers.
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.s   h19_vpv35_not_audio_return
        move.l  #1,vpv21_audio_returned
        bra.w   h19_consume
h19_vpv35_not_audio_return:

        ; Input callback? Nice diagnostic, but no bulk receive.
        move.l  buffer_drv_port,d0
        cmp.l   input_port_handle,d0
        bne.w   h19_check_output_buffer
        move.l  buffer_drv_context,d0
        cmp.l   #MMAL_EOS_BUFFER_CONTEXT,d0
        beq.w   h19a_eos_input_return

        ; Normal TEST33 pool contexts are BASE + slot (0..19).
        cmp.l   #MMAL_BUFFER_CONTEXT_BASE,d0
        bcs.w   h19_bad_reply
        sub.l   #MMAL_BUFFER_CONTEXT_BASE,d0
        cmp.l   #INPUT_POOL_COUNT,d0
        bcc.w   h19_bad_reply
        bra.w   h19a_normal_input_return

h19a_eos_input_return:
        ; EOS input buffer itself came back from VideoCore.
        move.l  #1,eos_return_seen
        lea     msg19a_eos_return,a1
        move.l  #msg19a_eos_return_end-msg19a_eos_return,d3
        bsr     print
        bra.w   h19_consume

h19a_normal_input_return:
        ; D0 = pool slot index.  A slot becomes reusable only here, not at
        ; BULK_TX_DONE.  Duplicate/unknown returns are treated as corruption.
        move.l  d0,d1
        lsl.l   #2,d1
        lea     input_slot_state,a0
        adda.l  d1,a0
        tst.l   (a0)
        beq.w   h19_bad_reply
        clr.l   (a0)
        subq.l  #1,input_in_use_count
        move.l  #1,buffer_seen
        addq.l  #1,input_return_total
        bra.w   h19_consume

h19_check_output_buffer:
        move.l  buffer_drv_port,d0
        cmp.l   output_port_handle,d0
        bne.w   h19_consume

        ; V10P: output contexts are BASE + slot for every offered host slot.
        move.l  buffer_drv_context,d0
        sub.l   #MMAL_OUTPUT_BUFFER_CONTEXT0,d0
        bcs.w   h19_consume
        cmp.l   v10j_output_req_count,d0
        bcc.w   h19_consume
        move.l  d0,output_header_idx

        ; H264RGB2: this is now proven to be an OUTPUT callback. TEST66's
        ; hardware log ends with a zero-length output carrying flags=EOS.
        ; Record EOS here (not on INPUT callbacks, whose EOS flag is separate).
        move.l  buffer_flags,d0
        and.l   #MMAL_BUFFER_FLAG_EOS,d0
        beq.s   h264rgb2_output_header_not_eos
        move.l  #1,output_eos_seen
h264rgb2_output_header_not_eos:

        move.l  #1,output_buffer_seen
        addq.l  #1,output_bth_total

        ; V9: no per-frame DOS/console output during streaming.
        ; V8D logged every OUTPUT header from frame 150 onward; on real Amiga
        ; hardware that means roughly 1650 long console lines for the anime and
        ; materially steals time from the 25-fps RGB path.  Keep only zero-length
        ; callbacks (notably terminal EOS) visible; all timing counters remain.
        move.l  buffer_length,d0
        tst.l   d0
        bne.w   h31s_after_hdr_log
        bsr     h31s_log_output_header
h31s_after_hdr_log:

        ; Empty callback: ownership returned without a bulk payload. Normal
        ; empties are requeued. An EOS empty is terminal. With two output
        ; buffers, if EOS arrives while one BULK_RX is active, that active
        ; payload is the last picture and must receive final-frame timing.
        move.l  buffer_length,d0
        bne.w   h61_nonempty_output
        addq.l  #1,output_empty_total
        move.l  output_header_idx,d0
        move.l  d0,output_empty_idx
        move.l  buffer_flags,d0
        and.l   #MMAL_BUFFER_FLAG_EOS,d0
        beq.s   h264rgb2_empty_not_eos
        move.l  output_bulk_queued,d0
        tst.l   d0
        beq.s   h264rgb2_empty_eos_marked
        move.l  #1,output_current_eos
h264rgb2_empty_eos_marked:
        move.l  #1,output_empty_requeue_pending
        bra.w   h19_consume
h264rgb2_empty_not_eos:
        move.l  #1,output_empty_requeue_pending
        bra.w   h19_consume

h61_nonempty_output:
        move.l  buffer_payload,d0
        tst.l   d0
        bne.w   h19_bad_output_payload

        move.l  buffer_length,d0
        cmp.l   output_buf_size_saved,d0
        bhi.w   h19_output_too_big
        addq.l  #3,d0
        and.l   #$fffffffc,d0

        ; Preserve whether this particular non-empty header carries EOS.
        moveq   #0,d2
        move.l  buffer_flags,d1
        and.l   #MMAL_BUFFER_FLAG_EOS,d1
        beq.s   h264rgb2_nonempty_eos_ready
        moveq   #1,d2
h264rgb2_nonempty_eos_ready:

        ; One host BULK_RX remains serialized. With up to 20 MMAL output
        ; buffers, several decoded headers may arrive while the current payload
        ; is being transferred/converted. Preserve them in decode order in a
        ; bounded FIFO instead of the old single deferred slot.
        move.l  output_bulk_queued,d1
        tst.l   d1
        beq.s   h61_output_bulk_now
        move.l  output_deferred_count,d1
        cmp.l   v10j_output_req_count,d1
        bcc.w   h19_bad_reply
        move.l  output_deferred_tail,d3
        move.l  d3,d4
        lsl.l   #2,d4
        lea     output_deferred_idx_q,a0
        move.l  output_header_idx,0(a0,d4.l)
        lea     output_deferred_len_q,a0
        move.l  d0,0(a0,d4.l)
        lea     output_deferred_eos_q,a0
        move.l  d2,0(a0,d4.l)
        addq.l  #1,d3
        cmpi.l  #OUTPUT_POOL_MAX,d3
        bcs.s   v10j_deferred_tail_ok
        moveq   #0,d3
v10j_deferred_tail_ok:
        move.l  d3,output_deferred_tail
        addq.l  #1,output_deferred_count
        addq.l  #1,t61_deferred_total
        bra.w   h19_consume

h61_output_bulk_now:
        move.l  d0,output_bulk_len
        move.l  d2,output_current_eos
        move.l  output_header_idx,d0
        bsr     h61_select_output_idx
        tst.l   d0
        bne.w   h19_bad_reply

        ; Consume BUFFER_TO_HOST BEFORE publishing BULK_RX.
        move.l  bulk_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        bra.w   h19_queue_bulk_rx

h19_event:
        move.l  #1,event_seen

        move.l  bulk_rx_size,d0
        cmp.l   #44,d0
        bcs.w   h19_consume

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,event_port_type
        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,event_port_num
        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,buffer_event_cmd
        lea     48(a2),a0
        bsr     load_le32
        move.l  d0,buffer_event_length

        lea     msg19_event,a1
        move.l  #msg19_event_end-msg19_event,d3
        bsr     print
        move.l  event_port_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  event_port_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_event_cmd,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  buffer_event_length,d0
        bsr     print_hex32
        bsr     newline

        move.l  event_port_type,d0
        cmp.l   #MMAL_PORT_OUTPUT,d0
        beq.w   h19c_output_event
        cmp.l   #MMAL_PORT_CONTROL,d0
        beq.w   h19c_control_event
        bra.w   h19_consume

h19c_output_event:
        move.l  #1,output_event_seen
        bra.w   h19_consume

h19c_control_event:
        move.l  #1,control_event_seen

        ; V10P: an MMAL ERROR event carries a 4-byte MMAL_STATUS_T in data[].
        ; Print exactly the first one together with the last submitted MKV/MMAL
        ; input context, then stop after consuming this VCHIQ record. This turns
        ; the previous endless ERRO flood into one deterministic diagnostic.
        move.l  buffer_event_cmd,d0
        cmpi.l  #MMAL_EVENT_ERROR,d0
        bne.w   h19c_control_event_normal
        move.l  buffer_event_length,d0
        cmpi.l  #4,d0
        bcs.w   h19c_control_event_short_error

        lea     52(a2),a0              ; mmal_worker_event_to_host.data[0]
        bsr     load_le32
        move.l  d0,v10h_error_status
        move.l  #1,v10h_error_seen

        lea     msg_v10h_error_status,a1
        move.l  #msg_v10h_error_status_end-msg_v10h_error_status,d3
        bsr     print
        move.l  v10h_error_status,d0
        bsr     print_hex32
        lea     msg_v10h_error_name,a1
        move.l  #msg_v10h_error_name_end-msg_v10h_error_name,d3
        bsr     print
        move.l  v10h_error_status,d0
        bsr     v10h_print_status_name
        bsr     newline

        lea     msg_v10h_error_ctx1,a1
        move.l  #msg_v10h_error_ctx1_end-msg_v10h_error_ctx1,d3
        bsr     print
        move.l  v10h_last_frame_no,d0
        bsr     print_hex32
        lea     msg_v10h_error_payload,a1
        move.l  #msg_v10h_error_payload_end-msg_v10h_error_payload,d3
        bsr     print
        move.l  v10h_last_frame_payload,d0
        bsr     print_hex32
        lea     msg_v10h_error_pts,a1
        move.l  #msg_v10h_error_pts_end-msg_v10h_error_pts,d3
        bsr     print
        move.l  v10h_last_pts_ticks,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v10h_error_ctx2,a1
        move.l  #msg_v10h_error_ctx2_end-msg_v10h_error_ctx2,d3
        bsr     print
        move.l  v10h_last_nal_count,d0
        bsr     print_hex32
        lea     msg_v10h_error_frag,a1
        move.l  #msg_v10h_error_frag_end-msg_v10h_error_frag,d3
        bsr     print
        move.l  v10h_last_fragment_no,d0
        bsr     print_hex32
        lea     msg_v10h_error_len,a1
        move.l  #msg_v10h_error_len_end-msg_v10h_error_len,d3
        bsr     print
        move.l  v10h_last_chunk_len,d0
        bsr     print_hex32
        lea     msg_v10h_error_flags,a1
        move.l  #msg_v10h_error_flags_end-msg_v10h_error_flags,d3
        bsr     print
        move.l  v10h_last_chunk_flags,d0
        bsr     print_hex32
        lea     msg_v10h_error_naltype,a1
        move.l  #msg_v10h_error_naltype_end-msg_v10h_error_naltype,d3
        bsr     print
        move.l  v10h_last_nal_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v10h_error_pipe,a1
        move.l  #msg_v10h_error_pipe_end-msg_v10h_error_pipe,d3
        bsr     print
        move.l  input_in_use_count,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_bulk_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_return_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_bulk_pending,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v10h_error_stop,a1
        move.l  #msg_v10h_error_stop_end-msg_v10h_error_stop,d3
        bsr     print
        bra.w   h19_consume

h19c_control_event_short_error:
        move.l  #$FFFFFFFF,v10h_error_status
        move.l  #1,v10h_error_seen
        lea     msg_v10h_error_short,a1
        move.l  #msg_v10h_error_short_end-msg_v10h_error_short,d3
        bsr     print
        bra.w   h19_consume

h19c_control_event_normal:
        lea     msg19c_control_event,a1
        move.l  #msg19c_control_event_end-msg19c_control_event,d3
        bsr     print
        bra.w   h19_consume

; V10P status-name helper. D0=status.
v10h_print_status_name:
        movem.l d0-d3/a1,-(sp)
        cmpi.l  #MMAL_SUCCESS,d0
        beq.w   v10h_status_success
        cmpi.l  #MMAL_ENOMEM,d0
        beq.w   v10h_status_enomem
        cmpi.l  #MMAL_ENOSPC,d0
        beq.w   v10h_status_enospc
        cmpi.l  #MMAL_EINVAL,d0
        beq.w   v10h_status_einval
        cmpi.l  #MMAL_ENOSYS,d0
        beq.w   v10h_status_enosys
        cmpi.l  #MMAL_ENOENT,d0
        beq.w   v10h_status_enoent
        cmpi.l  #MMAL_ENXIO,d0
        beq.w   v10h_status_enxio
        cmpi.l  #MMAL_EIO,d0
        beq.w   v10h_status_eio
        cmpi.l  #MMAL_ESPIPE,d0
        beq.w   v10h_status_espipe
        cmpi.l  #MMAL_ECORRUPT,d0
        beq.w   v10h_status_ecorrupt
        cmpi.l  #MMAL_ENOTREADY,d0
        beq.w   v10h_status_enotready
        cmpi.l  #MMAL_ECONFIG,d0
        beq.w   v10h_status_econfig
        cmpi.l  #MMAL_EISCONN,d0
        beq.w   v10h_status_eisconn
        cmpi.l  #MMAL_ENOTCONN,d0
        beq.w   v10h_status_enotconn
        cmpi.l  #MMAL_EAGAIN,d0
        beq.w   v10h_status_eagain
        cmpi.l  #MMAL_EFAULT,d0
        beq.w   v10h_status_efault
        lea     msg_v10h_status_unknown,a1
        bra.w   v10h_status_print
v10h_status_success:   lea msg_v10h_status_success,a1
        bra.w v10h_status_print
v10h_status_enomem:    lea msg_v10h_status_enomem,a1
        bra.w v10h_status_print
v10h_status_enospc:    lea msg_v10h_status_enospc,a1
        bra.w v10h_status_print
v10h_status_einval:    lea msg_v10h_status_einval,a1
        bra.w v10h_status_print
v10h_status_enosys:    lea msg_v10h_status_enosys,a1
        bra.w v10h_status_print
v10h_status_enoent:    lea msg_v10h_status_enoent,a1
        bra.w v10h_status_print
v10h_status_enxio:     lea msg_v10h_status_enxio,a1
        bra.w v10h_status_print
v10h_status_eio:       lea msg_v10h_status_eio,a1
        bra.w v10h_status_print
v10h_status_espipe:    lea msg_v10h_status_espipe,a1
        bra.w v10h_status_print
v10h_status_ecorrupt:  lea msg_v10h_status_ecorrupt,a1
        bra.w v10h_status_print
v10h_status_enotready: lea msg_v10h_status_enotready,a1
        bra.w v10h_status_print
v10h_status_econfig:   lea msg_v10h_status_econfig,a1
        bra.w v10h_status_print
v10h_status_eisconn:   lea msg_v10h_status_eisconn,a1
        bra.w v10h_status_print
v10h_status_enotconn:  lea msg_v10h_status_enotconn,a1
        bra.w v10h_status_print
v10h_status_eagain:    lea msg_v10h_status_eagain,a1
        bra.w v10h_status_print
v10h_status_efault:    lea msg_v10h_status_efault,a1
v10h_status_print:
        moveq   #0,d3
v10h_status_len:
        tst.b   0(a1,d3.l)
        beq.s   v10h_status_len_done
        addq.l  #1,d3
        bra.s   v10h_status_len
v10h_status_len_done:
        bsr     print
        movem.l (sp)+,d0-d3/a1
        rts

; ------------------------------------------------------------
; Queue VCHIQ BULK_RX after an output BUFFER_TO_HOST announced data.
; Shared VCHIQ RAM is CPU-owned on entry.
; port_rx_pos already consumed the BUFFER_TO_HOST message.
; ------------------------------------------------------------
h19_queue_bulk_rx:

        ; Pagelist:
        ; u32 length
        ; u16 type=PAGELIST_READ (VC -> host RAM)
        ; u16 offset=0
        ; addrs[0] = base page | (number_of_pages - 1)
        move.l  output_pagelist_ptr,a0
        move.l  output_bulk_len,d0
        bsr     store_le32

        move.l  output_pagelist_ptr,a0
        move.b  #PAGELIST_READ,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)

        move.l  output_bulk_len,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        move.l  d0,output_pages
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  output_data_bus,d1
        and.l   #$fffff000,d1
        or.l    d0,d1
        move.l  output_pagelist_ptr,a0
        lea     8(a0),a0
        move.l  d1,d0
        bsr     store_le32

        ; Pagelist is read FROM RAM by VideoCore.
        move.l  #12,output_pagelist_dma_len
        move.l  output_pagelist_ptr,a0
        lea     output_pagelist_dma_len,a1
        move.l  #DMA_ReadFromRAM,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,output_pagelist_phys
        cmp.l   output_pagelist_ptr,d0
        bne.w   h19_pagelist_dma_fail
        move.l  output_pagelist_dma_len,d1
        cmp.l   #12,d1
        bcs.w   h19_pagelist_dma_fail
        move.l  #1,output_pagelist_dma_active

        ; Host VCHIQ BULK_RX control record (16-byte stride).
        move.l  #16,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   h19_bad_reply

        move.l  a2,a0
        move.l  #VCHIQ_MSG_BULK_RX,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        move.l  d0,output_bulk_rx_msgid
        bsr     store_le32
        lea     4(a2),a0
        move.l  #8,d0
        bsr     store_le32
        lea     8(a2),a0
        move.l  output_pagelist_bus,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  output_bulk_len,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #16,d0
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,output_armed

        move.l  #1,output_bulk_queued

        bsr     dma_pre_all
        move.l  output_armed,d0
        tst.l   d0
        beq.w   h19_after_rx_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
h19_after_rx_bell:
        ; Return directly to polling. Shared VCHIQ RAM is DMA-owned.
        bra.w   h19_poll

h19_other_vchiq:
        ; TEST33: ignore expected non-MMAL housekeeping messages silently
        ; during streaming so redirected stdout cannot perturb timing.
        bra.w   h19_consume

h19_consume:
        ; TEST33: every consumed VCHIQ/MMAL message is real forward progress.
        ; Give the decoder a fresh observation window so a long post-EOF drain
        ; cannot exhaust one cumulative POLL_COUNT budget after many good frames.
        move.l  #POLL_COUNT,d7

        ; TEST33: remember which remote stream slot owns the message
        ; we are about to release. If advancing reaches the next 4-KiB slot,
        ; the previous physical MASTER slot is now completely consumed and
        ; must be returned through master.slot_queue_recycle.
        move.l  port_rx_pos,d1
        move.l  d1,rx_pos_before_consume

        move.l  bulk_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        move.l  rx_pos_before_consume,d0
        move.l  d0,d1
        and.l   #$fffff000,d1
        move.l  port_rx_pos,d2
        and.l   #$fffff000,d2
        cmp.l   d1,d2
        beq.w   h31s_no_rx_slot_recycle
        bsr     h31s_recycle_rx_slot
        tst.l   d0
        bne.w   h31s_recycle_fail
h31s_no_rx_slot_recycle:

        ; TEST26 long run: report the first time either VCHIQ stream position
        ; reaches the next 4-KiB slot. This is diagnostic only; addressing is
        ; intentionally still the proven pre-TEST26 path so a boundary fault is visible.
        bsr     h26_log_slot_crossings

        ; V10P: never keep polling an ERRO storm. The first ERROR record has
        ; already been decoded and logged in h19c_control_event.
        move.l  v10h_error_seen,d0
        tst.l   d0
        bne.w   h19_v10h_error_abort

        ; TEST33: A zero-length OUTPUT BUFFER_TO_HOST still returns ownership
        ; of the output buffer. End its DMA phase and immediately offer the same
        ; header again. Without this, one empty return would leave the decoder
        ; permanently without an output buffer.
        move.l  output_empty_requeue_pending,d0
        tst.l   d0
        beq.w   h31s_no_empty_requeue
        clr.l   output_empty_requeue_pending

        move.l  output_empty_idx,d0
        bsr     h61_post_output_dma_idx
        tst.l   d0
        bne.w   h22_requeue_fail
h31s_empty_dma_closed:
        clr.l   output_buffer_seen
        move.l  output_eos_seen,d0
        tst.l   d0
        bne.s   h264rgb2_empty_terminal
        tst.l   v32_resize_pending
        bne.s   h31s_empty_hold_for_resize
        move.l  output_empty_idx,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        addq.l  #1,output_empty_requeue_total
        bra.s   h31s_empty_requeue_done_v25
h31s_empty_hold_for_resize:
        addq.l  #1,v32_resize_held
        bra.s   h31s_no_empty_requeue
h31s_empty_requeue_done_v25:
        lea     msg31s_empty_requeued,a1
        move.l  #msg31s_empty_requeued_end-msg31s_empty_requeued,d3
        bsr     print
        move.l  output_frame_total,d0
        bsr     print_hex32
        bsr     newline
        bra.s   h31s_no_empty_requeue
h264rgb2_empty_terminal:
        lea     msg_h264rgb2_output_eos,a1
        move.l  #msg_h264rgb2_output_eos_end-msg_h264rgb2_output_eos,d3
        bsr     print
h31s_no_empty_requeue:

        ; TEST26: input blocks and decoded output frames are deliberately independent.
        ; Output: after each completed BULK_RX, immediately recycle the one output buffer.
        move.l  output_bulk_done,d0
        tst.l   d0
        beq.w   h25_check_input_recycle

        clr.l   output_bulk_done
        clr.l   output_buffer_seen
        clr.l   output_bulk_queued

        ; H264RGB2: once decoder OUTPUT EOS has been observed, no more output
        ; buffers are needed. This also covers the case where the EOS-bearing
        ; final header is deferred behind the just-finished payload.
        move.l  output_eos_seen,d0
        tst.l   d0
        bne.s   h264rgb2_skip_current_requeue
        tst.l   v32_resize_pending
        bne.s   h264rgb2_hold_current_for_resize
        move.l  output_current_idx,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        bra.s   h264rgb2_skip_current_requeue
h264rgb2_hold_current_for_resize:
        addq.l  #1,v32_resize_held
h264rgb2_skip_current_requeue:
        clr.l   output_current_eos

        ; V10P: start the oldest deferred output payload, if any.
        move.l  output_deferred_count,d0
        tst.l   d0
        beq.w   h25_check_input_recycle
        move.l  output_deferred_head,d3
        move.l  d3,d4
        lsl.l   #2,d4
        lea     output_deferred_idx_q,a0
        move.l  0(a0,d4.l),d0
        lea     output_deferred_len_q,a0
        move.l  0(a0,d4.l),d1
        move.l  d1,output_bulk_len
        lea     output_deferred_eos_q,a0
        move.l  0(a0,d4.l),d1
        move.l  d1,output_current_eos
        addq.l  #1,d3
        cmpi.l  #OUTPUT_POOL_MAX,d3
        bcs.s   v10j_deferred_head_ok
        moveq   #0,d3
v10j_deferred_head_ok:
        move.l  d3,output_deferred_head
        subq.l  #1,output_deferred_count
        bsr     h61_select_output_idx
        tst.l   d0
        bne.w   h22_requeue_fail
        bra.w   h19_queue_bulk_rx

h25_check_input_recycle:
        ; V41B mode 3: renderer stays alpha=0 while the restart fast-forwards
        ; to the saved frame/sample position, then becomes visible exactly once.
        cmpi.l  #3,v41_display_style
        bne.s   v41b_no_renderer_resume_check
        jsr     v41b_renderer_maybe_show
        ; V41D: once the saved restart position has been reached, stop feeding
        ; new H264 blocks until all currently outstanding input/BULK callbacks
        ; have passed through the normal streaming dispatcher. DISPLAYREGION is
        ; then changed in a quiet RX window instead of racing those callbacks.
        tst.l   v41b_renderer_reveal_pending
        bne.w   h25_check_success
v41b_no_renderer_resume_check:
        ; V40: while a live size switch is active, pause only NEW H264 input.
        ; Existing decoder input/output traffic continues to drain through the
        ; normal callback engine until v40_resize_service advances the phases.
        tst.l   v40_resize_state
        bne.w   h25_check_success

        ; BerryMP314: service one live PCM buffer through the SAME streaming
        ; dispatcher. If it publishes AUDIO BULK_TX now, video must wait until
        ; that transport completion arrives; MMAL callbacks remain interleaved.
        jsr     vpv47_audio_service
        tst.l   d0
        beq.s   vpv39_no_new_audio_bulk
        move.l  #POLL_COUNT,d7
        bra.w   h19_poll
vpv39_no_new_audio_bulk:
        tst.l   vpv39_audio_bulk_pending
        bne.w   h25_check_success

        ; TEST33 feeder: whenever the serialized BULK_TX engine is idle,
        ; publish another file block into any free MMAL pool slot.  Returned
        ; slots are independent; a held buffer no longer stalls the stream.
        move.l  eos_sent,d0
        tst.l   d0
        bne.w   h25_check_success

        move.l  input_eof_seen,d0
        tst.l   d0
        bne.w   h25_check_eos_ready

        move.l  input_bulk_pending,d0
        tst.l   d0
        bne.w   h25_check_success

        bsr     t31s_feed_next_input
        cmp.l   #1,d0
        beq.w   h22_resend_fail
        cmp.l   #0,d0
        bne.w   h25_check_eos_ready

        ; A new block was published and shared VCHIQ memory is DMA-owned.
        addq.l  #1,frame_cycle
        move.l  #POLL_COUNT,d7
        bra.w   h19_poll

h25_check_eos_ready:
        ; V40B: EOS strictly one-shot.  V40 could re-enter this label from
        ; h19_no_msg after a resize failure and resend EOS indefinitely.
        tst.l   eos_sent
        bne.w   h25_check_success

        ; Once the complete file and final normal BULK_TX are published,
        ; send EOS immediately through the dedicated EOS pool page. Do NOT
        ; wait for every normal MMAL buffer to return: the decoder may hold
        ; one or more input buffers until the EOS marker arrives.
        move.l  input_eof_seen,d0
        tst.l   d0
        beq.w   h25_check_success
        move.l  input_bulk_pending,d0
        tst.l   d0
        bne.w   h25_check_success

        ; TEST33: EOF + kein laufender BULK genuegt. Die Zahl der
        ; Dateibloecke haengt nur von der realen Dateigroesse ab.
        move.l  input_bulk_total,d0
        tst.l   d0
        beq.w   h22_resend_fail

        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   v15_eos_natural_message
        lea     msg_v15_ctrlc_eos,a1
        move.l  #msg_v15_ctrlc_eos_end-msg_v15_ctrlc_eos,d3
        bsr     print
        bra.s   v15_eos_message_done
v15_eos_natural_message:
        lea     msg22_three_done,a1
        move.l  #msg22_three_done_end-msg22_three_done,d3
        bsr     print
v15_eos_message_done:
        bra.w   h19a_send_eos

h25_check_success:
        ; HDMI_v41L has no host output buffers. Completion is therefore based
        ; on complete input ownership return + official input EOS. Once that is
        ; true, give ril.video_render a bounded 0.5 s drain window, then consume
        ; any final MMAL/VCHIQ records before declaring the test complete.
        move.l  input_eof_seen,d0
        tst.l   d0
        beq.w   h19_more
        move.l  input_bulk_pending,d0
        tst.l   d0
        bne.w   h19_more
        move.l  input_bulk_total,d0
        cmp.l   input_return_total,d0
        bne.w   h19_more
        tst.l   d0
        beq.w   h19_more
        move.l  eos_bulk_done,d0
        tst.l   d0
        beq.w   h19_more
        move.l  eos_return_seen,d0
        tst.l   d0
        beq.w   h19_more
        move.l  input_in_use_count,d0
        tst.l   d0
        bne.w   h19_more
        move.l  bulk_dma_active,d0
        tst.l   d0
        bne.w   h19_more
        tst.l   vpv39_audio_bulk_pending
        bne.w   h19_more
        ; BerryMP314: do not free the two PCM DMA slots until audio_render has
        ; returned every queued context, even though video EOS is complete.
        tst.l   vpv47_inflight
        bne.w   h19_more
        tst.l   vpv21_audio_dma_active
        bne.w   h19_more

        move.l  hdmi_v40o_drain_done,d0
        tst.l   d0
        bne.w   h19_more

        lea     msg_hdmi_v40o_drain,a1
        move.l  #msg_hdmi_v40o_drain_end-msg_hdmi_v40o_drain,d3
        bsr     print
        ; Delay() must run while the shared VCHIQ block is VideoCore/DMA-owned.
        bsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1                 ; 25 DOS ticks = 0.5 s
        jsr     Delay(a6)
        bsr     dma_post_all
        move.l  #1,hdmi_v40o_drain_done
        ; No host output buffers exist in HDMI mode. Reuse the established
        ; cleanup gate bit after the bounded renderer drain has completed.
        move.l  #1,output_eos_seen
        move.l  #POLL_COUNT,d7
        bra.w   h19_poll


h19_more:
        cmp.l   port_rx_pos,d5
        bhi.w   h19_check

h19_no_msg:
        move.l  hdmi_v40o_drain_done,d0
        tst.l   d0
        bne.w   hdmi_v40o_stream_success

        ; V14: a Ctrl-C may arrive while no VCHIQ record is pending. Once the
        ; current input BULK is idle, route straight into the normal EOS path.
        move.l  v15_stop_requested,d0
        tst.l   d0
        beq.s   h19_no_msg_normal
        move.l  input_bulk_pending,d0
        tst.l   d0
        beq.w   h25_check_eos_ready
h19_no_msg_normal:
        ; V40 resize has its own bounded wait counter. Avoid the generic
        ; 100-poll stream timeout while intentionally quiescing the pipeline.
        tst.l   v40_resize_state
        beq.s   v40_no_resize_wait
        move.l  #POLL_COUNT,d7
        bsr     dma_pre_all
        bra.w   h19_poll
v40_no_resize_wait:
        ; Before input BULK_TX_DONE use full timeout.
        move.l  bulk_done_seen,d0
        tst.l   d0
        beq.w   h19_long_wait

        ; H264RGB2: do not use the legacy EVENT grace path as a success
        ; condition. Completion is now tied to the decoder's real OUTPUT EOS,
        ; so a format/control event can never terminate the movie early.
h19_long_wait:
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   h19_poll
        bsr     dma_post_all
        bra.w   h19_timeout

h19_event_grace:
        move.l  bulk_grace,d0
        subq.l  #1,d0
        move.l  d0,bulk_grace
        beq.w   h19_success_event
        bsr     dma_pre_all
        bra.w   h19_poll

; H264RGB2 final display drain. If the EOS marker arrived too late to mark
; the final I420 payload inside t31s_stream_current_frame, wait until any
; scheduled last frame has actually become ACTIVE, give it two PAL refreshes
; exactly like the old fixed-frame final path, then restore the system display.
t31s_finish_dynamic_stream:
        movem.l d0-d1,-(sp)
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.s   t31s_finish_dynamic_done
        move.l  #V5_SPIN_TIMEOUT,d0
t31s_finish_dynamic_pending:
        move.l  t31s_pending_valid,d1
        tst.l   d1
        beq.s   t31s_finish_dynamic_pending_done
        subq.l  #1,d0
        bne.s   t31s_finish_dynamic_pending
        move.l  #4,v5_wait_stage
        bsr     v5_mark_wait_timeout
        bra.s   t31s_finish_dynamic_restore
t31s_finish_dynamic_pending_done:
        move.l  #4,v5_wait_stage
        bsr     t31s_wait_frame_start
t31s_finish_dynamic_restore:
        bsr     t30_display_end
        clr.l   t31s_display_started
t31s_finish_dynamic_done:
        movem.l (sp)+,d0-d1
        rts

hdmi_v40o_stream_success:
        lea     msg_vpv21t_stream_success_enter,a1
        move.l  #msg_vpv21t_stream_success_enter_end-msg_vpv21t_stream_success_enter,d3
        jsr     vpv21n_trace
        move.l  hdmi_v40o_live_switches,hdmi_v40o_merge_count
        move.l  hdmi_v40o_live_misses,hdmi_v40o_merge_retry
        lea     msg_hdmi_v40o_hvs_during,a1
        move.l  #msg_hdmi_v40o_hvs_during_end-msg_hdmi_v40o_hvs_during,d3
        bsr     print
        jsr     hdmi_v40o_log_hvs_ptr
        jsr     hdmi_v40o_log_hvs_all
        lea     msg_hdmi_v40o_dump_final,a1
        move.l  #msg_hdmi_v40o_dump_final_end-msg_hdmi_v40o_dump_final,d3
        bsr     print
        move.l  hdmi_v40o_hvs_last,d0
        jsr     hdmi_v40o_dump_dlist_at
        lea     msg_hdmi_v40o_merge_summary,a1
        move.l  #msg_hdmi_v40o_merge_summary_end-msg_hdmi_v40o_merge_summary,d3
        jsr     print
        move.l  hdmi_v40o_merge_count,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_merge_retry_summary,a1
        move.l  #msg_hdmi_v40o_merge_retry_summary_end-msg_hdmi_v40o_merge_retry_summary,d3
        jsr     print
        move.l  hdmi_v40o_merge_retry,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_reassert_summary,a1
        move.l  #msg_hdmi_v40o_reassert_summary_end-msg_hdmi_v40o_reassert_summary,d3
        jsr     print
        move.l  hdmi_v40o_live_reasserts,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_stream_ok,a1
        move.l  #msg_hdmi_v40o_stream_ok_end-msg_hdmi_v40o_stream_ok,d3
        bsr     print
        lea     msg_hdmi_v40o_stream_stats,a1
        move.l  #msg_hdmi_v40o_stream_stats_end-msg_hdmi_v40o_stream_stats,d3
        bsr     print
        move.l  input_bulk_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  input_return_total,d0
        bsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_paced_stats,a1
        move.l  #msg_hdmi_v40o_paced_stats_end-msg_hdmi_v40o_paced_stats,d3
        bsr     print
        move.l  v04_paced_frames,d0
        bsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_rtg_frames,a1
        move.l  #msg_hdmi_v40o_rtg_frames_end-msg_hdmi_v40o_rtg_frames,d3
        jsr     print
        move.l  hdmi_v40o_rtg_frames,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_v40c_window_skip_stats,a1
        move.l  #msg_v40c_window_skip_stats_end-msg_v40c_window_skip_stats,d3
        jsr     print
        move.l  v40c_window_wait_skips,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_resize_count,a1
        move.l  #msg_hdmi_v40o_resize_count_end-msg_hdmi_v40o_resize_count,d3
        jsr     print
        move.l  v32_switch_requests,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_hdmi_v40o_resize_apply_count,a1
        move.l  #msg_hdmi_v40o_resize_apply_count_end-msg_hdmi_v40o_resize_apply_count,d3
        jsr     print
        move.l  v32_resize_applied,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v32_resize_fail,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v32_resize_held,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_vpv21t_stream_success_return,a1
        move.l  #msg_vpv21t_stream_success_return_end-msg_vpv21t_stream_success_return,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h19_success_frame:
        ; H264RGB2: if the final frame was not already closed by the live EOS
        ; timing path, drain it now before printing diagnostics.
        bsr     t31s_finish_dynamic_stream
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.w   h19_v5_wait_fail

        ; TEST33: prove that long-run VCHIQ receive slots were actually returned.
        lea     msg31s_recycle_stats,a1
        move.l  #msg31s_recycle_stats_end-msg31s_recycle_stats,d3
        bsr     print
        move.l  rx_recycle_total,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  rx_recycle_last_slot,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  rx_recycle_last_q,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_rx_pos,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        ; Streaming has already displayed all decoded frames while MMAL/file I/O
        ; were active. Dynamic EOS drain above has also completed the last frame.
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.w   h31e_display_already_off
        bsr     t30_display_end
        clr.l   t31s_display_started
h31e_display_already_off:
        ; TEST33: print only after streaming is complete so diagnostics do not
        ; perturb the frame-critical path. Values are 50-Hz VBlank boundaries.
        lea     msg31u_timing_head,a1
        move.l  #msg31u_timing_head_end-msg31u_timing_head,d3
        bsr     print

        lea     msg31u_run,a1
        move.l  #msg31u_run_end-msg31u_run,d3
        bsr     print
        move.l  t31s_vblank_counter,d0
        bsr     print_hex32
        bsr     newline

        ; Counter 0->1 is the synchronization VBlank at which frame 1 becomes
        ; visible.  Subtract it to report the actual visible RGB interval.
        lea     msg63_visible,a1
        move.l  #msg63_visible_end-msg63_visible,d3
        bsr     print
        move.l  t31s_vblank_counter,d0
        tst.l   d0
        beq.s   t63_visible_zero
