        movem.l (sp)+,d2-d7/a2-a3
        rts

h19_output_too_big:
        lea     e19_output_too_big,a1
        move.l  #e19_output_too_big_end-e19_output_too_big,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h19_pagelist_dma_fail:
        lea     e19_pagelist_dma,a1
        move.l  #e19_pagelist_dma_end-e19_pagelist_dma,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h19_bad_reply:
        lea     e_buffer_reply,a1
        move.l  #e_buffer_reply_end-e_buffer_reply,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

; --------------------------------------------------------------------
; TEST26C - slot-safe VCHIQ stream helpers
;
; Broadcom/Linux stream semantics:
;   low 12 bits of tx_pos/rx_pos = offset within a 4096-byte slot
;   upper bits                  = index into owner->slot_queue
;
; A VCHIQ record may NOT cross a slot boundary. If the requested stride
; does not fit, reserve_space() semantics require a PADDING header filling
; the remainder, then the real record starts in the next queued slot.
; --------------------------------------------------------------------

; Input:
;   D0 = complete VCHIQ stride to reserve (already 8-byte aligned)
; Output:
;   A2 = CPU address for the record start
;   D0 = 0 success / 1 invalid queue slot
; Side effect:
;   port_tx_pos may advance to next 4-KiB boundary after writing PADDING.
h26a_reserve_tx:
        movem.l d1-d6/a0-a1,-(sp)

        ; TEST26C CRASH-FIX:
        ; D4 is the AmigaDOS output handle used by print().
        ; TEST26A/B repurposed D4 below as the slot-queue index.
        ; Save the valid DOS handle before doing so.
        move.l  d4,h26c_print_handle

        move.l  d0,d6

        move.l  port_tx_pos,d1
        move.l  d1,d2
        and.l   #$00000fff,d2
        move.l  #SLOT_SIZE,d3
        sub.l   d2,d3                  ; bytes left in current slot

        cmp.l   d3,d6
        bls.w   h26a_tx_map_start

        ; Map the current TX slot through SLAVE_QUEUE and fill its remainder
        ; with one legal PADDING record.
        move.l  d1,d4
        lsr.l   #8,d4
        lsr.l   #4,d4
        and.l   #$0000003f,d4
        lsl.l   #2,d4

        move.l  slot_ptr,a0
        lea     SLAVE_QUEUE(a0),a1
        adda.l  d4,a1
        move.l  a1,a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   #34,d5
        bcs.w   h26a_tx_fail
        cmp.l   #64,d5
        bhi.w   h26a_tx_fail

        move.l  slot_ptr,a0
        move.l  d5,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  d2,a0

        ; PADDING msgid = 0, payload size = remaining slot bytes - header.
        moveq   #0,d0
        bsr     store_le32
        lea     4(a0),a0
        move.l  d3,d0
        subq.l  #8,d0
        bsr     store_le32

        add.l   d3,d1
        move.l  d1,port_tx_pos

        addq.l  #1,h26a_padding_count

        ; TEST33: no per-slot DOS/console logging here. Restore D4 because
        ; it is the caller's AmigaDOS output handle, then continue.
        move.l  h26c_print_handle,d4

h26a_tx_map_start:
        ; Select current slot from SLAVE_QUEUE[(tx_pos >> 12) & 63].
        move.l  port_tx_pos,d1
        move.l  d1,d2
        and.l   #$00000fff,d2
        move.l  d1,d4
        lsr.l   #8,d4
        lsr.l   #4,d4
        and.l   #$0000003f,d4
        lsl.l   #2,d4

        move.l  slot_ptr,a0
        lea     SLAVE_QUEUE(a0),a1
        adda.l  d4,a1
        move.l  a1,a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   #34,d5
        bcs.w   h26a_tx_fail
        cmp.l   #64,d5
        bhi.w   h26a_tx_fail

        move.l  slot_ptr,a0
        move.l  d5,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  d2,a0
        move.l  a0,a2

        moveq   #0,d0
        movem.l (sp)+,d1-d6/a0-a1
        rts

h26a_tx_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d6/a0-a1
        rts

; Output:
;   A2 = CPU address of MASTER stream record at port_rx_pos
;   D0 = 0 success / 1 invalid queue slot
h26a_map_rx_current:
        movem.l d1-d4/a0-a1,-(sp)

        move.l  port_rx_pos,d1
        move.l  d1,d2
        and.l   #$00000fff,d2
        move.l  d1,d3
        lsr.l   #8,d3
        lsr.l   #4,d3
        and.l   #$0000003f,d3
        lsl.l   #2,d3

        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a1
        adda.l  d3,a1
        move.l  a1,a0
        bsr     load_le32
        move.l  d0,d4
        cmp.l   #2,d4
        bcs.w   h26a_rx_fail
        cmp.l   #32,d4
        bhi.w   h26a_rx_fail

        move.l  slot_ptr,a0
        move.l  d4,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  d2,a0
        move.l  a0,a2

        moveq   #0,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts

h26a_rx_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts

; --------------------------------------------------------------------
; V10P - conservative early compatibility check.
;
; The exact SPS below is the one that repeatedly returns MMAL_ENOSPC on the
; tested VideoCore IV setup (32 MiB VC RAM), even after all isolated host-side
; fixes tried through V10O.  V10P does NOT rewrite it.  It simply returns D0=1
; before MMAL/VCHIQ starts.  All other SPS data returns D0=0 unchanged.
;
; Signature: Annex-B SPS length 32, High Profile (100), Level 4.1, the exact
; ue(16) max-ref/max-buffering bit positions seen in this stream.  Additional
; bytes are checked to avoid broadly rejecting unrelated High@4.1 material.
; --------------------------------------------------------------------
v10p_check_unsupported_sps:
        movem.l d1-d3/a0,-(sp)
        moveq   #0,d0
        cmpi.l  #16,v10j_max_num_ref_frames
        bne.s   v10p_compat_done
        cmpi.l  #32,h264_sps_len
        bne.s   v10p_compat_done
        lea     h264_file_extradata,a0
        cmpi.l  #$00000001,(a0)
        bne.s   v10p_compat_done
        cmpi.b  #$67,4(a0)                 ; SPS NAL header
        bne.s   v10p_compat_done
        cmpi.b  #$64,5(a0)                 ; profile_idc = High (100)
        bne.s   v10p_compat_done
        cmpi.b  #$00,6(a0)                 ; constraint flags / reserved
        bne.s   v10p_compat_done
        cmpi.b  #$29,7(a0)                 ; level_idc = 41
        bne.s   v10p_compat_done
        cmpi.b  #$40,11(a0)                ; exact ue(16) max_num_ref_frames tail
        bne.s   v10p_compat_done
        cmpi.b  #$60,31(a0)                ; exact ue(16) max_dec_frame_buffering tail
        bne.s   v10p_compat_done
        moveq   #1,d0
v10p_compat_done:
        movem.l (sp)+,d1-d3/a0
        rts

; --------------------------------------------------------------------
; V10P - dynamic DPB/output pool sizing for high-DPB H.264.
;
; High-DPB streams that pass the V10P compatibility guard still use
; dynamic MMAL OUTPUT sizing; the host pool matches the requested count:
;   refs <= 4 : keep proven value 2
;   refs >  4 : request refs + 3, capped at 20
; The host side allocates and offers exactly the requested number of I420 output slots.
; BULK_RX remains serialized and deferred output headers are queued in a FIFO.
; Return D0 = requested OUTPUT buffer_num.
; --------------------------------------------------------------------
v10j_choose_output_count:
        move.l  v10j_max_num_ref_frames,d0
        cmpi.l  #4,d0
        bhi.s   v10j_output_high_dpb
        moveq   #2,d0
        bra.s   v10j_output_count_ready
v10j_output_high_dpb:
        addq.l  #3,d0
        cmpi.l  #20,d0
        bls.s   v10j_output_count_ready
        moveq   #20,d0
v10j_output_count_ready:
        move.l  d0,v10j_output_req_count
        rts

; --------------------------------------------------------------------
; TEST22 - h22_requeue_output
;
; Re-arm the SAME dynamic-size output DMA buffer and queue the same output
; buffer header again after its previous BULK_RX_DONE.
; Entry: shared VCHIQ memory CPU-owned.
; Return: shared VCHIQ memory CPU-owned, D0=0 OK / D0=1 failure.
; --------------------------------------------------------------------
h22_requeue_output:
        move.l  output_current_idx,d0
        bra.w   h61_queue_output_idx

; --------------------------------------------------------------------
; V10P - generic host output-pool helpers (2..20 slots).
; Slots are page aligned and separated by OUTPUT_SLOT_STRIDE.
; --------------------------------------------------------------------
v10j_output_ptr_for_idx:
        cmp.l   v10j_output_req_count,d0
        bcc.s   v10j_output_ptr_bad
        move.l  d0,d1
        mulu    #$0E70,d1                  ; v25: idx * 0xE70
        lsl.l   #8,d1                      ; idx * 0xE7000
        add.l   output_data_ptr0,d1
        moveq   #0,d0
        rts
v10j_output_ptr_bad:
        moveq   #1,d0
        rts

; D0=index. Updates current output pointer/bus/index.
h61_select_output_idx:
        move.l  d0,d2
        bsr     v10j_output_ptr_for_idx
        tst.l   d0
        bne.s   h61_select_bad
        move.l  d2,output_current_idx
        move.l  d1,output_data_ptr
        or.l    #$c0000000,d1
        move.l  d1,output_data_bus
        moveq   #0,d0
        rts
h61_select_bad:
        moveq   #1,d0
        rts

; End CachePreDMA for one returned output slot.
; D0=index. Return 0 success / 1 invalid.
h61_post_output_dma_idx:
        movem.l d1-d4/a0-a1/a6,-(sp)
        move.l  d0,d3
        cmp.l   v10j_output_req_count,d3
        bcc.s   h61_post_bad
        move.l  d3,d4
        lsl.l   #2,d4
        lea     output_dma_active_slots,a0
        tst.l   0(a0,d4.l)
        beq.s   h61_post_ok
        move.l  d3,d0
        bsr     v10j_output_ptr_for_idx
        tst.l   d0
        bne.s   h61_post_bad
        move.l  d1,a0
        move.l  output_buf_size_saved,output_dma_len
        lea     output_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        lea     output_dma_active_slots,a0
        clr.l   0(a0,d4.l)
h61_post_ok:
        moveq   #0,d0
        bra.s   h61_post_done
h61_post_bad:
        moveq   #1,d0
h61_post_done:
        movem.l (sp)+,d1-d4/a0-a1/a6
        rts

; Count currently active host output DMA slots. Return D0=count.
v10j_count_output_dma_active:
        movem.l d1-d3/a0,-(sp)
        moveq   #0,d0
        moveq   #0,d1
        lea     output_dma_active_slots,a0
        move.l  v10j_output_req_count,d2
        tst.l   d2
        beq.s   v10j_count_dma_done
v10j_count_dma_loop:
        move.l  (a0)+,d3
        tst.l   d3
        beq.s   v10j_count_dma_next
        addq.l  #1,d0
v10j_count_dma_next:
        addq.l  #1,d1
        cmp.l   d2,d1
        bcs.s   v10j_count_dma_loop
v10j_count_dma_done:
        movem.l (sp)+,d1-d3/a0
        rts

; Queue one empty MMAL output buffer. D0=index 0..requested_count-1.
h61_queue_output_idx:
        movem.l d1-d4/d7/a0-a3/a6,-(sp)
        move.l  d0,h61_queue_idx
        move.l  d0,d3
        bsr     v10j_output_ptr_for_idx
        tst.l   d0
        bne.w   h61_queue_fail
        move.l  d1,h61_queue_ptr
        move.l  d3,d2
        add.l   #MMAL_OUTPUT_BUFFER_CONTEXT0,d2
        move.l  d2,h61_queue_context

        ; VideoCore will own/write this slot until its callback/BULK_RX completes.
        move.l  output_buf_size_saved,output_dma_len
        move.l  h61_queue_ptr,a0
        lea     output_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   h61_queue_ptr,d0
        bne.w   h61_queue_fail
        move.l  output_dma_len,d1
        cmp.l   output_buf_size_saved,d1
        bcs.w   h61_queue_fail
        move.l  h61_queue_idx,d4
        lsl.l   #2,d4
        lea     output_dma_active_slots,a0
        move.l  #1,0(a0,d4.l)

        move.l  #304,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   h61_queue_fail_post

        move.l  a2,a0
        move.l  #75,d7
h61_clear_output_msg:
        clr.l   (a0)+
        dbra    d7,h61_clear_output_msg

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        bsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  h61_queue_context,d0
        bsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  output_component_handle,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  output_port_handle,d0
        bsr     store_le32
        lea     44(a2),a0
        move.l  h61_queue_context,d0
        bsr     store_le32

        lea     76(a2),a0
        move.l  h61_queue_ptr,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  output_buf_size_saved,d0
        bsr     store_le32

        lea     96(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #304,d0
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,output_armed

        bsr     dma_pre_all
        move.l  output_armed,d0
        tst.l   d0
        beq.s   h61_queue_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
h61_queue_no_bell:
        bsr     short_delay
        bsr     dma_post_all
        moveq   #0,d0
        bra.s   h61_queue_done

h61_queue_fail_post:
        move.l  h61_queue_idx,d0
        bsr     h61_post_output_dma_idx
h61_queue_fail:
        moveq   #1,d0
h61_queue_done:
        movem.l (sp)+,d1-d4/d7/a0-a3/a6
        rts

; --------------------------------------------------------------------
; TEST26 - h22_load_frame_data
;
; Read the next raw Annex-B file block, or one MKV access-unit chunk, into the reusable input DMA buffer.
; No NAL/access-unit/frame parsing is done here.
;
; Fixed request size: 65536 bytes.
; TEST33 akzeptiert beliebig viele volle 65536-Byte-Bloecke, einen letzten Teilblock,
; danach liefert Read() 0 -> echtes EOF
;
; Return:
;   D0=0  data block ready
;   D0=2  clean EOF after at least one successfully read byte
;   D0=1  open/read/truncation failure
; Shared VCHIQ memory and input DMA buffer must be CPU-owned.
; --------------------------------------------------------------------
h22_load_frame_data:
        movem.l d1-d7/a0-a2/a6,-(sp)

        ; V10P MKV path: fill the 256-KiB MMAL input slot directly
        ; from the Matroska source. D0=0 data, 2 clean EOF, 1 failure. The live
        ; demux also returns MMAL CONFIG/FRAME_START/FRAME_END flags per fragment.
        tst.l   v12e_input_is_mp4
        beq.s   h22_check_mkv
        jsr     v12e_next_annexb_chunk
        cmpi.l  #2,d0
        beq.w   h25_file_eof
        tst.l   d0
        bne.w   h23_file_read_fail
        move.l  v12e_chunk_len,d0
        move.l  d0,t23_last_read
        clr.l   current_h264_flags
        move.l  v04_mp4_new_sample,d1
        beq.s   hdmi_v40o_mp4_no_pace
        bsr     v04_pace_new_frame
hdmi_v40o_mp4_no_pace:
        bra.w   h22_accept_block
h22_check_mkv:
        tst.l   v10b_input_is_mkv
        beq.w   h22_raw_file_path
        jsr     v10b_next_annexb_chunk
        cmpi.l  #2,d0
        beq.w   h25_file_eof
        tst.l   d0
        bne.w   h23_file_read_fail
        move.l  v10b_chunk_len,d0
        move.l  d0,t23_last_read
        move.l  v10g_chunk_flags,d1
        move.l  d1,current_h264_flags
        andi.l  #MMAL_BUFFER_FLAG_FRAME_START,d1
        beq.s   hdmi_v40o_mkv_no_pace
        bsr     v04_pace_new_frame
hdmi_v40o_mkv_no_pace:
        bra.w   h22_accept_block

h22_raw_file_path:
        clr.l   current_h264_flags
        move.l  t23_file_handle,d0
        bne.w   h25_file_is_open

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   h23_file_open_fail
        move.l  d0,t23_file_handle
        clr.l   t23_total_read

        lea     msg23_file_open,a1
        move.l  #msg23_file_open_end-msg23_file_open,d3
        bsr     print

h25_file_is_open:
        move.l  t23_file_handle,d1
        move.l  bulk_data_ptr,d2
        move.l  #H264_STREAM_CHUNK,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,t23_last_read
        tst.l   d0
        bmi.w   h23_file_read_fail
        beq.w   h25_file_eof

h22_accept_block:
        ; Both raw-H264 and MKV streaming deliver an ordinary positive Annex-B
        ; chunk here. t23_total_read therefore counts bytes actually fed to MMAL.
        move.l  t23_last_read,d0
        move.l  t23_total_read,d1
        add.l   d0,d1
        move.l  d1,t23_total_read

        move.l  d0,current_h264_len
        addq.l  #3,d0
        and.l   #$fffffffc,d0
        move.l  d0,current_h264_bulk_len

        ; V10P diagnostic snapshot: exact latest MKV chunk about to be published.
        tst.l   v10b_input_is_mkv
        beq.w   v10h_diag_chunk_done
        move.l  v10b_video_block_count,v10h_last_frame_no
        move.l  v10h_current_frame_payload,v10h_last_frame_payload
        move.l  v10b_last_pts_ticks,v10h_last_pts_ticks
        move.l  v10b_nal_count,v10h_last_nal_count
        move.l  v10h_chunk_fragment_no,v10h_last_fragment_no
        move.l  current_h264_len,v10h_last_chunk_len
        move.l  current_h264_flags,v10h_last_chunk_flags
        clr.l   v10h_last_nal_type
        move.l  current_h264_len,d1
        cmpi.l  #5,d1
        bcs.s   v10h_diag_chunk_done
        move.l  bulk_data_ptr,a0
        moveq   #0,d1
        move.b  4(a0),d1
        andi.l  #$0000001F,d1
        move.l  d1,v10h_last_nal_type
v10h_diag_chunk_done:

        ; Clear up to three bulk-rounding guard bytes after the actual payload.
        move.l  bulk_data_ptr,a1
        adda.l  current_h264_len,a1
        clr.b   (a1)+
        clr.b   (a1)+
        clr.b   (a1)+

        move.l  bulk_pagelist_ptr,a0
        move.l  current_h264_bulk_len,d0
        bsr     store_le32

        moveq   #0,d0
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

h25_file_eof:
        move.l  t23_total_read,d0
        tst.l   d0
        beq.w   h23_file_read_fail

        tst.l   v12e_input_is_mp4
        beq.s   h25_check_mkv_eof
