        lea     msg_v10b_stream_pos,a1
        move.l  #msg_v10b_stream_pos_end-msg_v10b_stream_pos,d3
        bsr     print
        move.l  v10b_abs_pos,d0
        bsr     print_hex32
        bsr     newline
        bra.s   h23_load_frame_fail
h23_raw_read_error:
