; --------------------------------------------------------------------
; TEST33 - feed next H264 block into a free MMAL input pool slot.
;
; Return:
;   D0=0 block published; shared VCHIQ memory DMA-owned
;   D0=2 clean EOF already reached; CPU-owned
;   D0=3 no free slot / bulk still active; CPU-owned
;   D0=1 failure
; --------------------------------------------------------------------
t31s_feed_next_input:
        movem.l d1-d7/a0-a3/a6,-(sp)

        ; VPv59: hard global BULK_TX invariant. Audio and video share the
        ; same VCHIQ bulk completion path, so absolutely no video BULK_TX may
        ; start while an audio BULK_TX is pending. The main poll caller already
        ; enforces this; keep the guard here too so every direct/wrapper caller
        ; is safe and count any attempt that reaches this local backstop.
        move.l  input_bulk_pending,d0
        tst.l   d0
        bne.w   t31s_feed_no_slot
        tst.l   vpv39_audio_bulk_pending
        beq.s   t31s_bulk_transport_idle
        addq.l  #1,vpv58_bulk_guard_hits
        bra.w   t31s_feed_no_slot
t31s_bulk_transport_idle:
        move.l  input_eof_seen,d0
        tst.l   d0
        bne.w   t31s_feed_eof_already

        ; V40 size restart is a deliberate short stream end.  Do not race
        ; through the remainder of a long movie: as soon as the current bulk
        ; transport is idle, publish normal decoder EOS and enter the proven
        ; cleanup path.
        tst.l   v32r_restart_armed
        beq.s   v32r_feed_continue
        move.l  #1,input_eof_seen
        moveq   #2,d0
        bra.w   t31s_feed_done
v32r_feed_continue:

        ; Find a host-owned pool slot.
        lea     input_slot_state,a0
        moveq   #0,d6
        moveq   #INPUT_POOL_COUNT-1,d7
t31s_find_free_slot:
        tst.l   (a0)
        beq.w   t31s_have_free_slot
        addq.l  #4,a0
        addq.l  #1,d6
        dbra    d7,t31s_find_free_slot
        bra.w   t31s_feed_no_slot

t31s_have_free_slot:
        move.l  #1,(a0)
        addq.l  #1,input_in_use_count
        move.l  d6,bulk_current_slot

        ; slot_base = pool_base + slot * 0x42000.
        ; 0x42000 = 66 * 4096, so multiply the small slot index by 66
        ; and then convert pages -> bytes without requiring a 32-bit MUL.
        move.l  d6,d1
        mulu.w  #66,d1
        lsl.l   #8,d1
        lsl.l   #4,d1
        move.l  bulk_pool_base,d0
        add.l   d1,d0
        move.l  d0,bulk_data_ptr
        move.l  d0,d2
        add.l   #INPUT_PAGELIST_OFFSET,d2
        move.l  d2,bulk_pagelist_ptr

        move.l  d0,d1
        or.l    #$c0000000,d1
        move.l  d1,bulk_data_bus
        move.l  d2,d1
        or.l    #$c0000000,d1
        move.l  d1,bulk_pagelist_bus

        move.l  d6,d0
        add.l   #MMAL_BUFFER_CONTEXT_BASE,d0
        move.l  d0,bulk_current_context

        ; Read the next 65536-byte Annex-B chunk into this slot.
        bsr     h22_load_frame_data
        cmp.l   #2,d0
        beq.w   t31s_feed_hit_eof
        tst.l   d0
        bne.w   t31s_feed_fail_release

        ; TEST33 multi-page VCHIQ pagelist.  Broadcom's pagelist format
        ; compresses physically consecutive pages: the low 12 bits of addrs[0]
        ; hold the number of *following* consecutive pages.  Our slot data is
        ; page aligned and contiguous, so one address entry describes up to
        ; all 16 pages of the 0x10000-byte MMAL input buffer.
        move.l  bulk_pagelist_ptr,a0
        move.l  current_h264_bulk_len,d0
        bsr     store_le32
        move.l  bulk_pagelist_ptr,a0
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)

        move.l  current_h264_bulk_len,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0              ; ceil(bytes/4096) = page count
        subq.l  #1,d0              ; encoded as following-page count
        move.l  bulk_data_bus,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        bsr     store_le32

        ; Give this slot's data page + pagelist page to DMA.
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   bulk_data_ptr,d0
        bne.w   t31s_feed_fail_dma
        move.l  bulk_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   t31s_feed_fail_dma
        move.l  #1,bulk_dma_active

        ; Worker11 + one serialized BULK_TX.
        move.l  #320,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   t31s_feed_fail_dma_post

        move.l  a2,a0
        move.l  #79,d7
t31s_clear_input_control:
        clr.l   (a0)+
        dbra    d7,t31s_clear_input_control

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        bsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  bulk_current_context,d0
        bsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  component_handle,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  input_port_handle,d0
        bsr     store_le32
        lea     44(a2),a0
        move.l  bulk_current_context,d0
        bsr     store_le32

        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  #INPUT_DATA_SIZE,d0
        bsr     store_le32
        lea     84(a2),a0
        move.l  current_h264_len,d0
        bsr     store_le32
        lea     92(a2),a0
        move.l  current_h264_flags,d0
        bsr     store_le32

        lea     96(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        bsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        bsr     store_le32
        lea     12(a3),a0
        move.l  current_h264_bulk_len,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #320,d0
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,bulk_armed

        move.l  #1,input_bulk_pending
        clr.l   bulk_done_seen
        bsr     dma_pre_all
        move.l  bulk_armed,d0
        tst.l   d0
        beq.w   t31s_feed_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
t31s_feed_no_bell:
        moveq   #0,d0
        bra.w   t31s_feed_done

t31s_feed_hit_eof:
        ; The selected slot was never published; release it immediately.
        move.l  bulk_current_slot,d1
        lsl.l   #2,d1
        lea     input_slot_state,a0
        adda.l  d1,a0
        clr.l   (a0)
        subq.l  #1,input_in_use_count
        move.l  #1,input_eof_seen
        moveq   #2,d0
        bra.w   t31s_feed_done

t31s_feed_fail_dma_post:
        move.l  bulk_dma_active,d0
        tst.l   d0
        beq.w   t31s_feed_fail_release
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   bulk_dma_active
        bra.w   t31s_feed_fail_release

t31s_feed_fail_dma:
        clr.l   bulk_dma_active

t31s_feed_fail_release:
        move.l  bulk_current_slot,d1
        lsl.l   #2,d1
        lea     input_slot_state,a0
        adda.l  d1,a0
        clr.l   (a0)
        subq.l  #1,input_in_use_count
        moveq   #1,d0
        bra.w   t31s_feed_done

t31s_feed_no_slot:
        moveq   #3,d0
        bra.w   t31s_feed_done

t31s_feed_eof_already:
        moveq   #2,d0

t31s_feed_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Legacy compatibility wrapper; TEST33 uses t31s_feed_next_input directly.
h22_resend_input:
        bra.w   t31s_feed_next_input

; --------------------------------------------------------------------
; TEST20 - save_frame20
;
; Writes the decoded I420 buffer to:
;   f20.i420
;
; Uses AmigaDOS:
;   Open(name, MODE_NEWFILE)
;   Write(handle, buffer, 115200)
;   Close(handle)
;
; Return D0=0 success, D0=1 failure.
; Does not modify the decoder/VCHIQ state.
; --------------------------------------------------------------------
save_frame20:
        movem.l d1-d3/a0-a1/a6,-(sp)

        move.l  a5,a6
        lea     frame20_name,a0
        move.l  a0,d1
        move.l  #MODE_NEWFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   save_frame20_fail

        move.l  d0,frame20_handle

        move.l  d0,d1
        move.l  output_data_ptr,d2
        move.l  #$0001c200,d3
        move.l  a5,a6
        jsr     Write(a6)
        move.l  d0,frame20_written

        ; Always close the file handle.
        move.l  frame20_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   frame20_handle

        move.l  frame20_written,d0
        cmp.l   #$0001c200,d0
        bne.w   save_frame20_fail

        moveq   #0,d0
        movem.l (sp)+,d1-d3/a0-a1/a6
        rts

save_frame20_fail:
        ; If Open succeeded but Write path failed before Close, close it.
        move.l  frame20_handle,d0
        beq.w   save_frame20_fail_done
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   frame20_handle

save_frame20_fail_done:
        moveq   #1,d0
        movem.l (sp)+,d1-d3/a0-a1/a6
        rts

; --------------------------------------------------------------------
; Failure paths
; --------------------------------------------------------------------
fail53_shadow_alloc:
        lea     e53_shadow_alloc,a1
        move.l  #e53_shadow_alloc_end-e53_shadow_alloc,d3
        bsr     print
        bra.w   close_prog

fail33_fast_alloc:
        lea     e33_fast_alloc,a1
        move.l  #e33_fast_alloc_end-e33_fast_alloc,d3
        bsr     print
        bra.w   close_prog

fail30_store_alloc:
        lea     e30_store_alloc,a1
        move.l  #e30_store_alloc_end-e30_store_alloc,d3
        bsr     print
        bra.w   close_prog

fail_alloc:
        lea     e_alloc,a1
        move.l  #e_alloc_end-e_alloc,d3
        bsr     print
        bra.w   close_prog

fail_range:
        lea     e_range,a1
        move.l  #e_range_end-e_range,d3
        bsr     print
        bra.w   close_prog

fail_dma_len:
        lea     e_dma_len,a1
        move.l  #e_dma_len_end-e_dma_len,d3
        bsr     print
        bra.w   close_prog

fail_identity:
        lea     e_identity,a1
        move.l  #e_identity_end-e_identity,d3
        bsr     print
        bra.w   close_prog

fail_prop_alloc:
        lea     e_prop_alloc,a1
        move.l  #e_prop_alloc_end-e_prop_alloc,d3
        bsr     print
        bra.w   close_prog

fail_prop_identity:
        lea     e_prop_identity,a1
        move.l  #e_prop_identity_end-e_prop_identity,d3
        bsr     print
        bra.w   close_prog

fail_tx_timeout:
        lea     e_tx,a1
        move.l  #e_tx_end-e_tx,d3
        bsr     print
        bra.w   close_prog

fail_rx_timeout:
        lea     e_rx,a1
        move.l  #e_rx_end-e_rx,d3
        bsr     print
        bra.w   close_prog

fail_fw_status:
        lea     e_fw,a1
        move.l  #e_fw_end-e_fw,d3
        bsr     print
        bra.w   close_prog

fail_channelbase:
        lea     e_chan,a1
        move.l  #e_chan_end-e_chan,d3
        bsr     print
        bra.w   close_prog

fail_v9d_resource:
        lea     e_v9d_resource,a1
        move.l  #e_v9d_resource_end-e_v9d_resource,d3
        bsr     print
        bra.w   close_prog

fail_master_init:
        lea     e_master,a1
        move.l  #e_master_end-e_master,d3
        bsr     print
        bra.w   close_prog

fail_connect_timeout:
        ; No CONNECT reply during this polling window.
        ; Shared memory is currently in DMA ownership because the polling
        ; loop called dma_pre_all before branching here.
        move.l  connect_retries,d0
        tst.l   d0
        beq.w   connect_retries_exhausted

        subq.l  #1,d0
        move.l  d0,connect_retries

        ; Re-acquire CPU view and first check whether the reply arrived
        ; exactly at the polling boundary.
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   #8,d0
        bcc.w   connect_response_seen_a

        ; Re-assert the same remote event. Do NOT write another CONNECT and
        ; do NOT advance tx_pos again.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,connect_retry_arm

        move.l  connect_retries,d0
        cmp.l   #1,d0
        beq.w   connect_retry_msg2

        lea     msg_retry3,a1
        move.l  #msg_retry3_end-msg_retry3,d3
        bsr     print
        bra.w   connect_retry_diag

connect_retry_msg2:
        lea     msg_retry2,a1
        move.l  #msg_retry2_end-msg_retry2,d3
        bsr     print

connect_retry_diag:
        lea     msg_retry_arm,a1
        move.l  #msg_retry_arm_end-msg_retry_arm,d3
        bsr     print
        move.l  connect_retry_arm,d0
        bsr     print_hex32
        bsr     newline

        ; Publish fired=1 to VideoCore.
        bsr     dma_pre_all

        ; Follow VCHIQ remote-event semantics: ring only if VC is armed.
        move.l  connect_retry_arm,d0
        tst.l   d0
        beq.w   connect_retry_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_retry_bell,a1
        move.l  #msg_retry_bell_end-msg_retry_bell,d3
        bsr     print
        bra.w   connect_retry_wait

connect_retry_no_bell:
        lea     msg_retry_nobell,a1
        move.l  #msg_retry_nobell_end-msg_retry_nobell,d3
        bsr     print

connect_retry_wait:
        move.l  #POLL_COUNT,d7
        bra.w   connect_poll_loop_a

connect_retries_exhausted:
        ; Final failure. Re-acquire CPU ownership only for diagnostics.
        bsr     dma_post_all

        lea     e_connect_retry,a1
        move.l  #e_connect_retry_end-e_connect_retry,d3
        bsr     print

