; Common PORT_INFO_GET unwind.  Enter by BRA, so there is no extra helper
; return address.  Nested graph calls return to v12a_setup_isp_graph; direct
; startup calls keep the historical fatal unwind to close_prog.
fail_port_return_or_close:
        tst.l   v12a_local_get_active
        beq.s   fail_port_return_legacy
        movem.l (sp)+,d2-d7/a2-a3
        moveq   #1,d0
        rts
fail_port_return_legacy:
        movem.l (sp)+,d2-d7/a2-a3
        addq.l  #4,sp
        bra.w   close_prog

fail_set_timeout:
        lea     e_set_timeout,a1
        move.l  #e_set_timeout_end-e_set_timeout,d3
        bsr     print
        tst.l   v12c_local_set_active
        beq.s   fail_set_timeout_legacy
        ; SET timeout loop also ended after CachePreDMA. Reacquire CPU side.
        bsr     dma_post_all
        clr.l   v12c_local_set_active
        movem.l (sp)+,d2-d7/a2-a3
        moveq   #1,d0
        rts
fail_set_timeout_legacy:
        movem.l (sp)+,d2-d7/a2-a3
        addq.l  #4,sp
        bra.w   close_prog

