        bsr     print
        ; Sanity failure occurs before the message is handed to VideoCore.
        bra.w   fail_set_return_or_close

; Common PORT_INFO_SET unwind. Enter by BRA, no extra stack frame.
fail_set_return_or_close:
        tst.l   v12c_local_set_active
        beq.s   fail_set_return_legacy
        clr.l   v12c_local_set_active
        movem.l (sp)+,d2-d7/a2-a3
