        section bss,bss
        even
v9d_res_ptr: ds.l 1
slot_alloc: ds.l 1
slot_ptr: ds.l 1
slot_phys: ds.l 1
slot_bus: ds.l 1
dma_len: ds.l 1
prop_alloc: ds.l 1
prop_ptr: ds.l 1
prop_phys: ds.l 1
