; V10P firmware ARM/VideoCore memory split diagnostic.
; Reuses the proven normal prop_ptr/prop_phys buffer; no extra DMA allocation.
v10k_arm_base: ds.l 1
v10k_arm_size: ds.l 1
v10k_vc_base: ds.l 1
v10k_vc_size: ds.l 1
v10k_query_result: ds.l 1

remote_tx_before: ds.l 1
remote_slot0: ds.l 1
vc_armed: ds.l 1
stabil_fired: ds.l 1
rx_msgid: ds.l 1
rx_size: ds.l 1
remote_seen: ds.l 1
connect_retries: ds.l 1
connect_retry_arm: ds.l 1
open_armed: ds.l 1
open_msgid: ds.l 1
open_size: ds.l 1
mmal_remote_port: ds.l 1
mmal_peer_ver: ds.l 1
mmal_rx_before: ds.l 1
data_armed: ds.l 1
data_tx_msgid: ds.l 1
data_rx_msgid: ds.l 1
data_rx_size: ds.l 1
worker_magic: ds.l 1
worker_type: ds.l 1
worker_context: ds.l 1
worker_status: ds.l 1
worker_flags: ds.l 1
worker_major: ds.l 1
worker_minor: ds.l 1
worker_minimum: ds.l 1

comp_rx_before: ds.l 1
comp_armed: ds.l 1
comp_tx_msgid: ds.l 1
comp_rx_msgid: ds.l 1
comp_rx_size: ds.l 1
comp_magic: ds.l 1
comp_type: ds.l 1
comp_context: ds.l 1
comp_hdr_status: ds.l 1
