        dc.w 80,60                       ; LeftEdge, TopEdge
        dc.w 216,144                     ; Width, Height
        dc.b $ff,$ff                     ; DetailPen, BlockPen = screen defaults
        dc.l IDCMP_CLOSEWINDOW|IDCMP_VANILLAKEY
        dc.l WFLG_DRAGBAR|WFLG_CLOSEGADGET|WFLG_ACTIVATE
        dc.l 0                           ; FirstGadget
        dc.l 0                           ; CheckMark
        dc.l hdmi_v40o_window_title
        dc.l 0                           ; Screen (ignored for WBENCHSCREEN)
        dc.l 0                           ; BitMap
        dc.w 80,60                       ; V40J defensive min size
