        dc.w $000,$444,$777,$AAA,$FFF,$B74,$235,$DCB
        dc.w $B41,$611,$568,$210,$A99,$D86,$865,$346
        dc.w $821,$D74,$124,$DB8,$A53,$421,$942,$643
        dc.w $457,$A87,$C53,$E93,$EED,$C85,$BBA,$A31

