t44_pair6_lut_end:

; --------------------------------------------------------------------
; V10: the 18.5-MiB HAM speed LUTs are no longer embedded in this Hunk.
; ham.bin / edge.bin / state.bin are loaded into Fast RAM at runtime.
; --------------------------------------------------------------------
        even


; ====================================================================
; V10 - SECOND CLI INVOCATION LIVE-TRANSPORT PROBE
; Appended after LUT data intentionally: existing V9C code/data addresses and
; fragile 68000 PC-relative displacements remain unchanged. All calls/data
; accesses in this block use absolute addressing.
; ====================================================================
        even
        section bss,bss
v9d_remote_port_abs: ds.l 1
v9d_open_msgid_abs: ds.l 1
v9d_open_size_abs: ds.l 1
v9d_peer_version_abs: ds.l 1
v9d_data_msgid_abs: ds.l 1
v9d_data_size_abs: ds.l 1
v9d_probe_magic_abs: ds.l 1
v9d_probe_type_abs: ds.l 1
v9d_probe_context_abs: ds.l 1
v9d_probe_status_abs: ds.l 1
v9d_probe_major_abs: ds.l 1
v9d_probe_minor_abs: ds.l 1
v9d_probe_minimum_abs: ds.l 1

        section code,code
v9d_second_start_probe:
        movem.l d1-d7/a0-a3,-(sp)

        ; V12F: all reused generic ISP/MMAL workers must address local service 1.
        move.l  #1,v12f_local_port
        move.l  #$00001000,v12f_local_bits

        ; v9d_try_attach returns with shared slot RAM in DMA ownership.
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        jsr     load_le32
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        move.l  d0,port_rx_pos

        lea     msg_v9d_probe_start,a1
        move.l  #msg_v9d_probe_start_end-msg_v9d_probe_start,d3
        jsr     print
        lea     msg_v9d_probe_tx0,a1
        move.l  #msg_v9d_probe_tx0_end-msg_v9d_probe_tx0,d3
        jsr     print
        move.l  port_tx_pos,d0
        jsr     print_hex32
        lea     msg_v9d_probe_rx0,a1
        move.l  #msg_v9d_probe_rx0_end-msg_v9d_probe_rx0,d3
        jsr     print
        move.l  port_rx_pos,d0
        jsr     print_hex32
        jsr     newline

        ; OPEN('mmal') from NEW local VCHIQ port 1.
        move.l  #24,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9d_probe_fail_cpu
        move.l  a2,a3
        move.l  #VCHIQ_MSG_OPEN,d0
        or.l    #$00001000,d0
        move.l  a3,a0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #12,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_FOURCC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #1,d0
        jsr     store_le32
        lea     16(a3),a0
        move.b  #MMAL_VER,(a0)
        clr.b   1(a0)
        move.b  #MMAL_VER_MIN,2(a0)
        clr.b   3(a0)

        add.l   #24,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6

        lea     msg_v9d_open_sent,a1
        move.l  #msg_v9d_open_sent_end-msg_v9d_open_sent,d3
        jsr     print
        move.l  port_tx_pos,d0
        jsr     print_hex32
        lea     msg_v9d_probe_arm,a1
        move.l  #msg_v9d_probe_arm_end-msg_v9d_probe_arm,d3
        jsr     print
        move.l  d6,d0
        jsr     print_hex32
        jsr     newline

        jsr     dma_pre_all
        tst.l   d6
        beq.s   v9d_open_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v9d_open_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
v9d_open_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v9d_open_have_record
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v9d_open_wait
        jsr     dma_post_all
        lea     msg_v9d_open_timeout,a1
        move.l  #msg_v9d_open_timeout_end-msg_v9d_open_timeout,d3
        jsr     print
        bra.w   v9d_probe_fail_cpu

v9d_open_have_record:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   v9d_probe_fail_cpu
        move.l  a2,a3
        move.l  a3,a0
        jsr     load_le32
        move.l  d0,v9d_open_msgid_abs
        lea     4(a3),a0
        jsr     load_le32
        move.l  d0,v9d_open_size_abs

        move.l  v9d_open_msgid_abs,d0
        and.l   #$FF000000,d0
        beq.w   v9d_open_skip_record
        cmp.l   #VCHIQ_MSG_CLOSE,d0
        beq.w   v9d_open_maybe_close
        cmp.l   #VCHIQ_MSG_OPENACK,d0
        bne.w   v9d_open_skip_record
        move.l  v9d_open_msgid_abs,d0
        and.l   #$00000FFF,d0
        cmp.l   #1,d0
        bne.w   v9d_open_skip_record

        move.l  v9d_open_msgid_abs,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        move.l  d0,v9d_remote_port_abs
        move.l  d0,mmal_remote_port
        move.l  v9d_open_size_abs,d0
        cmp.l   #2,d0
        bcs.w   v9d_probe_fail_cpu
        lea     8(a3),a0
        jsr     load_le16
        move.l  d0,v9d_peer_version_abs

        lea     msg_v9d_open_ok,a1
        move.l  #msg_v9d_open_ok_end-msg_v9d_open_ok,d3
        jsr     print
        move.l  v9d_remote_port_abs,d0
        jsr     print_hex32
        lea     msg_v9d_open_ver,a1
        move.l  #msg_v9d_open_ver_end-msg_v9d_open_ver,d3
        jsr     print
        move.l  v9d_peer_version_abs,d0
        jsr     print_hex32
        jsr     newline
        move.l  v9d_open_size_abs,d0
        jsr     v9_consume_rx
        bra.w   v9d_send_get_version

v9d_open_maybe_close:
        move.l  v9d_open_msgid_abs,d0
        and.l   #$00000FFF,d0
        cmp.l   #1,d0
        bne.w   v9d_open_skip_record
        lea     msg_v9d_open_rejected,a1
        move.l  #msg_v9d_open_rejected_end-msg_v9d_open_rejected,d3
        jsr     print
        bra.w   v9d_probe_fail_cpu

v9d_open_skip_record:
        move.l  v9d_open_size_abs,d0
        jsr     v9_consume_rx
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9d_open_wait
        jsr     dma_post_all
        lea     msg_v9d_open_timeout,a1
        move.l  #msg_v9d_open_timeout_end-msg_v9d_open_timeout,d3
        jsr     print
        bra.w   v9d_probe_fail_cpu

v9d_send_get_version:
        move.l  #48,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9d_probe_fail_cpu
        move.l  a2,a3
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        move.l  d0,v9d_data_msgid_abs
        move.l  a3,a0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #40,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_GET_VERSION,d0
        jsr     store_le32
        lea     16(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  #$9D000001,d0
        jsr     store_le32
        lea     24(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     28(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     32(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     36(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     40(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     44(a3),a0
        moveq   #0,d0
        jsr     store_le32

        add.l   #48,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6

        lea     msg_v9d_getver_sent,a1
        move.l  #msg_v9d_getver_sent_end-msg_v9d_getver_sent,d3
        jsr     print
        move.l  v9d_data_msgid_abs,d0
        jsr     print_hex32
        lea     msg_v9d_probe_tx1,a1
        move.l  #msg_v9d_probe_tx1_end-msg_v9d_probe_tx1,d3
        jsr     print
        move.l  port_tx_pos,d0
        jsr     print_hex32
        jsr     newline

        jsr     dma_pre_all
        tst.l   d6
        beq.s   v9d_data_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v9d_data_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
v9d_data_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v9d_data_have_record
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v9d_data_wait
        jsr     dma_post_all
        lea     msg_v9d_data_timeout,a1
        move.l  #msg_v9d_data_timeout_end-msg_v9d_data_timeout,d3
        jsr     print
        bra.w   v9d_probe_fail_cpu

v9d_data_have_record:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   v9d_probe_fail_cpu
        move.l  a2,a3
        move.l  a3,a0
        jsr     load_le32
        move.l  d0,v9d_data_msgid_abs
        lea     4(a3),a0
        jsr     load_le32
        move.l  d0,v9d_data_size_abs
        move.l  v9d_data_msgid_abs,d0
        and.l   #$FF000000,d0
        beq.w   v9d_data_skip_record
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   v9d_data_skip_record
        move.l  v9d_data_msgid_abs,d0
        and.l   #$00000FFF,d0
        cmp.l   #1,d0
        bne.w   v9d_data_skip_record
        move.l  v9d_data_msgid_abs,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        cmp.l   v9d_remote_port_abs,d0
        bne.w   v9d_data_skip_record
        move.l  v9d_data_size_abs,d0
        cmp.l   #40,d0
        bcs.w   v9d_probe_fail_cpu

        lea     8(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_magic_abs
        lea     12(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_type_abs
        lea     20(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_context_abs
        lea     24(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_status_abs
        lea     36(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_major_abs
        lea     40(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_minor_abs
        lea     44(a3),a0
        jsr     load_le32
        move.l  d0,v9d_probe_minimum_abs

        cmpi.l  #MMAL_MAGIC,v9d_probe_magic_abs
        bne.w   v9d_probe_bad_reply
        cmpi.l  #MMAL_GET_VERSION,v9d_probe_type_abs
        bne.w   v9d_probe_bad_reply
        cmpi.l  #$9D000001,v9d_probe_context_abs
        bne.w   v9d_probe_bad_reply
        tst.l   v9d_probe_status_abs
        bne.w   v9d_probe_bad_reply

        lea     msg_v9d_getver_ok,a1
        move.l  #msg_v9d_getver_ok_end-msg_v9d_getver_ok,d3
        jsr     print
        move.l  v9d_probe_major_abs,d0
        jsr     print_hex32
        lea     msg_v9d_probe_minor,a1
        move.l  #msg_v9d_probe_minor_end-msg_v9d_probe_minor,d3
        jsr     print
        move.l  v9d_probe_minor_abs,d0
        jsr     print_hex32
        lea     msg_v9d_probe_min,a1
        move.l  #msg_v9d_probe_min_end-msg_v9d_probe_min,d3
        jsr     print
        move.l  v9d_probe_minimum_abs,d0
        jsr     print_hex32
        jsr     newline
        move.l  v9d_data_size_abs,d0
        jsr     v9_consume_rx
        ; VPv59 AUDIO-ONLY second start: local-1 MMAL service + GET_VERSION are
        ; ready.  Do not create a second H264 decoder.  Reuse the same audio-only
        ; routine; generic MMAL helpers already honor v12f_local_port/local_bits.
        lea     msg_vpv59_second_audio,a1
        move.l  #msg_vpv59_second_audio_end-msg_vpv59_second_audio,d3
        jsr     print
        jsr     vpv59_audio_only_run
        bra.w   v9d_probe_done

v9d_data_skip_record:
        move.l  v9d_data_size_abs,d0
        jsr     v9_consume_rx
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9d_data_wait
        jsr     dma_post_all
        lea     msg_v9d_data_timeout,a1
        move.l  #msg_v9d_data_timeout_end-msg_v9d_data_timeout,d3
        jsr     print
        bra.s   v9d_probe_fail_cpu

v9d_probe_bad_reply:
        lea     msg_v9d_bad_reply,a1
        move.l  #msg_v9d_bad_reply_end-msg_v9d_bad_reply,d3
        jsr     print
        move.l  v9d_probe_magic_abs,d0
        jsr     print_hex32
        lea     msg_v9d_bad_type,a1
        move.l  #msg_v9d_bad_type_end-msg_v9d_bad_type,d3
        jsr     print
        move.l  v9d_probe_type_abs,d0
        jsr     print_hex32
        lea     msg_v9d_bad_ctx,a1
        move.l  #msg_v9d_bad_ctx_end-msg_v9d_bad_ctx,d3
        jsr     print
        move.l  v9d_probe_context_abs,d0
        jsr     print_hex32
        lea     msg_v9d_bad_status,a1
        move.l  #msg_v9d_bad_status_end-msg_v9d_bad_status,d3
        jsr     print
        move.l  v9d_probe_status_abs,d0
        jsr     print_hex32
        jsr     newline
v9d_probe_fail_cpu:
        jsr     dma_pre_all
        lea     msg_v9d_probe_fail,a1
        move.l  #msg_v9d_probe_fail_end-msg_v9d_probe_fail,d3
        jsr     print
        moveq   #1,d0
v9d_probe_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

        section data,data
msg_v9d_probe_start:
        dc.b 10,"[V10P] ZWEITER START: Live-VCHIQ wird weiterbenutzt; kein VCHIQ_INIT, kein CONNECT.",10
        dc.b "[V10P] Ziel: frischer local-1-Decoder + komplette zweite H264/HAM6-Wiedergabe bis EOS.",10
msg_v9d_probe_start_end:
msg_v9d_probe_tx0: dc.b "[V10P] Start slave.txpos=0x"
msg_v9d_probe_tx0_end:
msg_v9d_probe_rx0: dc.b " master.txpos=0x"
msg_v9d_probe_rx0_end:
msg_v9d_open_sent: dc.b "[V10P] OPEN(local=1) gesendet; neuer slave.txpos=0x"
msg_v9d_open_sent_end:
msg_v9d_probe_arm: dc.b " armed=0x"
msg_v9d_probe_arm_end:
msg_v9d_open_ok: dc.b "[V10P] OPENACK(local=1): neuer VC-MMAL-Port=0x"
msg_v9d_open_ok_end:
msg_v9d_open_ver: dc.b " peer-version=0x"
msg_v9d_open_ver_end:
msg_v9d_open_timeout: dc.b "[V10P] FEHLER: keine OPENACK-Antwort fuer lokalen Port 1.",10
msg_v9d_open_timeout_end:
msg_v9d_open_rejected: dc.b "[V10P] FEHLER: VideoCore hat den neuen MMAL-Service mit CLOSE abgelehnt.",10
msg_v9d_open_rejected_end:
msg_v9d_getver_sent: dc.b "[V10P] GET_VERSION DATA msgid=0x"
msg_v9d_getver_sent_end:
msg_v9d_probe_tx1: dc.b " neuer slave.txpos=0x"
msg_v9d_probe_tx1_end:
msg_v9d_getver_ok: dc.b "[V10P] GET_VERSION OK: major=0x"
msg_v9d_getver_ok_end:
msg_v9d_probe_minor: dc.b " minor=0x"
msg_v9d_probe_minor_end:
msg_v9d_probe_min: dc.b " minimum=0x"
msg_v9d_probe_min_end:
msg_v9d_data_timeout: dc.b "[V10P] FEHLER: keine DATA-Antwort auf GET_VERSION ueber lokalen Port 1.",10
msg_v9d_data_timeout_end:
msg_v9d_bad_reply: dc.b "[V10P] FEHLER GET_VERSION-Antwort: magic=0x"
msg_v9d_bad_reply_end:
msg_v9d_bad_type: dc.b " type=0x"
msg_v9d_bad_type_end:
msg_v9d_bad_ctx: dc.b " ctx=0x"
msg_v9d_bad_ctx_end:
msg_v9d_bad_status: dc.b " status=0x"
msg_v9d_bad_status_end:
msg_v9d_probe_success:
        dc.b "[V10P] ZWEITER LAUF: SERVICE + DECODER + PORTS + STREAMING + EOS + HAM6/RGB: OK.",10
        dc.b "[HDMI_v41L] Zweite Filmwiedergabe ohne Reboot bis Cleanup beendet; Workbench-Zustand bitte sichtbar pruefen.",10
        dc.b "[V10P] Mehrfachstart erfolgreich; bei DMA-Free OK sollten auch weitere Filme ohne schleichenden 1064-KiB-RAM-Verlust starten.",10,"hdmi_v41l Ende.",10
msg_v9d_probe_success_end:
msg_v15_probe_stop_success:
        dc.b "[HDMI_v41L] CTRL-C-STOPP AUCH IM ZWEITEN LAUF: OK. Service/Decoder/Renderer bis Decoder-EOS abgebaut; Workbench-Zustand bitte sichtbar pruefen.",10,"hdmi_v41l Ende.",10
msg_v15_probe_stop_success_end:
msg_v9d_probe_fail:
        dc.b "[V10P] Zweitstart-Probe fehlgeschlagen. Jetzt bitte rebooten und beide Logs schicken.",10,"hdmi_v41l Ende.",10
msg_v9d_probe_fail_end:
        even


; ====================================================================
; V10 - SECOND CLI INVOCATION: FRESH DECODER COMPONENT_CREATE PROBE
; Entry: shared VCHIQ RAM CPU-owned, local MMAL service 1 open, GET_VERSION OK.
; Exit: shared VCHIQ RAM returned to VC DMA ownership. D0=0 success / 1 fail.
; No port configuration and no second playback in this isolated test.
; ====================================================================
        even
        section bss,bss
v9e_comp_msgid_abs: ds.l 1
v9e_comp_size_abs: ds.l 1
v9e_comp_magic_abs: ds.l 1
v9e_comp_type_abs: ds.l 1
v9e_comp_context_abs: ds.l 1
v9e_comp_hdr_status_abs: ds.l 1
v9e_comp_reply_status_abs: ds.l 1
v9e_comp_handle_abs: ds.l 1
v9e_comp_inputs_abs: ds.l 1
v9e_comp_outputs_abs: ds.l 1
v9e_comp_clocks_abs: ds.l 1

        section code,code
v9e_second_component_create:
        movem.l d1-d7/a0-a3,-(sp)
        lea     msg_v9e_comp_start,a1
        move.l  #msg_v9e_comp_start_end-msg_v9e_comp_start,d3
        jsr     print

        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9e_comp_fail_cpu
        move.l  a2,a3

        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        move.l  d0,v9e_comp_msgid_abs
        move.l  a3,a0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #160,d0
        jsr     store_le32

        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     16(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  #$9E000002,d0
        jsr     store_le32
        lea     24(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     28(a3),a0
        moveq   #0,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  #$9ECA0001,d0
        jsr     store_le32

        lea     36(a3),a0
        move.l  #31,d7
v9e_comp_name_clear:
        clr.l   (a0)+
        dbra    d7,v9e_comp_name_clear
        lea     36(a3),a0
        lea     comp_name,a1
        move.l  #comp_name_end-comp_name-1,d7
v9e_comp_name_copy:
        move.b  (a1)+,(a0)+
        dbra    d7,v9e_comp_name_copy
        lea     164(a3),a0
        moveq   #0,d0
        jsr     store_le32

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6

        lea     msg_v9e_comp_sent,a1
        move.l  #msg_v9e_comp_sent_end-msg_v9e_comp_sent,d3
        jsr     print
        move.l  v9e_comp_msgid_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_txpos,a1
        move.l  #msg_v9e_comp_txpos_end-msg_v9e_comp_txpos,d3
        jsr     print
        move.l  port_tx_pos,d0
        jsr     print_hex32
        jsr     newline

        jsr     dma_pre_all
        tst.l   d6
        beq.s   v9e_comp_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v9e_comp_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
v9e_comp_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v9e_comp_have_record
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v9e_comp_wait
        jsr     dma_post_all
        lea     msg_v9e_comp_timeout,a1
        move.l  #msg_v9e_comp_timeout_end-msg_v9e_comp_timeout,d3
        jsr     print
        bra.w   v9e_comp_fail_cpu

v9e_comp_have_record:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   v9e_comp_fail_cpu
        move.l  a2,a3
        move.l  a3,a0
        jsr     load_le32
        move.l  d0,v9e_comp_msgid_abs
        lea     4(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_size_abs

        move.l  v9e_comp_msgid_abs,d0
        and.l   #$FF000000,d0
        beq.w   v9e_comp_skip_record
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   v9e_comp_skip_record
        move.l  v9e_comp_msgid_abs,d0
        and.l   #$00000FFF,d0
        cmp.l   #1,d0
        bne.w   v9e_comp_skip_record
        move.l  v9e_comp_msgid_abs,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        cmp.l   v9d_remote_port_abs,d0
        bne.w   v9e_comp_skip_record
        move.l  v9e_comp_size_abs,d0
        cmp.l   #44,d0
        bcs.w   v9e_comp_bad_reply

        lea     8(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_magic_abs
        lea     12(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_type_abs
        lea     20(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_context_abs
        lea     24(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_hdr_status_abs
        lea     32(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_reply_status_abs
        lea     36(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_handle_abs
        lea     40(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_inputs_abs
        lea     44(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_outputs_abs
        lea     48(a3),a0
        jsr     load_le32
        move.l  d0,v9e_comp_clocks_abs

        cmpi.l  #MMAL_MAGIC,v9e_comp_magic_abs
        bne.w   v9e_comp_bad_reply
        cmpi.l  #MMAL_COMPONENT_CREATE,v9e_comp_type_abs
        bne.w   v9e_comp_bad_reply
        cmpi.l  #$9E000002,v9e_comp_context_abs
        bne.w   v9e_comp_bad_reply
        tst.l   v9e_comp_hdr_status_abs
        bne.w   v9e_comp_bad_reply
        tst.l   v9e_comp_reply_status_abs
        bne.w   v9e_comp_bad_reply
        tst.l   v9e_comp_handle_abs
        beq.w   v9e_comp_bad_reply

        lea     msg_v9e_comp_ok,a1
        move.l  #msg_v9e_comp_ok_end-msg_v9e_comp_ok,d3
        jsr     print
        move.l  v9e_comp_handle_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_ports,a1
        move.l  #msg_v9e_comp_ports_end-msg_v9e_comp_ports,d3
        jsr     print
        move.l  v9e_comp_inputs_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_slash,a1
        move.l  #msg_v9e_comp_slash_end-msg_v9e_comp_slash,d3
        jsr     print
        move.l  v9e_comp_outputs_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_slash,a1
        move.l  #msg_v9e_comp_slash_end-msg_v9e_comp_slash,d3
        jsr     print
        move.l  v9e_comp_clocks_abs,d0
        jsr     print_hex32
        jsr     newline

        move.l  v9e_comp_size_abs,d0
        jsr     v9_consume_rx
        jsr     dma_pre_all
        moveq   #0,d0
        bra.w   v9e_comp_done

v9e_comp_skip_record:
        move.l  v9e_comp_size_abs,d0
        jsr     v9_consume_rx
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9e_comp_wait
        jsr     dma_post_all
        lea     msg_v9e_comp_timeout,a1
        move.l  #msg_v9e_comp_timeout_end-msg_v9e_comp_timeout,d3
        jsr     print
        bra.s   v9e_comp_fail_cpu

v9e_comp_bad_reply:
        lea     msg_v9e_comp_bad,a1
        move.l  #msg_v9e_comp_bad_end-msg_v9e_comp_bad,d3
        jsr     print
        move.l  v9e_comp_magic_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_bad_type,a1
        move.l  #msg_v9e_comp_bad_type_end-msg_v9e_comp_bad_type,d3
        jsr     print
        move.l  v9e_comp_type_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_bad_ctx,a1
        move.l  #msg_v9e_comp_bad_ctx_end-msg_v9e_comp_bad_ctx,d3
        jsr     print
        move.l  v9e_comp_context_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_bad_status,a1
        move.l  #msg_v9e_comp_bad_status_end-msg_v9e_comp_bad_status,d3
        jsr     print
        move.l  v9e_comp_hdr_status_abs,d0
        jsr     print_hex32
        lea     msg_v9e_comp_bad_rstatus,a1
        move.l  #msg_v9e_comp_bad_rstatus_end-msg_v9e_comp_bad_rstatus,d3
        jsr     print
        move.l  v9e_comp_reply_status_abs,d0
        jsr     print_hex32
        jsr     newline
        move.l  v9e_comp_size_abs,d0
        jsr     v9_consume_rx

v9e_comp_fail_cpu:
        jsr     dma_pre_all
        lea     msg_v9e_comp_fail,a1
        move.l  #msg_v9e_comp_fail_end-msg_v9e_comp_fail,d3
        jsr     print
        moveq   #1,d0
v9e_comp_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

        section data,data
msg_v9e_getver_stage_ok:
        dc.b "[V10P] GET_VERSION-Stufe bestaetigt; teste jetzt frischen Decoder im zweiten CLI-Prozess.",10
msg_v9e_getver_stage_ok_end:
msg_v9e_comp_start:
        dc.b "[V10P] COMPONENT_CREATE 'ril.video_decode' ueber local port 1 senden ...",10
msg_v9e_comp_start_end:
msg_v9e_comp_sent:
        dc.b "[V10P] COMPONENT_CREATE DATA msgid=0x"
msg_v9e_comp_sent_end:
msg_v9e_comp_txpos:
        dc.b " neuer slave.txpos=0x"
msg_v9e_comp_txpos_end:
msg_v9e_comp_timeout:
        dc.b "[V10P] FEHLER: keine COMPONENT_CREATE-Antwort im zweiten CLI-Prozess.",10
msg_v9e_comp_timeout_end:
msg_v9e_comp_ok:
        dc.b "[V10P] COMPONENT_CREATE OK: handle=0x"
msg_v9e_comp_ok_end:
msg_v9e_comp_ports:
        dc.b " input/output/clock=0x"
msg_v9e_comp_ports_end:
msg_v9e_comp_slash:
        dc.b "/"
msg_v9e_comp_slash_end:
msg_v9e_comp_bad:
        dc.b "[V10P] FEHLER COMPONENT_CREATE reply: magic=0x"
msg_v9e_comp_bad_end:
msg_v9e_comp_bad_type:
        dc.b " type=0x"
msg_v9e_comp_bad_type_end:
msg_v9e_comp_bad_ctx:
        dc.b " ctx=0x"
msg_v9e_comp_bad_ctx_end:
msg_v9e_comp_bad_status:
        dc.b " hdrstatus=0x"
msg_v9e_comp_bad_status_end:
msg_v9e_comp_bad_rstatus:
        dc.b " replystatus=0x"
msg_v9e_comp_bad_rstatus_end:
msg_v9e_comp_fail:
        dc.b "[V10P] Zweitstart-COMPONENT_CREATE-Test fehlgeschlagen. Jetzt rebooten.",10,"hdmi_v41l Ende.",10
msg_v9e_comp_fail_end:
        even

; ====================================================================
; V9F - SECOND CLI INVOCATION: FULL FRESH-DECODER CONFIGURATION PROBE
;
; V10 already proved: persistent VCHIQ attach, local-port-1 mmal OPEN,
; GET_VERSION, and fresh ril.video_decode COMPONENT_CREATE.
;
; V9F continues ONLY on that second-CLI path:
;   - query CONTROL/INPUT/OUTPUT/CLOCK with slot-safe absolute stream mapping
;   - enable CONTROL
;   - commit dynamic H264 INPUT format/extradata/geometry/FPS and enable INPUT
;   - request OUTPUT buffer_num=2 and enable OUTPUT
;   - verify aligned I420 payload <= returned output buffer capacity
;   - COMPONENT_ENABLE
; Then STOP. No output DMA buffers and no H264 stream are submitted here.
;
; All V9F helpers scan the live MASTER stream and skip unrelated records.
; They never assume that replies are still in the first VC data slot.
; ====================================================================
        even
        section bss,bss
v9f_expect_type_abs: ds.l 1
v9f_expect_context_abs: ds.l 1
v9f_expect_min_abs: ds.l 1
v9f_rx_msgid_abs: ds.l 1
v9f_rx_size_abs: ds.l 1
v9f_wait_armed_abs: ds.l 1
v9f_action_handle_abs: ds.l 1
v9f_action_type_abs: ds.l 1
v9f_stage_abs: ds.l 1
v9f_i420_expected_abs: ds.l 1
v9f_i420_capacity_abs: ds.l 1

; ------------------------------------------------------------
; Publish the already-built VCHIQ record and wait for the matching
; local-port-1 MMAL synchronous reply.
;
; Entry: D0 = complete aligned VCHIQ request stride.
;        request begins at the A2 returned by h26a_reserve_tx.
;        v9f_expect_type/context/min set by caller.
; Return success: D0=0, A2 -> matching RX record, shared RAM CPU-owned.
;        failure: D0=1, shared RAM CPU-owned.
; Matching is DATA, dest local=1, source=current new VC MMAL port,
; MMAL magic/type/context, and header status 0. Unrelated records are
; consumed and slot-recycled with v9_consume_rx.
; ------------------------------------------------------------
        section code,code
v9f_publish_wait:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  d0,d6
        add.l   d6,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,v9f_wait_armed_abs

        jsr     dma_pre_all
        move.l  v9f_wait_armed_abs,d0
        tst.l   d0
        beq.s   v9f_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v9f_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
v9f_wait_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v9f_wait_have_record
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v9f_wait_loop
        ; timeout: switch back to CPU ownership before returning
        jsr     dma_post_all
        lea     msg_v9f_wait_timeout,a1
        move.l  #msg_v9f_wait_timeout_end-msg_v9f_wait_timeout,d3
        jsr     print
        move.l  v9f_expect_type_abs,d0
        jsr     print_hex32
        lea     msg_v9f_ctx,a1
        move.l  #msg_v9f_ctx_end-msg_v9f_ctx,d3
        jsr     print
        move.l  v9f_expect_context_abs,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
        bra.w   v9f_wait_done

v9f_wait_have_record:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   v9f_wait_map_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,v9f_rx_msgid_abs
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v9f_rx_size_abs

        ; DATA record?
        move.l  v9f_rx_msgid_abs,d0
        and.l   #$FF000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   v9f_wait_skip
        ; Destination is our new local port 1?
        move.l  v9f_rx_msgid_abs,d0
        and.l   #$00000FFF,d0
        cmp.l   #1,d0
        bne.w   v9f_wait_skip
        ; Source is the newly opened VC MMAL service?
        move.l  v9f_rx_msgid_abs,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        cmp.l   v9d_remote_port_abs,d0
        bne.w   v9f_wait_skip
        move.l  v9f_rx_size_abs,d0
        cmp.l   v9f_expect_min_abs,d0
        bcs.w   v9f_wait_bad_matching

        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v9f_wait_skip
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   v9f_expect_type_abs,d0
        bne.w   v9f_wait_skip
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   v9f_expect_context_abs,d0
        bne.w   v9f_wait_skip
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   v9f_wait_bad_matching

        moveq   #0,d0
        bra.w   v9f_wait_done

v9f_wait_skip:
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   v9f_wait_loop
        jsr     dma_post_all
        lea     msg_v9f_wait_timeout,a1
        move.l  #msg_v9f_wait_timeout_end-msg_v9f_wait_timeout,d3
        jsr     print
        move.l  v9f_expect_type_abs,d0
        jsr     print_hex32
        lea     msg_v9f_ctx,a1
        move.l  #msg_v9f_ctx_end-msg_v9f_ctx,d3
        jsr     print
        move.l  v9f_expect_context_abs,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
        bra.s   v9f_wait_done

v9f_wait_bad_matching:
        lea     msg_v9f_wait_bad,a1
        move.l  #msg_v9f_wait_bad_end-msg_v9f_wait_bad,d3
        jsr     print
        move.l  v9f_rx_msgid_abs,d0
        jsr     print_hex32
        lea     msg_v9f_size,a1
        move.l  #msg_v9f_size_end-msg_v9f_size,d3
        jsr     print
        move.l  v9f_rx_size_abs,d0
        jsr     print_hex32
        jsr     newline
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        moveq   #1,d0
        bra.s   v9f_wait_done

v9f_wait_map_fail:
        lea     msg_v9f_wait_map,a1
        move.l  #msg_v9f_wait_map_end-msg_v9f_wait_map,d3
        jsr     print
        moveq   #1,d0
v9f_wait_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; ------------------------------------------------------------
; Slot-safe PORT_INFO_GET for the second local MMAL service.
; Uses the existing port_* globals as the decoded mmal_port snapshot.
; ------------------------------------------------------------
v9f_port_info_get:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  #$9F100000,d0
        move.l  port_query_type,d1
        or.l    d1,d0
        move.l  d0,port_query_context

        move.l  #48,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9f_get_fail
        move.l  a2,a3
        move.l  a3,a0
        moveq   #11,d7
v9f_get_clear:
        clr.l   (a0)+
        dbra    d7,v9f_get_clear

        move.l  a3,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #36,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_PORT_INFO_GET,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  port_query_context,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  component_handle,d0
        jsr     store_le32
        lea     36(a3),a0
        move.l  port_query_type,d0
        jsr     store_le32
        lea     40(a3),a0
        move.l  port_query_index,d0
        jsr     store_le32

        move.l  #MMAL_PORT_INFO_GET,v9f_expect_type_abs
        move.l  port_query_context,d0
        move.l  d0,v9f_expect_context_abs
        move.l  #188,v9f_expect_min_abs
        move.l  #48,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.w   v9f_get_fail

        ; Fixed PORT_INFO_GET reply identity.
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   v9f_get_bad_consume
        lea     36(a2),a0
        jsr     load_le32
        cmp.l   component_handle,d0
        bne.w   v9f_get_bad_consume
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   port_query_type,d0
        bne.w   v9f_get_bad_consume
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   port_query_index,d0
        bne.w   v9f_get_bad_consume

        lea     52(a2),a0
        jsr     load_le32
        move.l  d0,port_last_handle
        lea     72(a2),a0
        jsr     load_le32
        move.l  d0,port_enabled
        lea     80(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_num_min
        lea     84(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_size_min
        lea     88(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_align
        lea     92(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_num_rec
        lea     96(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_size_rec
        lea     100(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_num
        lea     104(a2),a0
        jsr     load_le32
        move.l  d0,port_buf_size
        lea     116(a2),a0
        jsr     load_le32
        move.l  d0,port_caps
        lea     120(a2),a0
        jsr     load_le32
        move.l  d0,port_fmt_type
        lea     124(a2),a0
        jsr     load_le32
        move.l  d0,port_fmt_encoding
        lea     128(a2),a0
        jsr     load_le32
        move.l  d0,port_fmt_variant
        lea     136(a2),a0
        jsr     load_le32
        move.l  d0,port_fmt_bitrate
        lea     140(a2),a0
        jsr     load_le32
        move.l  d0,port_fmt_flags
        lea     144(a2),a0
        jsr     load_le32
        move.l  d0,port_fmt_extra
        lea     152(a2),a0
        jsr     load_le32
        move.l  d0,port_video_width
        lea     156(a2),a0
        jsr     load_le32
        move.l  d0,port_video_height
        lea     160(a2),a0
        jsr     load_le32
        move.l  d0,port_crop_x
        lea     164(a2),a0
        jsr     load_le32
        move.l  d0,port_crop_y
        lea     168(a2),a0
        jsr     load_le32
        move.l  d0,port_crop_width
        lea     172(a2),a0
        jsr     load_le32
        move.l  d0,port_crop_height
        lea     176(a2),a0
        jsr     load_le32
        move.l  d0,port_fps_num
        lea     180(a2),a0
        jsr     load_le32
        move.l  d0,port_fps_den
        lea     184(a2),a0
        jsr     load_le32
        move.l  d0,port_par_num
        lea     188(a2),a0
        jsr     load_le32
        move.l  d0,port_par_den
        lea     192(a2),a0
        jsr     load_le32
        move.l  d0,port_color_space

        ; Keep returned INPUT extradata, mainly for post-SET verification.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        bne.s   v9f_get_no_extra
        tst.l   port_query_index
        bne.s   v9f_get_no_extra
        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   v9f_get_bad_consume
        move.l  d0,d1
        add.l   #188,d1
        cmp.l   v9f_rx_size_abs,d1
        bhi.w   v9f_get_bad_consume
        lea     input_extradata,a0
        moveq   #31,d7
v9f_get_extra_clear:
        clr.l   (a0)+
        dbra    d7,v9f_get_extra_clear
        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.s   v9f_get_no_extra
        subq.l  #1,d7
        lea     196(a2),a0
        lea     input_extradata,a1
v9f_get_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,v9f_get_extra_copy

v9f_get_no_extra:
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        moveq   #0,d0
        bra.s   v9f_get_done
v9f_get_bad_consume:
        lea     msg_v9f_get_bad,a1
        move.l  #msg_v9f_get_bad_end-msg_v9f_get_bad,d3
        jsr     print
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
v9f_get_fail:
        moveq   #1,d0
v9f_get_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; ------------------------------------------------------------
; PORT_INFO_SET for INPUT 0. Layout is the same worker structure already
; proven by the first-run decoder, now sent on local port 1 and with
; slot-safe TX/RX mapping.
; ------------------------------------------------------------
v9f_port_info_set_input:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   v9f_set_fail
        move.l  #312,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9f_set_fail
        move.l  a2,a3
        move.l  a3,a0
        move.l  #77,d7
v9f_set_clear:
        clr.l   (a0)+
        dbra    d7,v9f_set_clear

        move.l  a3,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #304,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_PORT_INFO_SET,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  #$9F200002,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  component_handle,d0
        jsr     store_le32
        lea     36(a3),a0
        move.l  #MMAL_PORT_INPUT,d0
        jsr     store_le32
        ; index 0 at +40 remains clear.
        lea     88(a3),a0
        move.l  port_buf_num,d0
        jsr     store_le32
        lea     92(a3),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     100(a3),a0
        move.l  #MMAL_INPUT_USERDATA,d0
        jsr     store_le32
        lea     108(a3),a0
        move.l  port_fmt_type,d0
        jsr     store_le32
        lea     112(a3),a0
        move.l  port_fmt_encoding,d0
        jsr     store_le32
        lea     116(a3),a0
        move.l  port_fmt_variant,d0
        jsr     store_le32
        lea     124(a3),a0
        move.l  port_fmt_bitrate,d0
        jsr     store_le32
        lea     128(a3),a0
        move.l  port_fmt_flags,d0
        jsr     store_le32
        lea     132(a3),a0
        move.l  port_fmt_extra,d0
        jsr     store_le32
        lea     140(a3),a0
        move.l  port_video_width,d0
        jsr     store_le32
        lea     144(a3),a0
        move.l  port_video_height,d0
        jsr     store_le32
        lea     148(a3),a0
        move.l  port_crop_x,d0
        jsr     store_le32
        lea     152(a3),a0
        move.l  port_crop_y,d0
        jsr     store_le32
        lea     156(a3),a0
        move.l  port_crop_width,d0
        jsr     store_le32
        lea     160(a3),a0
        move.l  port_crop_height,d0
        jsr     store_le32
        lea     164(a3),a0
        move.l  port_fps_num,d0
        jsr     store_le32
        lea     168(a3),a0
        move.l  port_fps_den,d0
        jsr     store_le32
        lea     172(a3),a0
        move.l  port_par_num,d0
        jsr     store_le32
        lea     176(a3),a0
        move.l  port_par_den,d0
        jsr     store_le32
        lea     180(a3),a0
        move.l  port_color_space,d0
        jsr     store_le32

        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.s   v9f_set_extra_done
        subq.l  #1,d7
        lea     input_extradata,a0
        lea     184(a3),a1
v9f_set_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,v9f_set_extra_copy
v9f_set_extra_done:
        move.l  #MMAL_PORT_INFO_SET,v9f_expect_type_abs
        move.l  #$9F200002,v9f_expect_context_abs
        move.l  #40,v9f_expect_min_abs
        move.l  #312,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.w   v9f_set_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_set_bad_consume
        lea     36(a2),a0
        jsr     load_le32
        cmp.l   component_handle,d0
        bne.s   v9f_set_bad_consume
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_INPUT,d0
        bne.s   v9f_set_bad_consume
        lea     44(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_set_bad_consume
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        moveq   #0,d0
        bra.s   v9f_set_done
v9f_set_bad_consume:
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
v9f_set_fail:
        moveq   #1,d0
v9f_set_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; ------------------------------------------------------------
; Enable one current port snapshot. Entry D0=port handle, D1=port type.
; Current port_* globals must describe that same port (fresh GET).
; ------------------------------------------------------------
v9f_port_enable:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  d0,v9f_action_handle_abs
        move.l  d1,v9f_action_type_abs
        move.l  #$9F300000,d0
        or.l    d1,d0
        move.l  d0,v9f_expect_context_abs

        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9f_action_fail
        move.l  a2,a3
        move.l  a3,a0
        moveq   #27,d7
v9f_action_clear:
        clr.l   (a0)+
        dbra    d7,v9f_action_clear
        move.l  a3,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #100,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  v9f_expect_context_abs,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  component_handle,d0
        jsr     store_le32
        lea     36(a3),a0
        move.l  v9f_action_handle_abs,d0
        jsr     store_le32
        lea     40(a3),a0
        move.l  #MMAL_PORT_ACTION_ENABLE,d0
        jsr     store_le32
        lea     52(a3),a0
        move.l  v9f_action_type_abs,d0
        jsr     store_le32
        lea     60(a3),a0
        move.l  port_enabled,d0
        jsr     store_le32
        lea     68(a3),a0
        move.l  port_buf_num_min,d0
        jsr     store_le32
        lea     72(a3),a0
        move.l  port_buf_size_min,d0
        jsr     store_le32
        lea     76(a3),a0
        move.l  port_buf_align,d0
        jsr     store_le32
        lea     80(a3),a0
        move.l  port_buf_num_rec,d0
        jsr     store_le32
        lea     84(a3),a0
        move.l  port_buf_size_rec,d0
        jsr     store_le32
        lea     88(a3),a0
        move.l  port_buf_num,d0
        jsr     store_le32
        lea     92(a3),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     100(a3),a0
        move.l  v9f_expect_context_abs,d0
        jsr     store_le32
        lea     104(a3),a0
        move.l  port_caps,d0
        jsr     store_le32

        move.l  #MMAL_PORT_ACTION,v9f_expect_type_abs
        move.l  #28,v9f_expect_min_abs
        move.l  #112,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.s   v9f_action_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_action_bad_consume
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        moveq   #0,d0
        bra.s   v9f_action_done
v9f_action_bad_consume:
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
v9f_action_fail:
        moveq   #1,d0
v9f_action_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; ------------------------------------------------------------
; COMPONENT_ENABLE for the fresh second decoder.
; ------------------------------------------------------------
v9f_component_enable:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  #40,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9f_comp_enable_fail
        move.l  a2,a3
        move.l  a3,a0
        moveq   #9,d7
v9f_comp_enable_clear:
        clr.l   (a0)+
        dbra    d7,v9f_comp_enable_clear
        move.l  a3,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #28,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_COMPONENT_ENABLE,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  #$9F400001,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  component_handle,d0
        jsr     store_le32
        move.l  #MMAL_COMPONENT_ENABLE,v9f_expect_type_abs
        move.l  #$9F400001,v9f_expect_context_abs
        move.l  #28,v9f_expect_min_abs
        move.l  #40,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.s   v9f_comp_enable_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_comp_enable_bad
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        moveq   #0,d0
        bra.s   v9f_comp_enable_done
v9f_comp_enable_bad:
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
v9f_comp_enable_fail:
        moveq   #1,d0
v9f_comp_enable_done:
        movem.l (sp)+,d1-d7/a0-a1/a3
        rts

; Print current port_* snapshot after a stage-specific prefix was already printed.
v9f_log_port_values:
        movem.l d0-d3/a1,-(sp)
        lea     msg_v9f_handle,a1
        move.l  #msg_v9f_handle_end-msg_v9f_handle,d3
        jsr     print
        move.l  port_last_handle,d0
        jsr     print_hex32
        lea     msg_v9f_enabled,a1
        move.l  #msg_v9f_enabled_end-msg_v9f_enabled,d3
        jsr     print
        move.l  port_enabled,d0
        jsr     print_hex32
        lea     msg_v9f_buf,a1
        move.l  #msg_v9f_buf_end-msg_v9f_buf,d3
        jsr     print
        move.l  port_buf_num,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_buf_size,d0
        jsr     print_hex32
        lea     msg_v9f_caps,a1
        move.l  #msg_v9f_caps_end-msg_v9f_caps,d3
        jsr     print
        move.l  port_caps,d0
        jsr     print_hex32
        lea     msg_v9f_fmt,a1
        move.l  #msg_v9f_fmt_end-msg_v9f_fmt,d3
        jsr     print
        move.l  port_fmt_type,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_fmt_encoding,d0
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d3/a1
        rts

; ------------------------------------------------------------
; V9F high-level isolated second-decoder setup.
; Entry from V10 component-create success: shared slot RAM DMA-owned.
; Return D0=0/1 and always restore live slot RAM to DMA ownership.
; ------------------------------------------------------------
v9f_second_configure:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  #1,v9f_stage_abs
        move.l  v9e_comp_handle_abs,d0
        move.l  d0,component_handle
        move.l  v9d_remote_port_abs,d0
        move.l  d0,mmal_remote_port
        jsr     dma_post_all

        lea     msg_v9f_begin,a1
        move.l  #msg_v9f_begin_end-msg_v9f_begin,d3
        jsr     print

        ; Initial GET of all four classes, as an isolated baseline snapshot.
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_control_get
        move.l  port_last_handle,d0
        move.l  d0,control_port_handle
        lea     msg_v9f_control_get,a1
        move.l  #msg_v9f_control_get_end-msg_v9f_control_get,d3
        jsr     print
        jsr     v9f_log_port_values

        move.l  #2,v9f_stage_abs
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_get
        move.l  port_last_handle,d0
        move.l  d0,input_port_handle
        lea     msg_v9f_input_get,a1
        move.l  #msg_v9f_input_get_end-msg_v9f_input_get,d3
        jsr     print
        jsr     v9f_log_port_values

        move.l  #3,v9f_stage_abs
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_output_get
        move.l  port_last_handle,d0
        move.l  d0,output_port_handle
        lea     msg_v9f_output_get,a1
        move.l  #msg_v9f_output_get_end-msg_v9f_output_get,d3
        jsr     print
        jsr     v9f_log_port_values

        move.l  #4,v9f_stage_abs
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_clock_get
        move.l  port_last_handle,d0
        move.l  d0,clock_port_handle
        lea     msg_v9f_clock_get,a1
        move.l  #msg_v9f_clock_get_end-msg_v9f_clock_get,d3
        jsr     print
        jsr     v9f_log_port_values

        ; CONTROL ENABLE: refresh snapshot, send ENABLE, verify enabled=1.
        move.l  #5,v9f_stage_abs
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_control_enable
        move.l  control_port_handle,d0
        move.l  #MMAL_PORT_CONTROL,d1
        jsr     v9f_port_enable
        tst.l   d0
        bne.w   v9f_fail_control_enable
        move.l  #MMAL_PORT_CONTROL,port_query_type
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_control_enable
        cmpi.l  #1,port_enabled
        bne.w   v9f_fail_control_enable
        lea     msg_v9f_control_enable_ok,a1
        move.l  #msg_v9f_control_enable_ok_end-msg_v9f_control_enable_ok,d3
        jsr     print

        ; INPUT format: refresh, replace format with dynamic parsed H264 values.
        move.l  #6,v9f_stage_abs
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_set
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_H264,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        tst.l   v10b_input_is_mkv
        beq.s   v10g_second_fmt_flags_done
        move.l  #MMAL_ES_FORMAT_FLAG_FRAMED,port_fmt_flags
v10g_second_fmt_flags_done:
        move.l  h264_codec_config_len,d0
        move.l  d0,port_fmt_extra
        move.l  v6_src_aligned_w,d0
        move.l  d0,port_video_width
        move.l  v6_src_aligned_h,d0
        move.l  d0,port_video_height
        move.l  v6_src_crop_x,d0
        move.l  d0,port_crop_x
        move.l  v6_src_crop_y,d0
        move.l  d0,port_crop_y
        move.l  v6_src_visible_w,d0
        move.l  d0,port_crop_width
        move.l  v6_src_visible_h,d0
        move.l  d0,port_crop_height
        move.l  v7_fps_num,d0
        move.l  d0,port_fps_num
        move.l  v7_fps_den,d0
        move.l  d0,port_fps_den
        move.l  #1,port_par_num
        move.l  #1,port_par_den
        clr.l   port_color_space
        move.l  #INPUT_POOL_COUNT,port_buf_num
        move.l  #INPUT_DATA_SIZE,port_buf_size

        lea     input_extradata,a0
        moveq   #31,d7
v9f_input_extra_clear:
        clr.l   (a0)+
        dbra    d7,v9f_input_extra_clear
        move.l  h264_codec_config_len,d7
        tst.l   d7
        beq.w   v9f_fail_input_set
        subq.l  #1,d7
        lea     h264_file_extradata,a0
        lea     input_extradata,a1
v9f_input_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,v9f_input_extra_copy

        jsr     v9f_port_info_set_input
        tst.l   d0
        beq.s   v41g_input_set_worker_ok
        lea     msg_v41g_input_set_worker_fail,a1
        move.l  #msg_v41g_input_set_worker_fail_end-msg_v41g_input_set_worker_fail,d3
        jsr     print
        bra.w   v9f_fail_input_set
v41g_input_set_worker_ok:

        ; V41G: read back the committed compressed-input format, but do not
        ; reject benign firmware normalization of aligned geometry, crop, PAR
        ; or AVC extradata. The SPS parser remains the source of display
        ; geometry. Critical identity/encoding/buffer checks stay strict.
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_set

        lea     msg_v41g_input_return,a1
        move.l  #msg_v41g_input_return_end-msg_v41g_input_return,d3
        jsr     print
        move.l  port_video_width,d0
        jsr     print_hex32
        lea     msg_v9f_x,a1
        moveq   #1,d3
        jsr     print
        move.l  port_video_height,d0
        jsr     print_hex32
        lea     msg_v41g_crop,a1
        move.l  #msg_v41g_crop_end-msg_v41g_crop,d3
        jsr     print
        move.l  port_crop_width,d0
        jsr     print_hex32
        lea     msg_v9f_x,a1
        moveq   #1,d3
        jsr     print
        move.l  port_crop_height,d0
        jsr     print_hex32
        lea     msg_v41g_par,a1
        move.l  #msg_v41g_par_end-msg_v41g_par,d3
        jsr     print
        move.l  port_par_num,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_par_den,d0
        jsr     print_hex32
        lea     msg_v41g_extra,a1
        move.l  #msg_v41g_extra_end-msg_v41g_extra,d3
        jsr     print
        move.l  port_fmt_extra,d0
        jsr     print_hex32
        jsr     newline

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   v9f_fail_input_set
        cmpi.l  #MMAL_ES_VIDEO,port_fmt_type
        bne.w   v9f_fail_input_set
        cmpi.l  #MMAL_ENCODING_H264,port_fmt_encoding
        bne.w   v9f_fail_input_set
        move.l  port_fmt_flags,d0
        and.l   #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        tst.l   v10b_input_is_mkv
        beq.s   v41g_second_verify_unframed
        cmpi.l  #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        bne.w   v9f_fail_input_set
        bra.s   v41g_second_verify_flags_ok
v41g_second_verify_unframed:
        tst.l   d0
        bne.w   v9f_fail_input_set
v41g_second_verify_flags_ok:
        move.l  port_buf_num,d0
        cmp.l   #INPUT_POOL_COUNT,d0
        bcs.w   v9f_fail_input_set
        move.l  port_buf_size,d0
        cmp.l   #H264_MAX_DATA_LEN,d0
        bcs.w   v9f_fail_input_set
        lea     msg_v9f_input_set_ok,a1
        move.l  #msg_v9f_input_set_ok_end-msg_v9f_input_set_ok,d3
        jsr     print
        lea     msg_v9f_geom,a1
        move.l  #msg_v9f_geom_end-msg_v9f_geom,d3
        jsr     print
        move.l  port_video_width,d0
        jsr     print_hex32
        lea     msg_v9f_x,a1
        moveq   #1,d3
        jsr     print
        move.l  port_video_height,d0
        jsr     print_hex32
        lea     msg_v9f_crop,a1
        move.l  #msg_v9f_crop_end-msg_v9f_crop,d3
        jsr     print
        move.l  port_crop_width,d0
        jsr     print_hex32
        lea     msg_v9f_x,a1
        moveq   #1,d3
        jsr     print
        move.l  port_crop_height,d0
        jsr     print_hex32
        lea     msg_v9f_fps,a1
        move.l  #msg_v9f_fps_end-msg_v9f_fps,d3
        jsr     print
        move.l  port_fps_num,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_fps_den,d0
        jsr     print_hex32
        lea     msg_v9f_extra,a1
        move.l  #msg_v9f_extra_end-msg_v9f_extra,d3
        jsr     print
        move.l  port_fmt_extra,d0
        jsr     print_hex32
        jsr     newline

        ; INPUT ENABLE with the freshly returned snapshot, then verify.
        move.l  #7,v9f_stage_abs
        move.l  input_port_handle,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
        tst.l   d0
        bne.w   v9f_fail_input_enable
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_enable
        cmpi.l  #1,port_enabled
        bne.w   v9f_fail_input_enable
        cmpi.l  #MMAL_ENCODING_H264,port_fmt_encoding
        bne.w   v9f_fail_input_enable
        move.l  port_buf_num,d0
        move.l  d0,input_before_buf_num
        move.l  port_buf_size,d0
        move.l  d0,input_before_buf_size
        move.l  port_fmt_extra,d0
        move.l  d0,input_before_extra
        lea     msg_v9f_input_enable_ok,a1
        move.l  #msg_v9f_input_enable_ok_end-msg_v9f_input_enable_ok,d3
        jsr     print

        ; V12F: the restart path must build the same VideoCore-only graph as
        ; first start.  Decoder OUTPUT becomes OPQV, is tunnelled into ril.isp,
        ; and only the small I420 ISP OUTPUT is exposed to the host.
        move.l  #8,v9f_stage_abs
        lea     msg_v12f_second_graph_start,a1
        move.l  #msg_v12f_second_graph_start_end-msg_v12f_second_graph_start,d3
        jsr     print
        lea     msg_v12g_slot_safe,a1
        move.l  #msg_v12g_slot_safe_end-msg_v12g_slot_safe,d3
        jsr     print
        lea     msg_v12h_get_route,a1
        move.l  #msg_v12h_get_route_end-msg_v12h_get_route,d3
        jsr     print
        jsr     v12a_setup_isp_graph
        tst.l   d0
        bne.w   v9f_fail_output_enable
        lea     msg_v12f_second_graph_ok,a1
        move.l  #msg_v12f_second_graph_ok_end-msg_v12f_second_graph_ok,d3
        jsr     print

        ; Finally enable the decoder component. No buffer headers follow.
        move.l  #9,v9f_stage_abs
        jsr     v9f_component_enable
        tst.l   d0
        bne.w   v9f_fail_component_enable
        lea     msg_v9f_component_enable_ok,a1
        move.l  #msg_v9f_component_enable_ok_end-msg_v9f_component_enable_ok,d3
        jsr     print

        ; VPv36: perform the same isolated audio_render CREATE + CONTROL0 + INPUT0 GET
        ; also on the persistent local-1/second-start path.  This makes the
        ; isolation test independent of whether V41L attached to an existing
        ; transport or bootstrapped a fresh one.  No SET, enable or PCM.
        move.l  component_handle,vpv21_saved_component
        move.l  input_port_handle,vpv21_saved_input
        move.l  port_query_index,vpv21_saved_port_qidx
        move.l  port_buf_size,vpv21_saved_port_buf_size
        move.l  port_query_type,vpv23_saved_port_qtype

        lea     msg_vpv23_second_create_begin,a1
        move.l  #msg_vpv23_second_create_begin_end-msg_vpv23_second_create_begin,d3
        jsr     vpv21n_trace
        jsr     vpv01_create_audio_render
        move.l  d0,d7

        ; Restore live video globals before inspecting result.
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
        tst.l   d7
        bne.w   vpv23_second_audio_fail

        lea     msg_vpv23_second_create_ok,a1
        move.l  #msg_vpv23_second_create_ok_end-msg_vpv23_second_create_ok,d3
        jsr     vpv21n_trace

        ; port_info_get automatically routes local-1 to the hardware-proven
        ; v9f_port_info_get worker because v12f_local_port == 1.
        lea     msg_vpv23_second_ctrl_begin,a1
        move.l  #msg_vpv23_second_ctrl_begin_end-msg_vpv23_second_ctrl_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv23_second_ctrl_fail
        move.l  port_last_handle,vpv01_audio_control
        lea     msg_vpv23_second_ctrl_ok,a1
        move.l  #msg_vpv23_second_ctrl_ok_end-msg_vpv23_second_ctrl_ok,d3
        jsr     vpv21n_trace

        ; VPv36 local-1: query audio INPUT 0 only. No SET/enable/PCM.
        lea     msg_vpv24_second_input_begin,a1
        move.l  #msg_vpv24_second_input_begin_end-msg_vpv24_second_input_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv24_second_input_fail
        move.l  port_last_handle,vpv01_audio_input
        lea     msg_vpv24_second_input_ok,a1
        move.l  #msg_vpv24_second_input_ok_end-msg_vpv24_second_input_ok,d3
        jsr     vpv21n_trace

        ; VPv36 local-1: same isolated INPUT0 PCM SET.
        lea     msg_vpv26_second_set_begin,a1
        move.l  #msg_vpv26_second_set_begin_end-msg_vpv26_second_set_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  v19_pcm_bitrate,d0
        move.l  d0,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v19_pcm_channels,d0
        move.l  d0,port_video_width
        move.l  v19_pcm_rate,d0
        move.l  d0,port_video_height
        move.l  v19_pcm_bits,d0
        move.l  d0,port_crop_x
        move.l  v19_pcm_blockalign,d0
        move.l  d0,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space
        move.l  port_buf_num_min,d0
        tst.l   d0
        bne.s   vpv26_second_set_num_ok
        moveq   #1,d0
vpv26_second_set_num_ok:
        move.l  d0,port_buf_num
        ; VPv36 local-1: same hardware-proven VPv20 64-KiB buffer sizing.
        move.l  #$00010000,d0
        cmp.l   port_buf_size_min,d0
        bcc.s   vpv26_second_set_size_ok
        move.l  port_buf_size_min,d0
vpv26_second_set_size_ok:
        cmp.l   #INPUT_DATA_SIZE,d0
        bhi.w   vpv26_second_set_fail
        move.l  d0,port_buf_size
        ; Local-1 already has the hardware-proven context-filtering worker.
        lea     msg_vpv30_dispatch_local1,a1
        move.l  #msg_vpv30_dispatch_local1_end-msg_vpv30_dispatch_local1,d3
        jsr     vpv21n_trace
        jsr     v9f_port_info_set_input
        move.l  d0,d7
        tst.l   d7
        bne.w   vpv26_second_set_fail
        lea     msg_vpv26_second_set_ok,a1
        move.l  #msg_vpv26_second_set_ok_end-msg_vpv26_second_set_ok,d3
        jsr     vpv21n_trace
        ; VPv36: same destination + INPUT enable + component enable test on local-1.
        jsr     vpv35_finish_audio_enable
        tst.l   d0
        beq.s   vpv35_second_audio_enable_ok
        lea     msg_vpv35_enable_fail_continue,a1
        move.l  #msg_vpv35_enable_fail_continue_end-msg_vpv35_enable_fail_continue,d3
        jsr     vpv21n_trace
        bra.s   vpv35_second_audio_enable_done
vpv35_second_audio_enable_ok:
        lea     msg_vpv35_enable_ok,a1
        move.l  #msg_vpv35_enable_ok_end-msg_vpv35_enable_ok,d3
        jsr     vpv21n_trace
        ; Same VPv36 real PCM prefix on persistent/local-1 transport.
        jsr     vpv21_queue_audio_prefix
        tst.l   d0
        beq.s   vpv35_second_audio_queue_ok
        lea     msg_vpv35_queue_fail_continue,a1
        move.l  #msg_vpv35_queue_fail_continue_end-msg_vpv35_queue_fail_continue,d3
        jsr     vpv21n_trace
        bra.s   vpv35_second_audio_enable_done
vpv35_second_audio_queue_ok:
        lea     msg_vpv35_queue_proven,a1
        move.l  #msg_vpv35_queue_proven_end-msg_vpv35_queue_proven,d3
        jsr     vpv21n_trace
vpv35_second_audio_enable_done:

        ; Restore fresh second video decoder state before handing back to playback.
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
        bra.w   vpv23_second_audio_done

vpv26_second_set_fail:
        lea     msg_vpv26_second_set_fail,a1
        move.l  #msg_vpv26_second_set_fail_end-msg_vpv26_second_set_fail,d3
        jsr     vpv21n_trace
        lea     msg_vpv26_set_fail_continue,a1
        move.l  #msg_vpv26_set_fail_continue_end-msg_vpv26_set_fail_continue,d3
        jsr     vpv21n_trace
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
        bra.w   vpv23_second_audio_done

vpv24_second_input_fail:
        lea     msg_vpv24_second_input_fail,a1
        move.l  #msg_vpv24_second_input_fail_end-msg_vpv24_second_input_fail,d3
        jsr     vpv21n_trace
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
        bra.w   vpv23_second_audio_fail

vpv23_second_ctrl_fail:
        lea     msg_vpv23_second_ctrl_fail,a1
        move.l  #msg_vpv23_second_ctrl_fail_end-msg_vpv23_second_ctrl_fail,d3
        jsr     vpv21n_trace
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  vpv23_saved_port_qtype,port_query_type
vpv23_second_audio_fail:
        lea     msg_vpv23_second_create_fail,a1
        move.l  #msg_vpv23_second_create_fail_end-msg_vpv23_second_create_fail,d3
        jsr     vpv21n_trace
        jsr     dma_pre_all
        moveq   #1,d0
        bra.w   v9f_config_done

vpv23_second_audio_done:
        jsr     dma_pre_all
        lea     msg_v9f_ready,a1
        move.l  #msg_v9f_ready_end-msg_v9f_ready,d3
        jsr     print
        moveq   #0,d0
        bra.w   v9f_config_done

v9f_fail_control_get:
        lea     msg_v9f_fail_control_get,a1
        bra.w   v9f_config_fail
v9f_fail_input_get:
        lea     msg_v9f_fail_input_get,a1
        bra.w   v9f_config_fail
v9f_fail_output_get:
        lea     msg_v9f_fail_output_get,a1
        bra.w   v9f_config_fail
v9f_fail_clock_get:
        lea     msg_v9f_fail_clock_get,a1
        bra.w   v9f_config_fail
v9f_fail_control_enable:
        lea     msg_v9f_fail_control_enable,a1
        bra.s   v9f_config_fail
v9f_fail_input_set:
        lea     msg_v9f_fail_input_set,a1
        bra.s   v9f_config_fail
v9f_fail_input_enable:
        lea     msg_v9f_fail_input_enable,a1
        bra.s   v9f_config_fail
v9f_fail_output_enable:
        lea     msg_v9f_fail_output_enable,a1
        bra.s   v9f_config_fail
v9f_fail_component_enable:
        lea     msg_v9f_fail_component_enable,a1
v9f_config_fail:
        ; Stage-specific fail string length is selected below.
        ; All stage-specific fail strings have equal fixed length? No: compute
        ; via NUL-free sentinel is unavailable, so use individual dispatch below.
        ; A1 points at a dc.b line whose first byte length is stored separately
        ; by labels; branch to printer selector.
        move.l  v9f_stage_abs,d0
        cmpi.l  #1,d0
        beq.s   v9f_pf1
        cmpi.l  #2,d0
        beq.s   v9f_pf2
        cmpi.l  #3,d0
        beq.s   v9f_pf3
        cmpi.l  #4,d0
        beq.s   v9f_pf4
        cmpi.l  #5,d0
        beq.s   v9f_pf5
        cmpi.l  #6,d0
        beq.s   v9f_pf6
        cmpi.l  #7,d0
        beq.s   v9f_pf7
        cmpi.l  #8,d0
        beq.s   v9f_pf8
        bra.s   v9f_pf9
v9f_pf1:
        lea     msg_v9f_fail_control_get,a1
        move.l  #msg_v9f_fail_control_get_end-msg_v9f_fail_control_get,d3
        bra.s   v9f_pf_print
v9f_pf2:
        lea     msg_v9f_fail_input_get,a1
        move.l  #msg_v9f_fail_input_get_end-msg_v9f_fail_input_get,d3
        bra.s   v9f_pf_print
v9f_pf3:
        lea     msg_v9f_fail_output_get,a1
        move.l  #msg_v9f_fail_output_get_end-msg_v9f_fail_output_get,d3
        bra.s   v9f_pf_print
v9f_pf4:
        lea     msg_v9f_fail_clock_get,a1
        move.l  #msg_v9f_fail_clock_get_end-msg_v9f_fail_clock_get,d3
        bra.s   v9f_pf_print
v9f_pf5:
        lea     msg_v9f_fail_control_enable,a1
        move.l  #msg_v9f_fail_control_enable_end-msg_v9f_fail_control_enable,d3
        bra.s   v9f_pf_print
v9f_pf6:
        lea     msg_v9f_fail_input_set,a1
        move.l  #msg_v9f_fail_input_set_end-msg_v9f_fail_input_set,d3
        bra.s   v9f_pf_print
v9f_pf7:
        lea     msg_v9f_fail_input_enable,a1
        move.l  #msg_v9f_fail_input_enable_end-msg_v9f_fail_input_enable,d3
        bra.s   v9f_pf_print
v9f_pf8:
        lea     msg_v9f_fail_output_enable,a1
        move.l  #msg_v9f_fail_output_enable_end-msg_v9f_fail_output_enable,d3
        bra.s   v9f_pf_print
v9f_pf9:
        lea     msg_v9f_fail_component_enable,a1
        move.l  #msg_v9f_fail_component_enable_end-msg_v9f_fail_component_enable,d3
v9f_pf_print:
        jsr     print
        ; CPU owns shared slot RAM here on every helper return.
        jsr     dma_pre_all
        moveq   #1,d0
v9f_config_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

