msg_v10_none_end:
msg_v10_video:
        dc.b "[V10P]   Video PixelWidth x PixelHeight = 0x"
msg_v10_video_end:
msg_v10_defdur:
        dc.b "  DefaultDuration(ns)=0x"
msg_v10_defdur_end:
msg_v10_audio:
        dc.b "[V10P]   Audio Channels=0x"
msg_v10_audio_end:
msg_v10_avc_selected:
        dc.b "[V10P]   -> erste H264/AVC-Videospur ausgewaehlt.",10
msg_v10_avc_selected_end:
msg_v10_avcc_profile:
        dc.b "[V10P]   avcC profile_idc=0x"
msg_v10_avcc_profile_end:
msg_v10_avcc_level:
        dc.b " level_idc=0x"
msg_v10_avcc_level_end:
msg_v10_avcc_ok:
        dc.b "[V10P]   avcC OK: NAL-Laengenfeld Bytes=0x"
msg_v10_avcc_ok_end:
msg_v10_avcc_sps:
        dc.b " SPS-Bytes=0x"
