v12a_create_status:        ds.l 1
v12a_create_hstatus:       ds.l 1
v12a_create_type:          ds.l 1
v12a_create_context_rx:    ds.l 1
v12a_connect_status:       ds.l 1
v12a_connect_rx_size:      ds.l 1
v12a_req_status:           ds.l 1
v12a_req_rx_size:          ds.l 1
v12a_saved_input_handle:   ds.l 1
v12f_local_port:           ds.l 1    ; 0 first MMAL service, 1 restart service
v12f_local_bits:           ds.l 1    ; 0 or $00001000 in VCHIQ source field
hdmi_v40o_renderer_handle: ds.l 1
hdmi_v40o_drain_done:      ds.l 1
hdmi_v40o_displayregion_ok: ds.l 1
hdmi_v40o_param_status:     ds.l 1
hdmi_v40o_param_rx_size:    ds.l 1
