        section code,code

; --------------------------------------------------------------------
; V12A - slot-safe synchronous RX helper.
; The V10P setup stayed inside MASTER slot 2. The extra ISP replies can
; cross the 4-KiB boundary, where VideoCore inserts a PADDING record and
; continues in MASTER_QUEUE[(rx_pos>>12)&63]. Keep the already proven
; TEST26C/TEST33 mapping and recycle semantics for these setup replies.
; --------------------------------------------------------------------
v12a_rx_advance_stride:
        movem.l d1-d3,-(sp)
        move.l  port_rx_pos,d1
        move.l  d1,d2
        add.l   d0,d2
        move.l  d2,port_rx_pos
        move.l  d1,d3
        and.l   #$fffff000,d3
        and.l   #$fffff000,d2
        cmp.l   d3,d2
        beq.s   v12a_rx_advance_ok
        move.l  d1,d0
        bsr     h31s_recycle_rx_slot
        tst.l   d0
        bne.s   v12a_rx_advance_fail
v12a_rx_advance_ok:
        moveq   #0,d0
        movem.l (sp)+,d1-d3
        rts
v12a_rx_advance_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d3
        rts

v12a_rx_consume_payload:
        add.l   #15,d0
        and.l   #$fffffff8,d0
        bra.w   v12a_rx_advance_stride

; Return A2 at the next non-PADDING MASTER record. D0=0 OK, 1 failure.
v12a_rx_map_data:
        movem.l d1-d4/a0-a1,-(sp)
v12a_rx_map_again:
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.s   v12a_rx_map_fail
        move.l  a2,a0
        bsr     load_le32
        tst.l   d0
        bne.s   v12a_rx_map_ok
        ; PADDING must consume exactly the remainder of this 4-KiB slot.
        lea     4(a2),a0
        bsr     load_le32
        add.l   #15,d0
        and.l   #$fffffff8,d0
        move.l  d0,d4
        move.l  port_rx_pos,d1
        and.l   #$00000fff,d1
        move.l  #SLOT_SIZE,d2
        sub.l   d1,d2
        cmp.l   d2,d4
        bne.s   v12a_rx_map_fail
        move.l  d4,d0
        bsr     v12a_rx_advance_stride
        tst.l   d0
        bne.s   v12a_rx_map_fail
        bra.s   v12a_rx_map_again
v12a_rx_map_ok:
        moveq   #0,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts
v12a_rx_map_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts

; Create ril.isp on the already open local-0 MMAL service.
; Entry/exit shared slot RAM CPU-owned. D0=0 success, 1 failure.
v12a_create_isp:
        movem.l d1-d7/a0-a3,-(sp)
        ; request is 168-byte VCHIQ stride
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_ispcreate_tx_legacy
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_create_fail
        bra.s   v12g_ispcreate_tx_ready
v12g_ispcreate_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_ispcreate_tx_ready:

        move.l  a2,a0
        moveq   #41,d7
v12a_create_clear:
        clr.l   (a0)+
        dbra    d7,v12a_create_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12A00001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$12A1A1A1,d0
        jsr     store_le32
        lea     36(a2),a0
        cmpi.l  #3,v41_display_style
        bne.s   v41b_create_name_isp
        lea     v41b_renderer_name,a1
        moveq   #16,d7               ; "ril.video_render" + NUL = 17 bytes
        bra.s   v12a_create_name
v41b_create_name_isp:
        lea     v12a_isp_name,a1
        moveq   #7,d7                ; "ril.isp" + terminating NUL = 8 bytes
v12a_create_name:
        move.b  (a1)+,(a0)+
        dbra    d7,v12a_create_name

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_create_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_create_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_create_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_create_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_create_wait
        jsr     dma_post_all
        bra.w   v12a_create_fail
v12a_create_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_create_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,d5
        and.l   #$ff000000,d5
        cmp.l   #VCHIQ_MSG_DATA,d5
        bne.w   v12a_create_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_size
        cmp.l   #44,d0
        bcs.w   v12a_create_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_create_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_type
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.w   v12a_create_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_context_rx
        cmp.l   #$12A00001,d0
        bne.w   v12a_create_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_hstatus
        tst.l   d0
        bne.w   v12a_create_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_status
        tst.l   d0
        bne.w   v12a_create_fail_consume
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,v12a_isp_handle
        tst.l   d0
        beq.w   v12a_create_fail_consume
        cmpi.l  #3,v41_display_style
        bne.s   v41b_create_handle_saved
        move.l  d0,hdmi_v40o_renderer_handle
v41b_create_handle_saved:

        move.l  v12a_create_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_create_fail
        lea     msg_v12a_isp_created,a1
        move.l  #msg_v12a_isp_created_end-msg_v12a_isp_created,d3
        jsr     print
        move.l  v12a_isp_handle,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12a_create_done
v12a_create_fail_consume:
        move.l  v12a_create_size,d0
        jsr     v12a_rx_consume_payload
v12a_create_fail:
        lea     msg_v12a_isp_create_fail,a1
        move.l  #msg_v12a_isp_create_fail_end-msg_v12a_isp_create_fail,d3
        jsr     print
        move.l  v12a_create_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
v12a_create_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Connect decoder output -> ISP input using worker PORT_ACTION CONNECT.
v12a_connect_ports:
        movem.l d1-d7/a0-a3,-(sp)
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_connect_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_connect_fail
        bra.s   v12g_connect_tx_ready
v12g_connect_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_connect_tx_ready:
        move.l  a2,a0
        moveq   #27,d7
v12a_connect_clear:
        clr.l   (a0)+
        dbra    d7,v12a_connect_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12C00001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  v12a_decoder_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  v12a_decoder_output,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_CONNECT,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  v12a_isp_handle,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  v12a_isp_input,d0
        jsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_connect_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_connect_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_connect_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_connect_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_connect_wait
        jsr     dma_post_all
        bra.w   v12a_connect_fail
v12a_connect_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_connect_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_rx_size
        cmp.l   #28,d0
        bcs.w   v12a_connect_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_connect_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   v12a_connect_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$12C00001,d0
        bne.w   v12a_connect_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   v12a_connect_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_status
        tst.l   d0
        bne.w   v12a_connect_fail_consume
        move.l  v12a_connect_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_connect_fail
        lea     msg_v12a_connected,a1
        move.l  #msg_v12a_connected_end-msg_v12a_connected,d3
        jsr     print
        moveq   #0,d0
        bra.s   v12a_connect_done
v12a_connect_fail_consume:
        move.l  v12a_connect_rx_size,d0
        jsr     v12a_rx_consume_payload
v12a_connect_fail:
        lea     msg_v12a_connect_fail,a1
        move.l  #msg_v12a_connect_fail_end-msg_v12a_connect_fail,d3
        jsr     print
        move.l  v12a_connect_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
v12a_connect_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; HDMI_v41L HVS diagnostic + controlled restore.
; VideoCore.card itself writes the active HVS display-list word index at
; $F2400024. v05 captures that little-endian offset before video_render is
; created. Only after renderer teardown, MMAL service close and the proven
; 0.5 s service-close stabilization does v05 wait for a raster-frame wrap and
; write EXACTLY that saved value back. No display-list RAM is modified.
hdmi_v40o_log_hvs_all:
        movem.l d0-d3/a0-a1,-(sp)
        lea     msg_hdmi_v40o_hvs_all,a1
        move.l  #msg_hdmi_v40o_hvs_all_end-msg_hdmi_v40o_hvs_all,d3
        jsr     print
        move.l  #HDMI_V18_HVS_DLIST0_PTR,a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_hdmi_v40o_hvs_sep,a1
        move.l  #msg_hdmi_v40o_hvs_sep_end-msg_hdmi_v40o_hvs_sep,d3
        jsr     print
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_hdmi_v40o_hvs_sep,a1
        move.l  #msg_hdmi_v40o_hvs_sep_end-msg_hdmi_v40o_hvs_sep,d3
        jsr     print
        move.l  #HDMI_V18_HVS_DLIST2_PTR,a0
        jsr     load_le32
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d3/a0-a1
        rts

hdmi_v40o_log_hvs_ptr:
        movem.l d0-d3/a0-a1,-(sp)
        lea     msg_hdmi_v40o_hvs_value,a1
        move.l  #msg_hdmi_v40o_hvs_value_end-msg_hdmi_v40o_hvs_value,d3
        jsr     print
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_hvs_last
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d3/a0-a1
        rts

; HDMI_v41L: Dump 32 HVS DWORDs from active-list word offset D0. READ ONLY.
hdmi_v40o_dump_dlist_at:
        movem.l d0-d7/a0-a2,-(sp)
        move.l  d0,d6
        lea     msg_hdmi_v40o_dump_offset,a1
        move.l  #msg_hdmi_v40o_dump_offset_end-msg_hdmi_v40o_dump_offset,d3
        jsr     print
        move.l  d6,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d7
hdmi_v40o_dump_row:
        lea     msg_hdmi_v40o_dump_row,a1
        move.l  #msg_hdmi_v40o_dump_row_end-msg_hdmi_v40o_dump_row,d3
        jsr     print
        move.l  d7,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_dump_colon,a1
        move.l  #msg_hdmi_v40o_dump_colon_end-msg_hdmi_v40o_dump_colon,d3
        jsr     print
        moveq   #0,d5
hdmi_v40o_dump_word:
        move.l  #HDMI_V14_HVS_DLIST_BASE,a0
        move.l  d6,d0
        add.l   d7,d0
        add.l   d5,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        jsr     load_le32
        jsr     print_hex32
        lea     msg_hdmi_v40o_space,a1
        moveq   #1,d3
        jsr     print
        addq.l  #1,d5
        cmpi.l  #4,d5
        bcs.s   hdmi_v40o_dump_word
        jsr     newline
        addq.l  #4,d7
        cmpi.l  #HDMI_V14_DUMP_WORDS,d7
        bcs.s   hdmi_v40o_dump_row
        movem.l (sp)+,d0-d7/a0-a2
        rts

; Capture up to two distinct non-Workbench active HVS list offsets in playback.
hdmi_v40o_probe_video_dlist:
        movem.l d0-d3/a0-a1,-(sp)
        move.l  hdmi_v40o_dump_count,d0
        cmpi.l  #2,d0
        bcc.s   hdmi_v40o_probe_done
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d2
        cmp.l   hdmi_v40o_hvs_saved,d2
        beq.s   hdmi_v40o_probe_done
        tst.l   hdmi_v40o_dump_count
        bne.s   hdmi_v40o_probe_second
        move.l  d2,hdmi_v40o_dump_first_offset
        move.l  #1,hdmi_v40o_dump_count
        lea     msg_hdmi_v40o_dump_video1,a1
        move.l  #msg_hdmi_v40o_dump_video1_end-msg_hdmi_v40o_dump_video1,d3
        jsr     print
        move.l  d2,d0
        jsr     hdmi_v40o_dump_dlist_at
        bra.s   hdmi_v40o_probe_done
hdmi_v40o_probe_second:
        cmp.l   hdmi_v40o_dump_first_offset,d2
        beq.s   hdmi_v40o_probe_done
        move.l  d2,hdmi_v40o_dump_second_offset
        move.l  #2,hdmi_v40o_dump_count
        lea     msg_hdmi_v40o_dump_video2,a1
        move.l  #msg_hdmi_v40o_dump_video2_end-msg_hdmi_v40o_dump_video2,d3
        jsr     print
        move.l  d2,d0
        jsr     hdmi_v40o_dump_dlist_at
hdmi_v40o_probe_done:
        movem.l (sp)+,d0-d3/a0-a1
        rts



; --------------------------------------------------------------------
; HDMI_v41L LIVE HVS-VBLANK MERGE
;
; v13 proved that the exact original Workbench main plane + exact MMAL H264
; element + original WB tail/mouse form a correct HVS display list when MMAL
; is no longer changing the channel pointer. v15 performs the same composition
; live, but only once per real HVS raster wrap. After the wrap it waits briefly
; for ril.video_render to publish its new MMAL list, copies that stable H264
; element into the *inactive* shadow list, then switches the HVS channel to the
; completed shadow. Two independent shadow lists ($400/$460) alternate so the
; list currently scanned by HVS is never modified.
; --------------------------------------------------------------------

; D7 = source MMAL list index, D4 = destination shadow list index.
; Return D0 = 0 success, 1 invalid/transient source.
hdmi_v40o_build_live_merge:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d7,d5
        moveq   #0,d6
hdmi_v40o_live_find_h264:
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d3
        btst    #31,d3
        bne.w   hdmi_v40o_live_build_fail
        move.l  d3,d0
        andi.l  #$0000000f,d0
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d0
        beq.s   hdmi_v40o_live_h264_found
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_live_build_fail
        add.l   d0,d5
        addq.l  #1,d6
        cmpi.l  #8,d6
        bcs.s   hdmi_v40o_live_find_h264
        bra.w   hdmi_v40o_live_build_fail

hdmi_v40o_live_h264_found:
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        move.l  d0,d6
        beq.w   hdmi_v40o_live_build_fail
        cmpi.l  #32,d6
        bhi.w   hdmi_v40o_live_build_fail

        ; Determine exact original WB main-plane length.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.w   hdmi_v40o_live_build_fail
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        beq.w   hdmi_v40o_live_build_fail
        cmpi.l  #32,d2
        bhi.w   hdmi_v40o_live_build_fail

        ; 1) exact original WB main plane.
        move.l  hdmi_v40o_hvs_saved,d3
        bsr     hdmi_v40o_static_copy_words

        ; 2) exact WB remainder (mouse etc.) BEFORE video.
        ; Hardware v13 showed that with WB -> H264 -> mouse, the cursor vanished
        ; inside the H264 rectangle. Putting the cursor element before H264 is
        ; the z-order experiment for v15: cursor must remain visible over video.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        add.l   d2,d3
hdmi_v40o_live_copy_tail:
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.s   hdmi_v40o_live_append_end
        move.l  d2,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_live_build_fail
        move.l  d0,d2
        bsr     hdmi_v40o_static_copy_words
        add.l   d2,d3
        bra.s   hdmi_v40o_live_copy_tail
hdmi_v40o_live_append_end:
        ; 3) append exact active MMAL H264 element LAST, then END.
        ; This reverses only mouse/video z-order relative to v14.
        move.l  d5,d3
        move.l  d6,d2
        bsr     hdmi_v40o_static_copy_words
        ; d1 still contains the original WB END marker.
        move.l  d4,d0
        bsr     hdmi_v40o_dlist_store_idx
        moveq   #0,d0
        bra.s   hdmi_v40o_live_build_out
hdmi_v40o_live_build_fail:
        moveq   #1,d0
hdmi_v40o_live_build_out:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Called very frequently from the existing passive pacing loops. It only does
; real work once when the HVS channel-1 line counter wraps.
hdmi_v40o_live_merge_poll:
        rts

; --------------------------------------------------------------------
; HDMI_v41L STATIC POST-EOS MERGE PROOF
;
; During live playback v15 performs NO HVS list or active-pointer writes.
; After input EOS + the established 0.5 s renderer drain, this routine takes
; the currently displayed final MMAL H264 element, copies it together with
; the *original* VideoCore.card Workbench main plane and WB tail (mouse/END)
; into an independent list at DWORD $400, activates that list once at HVS
; vblank, holds it for 3 seconds, then returns to the original final MMAL
; list before normal renderer cleanup.
;
; This deliberately freezes the final video frame.  The sole question is:
; can original WB + original H264 + original mouse coexist stably when no
; firmware frame-list writer is racing us?
; --------------------------------------------------------------------

; Copy D2 DWORDs from source index D3 to destination index D4.
hdmi_v40o_static_copy_words:
        movem.l d0-d3/a0,-(sp)
        tst.l   d2
        beq.s   hdmi_v40o_static_copy_done
hdmi_v40o_static_copy_loop:
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,-(sp)
        move.l  d4,d0
        move.l  (sp)+,d1
        bsr     hdmi_v40o_dlist_store_idx
        addq.l  #1,d3
        addq.l  #1,d4
        subq.l  #1,d2
        bne.s   hdmi_v40o_static_copy_loop
hdmi_v40o_static_copy_done:
        movem.l (sp)+,d0-d3/a0
        rts

; Wait for HVS channel-1 raster wrap. Read-only until caller writes pointer.
hdmi_v40o_wait_hvs_vblank:
        movem.l d0-d3/a0,-(sp)
        move.l  #HDMI_V14_HVS_DISPSTAT1,a0
        jsr     load_le32
        andi.l  #$00000fff,d0
        move.l  d0,d2
hdmi_v40o_hvs_vb_loop:
        move.l  #HDMI_V14_HVS_DISPSTAT1,a0
        jsr     load_le32
        andi.l  #$00000fff,d0
        cmp.l   d2,d0
        bcs.s   hdmi_v40o_hvs_vb_done
        move.l  d0,d2
        bra.s   hdmi_v40o_hvs_vb_loop
hdmi_v40o_hvs_vb_done:
        movem.l (sp)+,d0-d3/a0
        rts

hdmi_v40o_static_merge_test:
        movem.l d0-d7/a0-a3,-(sp)
        clr.l   hdmi_v40o_merge_count
        clr.l   hdmi_v40o_merge_retry

        ; Current final MMAL display list after EOS/drain.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d7
        move.l  d7,hdmi_v40o_merge_last_src
        cmp.l   hdmi_v40o_hvs_saved,d7
        beq.w   hdmi_v40o_static_fail
        cmpi.l  #$00000fff,d7
        bhi.w   hdmi_v40o_static_fail

        ; Find H264 element dynamically in final MMAL list.
        move.l  d7,d5
        moveq   #0,d6
hdmi_v40o_static_find_h264:
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d3
        btst    #31,d3
        bne.w   hdmi_v40o_static_fail
        move.l  d3,d0
        andi.l  #$0000000f,d0
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d0
        beq.s   hdmi_v40o_static_h264_found
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_static_fail
        add.l   d0,d5
        addq.l  #1,d6
        cmpi.l  #8,d6
        bcs.s   hdmi_v40o_static_find_h264
        bra.w   hdmi_v40o_static_fail

hdmi_v40o_static_h264_found:
        move.l  d3,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        move.l  d0,d6                    ; H264 element DWORD count
        beq.w   hdmi_v40o_static_fail
        cmpi.l  #32,d6
        bhi.w   hdmi_v40o_static_fail

        ; Original Workbench main-plane size.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.w   hdmi_v40o_static_fail
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        beq.w   hdmi_v40o_static_fail
        cmpi.l  #32,d2
        bhi.w   hdmi_v40o_static_fail

        ; Destination = independent test list @ DWORD $400.
        move.l  #HDMI_V14_MERGE_DLIST,d4
        ; 1) exact original WB main plane.
        move.l  hdmi_v40o_hvs_saved,d3
        bsr     hdmi_v40o_static_copy_words

        ; 2) exact remainder of original WB list (mouse etc.) BEFORE H264.
        ; v13 hardware observation: old order WB -> H264 -> mouse put the
        ; cursor underneath video. v15 tests WB -> mouse -> H264.
        move.l  hdmi_v40o_hvs_saved,d3
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        lsr.l   #8,d2
        andi.l  #$0000003f,d2
        add.l   d2,d3
hdmi_v40o_static_copy_wb_tail:
        move.l  d3,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        btst    #31,d2
        bne.s   hdmi_v40o_static_append_end
        move.l  d2,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        beq.w   hdmi_v40o_static_fail
        move.l  d0,d2
        move.l  d4,d0
        subi.l  #HDMI_V14_MERGE_DLIST,d0
        add.l   d2,d0
        cmpi.l  #HDMI_V14_MERGE_MAX_WORDS,d0
        bhi.w   hdmi_v40o_static_fail
        bsr     hdmi_v40o_static_copy_words
        add.l   d2,d3
        bra.s   hdmi_v40o_static_copy_wb_tail

hdmi_v40o_static_append_end:
        ; 3) append exact final MMAL H264 element LAST, then WB END marker.
        move.l  d5,d3
        move.l  d6,d2
        bsr     hdmi_v40o_static_copy_words
        ; d1 still contains WB END marker.
        move.l  d4,d0
        bsr     hdmi_v40o_dlist_store_idx

        lea     msg_hdmi_v40o_static_begin,a1
        move.l  #msg_hdmi_v40o_static_begin_end-msg_hdmi_v40o_static_begin,d3
        jsr     print
        move.l  d7,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_static_mid,a1
        move.l  #msg_hdmi_v40o_static_mid_end-msg_hdmi_v40o_static_mid,d3
        jsr     print
        move.l  d5,d0
        jsr     print_hex32
        jsr     newline

        ; Activate merged list ONCE after all video frames are drained.
        bsr     hdmi_v40o_wait_hvs_vblank
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  #HDMI_V14_MERGE_DLIST,d0
        jsr     store_le32
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmpi.l  #HDMI_V14_MERGE_DLIST,d0
        bne.w   hdmi_v40o_static_fail_restore
        move.l  #1,hdmi_v40o_merge_count

        lea     msg_hdmi_v40o_static_hold,a1
        move.l  #msg_hdmi_v40o_static_hold_end-msg_hdmi_v40o_static_hold,d3
        jsr     print

        ; 3 second observation window. No new decoder input is being fed.
        bsr     dma_pre_all
        move.l  a5,a6
        move.l  #150,d1
        jsr     Delay(a6)
        bsr     dma_post_all

        ; Did firmware leave our static list alone once frames had stopped?
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d2
        lea     msg_hdmi_v40o_static_after,a1
        move.l  #msg_hdmi_v40o_static_after_end-msg_hdmi_v40o_static_after,d3
        jsr     print
        move.l  d2,d0
        jsr     print_hex32
        jsr     newline
        cmpi.l  #HDMI_V14_MERGE_DLIST,d2
        beq.s   hdmi_v40o_static_restore_source
        addq.l  #1,hdmi_v40o_merge_retry

hdmi_v40o_static_restore_source:
        ; Return to the final MMAL list before renderer teardown, preserving
        ; the already hardware-proven cleanup ordering.
        bsr     hdmi_v40o_wait_hvs_vblank
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  hdmi_v40o_merge_last_src,d0
        jsr     store_le32
        lea     msg_hdmi_v40o_static_restore,a1
        move.l  #msg_hdmi_v40o_static_restore_end-msg_hdmi_v40o_static_restore,d3
        jsr     print
        bra.s   hdmi_v40o_static_done

hdmi_v40o_static_fail_restore:
        addq.l  #1,hdmi_v40o_merge_retry
        ; Best effort restore to original final MMAL list.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  hdmi_v40o_merge_last_src,d0
        jsr     store_le32
        bra.s   hdmi_v40o_static_fail_msg

hdmi_v40o_static_fail:
        addq.l  #1,hdmi_v40o_merge_retry
hdmi_v40o_static_fail_msg:
        lea     msg_hdmi_v40o_static_fail,a1
        move.l  #msg_hdmi_v40o_static_fail_end-msg_hdmi_v40o_static_fail,d3
        jsr     print
hdmi_v40o_static_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; --------------------------------------------------------------------
; HDMI_v41L legacy v12 live-patch code retained but NOT CALLED in v15.
;
; v10 proved that EXPANDING MMAL's 8-DWORD background element into the
; 16-DWORD scaled Workbench element is unsafe: firmware continues rebuilding
; its H264 element at the original +8 position, so the two layouts overlap.
;
; v12 NEVER changes element offsets or list length.  It learns the two MMAL
; lists and, while one list is inactive, overwrites ONLY DWORDs +0..+7 with
; an 8-DWORD compact Workbench UNITY element.  The H264 element remains at
; MMAL's original +8 position and is never moved or copied.
;
; The current Workbench is scaled by VideoCore.card (1280x720 -> 1920x1080),
; which needs a 16-DWORD PPF element.  For this isolation test v12 converts
; it to a UNITY element using the same framebuffer address/pitch/pixel mode.
; Therefore Workbench is intentionally shown at its native source size at
; x=0,y=0.  If this is stable, later work can add clipping/scaling safely.
; --------------------------------------------------------------------

; D0 = dword index. D1 = host-order word loaded.
hdmi_v40o_dlist_load_idx:
        movem.l d0/a0,-(sp)
        move.l  #HDMI_V14_HVS_DLIST_BASE,a0
        lsl.l   #2,d0
        adda.l  d0,a0
        jsr     load_le32
        move.l  d0,d1
        movem.l (sp)+,d0/a0
        rts

; D0 = destination dword index, D1 = host-order word.
hdmi_v40o_dlist_store_idx:
        movem.l d0/a0,-(sp)
        move.l  #HDMI_V14_HVS_DLIST_BASE,a0
        lsl.l   #2,d0
        adda.l  d0,a0
        move.l  d1,d0
        jsr     store_le32
        movem.l (sp)+,d0/a0
        rts

; Build the Workbench fields that can be transplanted into MMAL's existing
; 8-DWORD UNITY background element WITHOUT changing its layout or length.
;
; v11 built a new element and therefore changed too many semantics at once.
; v12 preserves MMAL's own control/layout/scratch words and changes only:
;   CTL0 format + pixel-order bits
;   POS2 native source width/height
;   PTR0 framebuffer address
;   PITCH0 bytes/row
;
; hdmi_v40o_wb_bg_tmp layout used here:
;   +0 = WB format/order mask (CONTROL_FORMAT + CONTROL_PIXEL_ORDER)
;   +2 = WB native source POS2 width/height
;   +4 = WB framebuffer pointer
;   +6 = WB pitch
; Return D0=0 success, 1 unsupported.
hdmi_v40o_build_wb_bg:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  hdmi_v40o_hvs_saved,d7

        ; Validate saved VideoCore.card Workbench main element.
        move.l  d7,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d6
        btst    #30,d6
        beq.w   hdmi_v40o_wb_bg_fail
        move.l  d6,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        cmpi.l  #8,d0
        bcs.w   hdmi_v40o_wb_bg_fail
        cmpi.l  #32,d0
        bhi.w   hdmi_v40o_wb_bg_fail

        lea     hdmi_v40o_wb_bg_tmp,a2
        ; Clear temp area first (8 DWORDs).
        moveq   #0,d0
        moveq   #7,d1
hdmi_v40o_wb_tmp_clear:
        move.l  d0,(a2)+
        dbra    d1,hdmi_v40o_wb_tmp_clear
        lea     hdmi_v40o_wb_bg_tmp,a2

        ; Exact Workbench HVS pixel format + pixel order.
        move.l  d6,d1
        andi.l  #$0000600f,d1
        move.l  d1,(a2)

        ; Scaled WB source POS2 is saved WB +3. Keep only native H/W fields;
        ; alpha/scaler mode bits from the scaled element are not valid for
        ; MMAL's UNITY background slot.
        move.l  d7,d0
        addq.l  #3,d0
        bsr     hdmi_v40o_dlist_load_idx
        andi.l  #$0fff0fff,d1
        move.l  d1,8(a2)

        ; Workbench framebuffer bus pointer.
        move.l  d7,d0
        addq.l  #5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,16(a2)

        ; Workbench pitch.
        move.l  d7,d0
        addq.l  #7,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,24(a2)

        moveq   #0,d0
        bra.s   hdmi_v40o_wb_bg_out
hdmi_v40o_wb_bg_fail:
        moveq   #1,d0
hdmi_v40o_wb_bg_out:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; D5 = inactive MMAL list start.
; Return D0: 1=patched, 0=already correct/no work, 2=transient/race.
hdmi_v40o_patch_inactive:
        movem.l d1-d7/a0-a3,-(sp)

        ; Never patch the list currently scanned by HVS.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmp.l   d5,d0
        beq.w   hdmi_v40o_patch_retry

        ; Firmware H264 element must remain exactly at +8.
        move.l  d5,d0
        addq.l  #8,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        andi.l  #$0000000f,d2
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d2
        bne.w   hdmi_v40o_patch_retry
        btst    #30,d1
        beq.w   hdmi_v40o_patch_retry

        ; MMAL first element must itself be VALID, exactly 8 DWORDs and UNITY.
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d6                    ; current MMAL CTL0
        btst    #30,d6
        beq.w   hdmi_v40o_patch_retry
        btst    #4,d6
        beq.w   hdmi_v40o_patch_retry
        move.l  d6,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        andi.l  #$0000003f,d0
        cmpi.l  #8,d0
        bne.w   hdmi_v40o_patch_retry

        bsr     hdmi_v40o_build_wb_bg
        tst.l   d0
        bne.w   hdmi_v40o_patch_retry
        lea     hdmi_v40o_wb_bg_tmp,a2

        ; Desired CTL0 = MMAL CTL0 with ONLY format/order replaced by WB.
        move.l  d6,d7
        andi.l  #$ffff9ff0,d7
        or.l    (a2),d7

        ; If all four stable fields are already ours, don't hammer firmware.
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   d7,d1
        bne.s   hdmi_v40o_patch_needed
        move.l  d5,d0
        addq.l  #2,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   8(a2),d1
        bne.s   hdmi_v40o_patch_needed
        move.l  d5,d0
        addq.l  #4,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   16(a2),d1
        bne.s   hdmi_v40o_patch_needed
        move.l  d5,d0
        addq.l  #6,d0
        bsr     hdmi_v40o_dlist_load_idx
        cmp.l   24(a2),d1
        bne.s   hdmi_v40o_patch_needed
        moveq   #0,d0
        bra.w   hdmi_v40o_patch_out

hdmi_v40o_patch_needed:
        ; Final ownership check. Four DWORD stores only; scratch/context words
        ; and MMAL's eighth private word are deliberately untouched.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmp.l   d5,d0
        beq.w   hdmi_v40o_patch_retry

        move.l  d7,d1
        move.l  d5,d0
        bsr     hdmi_v40o_dlist_store_idx
        move.l  8(a2),d1
        move.l  d5,d0
        addq.l  #2,d0
        bsr     hdmi_v40o_dlist_store_idx
        move.l  16(a2),d1
        move.l  d5,d0
        addq.l  #4,d0
        bsr     hdmi_v40o_dlist_store_idx
        move.l  24(a2),d1
        move.l  d5,d0
        addq.l  #6,d0
        bsr     hdmi_v40o_dlist_store_idx

        ; If firmware activated the list during those four stores, report a
        ; transient race; never touch the active-pointer register here.
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        cmp.l   d5,d0
        beq.s   hdmi_v40o_patch_retry

        move.l  d5,hdmi_v40o_last_patched
        moveq   #1,d0
        bra.s   hdmi_v40o_patch_out

hdmi_v40o_patch_retry:
        moveq   #2,d0
hdmi_v40o_patch_out:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Learn the two alternating MMAL lists. While one is active, patch only the
; other list's first eight background DWORDs. No element moves, no active
; pointer writes, no H264 data stores.
hdmi_v40o_merge_poll:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,d7
        cmp.l   hdmi_v40o_hvs_saved,d7
        beq.w   hdmi_v40o_merge_done
        cmpi.l  #$00000fff,d7
        bhi.w   hdmi_v40o_merge_bad

        ; Genuine MMAL list must have H264 exactly at +8 in v12.
        move.l  d7,d0
        addq.l  #8,d0
        bsr     hdmi_v40o_dlist_load_idx
        move.l  d1,d2
        andi.l  #$0000000f,d2
        cmpi.l  #HDMI_V14_HVS_FMT_H264,d2
        bne.w   hdmi_v40o_merge_done

        move.l  hdmi_v40o_slot_a,d0
        bne.s   hdmi_v40o_have_a
        move.l  d7,hdmi_v40o_slot_a
        bra.w   hdmi_v40o_merge_done
hdmi_v40o_have_a:
        cmp.l   d0,d7
        beq.s   hdmi_v40o_choose_inactive
        move.l  hdmi_v40o_slot_b,d1
        bne.s   hdmi_v40o_choose_inactive
        move.l  d7,hdmi_v40o_slot_b

hdmi_v40o_choose_inactive:
        move.l  hdmi_v40o_slot_b,d1
        beq.w   hdmi_v40o_merge_done
        move.l  hdmi_v40o_slot_a,d0
        cmp.l   d0,d7
        beq.s   hdmi_v40o_inactive_b
        cmp.l   d1,d7
        bne.w   hdmi_v40o_merge_done
        move.l  d0,d5
        bra.s   hdmi_v40o_do_patch
hdmi_v40o_inactive_b:
        move.l  d1,d5

hdmi_v40o_do_patch:
        bsr     hdmi_v40o_patch_inactive
        cmpi.l  #1,d0
        beq.s   hdmi_v40o_patch_counted
        cmpi.l  #2,d0
        bne.w   hdmi_v40o_maybe_report_slots
        addq.l  #1,hdmi_v40o_merge_retry
        cmpi.l  #1,hdmi_v40o_merge_retry
        bne.w   hdmi_v40o_maybe_report_slots
        lea     msg_hdmi_v40o_merge_fail,a1
        move.l  #msg_hdmi_v40o_merge_fail_end-msg_hdmi_v40o_merge_fail,d3
        jsr     print
        bra.w   hdmi_v40o_maybe_report_slots
hdmi_v40o_patch_counted:
        addq.l  #1,hdmi_v40o_merge_count
        move.l  d5,hdmi_v40o_merge_last_src

hdmi_v40o_maybe_report_slots:
        move.l  hdmi_v40o_slots_reported,d0
        bne.s   hdmi_v40o_merge_done
        move.l  hdmi_v40o_slot_a,d0
        beq.s   hdmi_v40o_merge_done
        move.l  hdmi_v40o_slot_b,d1
        beq.s   hdmi_v40o_merge_done
        move.l  #1,hdmi_v40o_slots_reported
        lea     msg_hdmi_v40o_merge_first,a1
        move.l  #msg_hdmi_v40o_merge_first_end-msg_hdmi_v40o_merge_first,d3
        jsr     print
        lea     msg_hdmi_v40o_merge_src,a1
        move.l  #msg_hdmi_v40o_merge_src_end-msg_hdmi_v40o_merge_src,d3
        jsr     print
        move.l  hdmi_v40o_slot_a,d0
        jsr     print_hex32
        lea     msg_hdmi_v40o_merge_rb,a1
        move.l  #msg_hdmi_v40o_merge_rb_end-msg_hdmi_v40o_merge_rb,d3
        jsr     print
        move.l  hdmi_v40o_slot_b,d0
        jsr     print_hex32
        jsr     newline
        bra.s   hdmi_v40o_merge_done

hdmi_v40o_merge_bad:
        addq.l  #1,hdmi_v40o_merge_retry
hdmi_v40o_merge_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; Wait for one complete PAL raster wrap using read-only custom-chip polling.
; No Exec interrupt server and no Copper/bitplane/DMA state is touched.
hdmi_v40o_wait_vblank:
        movem.l d0-d2,-(sp)
        jsr     v04_sample_raster
        move.l  d0,d1
hdmi_v40o_wait_vblank_loop:
        jsr     v04_sample_raster
        cmp.l   d1,d0
        bcs.s   hdmi_v40o_wait_vblank_done
        move.l  d0,d1
        bra.s   hdmi_v40o_wait_vblank_loop
hdmi_v40o_wait_vblank_done:
        movem.l (sp)+,d0-d2
        rts

; Restore exactly the HVS display-list offset that was active before
; ril.video_render existed. The MMIO register is little-endian from the 68k
; view, so use the same byte-swap helper as the diagnostic read.
hdmi_v40o_restore_hvs_ptr:
        movem.l d1-d3/a0-a1,-(sp)
        lea     msg_hdmi_v40o_hvs_restore_begin,a1
        move.l  #msg_hdmi_v40o_hvs_restore_begin_end-msg_hdmi_v40o_hvs_restore_begin,d3
        jsr     print
        move.l  hdmi_v40o_hvs_saved,d0
        jsr     print_hex32
        jsr     newline
        bsr     hdmi_v40o_wait_vblank
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        move.l  hdmi_v40o_hvs_saved,d0
        jsr     store_le32
        move.l  #HDMI_V14_HVS_DLIST_PTR,a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_hvs_last
        lea     msg_hdmi_v40o_hvs_restore_readback,a1
        move.l  #msg_hdmi_v40o_hvs_restore_readback_end-msg_hdmi_v40o_hvs_restore_readback,d3
        jsr     print
        move.l  hdmi_v40o_hvs_last,d0
        jsr     print_hex32
        jsr     newline
        move.l  hdmi_v40o_hvs_last,d0
        movem.l (sp)+,d1-d3/a0-a1
        rts

; HDMI_v41L: MMAL video_render display-region control with HVS restore.
; MMAL_DISPLAYREGION_T uses fullscreen TRUE and the native P96/Workbench area.
; The renderer may take over the HVS list while video is visible; after full
; MMAL teardown HDMI_v41L restores the exact VideoCore.card/Workbench HVS offset
; captured before renderer creation. Visible alpha is 255 | MMAL_DISPLAY_ALPHA_FLAGS_DISCARD_LOWER_LAYERS (bit 29).
; This asks VideoCore to discard lower display layers behind cinema video.
;
; set bits: NUM | FULLSCREEN | DEST_RECT | LAYER | ALPHA = 0x50B
; layer: 10, visible alpha: 0x200000FF, display number explicitly selected.
; Returns D0=0 success, D0=1 failure. Shared memory CPU-owned on return.
hdmi_v40o_set_displayregion:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   hdmi_v40o_param_status
        clr.l   hdmi_v40o_param_rx_size

        ; Worker payload is 32-byte prefix before param + 84-byte displayregion
        ; = 116 bytes. With 8-byte VCHIQ header, reserve/alignment stride = 128.
        tst.l   v12f_local_port
        beq.s   hdmi_v40o_param_tx_legacy
        move.l  #128,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   hdmi_v40o_param_fail
        bra.s   hdmi_v40o_param_tx_ready
hdmi_v40o_param_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
hdmi_v40o_param_tx_ready:
        move.l  a2,a0
        moveq   #31,d7
hdmi_v40o_param_clear:
        clr.l   (a0)+
        dbra    d7,hdmi_v40o_param_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #116,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_SET,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12D30001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  v12a_isp_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  v12a_isp_input,d0
        jsr     store_le32

        ; MMAL_DISPLAYREGION_T begins at worker param offset +40.
        lea     40(a2),a0
        move.l  #MMAL_PARAMETER_DISPLAYREGION,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #84,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  #HDMI_V14_DISPLAY_SET,d0
        jsr     store_le32
        ; +52 display_num = 1, explicitly selected by DISPLAY_SET_NUM.
        lea     52(a2),a0
        move.l  #HDMI_V18_DISPLAY_NUM,d0
        jsr     store_le32
        lea     56(a2),a0
        moveq   #1,d0                   ; renderer owns full HDMI display region
        jsr     store_le32
        ; +60 transform = 0. dest_rect = complete current P96/Workbench screen.
        lea     64(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     68(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     72(a2),a0
        move.l  hdmi_v40o_wb_width,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  hdmi_v40o_wb_height,d0
        jsr     store_le32
        lea     112(a2),a0
        move.l  #HDMI_V14_LAYER,d0
        jsr     store_le32
        ; +116 copyprotect = 0, left cleared.
        lea     120(a2),a0
        moveq   #0,d0
        tst.l   v41b_renderer_visible
        beq.s   v41b_displayregion_alpha_ready
        move.l  #HDMI_V41K_CINEMA_ALPHA,d0 ; 255 + DISCARD_LOWER_LAYERS when visible
v41b_displayregion_alpha_ready:
        jsr     store_le32

        add.l   #128,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   hdmi_v40o_param_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
hdmi_v40o_param_wait_setup:
        move.l  #POLL_COUNT,d7
hdmi_v40o_param_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   hdmi_v40o_param_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   hdmi_v40o_param_wait
        jsr     dma_post_all
        bra.w   hdmi_v40o_param_fail

hdmi_v40o_param_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   hdmi_v40o_param_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_param_rx_size
        cmp.l   #28,d0
        bcs.w   hdmi_v40o_param_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   hdmi_v40o_param_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.w   hdmi_v40o_param_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$12D30001,d0
        bne.w   hdmi_v40o_param_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,hdmi_v40o_param_status
        move.l  hdmi_v40o_param_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   hdmi_v40o_param_fail
        move.l  hdmi_v40o_param_status,d0
        tst.l   d0
        bne.w   hdmi_v40o_param_fail
        move.l  #1,hdmi_v40o_displayregion_ok
        lea     msg_hdmi_v40o_displayregion_ok,a1
        move.l  #msg_hdmi_v40o_displayregion_ok_end-msg_hdmi_v40o_displayregion_ok,d3
        jsr     print
        moveq   #0,d0
        bra.s   hdmi_v40o_param_done

hdmi_v40o_param_fail_consume:
        move.l  hdmi_v40o_param_rx_size,d0
        jsr     v12a_rx_consume_payload
hdmi_v40o_param_fail:
        clr.l   hdmi_v40o_displayregion_ok
        lea     msg_hdmi_v40o_displayregion_warn,a1
        move.l  #msg_hdmi_v40o_displayregion_warn_end-msg_hdmi_v40o_displayregion_warn,d3
        jsr     print
        move.l  hdmi_v40o_param_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
hdmi_v40o_param_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Apply buffer requirements to the connected ISP input. This mirrors
; mmal_vc_port_enable(): a connected output first sends
; MMAL_WORKER_PORT_ACTION_SET_REQUIREMENTS to the peer input, then enables
; the output. Current port_* globals must describe ISP INPUT 0.
v12a_set_isp_requirements:
        movem.l d1-d7/a0-a3,-(sp)
        ; 100-byte MMAL payload + 8-byte VCHIQ header -> 112-byte stride.
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_req_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_req_fail
        bra.s   v12g_req_tx_ready
v12g_req_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_req_tx_ready:
        move.l  a2,a0
        moveq   #27,d7
v12a_req_clear:
        clr.l   (a0)+
        dbra    d7,v12a_req_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  #$12A60001,d0
        bsr     store_le32
        lea     32(a2),a0
        move.l  v12a_isp_handle,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  v12a_isp_input,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_SET_REQUIREMENTS,d0
        bsr     store_le32
        ; struct mmal_port starts at offset 44.
        lea     52(a2),a0
        move.l  #MMAL_PORT_INPUT,d0
        bsr     store_le32
        lea     60(a2),a0
        move.l  port_enabled,d0
        bsr     store_le32
        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32
        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32
        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32
        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32
        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$12A60001,d0
        bsr     store_le32
        lea     104(a2),a0
        move.l  port_caps,d0
        bsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,d6
        bsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_req_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_req_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_req_wait:
        bsr     short_delay
        bsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_req_have
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_req_wait
        bsr     dma_post_all
        bra.w   v12a_req_fail
v12a_req_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_req_fail
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,v12a_req_rx_size
        cmp.l   #28,d0
        bcs.w   v12a_req_fail
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_req_fail_consume
        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   v12a_req_fail_consume
        lea     20(a2),a0
        bsr     load_le32
        cmp.l   #$12A60001,d0
        bne.w   v12a_req_fail_consume
        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   v12a_req_fail_consume
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,v12a_req_status
        move.l  v12a_req_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_req_fail
        move.l  v12a_req_status,d0
        tst.l   d0
        bne.w   v12a_req_fail
        lea     msg_v12a_requirements_ok,a1
        move.l  #msg_v12a_requirements_ok_end-msg_v12a_requirements_ok,d3
        bsr     print
        moveq   #0,d0
        bra.s   v12a_req_done
v12a_req_fail_consume:
        move.l  v12a_req_rx_size,d0
        jsr     v12a_rx_consume_payload
v12a_req_fail:
        lea     msg_v12a_requirements_fail,a1
        move.l  #msg_v12a_requirements_fail_end-msg_v12a_requirements_fail,d3
        bsr     print
        move.l  v12a_req_status,d0
        bsr     print_hex32
        bsr     newline
        moveq   #1,d0
v12a_req_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Main graph setup. Returns with decoder in component_handle and ISP output in
; output_port_handle/output_component_handle. Host output geometry is small.
v12a_setup_isp_graph:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  #1,v12a_local_get_active
        move.l  component_handle,v12a_decoder_handle
        move.l  input_port_handle,v12a_saved_input_handle
        move.l  output_port_handle,v12a_decoder_output

        ; Snapshot decoder output, deliberately WITHOUT the old 640x480 DMA cap.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_I420,d0
        bne.w   v12a_setup_fail
        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        move.l  port_video_width,v12a_dec_w
        move.l  port_video_height,v12a_dec_h
        move.l  port_crop_x,v12a_dec_crop_x
        move.l  port_crop_y,v12a_dec_crop_y
        move.l  port_crop_width,v12a_dec_crop_w
        move.l  port_crop_height,v12a_dec_crop_h
        move.l  port_fps_num,v12a_dec_fps_num
        move.l  port_fps_den,v12a_dec_fps_den
        move.l  port_par_num,v12a_dec_par_num
        move.l  port_par_den,v12a_dec_par_den
        move.l  port_color_space,v12a_dec_colorspace

        ; HDMI_v41L: no size is changed while a movie is running.  The user
        ; chooses the fixed ISP preset in the Intuition window BEFORE the ISP
        ; graph is created.  Until then no target geometry is committed.
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        clr.l   v32_fixed_mode

        ; HDMI_v41L: capture the live VideoCore.card/P96 framebuffer before
        ; any video component can touch HVS. The renderer-free path writes
        ; only into this normal Amiga/RTG framebuffer.
        jsr     hdmi_v40o_capture_wb_fb
        tst.l   d0
        bne.w   v12a_setup_fail

        ; V41L C: choose cinema window style before the very first OpenWindow,
        ; so direct cinema does not flash the small normal P96 window first.
        cmpi.l  #203,v40j_cli_mode
        bne.s   v41l_preopen_normal_style
        move.l  #3,v41_display_style
        bra.s   v41l_preopen_style_ready
v41l_preopen_normal_style:
        clr.l   v41_display_style
v41l_preopen_style_ready:
        ; Open a real Intuition surface. In C mode it is borderless/full-area
        ; from the start and serves only as the cinema key-event catcher.
        jsr     hdmi_v40o_open_window
        tst.l   d0
        bne.w   v12a_setup_fail

        ; V40: select the fixed VideoCore-ISP size now, before decoder OUTPUT
        ; is switched to OPQV and before ril.isp exists.  This is the core
        ; safety difference from v25/v30: the graph never changes mid-stream.
        jsr     v32_wait_initial_mode
        tst.l   d0
        bne.w   v12a_setup_fail

        lea     msg_v12a_target,a1
        move.l  #msg_v12a_target_end-msg_v12a_target,d3
        jsr     print
        move.l  v12a_dec_crop_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_crop_h,d0
        jsr     print_hex32
        lea     msg_v12a_arrow,a1
        move.l  #msg_v12a_arrow_end-msg_v12a_arrow,d3
        jsr     print
        move.l  v12a_target_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_target_h,d0
        jsr     print_hex32
        jsr     newline

        ; V12D: keep the full 1080p frame inside VideoCore.  The V12A
        ; I420 tunnel still described each connected buffer as a 0x2FD000-byte
        ; 1080p surface.  With only 32 MiB VC memory this can exhaust the
        ; firmware heap as soon as the decoder allocates its reference frames.
        ; The MMAL decoder supports OPQV output, and ril.isp supports OPQV input.
        ; Commit OPQV first, re-read its small buffer requirements, then commit
        ; the firmware MINIMUM header count before making the tunnel.
        move.l  v12a_decoder_handle,component_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_extra
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12b_dec_opaque_first_num_ok
        moveq   #2,d0
v12b_dec_opaque_first_num_ok:
        move.l  d0,port_buf_num
        ; First format commit may still carry the old I420 buffer_size.  No
        ; buffers are allocated yet; the following GET reveals OPQV minima.
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; V12D: use the decoder's MINIMUM opaque header count, not the
        ; recommended count.  This firmware reports min=3, recommended=10 at
        ; 1080p.  The official MMAL decoder example likewise uses buffer_num_min.
        ; Keeping ten OPQV surfaces is a prime ENOSPC suspect with only 32 MiB
        ; VideoCore memory.  Never go below the firmware-declared minimum.
        move.l  port_buf_num_min,d0
        cmpi.l  #2,d0
        bcc.s   v12b_dec_num_two_ok
        moveq   #2,d0
v12b_dec_num_two_ok:
        move.l  d0,port_buf_num

        move.l  port_buf_size_min,d0
        cmp.l   port_buf_size_rec,d0
        bcc.s   v12b_dec_size_rec_ok
        move.l  port_buf_size_rec,d0
v12b_dec_size_rec_ok:
        tst.l   d0
        bne.s   v12b_dec_size_nonzero
        move.l  #128,d0
v12b_dec_size_nonzero:
        move.l  d0,port_buf_size
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail
        ; V12D: OPQV carries the underlying pixel format in variant.
        ; Hardware returned I420 ($30323449) here; ISP input must receive
        ; the same variant instead of zero or it rejects PORT_INFO_SET/EINVAL.
        move.l  port_fmt_variant,v12c_dec_variant
        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        lea     msg_v12b_decoder_opaque,a1
        move.l  #msg_v12b_decoder_opaque_end-msg_v12b_decoder_opaque,d3
        jsr     print
        move.l  v12a_dec_buf_num,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_buf_size,d0
        jsr     print_hex32
        jsr     newline

        bsr     v12a_create_isp
        tst.l   d0
        bne.w   v12a_setup_fail
        cmpi.l  #3,v41_display_style
        bne.s   v41b_setup_continue_isp
        jsr     v41b_setup_renderer_after_create
        tst.l   d0
        bne.w   v12a_setup_fail
        moveq   #0,d0
        bra.w   v12a_setup_done
v41b_setup_continue_isp:

        ; ISP INPUT 0 = decoder full-size OPQV (opaque VideoCore frame handle).
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,v12a_isp_input
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12a_in_num_ok
        moveq   #2,d0
v12a_in_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; HDMI_v41L: ISP OUTPUT 0 = small aspect-correct BGRA8888. VideoCore does YUV->RGB.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,v12a_isp_output
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_BGRA,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_target_aw,port_video_width
        move.l  v12a_target_ah,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  v12a_target_w,port_crop_width
        move.l  v12a_target_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        moveq   #1,d0
        move.l  d0,port_par_num
        move.l  d0,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  v12a_target_aw,d0
        move.l  v12a_target_ah,d1
        mulu.w  d1,d0
        lsl.l   #2,d0                    ; RGBA: 4 bytes/pixel
        move.l  d0,port_buf_size
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_BGRA,d0
        bne.w   v12a_setup_fail

        ; Tunnel inside VideoCore.
        bsr     v12a_connect_ports
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Official MMAL VC client applies the peer input buffer requirements
        ; before enabling a connected output. Without this ril.isp can reject
        ; its input definition or never become enabled.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v12a_setup_fail
        bsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Enable decoder OUTPUT; connected ISP INPUT should be enabled automatically.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12a_dec_out_num_ok
        moveq   #2,d0
v12a_dec_out_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Verify ISP input came up through the tunnel.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_enabled,d0
        cmpi.l  #1,d0
        bne.w   v12a_setup_fail

        ; Enable host-facing ISP output with exactly two small buffers.
        move.l  v12a_isp_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  d0,v10j_output_req_count
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  port_enabled,d0
        cmpi.l  #1,d0
        bne.w   v12a_setup_fail

        ; ISP is a real component and must be enabled too.
        jsr     component_enable_worker
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Save only the SMALL ISP output for existing host/HAM6 code.
        move.l  v12a_isp_handle,output_component_handle
        move.l  v12a_isp_output,output_port_handle
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        move.l  output_width_saved,d0
        move.l  output_height_saved,d1
        mulu.w  d1,d0
        lsl.l   #2,d0                    ; RGBA: aligned width*height*4
        move.l  d0,output_frame_bytes_expected
        cmp.l   output_buf_size_saved,d0
        bhi.w   v12a_setup_fail

        ; V40: the chosen size is now final for this playback.  Resize the
        ; Intuition window exactly once to surround the fixed ISP crop.
        jsr     v32f_resize_window_fixed

        ; Restore decoder as the input-side component for H264/EOS messages.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle

        lea     msg_v12a_graph_ok,a1
        move.l  #msg_v12a_graph_ok_end-msg_v12a_graph_ok,d3
        jsr     print
        move.l  output_width_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_height_saved,d0
        jsr     print_hex32
        lea     msg_crop,a1
        move.l  #msg_crop_end-msg_crop,d3
        jsr     print
        move.l  output_crop_w_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_crop_h_saved,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12a_setup_done
v12a_setup_fail:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     msg_v12a_graph_fail,a1
        move.l  #msg_v12a_graph_fail_end-msg_v12a_graph_fail,d3
        jsr     print
        moveq   #1,d0
v12a_setup_done:
        clr.l   v12a_local_get_active
        movem.l (sp)+,d1-d7/a0-a3
        rts


; ====================================================================
; V12E - bounded-memory MP4 demux for the V12D VideoCore ISP path.
; Only the moov atom (max 8 MiB) is retained in Fast RAM. Movie samples
; are read directly from disk and converted avcC length-prefix -> Annex-B.
; Decoder input stays UNFRAMED, so sample fragments may span MMAL buffers.
; ====================================================================
        section code,code

; D0=1 for .mp4 (case-insensitive), else 0.
v12e_is_mp4:
        movem.l d1-d3/a0-a1,-(sp)
        lea     t23_file_name,a0
        move.l  a0,a1
        clr.l   d1
v12e_ext_len:
        tst.b   (a1)
        beq.s   v12e_ext_len_done
        addq.l  #1,a1
        addq.l  #1,d1
        bra.s   v12e_ext_len
v12e_ext_len_done:
        cmpi.l  #4,d1
        bcs.s   v12e_ext_no
        subq.l  #4,a1
        cmpi.b  #$2E,(a1)
        bne.s   v12e_ext_no
        moveq   #0,d2
        move.b  1(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$6D,d2
        bne.s   v12e_ext_no
        moveq   #0,d2
        move.b  2(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$70,d2
        bne.s   v12e_ext_no
        moveq   #0,d2
        move.b  3(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$34,d2
        bne.s   v12e_ext_no
        moveq   #1,d0
        bra.s   v12e_ext_done
v12e_ext_no:
        moveq   #0,d0
v12e_ext_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; big-endian 32-bit load, A0 unchanged.
v12e_be32:
        moveq   #0,d0
        move.b  (a0),d0
        lsl.l   #8,d0
        move.b  1(a0),d0
        lsl.l   #8,d0
        move.b  2(a0),d0
        lsl.l   #8,d0
        move.b  3(a0),d0
        rts

; Read exactly D3 bytes from t23_file_handle to D2 address. D0=0/1.
v12e_read_exact:
        movem.l d1-d3/a6,-(sp)
        move.l  t23_file_handle,d1
        tst.l   d1
        beq.s   v12e_read_exact_fail
        move.l  a5,a6
        jsr     Read(a6)
        cmp.l   d3,d0
        bne.s   v12e_read_exact_fail
        moveq   #0,d0
        bra.s   v12e_read_exact_done
v12e_read_exact_fail:
        moveq   #1,d0
v12e_read_exact_done:
        movem.l (sp)+,d1-d3/a6
        rts

; Seek absolute D0. D0=0 success/1 failure.
v12e_seek_abs:
        movem.l d1-d3/a6,-(sp)
        move.l  d0,d2
        move.l  t23_file_handle,d1
        move.l  #OFFSET_BEGINNING,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        beq.s   v12e_seek_fail
        moveq   #0,d0
        bra.s   v12e_seek_done
v12e_seek_fail:
        moveq   #1,d0
v12e_seek_done:
        movem.l (sp)+,d1-d3/a6
        rts

; Skip D0 bytes from current file position.
v12e_seek_cur:
        movem.l d1-d3/a6,-(sp)
        move.l  d0,d2
        move.l  t23_file_handle,d1
        move.l  #OFFSET_CURRENT,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        beq.s   v12e_seekc_fail
        moveq   #0,d0
        bra.s   v12e_seekc_done
v12e_seekc_fail:
        moveq   #1,d0
v12e_seekc_done:
        movem.l (sp)+,d1-d3/a6
        rts

; Parse a memory atom header. A0=atom, A1=container end.
; success D1=0, D0=type, A2=payload, A3=end. failure D1=1.
v12e_mem_atom:
        movem.l d2-d5,-(sp)
        moveq   #1,d1
        move.l  a1,d0
        sub.l   a0,d0
        cmpi.l  #8,d0
        bcs.w   v12e_mem_atom_done
        move.l  a0,d2                  ; original atom start
        bsr     v12e_be32
        move.l  d0,d3                  ; size low
        lea     4(a0),a0
        bsr     v12e_be32
        move.l  d0,d4                  ; type
        move.l  d2,a0
        moveq   #8,d5                  ; header bytes
        cmpi.l  #1,d3
        bne.s   v12e_mem_normal
        move.l  a1,d0
        sub.l   d2,d0
        cmpi.l  #16,d0
        bcs.s   v12e_mem_atom_done
        move.l  d2,a0
        lea     8(a0),a0
        bsr     v12e_be32
        tst.l   d0
        bne.s   v12e_mem_atom_done     ; nested atom >4 GiB unsupported
        move.l  d2,a0
        lea     12(a0),a0
        bsr     v12e_be32
        move.l  d0,d3
        moveq   #16,d5
v12e_mem_normal:
        move.l  d2,a0
        tst.l   d3
        bne.s   v12e_mem_have_size
        move.l  a1,d3
        sub.l   d2,d3                  ; size 0 = rest of parent
v12e_mem_have_size:
        cmp.l   d5,d3
        bcs.s   v12e_mem_atom_done
        move.l  d2,a3
        adda.l  d3,a3
        cmpa.l  a1,a3
        bhi.s   v12e_mem_atom_done
        move.l  d2,a2
        adda.l  d5,a2
        move.l  d4,d0
        move.l  d2,a0                  ; leave A0 at atom start for callers
        moveq   #0,d1
v12e_mem_atom_done:
        movem.l (sp)+,d2-d5
        rts

; Parse avc1/avc3 stsd and locate avcC.
; A0=stsd payload, A1=end.
v12e_parse_stsd:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  a1,d7
        move.l  d7,d0
        sub.l   a0,d0
        cmpi.l  #16,d0
        bcs.w   v12e_stsd_done
        lea     4(a0),a2
        move.l  a2,a0
        bsr     v12e_be32
        move.l  d0,d6                  ; entry count
        lea     4(a2),a2               ; first entry (payload+8)
v12e_stsd_entry_loop:
        tst.l   d6
        beq.w   v12e_stsd_done
        move.l  a2,a0
        move.l  d7,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.w   v12e_stsd_done
        move.l  d0,d5
        move.l  a3,d4                  ; preserve next entry across child parsing
        cmpi.l  #$61766331,d5          ; avc1
        beq.s   v12e_stsd_avc
        cmpi.l  #$61766333,d5          ; avc3
        bne.s   v12e_stsd_next
v12e_stsd_avc:
        move.l  #1,v12e_track_avc
        ; VisualSampleEntry fixed header is 86 bytes including size/type.
        move.l  a0,a0                  ; atom start restored by mem_atom
        lea     86(a0),a0
        cmpa.l  a3,a0
        bcc.s   v12e_stsd_next
v12e_stsd_child:
        move.l  a3,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.s   v12e_stsd_next
        cmpi.l  #$61766343,d0          ; avcC
        bne.s   v12e_stsd_child_next
        move.l  a2,v10_video_codecpriv_ptr
        move.l  a3,d0
        sub.l   a2,d0
        move.l  d0,v10_video_codecpriv_len
        clr.l   v10_avcc_ok
        jsr     v10_parse_avcc
        bra.s   v12e_stsd_next
v12e_stsd_child_next:
        move.l  a3,a0
        cmpa.l  a1,a0
        bcs.s   v12e_stsd_child
v12e_stsd_next:
        move.l  d4,a2
        subq.l  #1,d6
        bra.w   v12e_stsd_entry_loop
v12e_stsd_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; Recursive walker inside one trak. A0=start, A1=end.
v12e_walk_track:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  a0,a2
        move.l  a1,d7
v12e_walk_loop:
        cmp.l   d7,a2
        bcc.w   v12e_walk_done
        move.l  a2,a0
        move.l  d7,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.w   v12e_walk_done
        move.l  d0,d6                  ; type
        move.l  a3,d5                  ; atom end
        cmpi.l  #$68646C72,d6          ; hdlr
        bne.s   v12e_walk_not_hdlr
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #12,d0
        bcs.w   v12e_walk_advance
        lea     8(a2),a0
        bsr     v12e_be32
        cmpi.l  #$76696465,d0          ; vide
        bne.w   v12e_walk_advance
        move.l  #1,v12e_track_video
        bra.w   v12e_walk_advance
v12e_walk_not_hdlr:
        cmpi.l  #$73747364,d6          ; stsd
        bne.s   v12e_walk_not_stsd
        move.l  a2,a0
        move.l  a3,a1
        jsr     v12e_parse_stsd
        bra.w   v12e_walk_advance
v12e_walk_not_stsd:
        cmpi.l  #$73747363,d6          ; stsc
        bne.s   v12e_walk_not_stsc
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #8,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_stsc_count
        lea     8(a2),a0
        move.l  a0,v12e_stsc_ptr
        bra.w   v12e_walk_advance
v12e_walk_not_stsc:
        cmpi.l  #$7374737A,d6          ; stsz
        bne.s   v12e_walk_not_stsz
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #12,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_default_sample_size
        lea     8(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_sample_count
        lea     12(a2),a0
        move.l  a0,v12e_stsz_ptr
        bra.w   v12e_walk_advance
v12e_walk_not_stsz:
        cmpi.l  #$7374636F,d6          ; stco
        bne.s   v12e_walk_not_stco
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #8,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_chunk_count
        lea     8(a2),a0
        move.l  a0,v12e_chunk_ptr
        clr.l   v12e_chunk_is_co64
        bra.w   v12e_walk_advance
v12e_walk_not_stco:
        cmpi.l  #$636F3634,d6          ; co64
        bne.s   v12e_walk_not_table
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #8,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_chunk_count
        lea     8(a2),a0
        move.l  a0,v12e_chunk_ptr
        move.l  #1,v12e_chunk_is_co64
        bra.w   v12e_walk_advance
v12e_walk_not_table:
        ; recurse only through known container atoms in a trak
        cmpi.l  #$6D646961,d6          ; mdia
        beq.s   v12e_walk_recurse
        cmpi.l  #$6D696E66,d6          ; minf
        beq.s   v12e_walk_recurse
        cmpi.l  #$7374626C,d6          ; stbl
        bne.w   v12e_walk_advance
v12e_walk_recurse:
        move.l  a2,a0
        move.l  a3,a1
        jsr     v12e_walk_track
v12e_walk_advance:
        move.l  d5,a2
        bra.w   v12e_walk_loop
v12e_walk_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; A0=trak payload, A1=end. D0=0 selected usable video track, 1 otherwise.
v12e_parse_trak:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   v12e_track_video
        clr.l   v12e_track_avc
        clr.l   v12e_stsc_ptr
        clr.l   v12e_stsc_count
        clr.l   v12e_stsz_ptr
        clr.l   v12e_sample_count
        clr.l   v12e_default_sample_size
        clr.l   v12e_chunk_ptr
        clr.l   v12e_chunk_count
        clr.l   v12e_chunk_is_co64
        clr.l   v10_avcc_ok
        jsr     v12e_walk_track
        tst.l   v12e_track_video
        beq.s   v12e_trak_fail
        tst.l   v12e_track_avc
        beq.s   v12e_trak_fail
        tst.l   v10_avcc_ok
        beq.s   v12e_trak_fail
        cmpi.l  #4,v10_nal_length_size
        bne.s   v12e_trak_fail
        tst.l   v12e_stsc_ptr
        beq.s   v12e_trak_fail
        tst.l   v12e_stsc_count
        beq.s   v12e_trak_fail
        tst.l   v12e_sample_count
        beq.s   v12e_trak_fail
        tst.l   v12e_chunk_ptr
        beq.s   v12e_trak_fail
        tst.l   v12e_chunk_count
        beq.s   v12e_trak_fail
        moveq   #0,d0
        bra.s   v12e_trak_done
v12e_trak_fail:
        moveq   #1,d0
v12e_trak_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Scan moov for first usable H264 video trak. D0=0 success/1 fail.
v12e_parse_moov:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  v12e_moov_ptr,a2
        move.l  a2,a1
        adda.l  v12e_moov_bytes,a1
        move.l  a1,d7
v12e_moov_loop:
        cmp.l   d7,a2
        bcc.s   v12e_moov_fail
        move.l  a2,a0
        move.l  d7,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.s   v12e_moov_fail
        move.l  a3,d6
        cmpi.l  #$7472616B,d0          ; trak
        bne.s   v12e_moov_next
        move.l  a2,a0
        move.l  a3,a1
        jsr     v12e_parse_trak
        tst.l   d0
        beq.s   v12e_moov_ok
v12e_moov_next:
        move.l  d6,a2
        bra.s   v12e_moov_loop
v12e_moov_ok:
        moveq   #0,d0
        bra.s   v12e_moov_done
v12e_moov_fail:
        moveq   #1,d0
v12e_moov_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Reset sample/chunk traversal after successful probe. D0=0/1.
v12e_stream_init:
        movem.l d1-d4/a0,-(sp)
        clr.l   v12e_sample_index
        move.l  #1,v12e_chunk_index
        clr.l   v12e_sample_in_chunk
        clr.l   v12e_sample_remaining
        clr.l   v12e_nal_remaining
        clr.l   v12e_samples_done
        clr.l   v12e_nal_count
        clr.l   v12e_error_stage
        clr.l   t23_total_read
        clr.l   v12e_stsc_index
        move.l  v12e_stsc_ptr,a0
        bsr     v12e_be32
        cmpi.l  #1,d0
        bne.s   v12e_stream_init_fail
        lea     4(a0),a0
        bsr     v12e_be32
        tst.l   d0
        beq.s   v12e_stream_init_fail
        move.l  d0,v12e_samples_per_chunk
        cmpi.l  #1,v12e_stsc_count
        bls.s   v12e_stream_no_next
        move.l  v12e_stsc_ptr,a0
        lea     12(a0),a0
        bsr     v12e_be32
        move.l  d0,v12e_next_stsc_chunk
        bra.s   v12e_stream_init_ok
v12e_stream_no_next:
        move.l  #$FFFFFFFF,v12e_next_stsc_chunk
v12e_stream_init_ok:
        moveq   #0,d0
        bra.s   v12e_stream_init_done
v12e_stream_init_fail:
        moveq   #1,d0
v12e_stream_init_done:
        movem.l (sp)+,d1-d4/a0
        rts

; Get sample size for current v12e_sample_index. D0=size, D1=0/1.
v12e_get_sample_size:
        movem.l d2/a0,-(sp)
        moveq   #1,d1
        move.l  v12e_sample_index,d2
        cmp.l   v12e_sample_count,d2
        bcc.s   v12e_gss_done
        move.l  v12e_default_sample_size,d0
        tst.l   d0
        bne.s   v12e_gss_ok
        move.l  v12e_stsz_ptr,a0
        move.l  d2,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        bsr     v12e_be32
v12e_gss_ok:
        tst.l   d0
        beq.s   v12e_gss_done
        moveq   #0,d1
v12e_gss_done:
        movem.l (sp)+,d2/a0
        rts

; Get current 1-based chunk offset. D0=offset (<2GiB), D1=0/1.
v12e_get_chunk_offset:
        movem.l d2-d3/a0,-(sp)
        moveq   #1,d1
        move.l  v12e_chunk_index,d2
        tst.l   d2
        beq.s   v12e_gco_done
        cmp.l   v12e_chunk_count,d2
        bhi.s   v12e_gco_done
        subq.l  #1,d2
        move.l  v12e_chunk_ptr,a0
        tst.l   v12e_chunk_is_co64
        beq.s   v12e_gco_32
        move.l  d2,d3
        lsl.l   #3,d3
        adda.l  d3,a0
        bsr     v12e_be32
        tst.l   d0
        bne.s   v12e_gco_done
        lea     4(a0),a0
        bsr     v12e_be32
        bra.s   v12e_gco_check
v12e_gco_32:
        lsl.l   #2,d2
        adda.l  d2,a0
        bsr     v12e_be32
v12e_gco_check:
        btst    #31,d0
        bne.s   v12e_gco_done
        moveq   #0,d1
v12e_gco_done:
        movem.l (sp)+,d2-d3/a0
        rts

; Advance stsc mapping when entering a new chunk. D0=0/1.
v12e_update_stsc:
        movem.l d1-d4/a0,-(sp)
        move.l  v12e_chunk_index,d0
        cmp.l   v12e_next_stsc_chunk,d0
        bne.s   v12e_stsc_ok
        addq.l  #1,v12e_stsc_index
        move.l  v12e_stsc_index,d1
        cmp.l   v12e_stsc_count,d1
        bcc.s   v12e_stsc_fail
        move.l  v12e_stsc_ptr,a0
        move.l  d1,d2
        mulu.w  #12,d2
        adda.l  d2,a0
        lea     4(a0),a0
        bsr     v12e_be32
        tst.l   d0
        beq.s   v12e_stsc_fail
        move.l  d0,v12e_samples_per_chunk
        addq.l  #1,d1
        cmp.l   v12e_stsc_count,d1
        bcc.s   v12e_stsc_last
        move.l  v12e_stsc_ptr,a0
        move.l  d1,d2
        mulu.w  #12,d2
        adda.l  d2,a0
        bsr     v12e_be32
        move.l  d0,v12e_next_stsc_chunk
        bra.s   v12e_stsc_ok
v12e_stsc_last:
        move.l  #$FFFFFFFF,v12e_next_stsc_chunk
v12e_stsc_ok:
        moveq   #0,d0
        bra.s   v12e_stsc_done
v12e_stsc_fail:
        moveq   #1,d0
v12e_stsc_done:
        movem.l (sp)+,d1-d4/a0
        rts

; Prepare next sample and position DOS file at it. D0=0 data,2 EOF,1 fail.
v12e_prepare_sample:
        movem.l d1-d5/a0,-(sp)
        move.l  v12e_sample_index,d0
        cmp.l   v12e_sample_count,d0
        bcs.s   v12e_prep_have
        moveq   #2,d0
        bra.w   v12e_prep_done
v12e_prep_have:
        tst.l   v12e_sample_in_chunk
        bne.s   v12e_prep_same_chunk
        jsr     v12e_update_stsc
        tst.l   d0
        bne.s   v12e_prep_fail
        jsr     v12e_get_chunk_offset
        tst.l   d1
        bne.s   v12e_prep_fail
        move.l  d0,v12e_chunk_pos
        jsr     v12e_seek_abs
        tst.l   d0
        bne.s   v12e_prep_fail
v12e_prep_same_chunk:
        jsr     v12e_get_sample_size
        tst.l   d1
        bne.s   v12e_prep_fail
        move.l  d0,v12e_sample_remaining
        move.l  d0,v12e_sample_total
        clr.l   v12e_nal_remaining
        move.l  v12e_chunk_pos,d1
        add.l   d0,d1
        move.l  d1,v12e_chunk_pos
        addq.l  #1,v12e_sample_index
        moveq   #0,d0
        bra.s   v12e_prep_done
v12e_prep_fail:
        move.l  #$00000031,v12e_error_stage
        moveq   #1,d0
v12e_prep_done:
        movem.l (sp)+,d1-d5/a0
        rts

; Finish current sample and advance chunk/sample counters.
v12e_finish_sample:
        addq.l  #1,v12e_samples_done
        addq.l  #1,v12e_sample_in_chunk
        move.l  v12e_sample_in_chunk,d0
        cmp.l   v12e_samples_per_chunk,d0
        bcs.s   v12e_finish_done
        clr.l   v12e_sample_in_chunk
        addq.l  #1,v12e_chunk_index
v12e_finish_done:
        rts

; Return one <=64KiB Annex-B chunk in bulk_data_ptr.
; D0=0 data, 2 EOF, 1 failure. Flags stay zero (UNFRAMED decoder input).
v12e_next_annexb_chunk:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v12e_chunk_len
        clr.l   v04_mp4_new_sample
        move.l  v12e_sample_remaining,d0
        bne.s   v12e_chunk_have_sample
        jsr     v12e_prepare_sample
        cmpi.l  #2,d0
        beq.w   v12e_chunk_eof
        tst.l   d0
        bne.w   v12e_chunk_fail
        move.l  #1,v04_mp4_new_sample
v12e_chunk_have_sample:
        move.l  bulk_data_ptr,a2
        move.l  #H264_STREAM_CHUNK,d7
v12e_chunk_loop:
        move.l  v12e_sample_remaining,d0
        bne.s   v12e_chunk_not_sample_end
        tst.l   v12e_nal_remaining
        bne.w   v12e_chunk_fail_bad
        jsr     v12e_finish_sample
        bra.w   v12e_chunk_ready         ; one MP4 sample per logical output chunk
v12e_chunk_not_sample_end:
        tst.l   d7
        beq.w   v12e_chunk_ready
        move.l  v12e_nal_remaining,d0
        bne.s   v12e_chunk_copy_body
        cmpi.l  #4,v12e_sample_remaining
        bcs.w   v12e_chunk_fail_bad
        cmpi.l  #4,d7
        bcs.w   v12e_chunk_ready
        ; Read four-byte AVC NAL length directly into output then replace with startcode.
        move.l  a2,d2
        moveq   #4,d3
        jsr     v12e_read_exact
        tst.l   d0
        bne.w   v12e_chunk_fail_read
        move.l  a2,a0
        bsr     v12e_be32
        tst.l   d0
        beq.w   v12e_chunk_fail_bad
        move.l  v12e_sample_remaining,d1
        subq.l  #4,d1
        cmp.l   d1,d0
        bhi.w   v12e_chunk_fail_bad
        move.l  d0,v12e_nal_remaining
        clr.b   (a2)
        clr.b   1(a2)
        clr.b   2(a2)
        move.b  #1,3(a2)
        addq.l  #4,a2
        subq.l  #4,d7
        subq.l  #4,v12e_sample_remaining
        addq.l  #4,v12e_chunk_len
        addq.l  #1,v12e_nal_count
        bra.w   v12e_chunk_loop
v12e_chunk_copy_body:
        move.l  v12e_nal_remaining,d4
        cmp.l   v12e_sample_remaining,d4
        bls.s   v12e_body_sample_ok
        move.l  v12e_sample_remaining,d4
v12e_body_sample_ok:
        cmp.l   d7,d4
        bls.s   v12e_body_cap_ok
        move.l  d7,d4
v12e_body_cap_ok:
        tst.l   d4
        beq.w   v12e_chunk_ready
        move.l  a2,d2
        move.l  d4,d3
        jsr     v12e_read_exact
        tst.l   d0
        bne.w   v12e_chunk_fail_read
        adda.l  d4,a2
        sub.l   d4,d7
        sub.l   d4,v12e_sample_remaining
        sub.l   d4,v12e_nal_remaining
        add.l   d4,v12e_chunk_len
        bra.w   v12e_chunk_loop
v12e_chunk_ready:
        move.l  v12e_chunk_len,d0
        tst.l   d0
        beq.s   v12e_chunk_fail_bad
        moveq   #0,d0
        bra.s   v12e_chunk_done
v12e_chunk_eof:
        moveq   #2,d0
        bra.s   v12e_chunk_done
v12e_chunk_fail_read:
        move.l  #$00000033,v12e_error_stage
        bra.s   v12e_chunk_fail
v12e_chunk_fail_bad:
        move.l  #$00000034,v12e_error_stage
v12e_chunk_fail:
        moveq   #1,d0
v12e_chunk_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Free only the bounded MP4 moov allocation. File handle is owned by close_prog.
v12e_free_mp4:
        movem.l d0-d1/a1/a6,-(sp)
        move.l  v12e_moov_ptr,d0
        beq.s   v12e_free_done
        move.l  d0,a1
        move.l  v12e_moov_alloc,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v12e_moov_ptr
        clr.l   v12e_moov_alloc
        clr.l   v12e_moov_bytes
v12e_free_done:
        movem.l (sp)+,d0-d1/a1/a6
        rts

; Open MP4, locate/load moov, select H264 video track and init sample traversal.
; D0=0 success, 1 unsupported/error.
v12e_mp4_probe:
        movem.l d1-d7/a0-a3/a6,-(sp)
        jsr     v12e_free_mp4
        clr.l   t23_file_handle
        clr.l   h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len
        clr.l   v10_avcc_ok
        lea     msg_v12e_mp4_probe,a1
        move.l  #msg_v12e_mp4_probe_end-msg_v12e_mp4_probe,d3
        jsr     print
        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   v12e_probe_fail
        move.l  d0,t23_file_handle
v12e_probe_top_loop:
        move.l  t23_file_handle,d1
        lea     v12e_atom_hdr,a0
        move.l  a0,d2
        moveq   #8,d3
        move.l  a5,a6
        jsr     Read(a6)
        cmpi.l  #8,d0
        bne.w   v12e_probe_fail
        lea     v12e_atom_hdr,a0
        bsr     v12e_be32
        move.l  d0,d6                  ; atom size
        lea     v12e_atom_hdr+4,a0
        bsr     v12e_be32
        move.l  d0,d7                  ; type
        moveq   #8,d5                  ; header bytes
        cmpi.l  #1,d6
        bne.s   v12e_probe_size32
        move.l  t23_file_handle,d1
        lea     v12e_atom_hdr+8,a0
        move.l  a0,d2
        moveq   #8,d3
        move.l  a5,a6
        jsr     Read(a6)
        cmpi.l  #8,d0
        bne.w   v12e_probe_fail
        lea     v12e_atom_hdr+8,a0
        bsr     v12e_be32
        tst.l   d0
        bne.w   v12e_probe_fail
        lea     v12e_atom_hdr+12,a0
        bsr     v12e_be32
        move.l  d0,d6
        moveq   #16,d5
v12e_probe_size32:
        tst.l   d6
        beq.w   v12e_probe_fail
        cmp.l   d5,d6
        bcs.w   v12e_probe_fail
        move.l  d6,d4
        sub.l   d5,d4                  ; payload bytes
        cmpi.l  #$6D6F6F76,d7          ; moov
        beq.s   v12e_probe_found_moov
        move.l  d4,d0
        jsr     v12e_seek_cur
        tst.l   d0
        bne.w   v12e_probe_fail
        bra.w   v12e_probe_top_loop
v12e_probe_found_moov:
        tst.l   d4
        beq.w   v12e_probe_fail
        cmpi.l  #V12E_MAX_MOOV,d4
        bhi.w   v12e_probe_fail
        move.l  a4,a6
        move.l  d4,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   v12e_probe_fail
        move.l  d0,v12e_moov_ptr
        move.l  d4,v12e_moov_alloc
        move.l  d4,v12e_moov_bytes
        move.l  d0,d2
        move.l  d4,d3
        jsr     v12e_read_exact
        tst.l   d0
        bne.w   v12e_probe_fail
        jsr     v12e_parse_moov
        tst.l   d0
        bne.w   v12e_probe_fail
        jsr     v12e_stream_init
        tst.l   d0
        bne.w   v12e_probe_fail
        lea     msg_v12e_mp4_tables,a1
        move.l  #msg_v12e_mp4_tables_end-msg_v12e_mp4_tables,d3
        jsr     print
        move.l  v12e_sample_count,d0
        jsr     print_hex32
        lea     msg_v12e_mp4_chunks,a1
        move.l  #msg_v12e_mp4_chunks_end-msg_v12e_mp4_chunks,d3
        jsr     print
        move.l  v12e_chunk_count,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12e_probe_done
v12e_probe_fail:
        moveq   #1,d0
v12e_probe_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

