msg_vpv21n_after_predecode:
        dc.b "[BerryMP314][TRACE] MP3 priming block ready; BerryMP314 remains live on CPU1",10
msg_vpv21n_after_predecode_end:

msg_vpv21p_audio_skipped:
        dc.b "[BerryMP314][ISO] AAC/PCM prepared; audio COMPONENT_CREATE deferred until video graph is enabled",10
msg_vpv21p_audio_skipped_end:
msg_vpv21p_before_video_stream:
