        section data,data
v41l_quiet_enabled:           dc.l 1
        section bss,bss
v41l_force_print:             ds.l 1
v41l_error_line:              ds.l 1
        even


; ====================================================================
; VPv06 - SAFE FREEMEM FIX AUF BASIS DES HARDWARE-BESTAETIGTEN VPv05
; Base: HDMI_v41L VCHIQ/MMAL transport. No movie parser, no H264 decoder.
;
; Goal for real hardware:
;   VPv06 -> unveraenderter VPv05-Audiopfad + sichere Exec-Speicherfreigabe
;
; PCM: 48 kHz, stereo, signed 16-bit little-endian.
; One 0.25-s buffer = 12000 stereo frames = 48000 bytes, sent 8 times.
; Total nominal tone duration: 2.0 seconds.
; ====================================================================
VPV01_AUDIO_RATE       equ 48000
VPV01_AUDIO_CHANNELS   equ 2
VPV01_AUDIO_BITS       equ 16
VPV01_AUDIO_BLOCKALIGN equ 4
VPV01_AUDIO_BITRATE    equ 1536000
VPV01_TONE_FRAMES      equ 12000
VPV01_TONE_BYTES       equ 48000
VPV01_TONE_REPEATS     equ 8
VPV01_TONE_PHASE_MOD   equ 1200       ; 48000/440 = 1200/11
VPV01_TONE_PHASE_STEP  equ 11
VPV01_TONE_HALF        equ 600
VPV01_BUFFER_CONTEXT   equ $A0300001

        section bss,bss
vpv01_audio_handle:          ds.l 1
vpv01_audio_input:           ds.l 1
vpv01_audio_control:         ds.l 1
vpv01_create_size:           ds.l 1
vpv01_create_status:         ds.l 1
vpv01_param_port:            ds.l 1
vpv01_param_size:            ds.l 1
vpv01_param_status:          ds.l 1
vpv01_component_enabled:     ds.l 1
vpv01_bulk_done:             ds.l 1
vpv01_buffer_returned:       ds.l 1
vpv01_audio_dma_active:      ds.l 1
vpv01_audio_dma_len:         ds.l 1
vpv01_last_rx_size:          ds.l 1
vpv01_last_rx_msgid:         ds.l 1
vpv01_test_status:           ds.l 1
vpv01_cleanup_status:        ds.l 1
        even

        section code,code

; VPv06 ignores CLI arguments. Enter the same VCHIQ attach/init decision used
; by HDMI_v41L, but without touching file/container/video state.
vpv01_bootstrap:
        clr.l   v15_stop_requested
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr
        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control
        clr.l   vpv01_component_enabled
        clr.l   vpv01_test_status
        jmp     vpv01_vchiq_entry

; First-start GET_VERSION returns here with shared slot RAM CPU-owned.
vpv01_first_mmal_ready:
        jsr     vpv01_audio_test
        jmp     v9d_attach_exit

; Orchestrate one complete renderer/tone/cleanup pass.
vpv01_audio_test:
        jmp     vpv19_audio_test

vpv01_audio_test_v06_legacy:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_test_status
        clr.l   vpv01_component_enabled
        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control

        lea     msg_vpv01_mmal_ready,a1
        move.l  #msg_vpv01_mmal_ready_end-msg_vpv01_mmal_ready,d3
        jsr     print_force

        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv01_test_fail

        jsr     vpv01_configure_audio_render
        tst.l   d0
        bne.w   vpv01_test_fail

        jsr     vpv01_prepare_tone
        tst.l   d0
        bne.w   vpv01_test_fail

        lea     msg_vpv01_tone_begin,a1
        move.l  #msg_vpv01_tone_begin_end-msg_vpv01_tone_begin,d3
        jsr     print_force

        moveq   #VPV01_TONE_REPEATS-1,d7
vpv01_tone_repeat_loop:
        jsr     vpv01_send_tone_block
        tst.l   d0
        bne.w   vpv01_test_fail
        jsr     vpv01_wait_tone_block
        tst.l   d0
        bne.w   vpv01_test_fail
        dbra    d7,vpv01_tone_repeat_loop

        ; Let the HDMI renderer drain the last internally queued samples.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #10,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        lea     msg_vpv01_tone_ok,a1
        move.l  #msg_vpv01_tone_ok_end-msg_vpv01_tone_ok,d3
        jsr     print_force
        bra.w   vpv01_test_cleanup

vpv01_test_fail:
        move.l  #1,vpv01_test_status
        lea     msg_vpv01_fail,a1
        move.l  #msg_vpv01_fail_end-msg_vpv01_fail,d3
        jsr     print_force

vpv01_test_cleanup:
        jsr     vpv01_cleanup
        move.l  vpv01_test_status,d0
        tst.l   d0
        bne.w   vpv01_test_done
        lea     msg_vpv01_done,a1
        move.l  #msg_vpv01_done_end-msg_vpv01_done,d3
        jsr     print_force
vpv01_test_done:
        move.l  vpv01_test_status,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; Create ril.audio_render over whichever MMAL local service is active.
; ------------------------------------------------------------
vpv01_create_audio_render:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv01_create_status
        clr.l   vpv01_create_size
        clr.l   vpv01_param_status      ; VPv06: CREATE fail-stage (reuse, no new BSS)
        clr.l   vpv01_last_rx_msgid     ; VPv06: header status (reuse, no new BSS)

        tst.l   v12f_local_port
        beq.w   vpv01_create_tx_legacy
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        beq.w   vpv01_create_tx_ready
        move.l  #1,vpv01_param_status
        bra.w   vpv01_create_fail
vpv01_create_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
vpv01_create_tx_ready:
        move.l  a2,a0
        moveq   #41,d7
vpv01_create_clear:
        clr.l   (a0)+
        dbra    d7,vpv01_create_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A0100001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$A011A1A1,d0
        jsr     store_le32
        lea     36(a2),a0
        lea     vpv01_audio_render_name,a1
        moveq   #16,d7               ; 16 chars + NUL = 17 bytes
vpv01_create_name:
        move.b  (a1)+,(a0)+
        dbra    d7,vpv01_create_name

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv01_create_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv01_create_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv01_create_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv01_create_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_create_wait
        jsr     dma_post_all
        move.l  #2,vpv01_param_status
        bra.w   vpv01_create_fail
vpv01_create_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        beq.w   vpv04_create_rx_mapped
        move.l  #3,vpv01_param_status
        bra.w   vpv01_create_fail
vpv04_create_rx_mapped:
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_create_size
        cmp.l   #44,d0
        bcc.w   vpv04_create_size_ok
        move.l  #4,vpv01_param_status
        bra.w   vpv01_create_fail
vpv04_create_size_ok:
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        beq.w   vpv04_create_magic_ok
        move.l  #5,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_magic_ok:
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        beq.w   vpv04_create_type_ok
        move.l  #6,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_type_ok:
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A0100001,d0
        beq.w   vpv04_create_context_ok
        move.l  #7,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_context_ok:
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_msgid
        tst.l   d0
        beq.w   vpv04_create_hstatus_ok
        move.l  #8,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_hstatus_ok:
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_create_status
        tst.l   d0
        beq.w   vpv04_create_worker_ok
        move.l  #9,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_worker_ok:
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_audio_handle
        tst.l   d0
        bne.w   vpv04_create_handle_ok
        move.l  #10,vpv01_param_status
        bra.w   vpv01_create_fail_consume
vpv04_create_handle_ok:
        move.l  vpv01_create_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        beq.w   vpv04_create_consume_ok
        move.l  #11,vpv01_param_status
        bra.w   vpv01_create_fail
vpv04_create_consume_ok:

        lea     msg_vpv01_create_ok,a1
        move.l  #msg_vpv01_create_ok_end-msg_vpv01_create_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.w   vpv01_create_done
vpv01_create_fail_consume:
        move.l  vpv01_create_size,d0
        jsr     v12a_rx_consume_payload
vpv01_create_fail:
        lea     msg_vpv01_create_fail,a1
        move.l  #msg_vpv01_create_fail_end-msg_vpv01_create_fail,d3
        jsr     print_force

        ; VPv06: minimal safe diagnostics. No alias retry, no alternate CREATE.
        lea     msg_vpv04_diag_stage,a1
        move.l  #msg_vpv04_diag_stage_end-msg_vpv04_diag_stage,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv01_param_status,d0
        jsr     print_hex32
        clr.l   v41l_force_print
        lea     msg_vpv04_diag_worker,a1
        move.l  #msg_vpv04_diag_worker_end-msg_vpv04_diag_worker,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv01_create_status,d0
        jsr     print_hex32
        clr.l   v41l_force_print
        lea     msg_vpv04_diag_header,a1
        move.l  #msg_vpv04_diag_header_end-msg_vpv04_diag_header,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv01_last_rx_msgid,d0
        jsr     print_hex32
        clr.l   v41l_force_print
        move.l  #1,v41l_force_print
        jsr     newline
        clr.l   v41l_force_print
        moveq   #1,d0
vpv01_create_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; Configure audio_render INPUT0 as signed PCM LE, stereo, 48 kHz, 16 bit.
; Also resolve the real input/control port handles from VideoCore.
; ------------------------------------------------------------
vpv01_configure_audio_render:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  vpv01_audio_handle,component_handle

        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  port_last_handle,vpv01_audio_control

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  #VPV01_AUDIO_BITRATE,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra

        ; mmal_audio_format union occupies the same first four 32-bit slots
        ; that the legacy decoder helper names video_width/height/crop_x/crop_y.
        move.l  #VPV01_AUDIO_CHANNELS,port_video_width
        move.l  #VPV01_AUDIO_RATE,port_video_height
        move.l  #VPV01_AUDIO_BITS,port_crop_x
        move.l  #VPV01_AUDIO_BLOCKALIGN,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space

        move.l  port_buf_num_min,d0
        tst.l   d0
        bne.w   vpv01_buf_num_ok
        moveq   #1,d0
vpv01_buf_num_ok:
        move.l  d0,port_buf_num
        move.l  #$00010000,d0
        cmp.l   port_buf_size_min,d0
        bcc.w   vpv01_buf_size_min_ok
        move.l  port_buf_size_min,d0
vpv01_buf_size_min_ok:
        cmp.l   #INPUT_DATA_SIZE,d0
        bhi.w   vpv01_config_fail
        move.l  d0,port_buf_size

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_set_input
        tst.l   d0
        bne.w   vpv01_config_fail

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  port_last_handle,d0
        cmp.l   vpv01_audio_input,d0
        bne.w   vpv01_config_fail
        cmpi.l  #MMAL_ES_AUDIO,port_fmt_type
        bne.w   vpv01_config_fail
        cmpi.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        bne.w   vpv01_config_fail
        cmpi.l  #VPV01_AUDIO_CHANNELS,port_video_width
        bne.w   vpv01_config_fail
        cmpi.l  #VPV01_AUDIO_RATE,port_video_height
        bne.w   vpv01_config_fail
        cmpi.l  #VPV01_AUDIO_BITS,port_crop_x
        bne.w   vpv01_config_fail
        move.l  port_buf_size,d0
        cmpi.l  #VPV01_TONE_BYTES,d0
        bcs.w   vpv01_config_fail
        cmpi.l  #INPUT_DATA_SIZE,d0
        bhi.w   vpv01_config_fail

        ; Set HDMI output destination. First try INPUT0 (matching the original
        ; audio sketch); if firmware rejects it, retry on CONTROL0.
        move.l  vpv01_audio_input,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        beq.w   vpv01_dest_ok
        move.l  vpv01_audio_control,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        bne.w   vpv01_config_fail
vpv01_dest_ok:

        ; Enable host-fed INPUT0. Local-0 uses the original proven helper;
        ; attached local-1 uses the slot-safe second-service helper.
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        tst.l   v12f_local_port
        bne.w   vpv01_enable_input_second
        jsr     port_enable_current
        bra.w   vpv01_enable_input_done
vpv01_enable_input_second:
        move.l  vpv01_audio_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
vpv01_enable_input_done:
        tst.l   d0
        bne.w   vpv01_config_fail

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv01_config_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv01_config_fail

        move.l  vpv01_audio_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.w   vpv01_config_fail
        move.l  #1,vpv01_component_enabled

        lea     msg_vpv01_config_ok,a1
        move.l  #msg_vpv01_config_ok_end-msg_vpv01_config_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.w   vpv01_config_done
vpv01_config_fail:
        lea     msg_vpv01_config_fail,a1
        move.l  #msg_vpv01_config_fail_end-msg_vpv01_config_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_config_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; MMAL_PARAMETER_AUDIO_DESTINATION = "hdmi".
; D0 = target port handle. CPU-owned shared RAM on entry/exit.
; Parameter header size = 8 + 5 bytes = 13. Worker payload = 32 + 13 = 45.
; ------------------------------------------------------------
vpv01_set_hdmi_destination:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,vpv01_param_port
        clr.l   vpv01_param_status
        clr.l   vpv01_param_size

        move.l  #56,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv01_param_fail
        move.l  a2,a0
        moveq   #13,d7
vpv01_param_clear:
        clr.l   (a0)+
        dbra    d7,vpv01_param_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #45,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_PARAMETER_SET,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$A0200001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_param_port,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PARAMETER_AUDIO_DESTINATION,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #13,d0
        jsr     store_le32
        lea     48(a2),a0
        lea     vpv01_audio_dest_hdmi,a1
        moveq   #4,d7
vpv01_param_copy:
        move.b  (a1)+,(a0)+
        dbra    d7,vpv01_param_copy

        add.l   #56,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv01_param_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv01_param_wait_setup:
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv01_param_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv01_param_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_param_wait
        jsr     dma_post_all
        bra.w   vpv01_param_fail
vpv01_param_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv01_param_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_param_size
        cmp.l   #28,d0
        bcs.w   vpv01_param_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv01_param_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_PARAMETER_SET,d0
        bne.w   vpv01_param_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$A0200001,d0
        bne.w   vpv01_param_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_param_status
        move.l  vpv01_param_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv01_param_fail
        tst.l   vpv01_param_status
        bne.w   vpv01_param_fail
        moveq   #0,d0
        bra.w   vpv01_param_done
vpv01_param_fail_consume:
        move.l  vpv01_param_size,d0
        jsr     v12a_rx_consume_payload
vpv01_param_fail:
        moveq   #1,d0
vpv01_param_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; ------------------------------------------------------------
; Allocate one aligned DMA input area and generate exactly 0.25 s of
; 440-Hz stereo square wave. Samples are written little-endian bytewise.
; ------------------------------------------------------------
vpv01_prepare_tone:
        movem.l d1-d7/a0-a2/a6,-(sp)
        move.l  a4,a6
        move.l  #BULK_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv01_prepare_fail
        move.l  d0,bulk_alloc
        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,bulk_pool_base
        cmp.l   #$3f000000,d0
        bcc.w   vpv01_prepare_fail_free
        move.l  d0,d1
        add.l   #INPUT_DMA_SPAN-1,d1
        cmp.l   #$3f000000,d1
        bcc.w   vpv01_prepare_fail_free

        move.l  bulk_pool_base,d0
        move.l  d0,bulk_data_ptr
        move.l  d0,d1
        or.l    #$c0000000,d1
        move.l  d1,bulk_data_bus
        move.l  d0,d2
        add.l   #INPUT_PAGELIST_OFFSET,d2
        move.l  d2,bulk_pagelist_ptr
        move.l  d2,d1
        or.l    #$c0000000,d1
        move.l  d1,bulk_pagelist_bus

        move.l  bulk_data_ptr,a0
        moveq   #0,d6                 ; phase 0..1199
        move.l  #VPV01_TONE_FRAMES-1,d7
vpv01_tone_gen_loop:
        cmpi.l  #VPV01_TONE_HALF,d6
        bcc.w   vpv01_tone_negative
        ; +0x1800, little endian, L + R
        clr.b   (a0)+
        move.b  #$18,(a0)+
        clr.b   (a0)+
        move.b  #$18,(a0)+
        bra.w   vpv01_tone_phase
vpv01_tone_negative:
        ; -0x1800 = 0xE800, little endian, L + R
        clr.b   (a0)+
        move.b  #$E8,(a0)+
        clr.b   (a0)+
        move.b  #$E8,(a0)+
vpv01_tone_phase:
        addi.l  #VPV01_TONE_PHASE_STEP,d6
        cmpi.l  #VPV01_TONE_PHASE_MOD,d6
        bcs.w   vpv01_tone_phase_ok
        subi.l  #VPV01_TONE_PHASE_MOD,d6
vpv01_tone_phase_ok:
        dbra    d7,vpv01_tone_gen_loop

        ; VCHIQ pagelist: length, type WRITE, one compressed contiguous run.
        move.l  bulk_pagelist_ptr,a0
        move.l  #VPV01_TONE_BYTES,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  #VPV01_TONE_BYTES,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        move.l  bulk_data_bus,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     store_le32

        lea     msg_vpv01_pcm_ready,a1
        move.l  #msg_vpv01_pcm_ready_end-msg_vpv01_pcm_ready,d3
        jsr     print_force
        moveq   #0,d0
        bra.w   vpv01_prepare_done
vpv01_prepare_fail_free:
        lea     bulk_alloc,a0
        move.l  #BULK_ALLOC_SIZE,d0
        jsr     vpv06_free_var_safe
vpv01_prepare_fail:
        lea     msg_vpv01_pcm_fail,a1
        move.l  #msg_vpv01_pcm_fail_end-msg_vpv01_pcm_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_prepare_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; ------------------------------------------------------------
; Publish one MMAL input header plus one VCHIQ BULK_TX for the PCM block.
; Returns with shared VCHIQ RAM DMA-owned on success.
; ------------------------------------------------------------
vpv01_send_tone_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_bulk_done
        clr.l   vpv01_buffer_returned

        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   bulk_data_ptr,d0
        bne.w   vpv01_send_fail_nomap
        move.l  vpv01_audio_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   vpv01_send_fail_post
        move.l  #1,vpv01_audio_dma_active

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv01_send_fail_post
        move.l  a2,a0
        moveq   #79,d7
vpv01_send_clear:
        clr.l   (a0)+
        dbra    d7,vpv01_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  #VPV01_TONE_BYTES,d0
        jsr     store_le32
        ; flags at +92 remain zero. PTS/DTS = MMAL_TIME_UNKNOWN.
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #VPV01_TONE_BYTES,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv01_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv01_send_no_bell:
        moveq   #0,d0
        bra.w   vpv01_send_done
vpv01_send_fail_post:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv01_send_fail_nomap
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv01_send_fail_nomap:
        lea     msg_vpv01_send_fail,a1
        move.l  #msg_vpv01_send_fail_end-msg_vpv01_send_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; Wait until both BULK_TX_DONE and BUFFER_TO_HOST for our PCM context arrived.
; Success returns with shared VCHIQ RAM CPU-owned and audio DMA mapping closed.
; ------------------------------------------------------------
vpv01_wait_tone_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv01_wait_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv01_wait_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_wait_loop
        jsr     dma_post_all
        bra.w   vpv01_wait_fail

vpv01_wait_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   vpv01_wait_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_size

        ; Ignore traffic not addressed to this local MMAL service.
        move.l  vpv01_last_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv01_wait_consume_continue
        move.l  vpv01_last_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv01_wait_consume_continue

        move.l  vpv01_last_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.w   vpv01_wait_bulk_done
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.w   vpv01_wait_data
        bra.w   vpv01_wait_consume_continue

vpv01_wait_bulk_done:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #4,d0
        bcs.w   vpv01_wait_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_TONE_BYTES,d0
        bne.w   vpv01_wait_fail
        move.l  #1,vpv01_bulk_done
        tst.l   vpv01_audio_dma_active
        beq.w   vpv01_wait_consume_check
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
        bra.w   vpv01_wait_consume_check

vpv01_wait_data:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #44,d0
        bcs.w   vpv01_wait_consume_continue
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv01_wait_consume_continue
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        bne.w   vpv01_wait_consume_continue
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv01_wait_fail
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   vpv01_audio_input,d0
        bne.w   vpv01_wait_consume_continue
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.w   vpv01_wait_consume_continue
        move.l  #1,vpv01_buffer_returned

vpv01_wait_consume_check:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv01_wait_fail
        tst.l   vpv01_bulk_done
        beq.w   vpv01_wait_more
        tst.l   vpv01_buffer_returned
        bne.w   vpv01_wait_success
vpv01_wait_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_wait_loop
        jsr     dma_post_all
        bra.w   vpv01_wait_fail

vpv01_wait_consume_continue:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv01_wait_fail
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv01_wait_loop
        jsr     dma_post_all
        bra.w   vpv01_wait_fail

vpv01_wait_success:
        moveq   #0,d0
        bra.w   vpv01_wait_done
vpv01_wait_fail:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv01_wait_fail_print
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv01_wait_fail_print:
        lea     msg_vpv01_wait_fail,a1
        move.l  #msg_vpv01_wait_fail_end-msg_vpv01_wait_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv01_wait_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; ------------------------------------------------------------
; VPv06: A0-safe variable-backed Exec FreeMem helper.
; D0 = allocation size, A0 = address of variable containing exact AllocMem base.
;
; The inherited v9_free_var performs FreeMem() and then clears (a0) without
; preserving A0 across the library call. Exec scratch registers may be changed
; by the call. VPv06 saves the variable address explicitly on the stack before
; FreeMem and restores it before clearing the variable.
; ------------------------------------------------------------
vpv06_free_var_safe:
        movem.l d1/a1/a6,-(sp)
        move.l  (a0),a1
        cmpa.l  #0,a1
        beq.s   vpv06_free_var_done
        move.l  d0,d1
        move.l  a0,-(sp)
        move.l  a4,a6
        jsr     FreeMem(a6)
        move.l  (sp)+,a0
        clr.l   (a0)
vpv06_free_var_done:
        movem.l (sp)+,d1/a1/a6
        rts

; ------------------------------------------------------------
; Service-owned teardown. Persistent global VCHIQ slot block remains until
; reboot, exactly as in HDMI_v41L. Stream DMA is freed only after input return.
; ------------------------------------------------------------
vpv01_cleanup:
        movem.l d0-d7/a0-a2/a6,-(sp)
        clr.l   vpv01_cleanup_status

        ; VPv06: keep the hardware-proven VPv05 MMAL/audio path unchanged.
        ; Restore only the two process-local frees using vpv06_free_var_safe.
        ; Persistent slot_alloc remains untouched until reboot as in HDMI_v41L.

        tst.l   vpv01_audio_dma_active
        beq.w   vpv05_cleanup_no_dma
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv05_cleanup_no_dma:

        lea     msg_vpv05_cleanup_disable,a1
        move.l  #msg_vpv05_cleanup_disable_end-msg_vpv05_cleanup_disable,d3
        jsr     print_force

        ; v9 worker/close helpers use port_query_index as shifted local bits.
        move.l  v12f_local_bits,port_query_index
        move.l  vpv01_audio_handle,component_handle
        tst.l   component_handle
        beq.w   vpv05_cleanup_close_service
        tst.l   vpv01_component_enabled
        beq.w   vpv05_cleanup_close_service
        move.l  #MMAL_COMPONENT_DISABLE,d0
        jsr     v9_component_cmd
        tst.l   d0
        beq.w   vpv05_cleanup_close_service
        move.l  #1,vpv01_cleanup_status

vpv05_cleanup_close_service:
        lea     msg_vpv05_cleanup_service,a1
        move.l  #msg_vpv05_cleanup_service_end-msg_vpv05_cleanup_service,d3
        jsr     print_force

        tst.l   mmal_remote_port
        beq.w   vpv05_cleanup_after_close
        jsr     v9_close_service
        tst.l   d0
        beq.w   vpv05_cleanup_after_close
        move.l  #1,vpv01_cleanup_status
vpv05_cleanup_after_close:
        ; Let VideoCore finish service-owned component deletion.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #25,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        ; VPv06: reclaim the exact process-local AllocMem bases only.
        lea     msg_vpv06_free_bulk,a1
        move.l  #msg_vpv06_free_bulk_end-msg_vpv06_free_bulk,d3
        jsr     print_force
        lea     bulk_alloc,a0
        move.l  #BULK_ALLOC_SIZE,d0
        jsr     vpv06_free_var_safe

        lea     msg_vpv06_free_prop,a1
        move.l  #msg_vpv06_free_prop_end-msg_vpv06_free_prop,d3
        jsr     print_force
        lea     prop_alloc,a0
        move.l  #$200,d0
        jsr     vpv06_free_var_safe

        lea     msg_vpv06_free_ok,a1
        move.l  #msg_vpv06_free_ok_end-msg_vpv06_free_ok,d3
        jsr     print_force

        clr.l   vpv01_audio_handle
        clr.l   vpv01_audio_input
        clr.l   vpv01_audio_control
        clr.l   component_handle
        clr.l   input_port_handle
        clr.l   mmal_remote_port
        clr.l   vpv01_component_enabled

        tst.l   vpv01_cleanup_status
        beq.w   vpv05_cleanup_status_ok
        move.l  #1,vpv01_test_status
        lea     msg_vpv01_cleanup_fail,a1
        move.l  #msg_vpv01_cleanup_fail_end-msg_vpv01_cleanup_fail,d3
        jsr     print_force
vpv05_cleanup_status_ok:
        ; Persistent VCHIQ RAM must be left in DMA ownership between CLI runs.
        jsr     dma_pre_all
        movem.l (sp)+,d0-d7/a0-a2/a6
        rts

        section data,data
vpv01_audio_render_name:
        dc.b "ril.audio_render",0
        even
vpv01_audio_dest_hdmi:
        dc.b "hdmi",0
        even

msg_vpv01_start:
        dc.b 10,"BerryMP314 - MP3 CPU1 -> PCM16 -> HDMI AUDIO",10
        dc.b "Helix MP3 auf CPU1; PCM16-Ausgabe direkt ueber Raspberry-Pi-HDMI.",10
        dc.b "Audio-only: MP3 -> CPU1 -> PCM16 -> ril.audio_render -> HDMI.",10,10
msg_vpv01_start_end:
msg_vpv01_mmal_ready:
        dc.b "[BerryMP314] MMAL-Service bereit. Erzeuge ril.audio_render ...",10
msg_vpv01_mmal_ready_end:
msg_vpv01_create_ok:
        dc.b "[BerryMP314] ril.audio_render: OK",10
msg_vpv01_create_ok_end:
msg_vpv01_create_fail:
        dc.b "[BerryMP314] FEHLER: ril.audio_render COMPONENT_CREATE fehlgeschlagen.",10
msg_vpv01_create_fail_end:
msg_vpv04_diag_stage:
        dc.b "[BerryMP314] CREATE stage=0x"
msg_vpv04_diag_stage_end:
msg_vpv04_diag_worker:
        dc.b " worker.status=0x"
msg_vpv04_diag_worker_end:
msg_vpv04_diag_header:
        dc.b " header.status=0x"
msg_vpv04_diag_header_end:
msg_vpv01_config_ok:
        dc.b "[BerryMP314] PCM 48kHz / Stereo / 16-bit + AUDIO_DESTINATION=hdmi + INPUT ENABLE: OK",10
msg_vpv01_config_ok_end:
msg_vpv01_config_fail:
        dc.b "[BerryMP314] FEHLER: audio_render Port/PCM/HDMI-Konfiguration fehlgeschlagen.",10
msg_vpv01_config_fail_end:
msg_vpv01_pcm_ready:
        dc.b "[BerryMP314] HDMI-PCM-DMA-Puffer vorbereitet: OK",10
msg_vpv01_pcm_ready_end:
msg_vpv01_pcm_fail:
        dc.b "[BerryMP314] FEHLER: Audio-DMA-Puffer konnte nicht vorbereitet werden.",10
msg_vpv01_pcm_fail_end:
msg_vpv01_tone_begin:
        dc.b "[BerryMP314] Spiele jetzt ca. 2 Sekunden Testton ueber Raspberry-Pi-HDMI ...",10
msg_vpv01_tone_begin_end:
msg_vpv01_send_fail:
        dc.b "[BerryMP314] FEHLER: MMAL PCM BUFFER_FROM_HOST/BULK_TX konnte nicht gesendet werden.",10
msg_vpv01_send_fail_end:
msg_vpv01_wait_fail:
        dc.b "[BerryMP314] FEHLER: PCM BULK_TX_DONE/BUFFER_TO_HOST nicht sauber zurueckgekommen.",10
msg_vpv01_wait_fail_end:
msg_vpv01_tone_ok:
        dc.b "[BerryMP314] Live MP3->PCM Wiedergabe wurde von audio_render verarbeitet.",10
msg_vpv01_tone_ok_end:
msg_vpv01_fail:
        dc.b "[BerryMP314] FEHLER: HDMI-Audiotest abgebrochen; sicherer Cleanup folgt.",10
msg_vpv01_fail_end:
msg_vpv01_cleanup_fail:
        dc.b "[BerryMP314] FEHLER: MMAL-Cleanup nicht vollstaendig bestaetigt.",10
msg_vpv01_cleanup_fail_end:
msg_vpv05_cleanup_disable:
        dc.b "[BerryMP314] Cleanup 1/5: audio_render COMPONENT_DISABLE ...",10
msg_vpv05_cleanup_disable_end:
msg_vpv05_cleanup_service:
        dc.b "[BerryMP314] Cleanup 2/5: MMAL-Service schliessen ...",10
msg_vpv05_cleanup_service_end:
msg_vpv06_free_bulk:
        dc.b "[BerryMP314] Cleanup 3/5: bulk_alloc sicher freigeben ...",10
msg_vpv06_free_bulk_end:
msg_vpv06_free_prop:
        dc.b "[BerryMP314] Cleanup 4/5: prop_alloc sicher freigeben ...",10
msg_vpv06_free_prop_end:
msg_vpv06_free_ok:
        dc.b "[BerryMP314] Cleanup 5/5: Exec-Speicherfreigabe abgeschlossen.",10
msg_vpv06_free_ok_end:
msg_vpv01_done:
        dc.b "[BerryMP314] Legacy-Testpfad beendet.",10
msg_vpv01_done_end:
        even


; ====================================================================
; VPv18 - SOFTWARE AAC -> HARDWARE HDMI AUDIO
;
; The VideoCore audio_decode experiment is intentionally abandoned here.
; VPv20 inherits the hardware-confirmed VPv06 ril.audio_render PCM path and
; loads MintAMP's external aac.decoder through AmigaDOS LoadSeg().
;
; Decoder module ABI (MintAMP Decoder Module ABI v2):
;   LoadSeg("aac.decoder") -> entry at BADDR(seg)+4 -> DecoderOps*
;   open(read,seek,user,info) -> opaque handle
;   decode(handle, short*, maxSamplesPerChan) -> signed 16-bit native m68k PCM
;
; m68k is big-endian while VPv06's proven MMAL renderer is configured for
; signed little-endian PCM. Therefore every decoded 16-bit sample is byte
; swapped in-place before the VCHIQ/MMAL BULK_TX.
; ====================================================================

DECODER_MODULE_MAGIC     equ $44454300
DECODER_MODULE_VERSION   equ 2
DECOPS_INFO               equ 0
DECOPS_OPEN               equ 4
DECOPS_DECODE             equ 8
DECOPS_SEEK               equ 12
DECOPS_CLOSE              equ 16
DECINFO_MAGIC             equ 0
DECINFO_VERSION           equ 4
DECSTREAM_RATE            equ 0
DECSTREAM_CHANNELS        equ 4
DECSTREAM_BITS            equ 6
DECSTREAM_TOTAL           equ 8
VPV18_MAX_SAMPLES_CH      equ 12000

        section bss,bss
vpv18_seg:                 ds.l 1
vpv18_ops:                 ds.l 1
vpv18_dec_handle:          ds.l 1
vpv18_stream_cur:          ds.l 1
vpv18_pcm_bytes:           ds.l 1
vpv18_pcm_samples:         ds.l 1
vpv18_pcm_blocks:          ds.l 1
vpv18_total_samples:       ds.l 1
vpv18_status:              ds.l 1
vpv18_stream_info:         ds.b 12
        even

        section code,code

vpv18_audio_test:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_test_status
        clr.l   vpv18_status
        clr.l   vpv18_seg
        clr.l   vpv18_ops
        clr.l   vpv18_dec_handle
        clr.l   vpv18_pcm_bytes
        clr.l   vpv18_pcm_samples
        clr.l   vpv18_pcm_blocks
        clr.l   vpv18_total_samples

        lea     msg_vpv18_load,a1
        move.l  #msg_vpv18_load_end-msg_vpv18_load,d3
        jsr     print_force
        jsr     vpv18_load_module
        tst.l   d0
        bne.w   vpv18_test_fail

        jsr     vpv18_open_module
        tst.l   d0
        bne.w   vpv18_test_fail

        ; This embedded test asset is known to be AAC-LC, 48 kHz stereo.
        ; Refuse a surprise format so the VPv06 renderer stays unchanged.
        cmpi.l  #VPV01_AUDIO_RATE,vpv18_stream_info+DECSTREAM_RATE
        bne.w   vpv18_bad_format
        cmpi.w  #VPV01_AUDIO_CHANNELS,vpv18_stream_info+DECSTREAM_CHANNELS
        bne.w   vpv18_bad_format
        cmpi.w  #16,vpv18_stream_info+DECSTREAM_BITS
        bne.w   vpv18_bad_format

        lea     msg_vpv18_info,a1
        move.l  #msg_vpv18_info_end-msg_vpv18_info,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_stream_info+DECSTREAM_RATE,d0
        jsr     print_hex32
        lea     msg_vpv18_info_ch,a1
        move.l  #msg_vpv18_info_ch_end-msg_vpv18_info_ch,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_CHANNELS,d0
        jsr     print_hex32
        lea     msg_vpv18_info_bits,a1
        move.l  #msg_vpv18_info_bits_end-msg_vpv18_info_bits,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_BITS,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        lea     msg_vpv01_mmal_ready,a1
        move.l  #msg_vpv01_mmal_ready_end-msg_vpv01_mmal_ready,d3
        jsr     print_force
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv18_test_fail
        jsr     vpv01_configure_audio_render
        tst.l   d0
        bne.w   vpv18_test_fail

        ; Reuse VPv06's proven aligned DMA allocation. The synthetic square
        ; wave it writes is never sent: each block is overwritten by decode().
        jsr     vpv01_prepare_tone
        tst.l   d0
        bne.w   vpv18_test_fail

        lea     msg_vpv18_play,a1
        move.l  #msg_vpv18_play_end-msg_vpv18_play,d3
        jsr     print_force

vpv18_decode_loop:
        jsr     vpv18_decode_block
        tst.l   d0
        bmi.w   vpv18_decode_error
        beq.w   vpv18_decode_eof

        move.l  d0,vpv18_pcm_samples
        add.l   d0,vpv18_total_samples
        move.l  d0,d1
        lsl.l   #2,d1                 ; stereo * 16 bit = 4 bytes/sample-frame
        move.l  d1,vpv18_pcm_bytes
        cmpi.l  #VPV01_TONE_BYTES,d1
        bhi.w   vpv18_decode_error

        jsr     vpv18_swap_pcm16
        jsr     vpv18_make_pagelist
        tst.l   d0
        bne.w   vpv18_decode_error
        jsr     vpv18_send_pcm_block
        tst.l   d0
        bne.w   vpv18_decode_error
        jsr     vpv18_wait_pcm_block
        tst.l   d0
        bne.w   vpv18_decode_error
        addq.l  #1,vpv18_pcm_blocks
        bra.w   vpv18_decode_loop

vpv18_decode_eof:
        ; Let audio_render drain its internal queue before tearing it down.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #20,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        lea     msg_vpv18_success,a1
        move.l  #msg_vpv18_success_end-msg_vpv18_success,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_pcm_blocks,d0
        jsr     print_hex32
        lea     msg_vpv18_success_samples,a1
        move.l  #msg_vpv18_success_samples_end-msg_vpv18_success_samples,d3
        jsr     print_force
        move.l  vpv18_total_samples,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        bra.w   vpv18_cleanup

vpv18_bad_format:
        lea     msg_vpv18_badfmt,a1
        move.l  #msg_vpv18_badfmt_end-msg_vpv18_badfmt,d3
        jsr     print_force
        bra.w   vpv18_test_fail

vpv18_decode_error:
        lea     msg_vpv18_decode_fail,a1
        move.l  #msg_vpv18_decode_fail_end-msg_vpv18_decode_fail,d3
        jsr     print_force
vpv18_test_fail:
        move.l  #1,vpv18_status
        move.l  #1,vpv01_test_status

vpv18_cleanup:
        jsr     vpv18_close_module
        jsr     vpv01_cleanup
        tst.l   vpv01_test_status
        beq.s   vpv18_cleanup_mmal_ok
        move.l  #1,vpv18_status
vpv18_cleanup_mmal_ok:
        tst.l   vpv18_status
        bne.s   vpv18_done
        lea     msg_vpv18_done,a1
        move.l  #msg_vpv18_done_end-msg_vpv18_done,d3
        jsr     print_force
vpv18_done:
        move.l  vpv18_status,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Load the MintAMP decoder. First try the same drawer as VPv18, then the
; original MintAMP "decoders/" layout as a fallback.
vpv18_load_module:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  a5,a6
        ; VPv36: first try decoder next to the executable, independent of CWD.
        lea     vpv18_decoder_name_progdir,a0
        move.l  a0,d1
        jsr     LoadSeg(a6)
        tst.l   d0
        bne.s   vpv18_load_have_seg
        ; Backward-compatible fallbacks: current drawer, then decoders/.
        lea     vpv18_decoder_name,a0
        move.l  a0,d1
        jsr     LoadSeg(a6)
        tst.l   d0
        bne.s   vpv18_load_have_seg
        lea     vpv18_decoder_name_alt,a0
        move.l  a0,d1
        jsr     LoadSeg(a6)
        tst.l   d0
        beq.w   vpv18_load_fail
vpv18_load_have_seg:
        move.l  d0,vpv18_seg
        lsl.l   #2,d0                 ; BADDR(BPTR)
        addq.l  #4,d0                 ; documented DecoderModuleEntry address
        move.l  d0,a0
        jsr     (a0)
        move.l  d0,vpv18_ops
        beq.w   vpv18_load_fail_unload
        move.l  d0,a0
        move.l  DECOPS_INFO(a0),a1
        cmpa.l  #0,a1
        beq.w   vpv18_load_fail_unload
        cmpi.l  #DECODER_MODULE_MAGIC,DECINFO_MAGIC(a1)
        bne.w   vpv18_load_fail_unload
        moveq   #0,d0
        move.w  DECINFO_VERSION(a1),d0
        cmpi.l  #DECODER_MODULE_VERSION,d0
        bhi.w   vpv18_load_fail_unload
        tst.l   DECOPS_OPEN(a0)
        beq.w   vpv18_load_fail_unload
        tst.l   DECOPS_DECODE(a0)
        beq.w   vpv18_load_fail_unload
        tst.l   DECOPS_CLOSE(a0)
        beq.w   vpv18_load_fail_unload
        lea     msg_vpv18_load_ok,a1
        move.l  #msg_vpv18_load_ok_end-msg_vpv18_load_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv18_load_done
vpv18_load_fail_unload:
        clr.l   vpv18_ops
        move.l  vpv18_seg,d1
        beq.s   vpv18_load_fail
        move.l  a5,a6
        jsr     UnLoadSeg(a6)
        clr.l   vpv18_seg
vpv18_load_fail:
        lea     msg_vpv18_load_fail,a1
        move.l  #msg_vpv18_load_fail_end-msg_vpv18_load_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_load_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Call DecoderOps.open(readCb, seekCb, userData, &streamInfo) using m68k cdecl.
vpv18_open_module:
        movem.l d2-d7/a2-a6,-(sp)
        lea     vpv18_test_aac,a0
        move.l  a0,vpv18_stream_cur
        lea     vpv18_stream_info,a0
        moveq   #2,d0
vpv18_open_clear:
        clr.l   (a0)+
        dbra    d0,vpv18_open_clear
        move.l  vpv18_ops,a0
        move.l  DECOPS_OPEN(a0),a0
        pea     vpv18_stream_info
        clr.l   -(sp)                  ; userData = NULL
        pea     vpv18_seek_cb
        pea     vpv18_read_cb
        jsr     (a0)
        lea     16(sp),sp
        move.l  d0,vpv18_dec_handle
        beq.s   vpv18_open_fail
        lea     msg_vpv18_open_ok,a1
        move.l  #msg_vpv18_open_ok_end-msg_vpv18_open_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv18_open_done
vpv18_open_fail:
        lea     msg_vpv18_open_fail,a1
        move.l  #msg_vpv18_open_fail_end-msg_vpv18_open_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_open_done:
        movem.l (sp)+,d2-d7/a2-a6
        rts

; Decode up to 12000 sample frames/channel directly into the proven DMA area.
; Return D0 = samples/channel, 0 EOF, negative error.
vpv18_decode_block:
        movem.l d2-d7/a2-a6,-(sp)
        move.l  vpv18_ops,a0
        move.l  DECOPS_DECODE(a0),a0
        move.l  #VPV18_MAX_SAMPLES_CH,-(sp)
        move.l  bulk_data_ptr,-(sp)
        move.l  vpv18_dec_handle,-(sp)
        jsr     (a0)
        lea     12(sp),sp
        movem.l (sp)+,d2-d7/a2-a6
        rts

; Native m68k short PCM is big-endian. Swap every 16-bit sample to LE.
vpv18_swap_pcm16:
        movem.l d0-d2/a0,-(sp)
        move.l  vpv18_pcm_bytes,d1
        lsr.l   #1,d1
        beq.s   vpv18_swap_done
        move.l  bulk_data_ptr,a0
vpv18_swap_loop:
        moveq   #0,d0
        move.w  (a0),d0
        rol.w   #8,d0
        move.w  d0,(a0)+
        subq.l  #1,d1
        bne.s   vpv18_swap_loop
vpv18_swap_done:
        movem.l (sp)+,d0-d2/a0
        rts

; Rewrite the VCHIQ pagelist for the actual decoded PCM byte count.
vpv18_make_pagelist:
        movem.l d1-d2/a0,-(sp)
        move.l  vpv18_pcm_bytes,d0
        beq.s   vpv18_pagelist_fail
        cmpi.l  #VPV01_TONE_BYTES,d0
        bhi.s   vpv18_pagelist_fail
        move.l  bulk_pagelist_ptr,a0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  vpv18_pcm_bytes,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        move.l  bulk_data_bus,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     store_le32
        moveq   #0,d0
        bra.s   vpv18_pagelist_done
vpv18_pagelist_fail:
        moveq   #1,d0
vpv18_pagelist_done:
        movem.l (sp)+,d1-d2/a0
        rts

; DecoderReadCb(void *user, unsigned char *buf, unsigned long maxBytes)
; cdecl stack: 4(sp)=user, 8(sp)=buf, 12(sp)=maxBytes.
vpv18_read_cb:
        move.l  12(sp),d0
        move.l  #vpv18_test_aac_end,d1
        sub.l   vpv18_stream_cur,d1
        cmp.l   d1,d0
        bls.s   vpv18_read_count_ok
        move.l  d1,d0
vpv18_read_count_ok:
        tst.l   d0
        beq.s   vpv18_read_done
        move.l  d0,d1
        move.l  vpv18_stream_cur,a1
        move.l  8(sp),a0
vpv18_read_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv18_read_loop
        move.l  a1,vpv18_stream_cur
vpv18_read_done:
        rts

; DecoderSeekCb(void *user, long offset, int whence), 0/1/2=set/cur/end.
vpv18_seek_cb:
        move.l  12(sp),d1
        cmpi.l  #0,d1
        beq.s   vpv18_seek_set
        cmpi.l  #1,d1
        beq.s   vpv18_seek_cur
        cmpi.l  #2,d1
        beq.s   vpv18_seek_end
        bra.s   vpv18_seek_fail
vpv18_seek_set:
        lea     vpv18_test_aac,a0
        bra.s   vpv18_seek_add
vpv18_seek_cur:
        move.l  vpv18_stream_cur,a0
        bra.s   vpv18_seek_add
vpv18_seek_end:
        lea     vpv18_test_aac_end,a0
vpv18_seek_add:
        adda.l  8(sp),a0
        move.l  a0,d0
        move.l  #vpv18_test_aac,d1
        cmp.l   d1,d0
        bcs.s   vpv18_seek_fail
        move.l  #vpv18_test_aac_end,d1
        cmp.l   d1,d0
        bhi.s   vpv18_seek_fail
        move.l  a0,vpv18_stream_cur
        moveq   #0,d0
        rts
vpv18_seek_fail:
        moveq   #-1,d0
        rts

; Close decoder state first, then unload the hunk after no module code is active.
vpv18_close_module:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  vpv18_dec_handle,d0
        beq.s   vpv18_close_unload
        move.l  vpv18_ops,a0
        move.l  DECOPS_CLOSE(a0),a0
        move.l  vpv18_dec_handle,-(sp)
        jsr     (a0)
        addq.l  #4,sp
        clr.l   vpv18_dec_handle
        lea     msg_vpv18_close_ok,a1
        move.l  #msg_vpv18_close_ok_end-msg_vpv18_close_ok,d3
        jsr     print_force
vpv18_close_unload:
        clr.l   vpv18_ops
        move.l  vpv18_seg,d1
        beq.s   vpv18_close_done
        move.l  a5,a6
        jsr     UnLoadSeg(a6)
        clr.l   vpv18_seg
        lea     msg_vpv18_unload_ok,a1
        move.l  #msg_vpv18_unload_ok_end-msg_vpv18_unload_ok,d3
        jsr     print_force
vpv18_close_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


vpv18_send_pcm_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_bulk_done
        clr.l   vpv01_buffer_returned

        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   bulk_data_ptr,d0
        bne.w   vpv18_send_fail_nomap
        move.l  vpv01_audio_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   vpv18_send_fail_post
        move.l  #1,vpv01_audio_dma_active

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv18_send_fail_post
        move.l  a2,a0
        moveq   #79,d7
vpv18_send_clear:
        clr.l   (a0)+
        dbra    d7,vpv18_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  vpv18_pcm_bytes,d0
        jsr     store_le32
        ; flags at +92 remain zero. PTS/DTS = MMAL_TIME_UNKNOWN.
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  vpv18_pcm_bytes,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.w   vpv18_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv18_send_no_bell:
        moveq   #0,d0
        bra.w   vpv18_send_done
vpv18_send_fail_post:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv18_send_fail_nomap
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv18_send_fail_nomap:
        lea     msg_vpv01_send_fail,a1
        move.l  #msg_vpv01_send_fail_end-msg_vpv01_send_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


vpv18_wait_pcm_block:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv18_wait_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.w   vpv18_wait_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv18_wait_loop
        jsr     dma_post_all
        bra.w   vpv18_wait_fail

vpv18_wait_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   vpv18_wait_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_msgid
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,vpv01_last_rx_size

        ; Ignore traffic not addressed to this local MMAL service.
        move.l  vpv01_last_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv18_wait_consume_continue
        move.l  vpv01_last_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv18_wait_consume_continue

        move.l  vpv01_last_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.w   vpv18_wait_bulk_done
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.w   vpv18_wait_data
        bra.w   vpv18_wait_consume_continue

vpv18_wait_bulk_done:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #4,d0
        bcs.w   vpv18_wait_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   vpv18_pcm_bytes,d0
        bne.w   vpv18_wait_fail
        move.l  #1,vpv01_bulk_done
        tst.l   vpv01_audio_dma_active
        beq.w   vpv18_wait_consume_check
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
        bra.w   vpv18_wait_consume_check

vpv18_wait_data:
        move.l  vpv01_last_rx_size,d0
        cmp.l   #44,d0
        bcs.w   vpv18_wait_consume_continue
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   vpv18_wait_consume_continue
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        bne.w   vpv18_wait_consume_continue
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv18_wait_fail
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   vpv01_audio_input,d0
        bne.w   vpv18_wait_consume_continue
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.w   vpv18_wait_consume_continue
        move.l  #1,vpv01_buffer_returned

vpv18_wait_consume_check:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv18_wait_fail
        tst.l   vpv01_bulk_done
        beq.w   vpv18_wait_more
        tst.l   vpv01_buffer_returned
        bne.w   vpv18_wait_success
vpv18_wait_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv18_wait_loop
        jsr     dma_post_all
        bra.w   vpv18_wait_fail

vpv18_wait_consume_continue:
        move.l  vpv01_last_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv18_wait_fail
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv18_wait_loop
        jsr     dma_post_all
        bra.w   vpv18_wait_fail

vpv18_wait_success:
        moveq   #0,d0
        bra.w   vpv18_wait_done
vpv18_wait_fail:
        tst.l   vpv01_audio_dma_active
        beq.w   vpv18_wait_fail_print
        move.l  #BULK_DMA_SIZE,vpv01_audio_dma_len
        move.l  bulk_data_ptr,a0
        lea     vpv01_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv01_audio_dma_active
vpv18_wait_fail_print:
        lea     msg_vpv01_wait_fail,a1
        move.l  #msg_vpv01_wait_fail_end-msg_vpv01_wait_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv18_wait_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts



; ====================================================================
; VPv20 - REAL MATROSKA AAC LONG PREFIX -> MINTAMP/HELIX -> PCM -> RPi HDMI
;
; This is deliberately the next bounded integration step, not yet A/V mixing:
;   VPv20 <film.mkv>
;     1) parse the existing V41L Matroska Tracks metadata,
;     2) select first A_AAC track,
;     3) extract up to 4096 real unlaced AAC access units from the MKV,
;     4) synthesize ADTS headers from CodecPrivate/AudioSpecificConfig,
;     5) decode with MintAMP aac.decoder,
;     6) send resulting PCM through the hardware-confirmed VPv06 renderer.
;
; The purpose is to prove REAL container AAC before merging it into the live
; H.264 playback loop.  Laced Matroska audio is detected and skipped in v19;
; a later combined player can add Xiph/fixed/EBML lacing once the base path is
; hardware-confirmed.
; ====================================================================

VPV19_AAC_BUF_SIZE      equ $00020000      ; BerryMP314: 128 KiB rolling ADTS window (movie length independent)
VPV19_TARGET_FRAMES     equ 4096              ; legacy prefix extractor only; BerryMP314 active path does not use this cap
VPV43_AUDIO_IO_SIZE     equ $00010000          ; independent 64 KiB MKV audio reader window
VPV43_ADTS_FILL_FRAMES  equ 128                ; refill granularity, bounded by 128 KiB ADTS window
VPV43_SYNC_SAMPLES_CH   equ 16384              ; BerryMP314: ~341-372 ms PCM blocks, fills one 64-KiB stereo/16-bit MMAL buffer
VPV43_TIMECODE_SCALE_MS equ 1000000             ; first PTS scheduler supports Matroska default 1 ms ticks
VPV44_ADTS_TOPUP_THRESHOLD equ $00004000         ; 16 KiB: top up outside Helix callback

        section bss,bss
v19_aac_found:              ds.l 1
v19_audio_track_num:        ds.l 1
v19_audio_codecpriv_len:    ds.l 1
v19_audio_probe_channels:   ds.l 1
v19_audio_codecpriv:        ds.b 16
v19_aac_buf_ptr:            ds.l 1
v19_aac_buf_len:            ds.l 1
v19_aac_buf_cur:            ds.l 1
v19_aac_frame_count:        ds.l 1
v19_audio_payload_len:      ds.l 1
v19_audio_lacing_seen:      ds.l 1
v19_adts_profile:           ds.l 1
v19_adts_freqidx:           ds.l 1
v19_adts_channels:          ds.l 1
v19_pcm_channels:           ds.l 1
v19_pcm_rate:               ds.l 1
v19_pcm_bits:               ds.l 1
v19_pcm_blockalign:         ds.l 1
v19_pcm_bitrate:            ds.l 1
v19_test_status:            ds.l 1
        even

        section code,code

; Exact CodecID comparison against Matroska "A_AAC".
v19_codec_is_aac:
        movem.l d1-d3/a0-a1,-(sp)
        move.l  v10_cur_codec_len,d1
        cmpi.l  #5,d1
        bne.s   v19_codec_aac_no
        move.l  v10_cur_codec_ptr,a0
        lea     v19_codec_aac,a1
        moveq   #4,d3
v19_codec_aac_cmp:
        move.b  (a0)+,d1
        cmp.b   (a1)+,d1
        bne.s   v19_codec_aac_no
        dbra    d3,v19_codec_aac_cmp
        moveq   #1,d0
        bra.s   v19_codec_aac_done
v19_codec_aac_no:
        moveq   #0,d0
v19_codec_aac_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; We arrive here after DOS/Output are open but before the VCHIQ bootstrap.
; Parse one filename, probe Tracks, and convert a bounded real AAC prefix to
; an in-memory ADTS stream.  Only then enter the proven VPv06 MMAL startup.
vpv19_cli_entry:
        ; MHI03: compressed MP3 bytes come from mhiberry.library, not a DOS file.
        jsr     vpv43_audio_stream_prepare
        tst.l   d0
        bne.w   vpv19_cli_extract_fail

        ; Prime one real MHI MP3->PCM16 batch on CPU1 before MMAL is created.
        jsr     vpv21_predecode_pcm
        tst.l   d0
        bne.w   vpv19_cli_extract_fail

        ; Enter the hardware-confirmed BerryMP314 audio-only VCHIQ/MMAL path.
        jmp     vpv01_vchiq_entry

vpv19_cli_no_aac:
        lea     msg_v19_no_aac,a1
        move.l  #msg_v19_no_aac_end-msg_v19_no_aac,d3
        jsr     print_force
        bra.s   vpv19_cli_fail_exit
vpv19_cli_bad_asc:
        lea     msg_v19_bad_asc,a1
        move.l  #msg_v19_bad_asc_end-msg_v19_bad_asc,d3
        jsr     print_force
        bra.s   vpv19_cli_fail_exit
vpv19_cli_extract_fail:
        lea     msg_v19_extract_fail,a1
        move.l  #msg_v19_extract_fail_end-msg_v19_extract_fail,d3
        jsr     print_force
        jsr     vpv19_free_aac_buffer
vpv19_cli_fail_exit:
        ; h264rgb_main saved these registers on entry.  No VCHIQ state exists yet.
        move.l  t23_file_handle,d0
        beq.s   vpv19_cli_no_open_file
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
vpv19_cli_no_open_file:
        jsr     v10b_stream_reset
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; Parse the first two bytes of MPEG-4 AudioSpecificConfig. v19 intentionally
; accepts AAC-LC only (audioObjectType=2), with an explicit sampling-frequency
; index and mono/stereo channelConfiguration.
vpv19_parse_asc:
        movem.l d1-d4/a0,-(sp)
        lea     v19_audio_codecpriv,a0
        moveq   #0,d1
        move.b  (a0),d1
        moveq   #0,d2
        move.b  1(a0),d2
        move.l  d1,d0
        lsr.l   #3,d0
        andi.l  #$1f,d0
        cmpi.l  #2,d0                  ; AAC-LC only in this first real MKV test
        bne.s   vpv19_asc_fail
        subq.l  #1,d0                  ; ADTS profile = objectType - 1
        move.l  d0,v19_adts_profile
        move.l  d1,d0
        andi.l  #7,d0
        lsl.l   #1,d0
        move.l  d2,d3
        lsr.l   #7,d3
        andi.l  #1,d3
        or.l    d3,d0
        cmpi.l  #12,d0
        bhi.s   vpv19_asc_fail
        move.l  d0,v19_adts_freqidx
        move.l  d2,d0
        lsr.l   #3,d0
        andi.l  #$0f,d0
        cmpi.l  #1,d0
        bcs.s   vpv19_asc_fail
        cmpi.l  #2,d0
        bhi.s   vpv19_asc_fail
        move.l  d0,v19_adts_channels
        moveq   #0,d0
        bra.s   vpv19_asc_done
vpv19_asc_fail:
        moveq   #1,d0
vpv19_asc_done:
        movem.l (sp)+,d1-d4/a0
        rts

; Find and extract up to 4096 actual AAC access units from the original MKV.
; Output is a contiguous ADTS stream in Fast RAM.
vpv19_extract_aac_prefix:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v19_aac_buf_ptr
        clr.l   v19_aac_buf_len
        clr.l   v19_aac_buf_cur
        clr.l   v19_aac_frame_count
        clr.l   v19_audio_lacing_seen
        clr.l   v10b_segment_end

        move.l  a4,a6
        move.l  #VPV19_AAC_BUF_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv19_extract_fail
        move.l  d0,v19_aac_buf_ptr
        move.l  d0,v19_aac_buf_cur

        jsr     v10b_stream_open
        tst.l   d0
        bne.w   vpv19_extract_fail_close
vpv19_extract_loop:
        move.l  v19_aac_frame_count,d0
        cmpi.l  #VPV19_TARGET_FRAMES,d0
        bcc.w   vpv19_extract_success
        jsr     vpv19_find_audio_block
        tst.l   d0
        beq.s   vpv19_extract_have_block
        cmpi.l  #2,d0
        beq.w   vpv19_extract_eof
        bra.w   vpv19_extract_fail_close
vpv19_extract_have_block:
        move.l  v19_audio_payload_len,d0
        addq.l  #7,d0
        move.l  v19_aac_buf_len,d1
        add.l   d0,d1
        cmpi.l  #VPV19_AAC_BUF_SIZE,d1
        bhi.w   vpv19_extract_success
        move.l  v19_audio_payload_len,d0
        jsr     vpv19_append_adts_header
        tst.l   d0
        bne.w   vpv19_extract_fail_close
        move.l  v19_audio_payload_len,d0
        jsr     vpv19_copy_audio_payload
        tst.l   d0
        bne.w   vpv19_extract_fail_close
        addq.l  #1,v19_aac_frame_count
        bra.w   vpv19_extract_loop
vpv19_extract_eof:
        tst.l   v19_aac_frame_count
        bne.s   vpv19_extract_eof_have
        tst.l   v19_audio_lacing_seen
        beq.w   vpv19_extract_fail_close
        lea     msg_v19_lacing,a1
        move.l  #msg_v19_lacing_end-msg_v19_lacing,d3
        jsr     print_force
        bra.w   vpv19_extract_fail_close
vpv19_extract_eof_have:
vpv19_extract_success:
        moveq   #0,d7
        bra.s   vpv19_extract_close
vpv19_extract_fail_close:
        moveq   #1,d7
vpv19_extract_close:
        move.l  t23_file_handle,d0
        beq.s   vpv19_extract_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
vpv19_extract_closed:
        jsr     v10b_stream_reset
        tst.l   d7
        beq.s   vpv19_extract_ok
vpv19_extract_fail:
        jsr     vpv19_free_aac_buffer
        moveq   #1,d0
        bra.s   vpv19_extract_done
vpv19_extract_ok:
        moveq   #0,d0
vpv19_extract_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Parse one Block/SimpleBlock payload. D0 contains payload bytes on entry.
; D0=0 selected, unlaced AAC block ready with reader at raw AAC payload;
; D0=3 other/laced block skipped; D0=1 malformed.
vpv19_begin_audio_block:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        cmpi.l  #4,d7
        bcs.w   vpv19_audio_block_fail
        jsr     v10b_read_size
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        move.l  d1,d6                  ; track number
        move.l  d2,d5                  ; track VINT bytes
        move.l  d5,d4
        addq.l  #3,d4                  ; timecode(2)+flags(1)
        cmp.l   d7,d4
        bhi.w   vpv19_audio_block_fail
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   vpv19_audio_block_fail
        move.l  d1,d2                  ; flags
        sub.l   d4,d7
        cmp.l   v19_audio_track_num,d6
        beq.s   vpv19_audio_selected
        move.l  d7,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   vpv19_audio_block_fail
        moveq   #3,d0
        bra.s   vpv19_audio_block_done
vpv19_audio_selected:
        move.l  d2,d1
        andi.l  #$00000006,d1
        beq.s   vpv19_audio_unlaced
        move.l  #1,v19_audio_lacing_seen
        move.l  d7,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   vpv19_audio_block_fail
        moveq   #3,d0
        bra.s   vpv19_audio_block_done
vpv19_audio_unlaced:
        tst.l   d7
        beq.s   vpv19_audio_block_fail
        move.l  d7,v19_audio_payload_len
        moveq   #0,d0
        bra.s   vpv19_audio_block_done
vpv19_audio_block_fail:
        moveq   #1,d0
vpv19_audio_block_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Sequential Matroska walker modelled after v10b_find_video_block, but dispatches
; only the selected AAC track and leaves its payload unread for the caller.
vpv19_find_audio_block:
        movem.l d1-d7/a0-a3,-(sp)
vpv19_find_loop:
        move.l  v10b_blockgroup_end,d1
        beq.s   vpv19_find_check_cluster
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv19_find_check_cluster
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv19_find_check_cluster
        clr.l   v10b_blockgroup_end
vpv19_find_check_cluster:
        move.l  v10b_cluster_end,d1
        beq.s   vpv19_find_header
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv19_find_header
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv19_find_header
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
vpv19_find_header:
        jsr     v10b_read_id
        cmpi.l  #2,d0
        beq.w   vpv19_find_eof
        tst.l   d0
        bne.w   vpv19_find_fail
        move.l  d1,d5
        jsr     v10b_read_size
        tst.l   d0
        bne.w   vpv19_find_fail
        move.l  d1,d6
        move.l  #$FFFFFFFF,d7
        cmpi.l  #$FFFFFFFF,d6
        beq.s   vpv19_find_end_ready
        move.l  v10b_abs_pos,d7
        add.l   d6,d7
        bcs.w   vpv19_find_fail
vpv19_find_end_ready:
        cmpi.l  #$1A45DFA3,d5
        beq.w   vpv19_find_skip
        cmpi.l  #$18538067,d5
        beq.w   vpv19_find_segment
        cmpi.l  #$1F43B675,d5
        beq.w   vpv19_find_cluster
        cmpi.l  #$114D9B74,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1549A966,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1654AE6B,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1C53BB6B,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1254C367,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1941A469,d5
        beq.s   vpv19_find_segment_meta
        cmpi.l  #$1043A770,d5
        beq.s   vpv19_find_segment_meta
        bra.s   vpv19_find_cluster_children
vpv19_find_segment_meta:
        move.l  v10b_cluster_end,d1
        cmpi.l  #$FFFFFFFF,d1
        bne.w   vpv19_find_skip
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        bra.w   vpv19_find_skip
vpv19_find_cluster_children:
        tst.l   v10b_cluster_active
        beq.w   vpv19_find_skip
        cmpi.l  #$000000E7,d5
        beq.w   vpv19_find_timecode
        cmpi.l  #$000000A0,d5
        beq.w   vpv19_find_blockgroup
        cmpi.l  #$000000A3,d5
        beq.w   vpv19_find_block
        cmpi.l  #$000000A1,d5
        bne.w   vpv19_find_skip
        tst.l   v10b_blockgroup_end
        beq.w   vpv19_find_skip
        bra.w   vpv19_find_block
vpv19_find_segment:
        move.l  d7,v10b_segment_end
        bra.w   vpv19_find_loop
vpv19_find_cluster:
        move.l  #1,v10b_cluster_active
        move.l  d7,v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_cluster_timecode_live
        bra.w   vpv19_find_loop
vpv19_find_blockgroup:
        move.l  d7,v10b_blockgroup_end
        bra.w   vpv19_find_loop
vpv19_find_timecode:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv19_find_fail
        move.l  d6,d0
        jsr     v10b_read_uint
        tst.l   d0
        bne.w   vpv19_find_fail
        move.l  d1,v10b_cluster_timecode_live
        bra.w   vpv19_find_loop
vpv19_find_block:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv19_find_fail
        move.l  d6,d0
        jsr     vpv19_begin_audio_block
        tst.l   d0
        beq.s   vpv19_find_found
        cmpi.l  #3,d0
        beq.w   vpv19_find_loop
        bra.w   vpv19_find_fail
vpv19_find_skip:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv19_find_fail
        move.l  d6,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.w   vpv19_find_fail
        bra.w   vpv19_find_loop
vpv19_find_found:
        moveq   #0,d0
        bra.s   vpv19_find_done
vpv19_find_eof:
        moveq   #2,d0
        bra.s   vpv19_find_done
vpv19_find_fail:
        moveq   #1,d0
vpv19_find_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; D0 = raw AAC payload bytes. Append a seven-byte MPEG-4 ADTS header.
vpv19_append_adts_header:
        movem.l d1-d7/a0,-(sp)
        move.l  d0,d7
        addq.l  #7,d7                  ; full ADTS frame length
        cmpi.l  #$1fff,d7
        bhi.w   vpv19_adts_fail
        move.l  v19_aac_buf_cur,a0
        move.b  #$ff,(a0)+
        move.b  #$f1,(a0)+             ; MPEG-4, layer 0, protection_absent
        move.l  v19_adts_profile,d1
        lsl.l   #6,d1
        move.l  v19_adts_freqidx,d2
        lsl.l   #2,d2
        or.l    d2,d1
        move.l  v19_adts_channels,d2
        lsr.l   #2,d2
        or.l    d2,d1
        move.b  d1,(a0)+
        move.l  v19_adts_channels,d1
        andi.l  #3,d1
        lsl.l   #6,d1
        move.l  d7,d2
        lsr.l   #8,d2
        lsr.l   #3,d2
        andi.l  #3,d2
        or.l    d2,d1
        move.b  d1,(a0)+
        move.l  d7,d1
        lsr.l   #3,d1
        move.b  d1,(a0)+
        move.l  d7,d1
        andi.l  #7,d1
        lsl.l   #5,d1
        ori.l   #$1f,d1
        move.b  d1,(a0)+
        move.b  #$fc,(a0)+             ; VBR fullness + 1 raw_data_block
        move.l  a0,v19_aac_buf_cur
        addq.l  #7,v19_aac_buf_len
        moveq   #0,d0
        bra.s   vpv19_adts_done
vpv19_adts_fail:
        moveq   #1,d0
vpv19_adts_done:
        movem.l (sp)+,d1-d7/a0
        rts

; D0 = bytes. Copy selected raw AAC payload from the bounded MKV reader into
; the ADTS output buffer.
vpv19_copy_audio_payload:
        movem.l d1-d7/a0,-(sp)
        move.l  d0,d7
        move.l  v19_aac_buf_cur,a0
vpv19_copy_audio_loop:
        tst.l   d7
        beq.s   vpv19_copy_audio_ok
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   vpv19_copy_audio_fail
        move.b  d1,(a0)+
        addq.l  #1,v19_aac_buf_len
        subq.l  #1,d7
        bra.s   vpv19_copy_audio_loop
vpv19_copy_audio_ok:
        move.l  a0,v19_aac_buf_cur
        moveq   #0,d0
        bra.s   vpv19_copy_audio_done
vpv19_copy_audio_fail:
        moveq   #1,d0
vpv19_copy_audio_done:
        movem.l (sp)+,d1-d7/a0
        rts

vpv19_free_aac_buffer:
        movem.l d0-d2/a1/a6,-(sp)
        ; BerryMP314 may own an independent live MKV audio reader as well.
        tst.l   vpv43_streaming_audio
        beq.s   vpv19_free_no_stream
        jsr     vpv43_audio_stream_cleanup
vpv19_free_no_stream:
        move.l  v19_aac_buf_ptr,d0
        beq.s   vpv19_free_aac_done
        move.l  d0,a1
        move.l  #VPV19_AAC_BUF_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v19_aac_buf_ptr
        clr.l   v19_aac_buf_len
        clr.l   v19_aac_buf_cur
vpv19_free_aac_done:
        movem.l (sp)+,d0-d2/a1/a6
        rts

; Open MintAMP's AAC decoder on the real ADTS buffer generated from the MKV.
vpv19_open_module:
        movem.l d2-d7/a2-a6,-(sp)
        move.l  v19_aac_buf_ptr,d0
        move.l  d0,vpv18_stream_cur
        lea     vpv18_stream_info,a0
        moveq   #2,d0
vpv19_open_clear:
        clr.l   (a0)+
        dbra    d0,vpv19_open_clear
        move.l  vpv18_ops,a0
        move.l  DECOPS_OPEN(a0),a0
        pea     vpv18_stream_info
        clr.l   -(sp)
        pea     vpv19_seek_cb
        pea     vpv19_read_cb
        jsr     (a0)
        lea     16(sp),sp
        move.l  d0,vpv18_dec_handle
        beq.s   vpv19_open_fail
        lea     msg_v19_open_ok,a1
        move.l  #msg_v19_open_ok_end-msg_v19_open_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv19_open_done
vpv19_open_fail:
        lea     msg_v19_open_fail,a1
        move.l  #msg_v19_open_fail_end-msg_v19_open_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv19_open_done:
        movem.l (sp)+,d2-d7/a2-a6
        rts


; ====================================================================
; BerryMP314 - rolling AAC/ADTS source reader + container PTS capture
; ====================================================================
; This reader is deliberately independent from V10P's video reader.  It opens
; the same MKV a second time, owns a separate 64-KiB source window, and keeps
; only a 128-KiB rolling ADTS window for Helix.  Movie duration therefore no
; longer determines audio memory use.

; Close the independent audio file and reset parser state, but keep allocations.
vpv43_audio_reader_close:
        movem.l d0-d2/a0-a1/a6,-(sp)
        move.l  vpv43_a_file_handle,d0
        beq.s   vpv43_arc_no_file
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   vpv43_a_file_handle
vpv43_arc_no_file:
        clr.l   vpv43_a_io_len
        clr.l   vpv43_a_io_pos
        clr.l   vpv43_a_abs_pos
        clr.l   vpv43_a_reader_eof
        clr.l   vpv43_a_reader_error
        clr.l   vpv43_a_segment_end
        clr.l   vpv43_a_cluster_active
        clr.l   vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
        clr.l   vpv43_a_cluster_timecode
        clr.l   vpv43_a_payload_len
        clr.l   vpv43_a_current_pts_ticks
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

; Reopen the same MKV from byte zero for the independent audio walker.
vpv43_audio_reader_reopen:
        movem.l d1-d3/a0/a6,-(sp)
        jsr     vpv43_audio_reader_close
        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   vpv43_arr_fail
        move.l  d0,vpv43_a_file_handle
        moveq   #0,d0
        bra.s   vpv43_arr_done
vpv43_arr_fail:
        moveq   #1,d0
vpv43_arr_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; BerryMP314: skip a leading ID3v2 tag before filling the raw MP3 window.
; This is required for files whose embedded APIC/cover image is larger than
; the 128-KiB rolling buffer. D0=0 success, D0=1 I/O/invalid-tag failure.
; On success the file position is either 0 (no ID3v2) or the first byte after
; the complete ID3v2 tag. The syncsafe tag size excludes the 10-byte header;
; ID3v2.4 footer flag adds another 10 bytes.
vpv306_skip_id3v2:
        movem.l d1-d7/a0-a2/a6,-(sp)
        clr.l   vpv306_id3_skip_bytes
        move.l  vpv43_a_file_handle,d1
        beq.w   vpv306_id3_fail

        lea     vpv306_id3_header,a0
        move.l  a0,d2
        moveq   #10,d3
        move.l  a5,a6
        jsr     Read(a6)
        tst.l   d0
        bmi.w   vpv306_id3_fail
        cmpi.l  #10,d0
        bne.w   vpv306_id3_rewind

        lea     vpv306_id3_header,a0
        cmpi.b  #$49,(a0)              ; 'I'
        bne.w   vpv306_id3_rewind
        cmpi.b  #$44,1(a0)             ; 'D'
        bne.w   vpv306_id3_rewind
        cmpi.b  #$33,2(a0)             ; '3'
        bne.w   vpv306_id3_rewind

        ; ID3v2 size bytes are syncsafe: every high bit must be zero.
        moveq   #0,d4
        move.b  6(a0),d4
        btst    #7,d4
        bne.w   vpv306_id3_fail
        lsl.l   #7,d4
        moveq   #0,d5
        move.b  7(a0),d5
        btst    #7,d5
        bne.w   vpv306_id3_fail
        or.l    d5,d4
        lsl.l   #7,d4
        moveq   #0,d5
        move.b  8(a0),d5
        btst    #7,d5
        bne.w   vpv306_id3_fail
        or.l    d5,d4
        lsl.l   #7,d4
        moveq   #0,d5
        move.b  9(a0),d5
        btst    #7,d5
        bne.w   vpv306_id3_fail
        or.l    d5,d4
        addq.l  #8,d4
        addq.l  #2,d4                 ; +10-byte ID3 header

        ; ID3v2.4 may carry a 10-byte footer (flag bit 4).
        moveq   #0,d5
        move.b  5(a0),d5
        btst    #4,d5
        beq.s   vpv306_id3_size_ready
        addq.l  #8,d4
        addq.l  #2,d4
vpv306_id3_size_ready:
        ; Seek uses a signed 32-bit offset. Reject absurd/corrupt tag sizes.
        tst.l   d4
        bmi.w   vpv306_id3_fail
        move.l  d4,d2
        move.l  vpv43_a_file_handle,d1
        move.l  #OFFSET_BEGINNING,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        beq.w   vpv306_id3_fail
        move.l  d4,vpv306_id3_skip_bytes
        moveq   #0,d0
        bra.s   vpv306_id3_done

vpv306_id3_rewind:
        moveq   #0,d2
        move.l  vpv43_a_file_handle,d1
        move.l  #OFFSET_BEGINNING,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        beq.s   vpv306_id3_fail
        moveq   #0,d0
        bra.s   vpv306_id3_done
vpv306_id3_fail:
        moveq   #1,d0
vpv306_id3_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; Refill independent 64-KiB source window. D0=0 data, 2 EOF, 1 error.
vpv43_a_refill:
        movem.l d1-d3/a0/a6,-(sp)
        move.l  vpv43_a_file_handle,d1
        beq.s   vpv43_a_refill_fail
        move.l  vpv43_a_io_ptr,d2
        beq.s   vpv43_a_refill_fail
        move.l  #VPV43_AUDIO_IO_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        tst.l   d0
        bmi.s   vpv43_a_refill_fail
        beq.s   vpv43_a_refill_eof
        move.l  d0,vpv43_a_io_len
        clr.l   vpv43_a_io_pos
        moveq   #0,d0
        bra.s   vpv43_a_refill_done
vpv43_a_refill_eof:
        move.l  #1,vpv43_a_reader_eof
        clr.l   vpv43_a_io_len
        clr.l   vpv43_a_io_pos
        moveq   #2,d0
        bra.s   vpv43_a_refill_done
vpv43_a_refill_fail:
        move.l  #1,vpv43_a_reader_error
        moveq   #1,d0
vpv43_a_refill_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; D0=status, D1=byte.
vpv43_a_get_byte:
        movem.l d2-d4/a0,-(sp)
vpv43_a_get_retry:
        move.l  vpv43_a_io_pos,d2
        move.l  vpv43_a_io_len,d3
        cmp.l   d3,d2
        bcs.s   vpv43_a_get_have
        jsr     vpv43_a_refill
        tst.l   d0
        bne.s   vpv43_a_get_done
        bra.s   vpv43_a_get_retry
vpv43_a_get_have:
        move.l  vpv43_a_io_ptr,a0
        adda.l  d2,a0
        moveq   #0,d1
        move.b  (a0),d1
        addq.l  #1,d2
        move.l  d2,vpv43_a_io_pos
        addq.l  #1,vpv43_a_abs_pos
        moveq   #0,d0
vpv43_a_get_done:
        movem.l (sp)+,d2-d4/a0
        rts

; Skip D0 bytes. D0=0 success, 1 failure.
vpv43_a_skip_bytes:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
vpv43_a_skip_loop:
        tst.l   d7
        beq.s   vpv43_a_skip_ok
        move.l  vpv43_a_io_len,d2
        move.l  vpv43_a_io_pos,d1
        sub.l   d1,d2
        bne.s   vpv43_a_skip_have
        jsr     vpv43_a_refill
        tst.l   d0
        bne.s   vpv43_a_skip_fail
        bra.s   vpv43_a_skip_loop
vpv43_a_skip_have:
        move.l  d7,d3
        cmp.l   d2,d3
        bls.s   vpv43_a_skip_n_ready
        move.l  d2,d3
vpv43_a_skip_n_ready:
        add.l   d3,vpv43_a_io_pos
        add.l   d3,vpv43_a_abs_pos
        sub.l   d3,d7
        bra.s   vpv43_a_skip_loop
vpv43_a_skip_ok:
        moveq   #0,d0
        bra.s   vpv43_a_skip_done
vpv43_a_skip_fail:
        moveq   #1,d0
vpv43_a_skip_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; EBML ID: D0=status, D1=ID, D2=encoded bytes.
vpv43_a_read_id:
        movem.l d3-d7/a0,-(sp)
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_read_id_done
        move.l  d1,d3
        moveq   #1,d4
        btst    #7,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #2,d4
        btst    #6,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #3,d4
        btst    #5,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #4,d4
        btst    #4,d3
        bne.s   vpv43_a_id_len_ready
        moveq   #1,d0
        bra.s   vpv43_a_read_id_done
vpv43_a_id_len_ready:
        move.l  d3,d5
        move.l  d4,d6
        subq.l  #1,d6
        beq.s   vpv43_a_id_success
vpv43_a_id_more:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_read_id_fail
        lsl.l   #8,d5
        or.l    d1,d5
        subq.l  #1,d6
        bne.s   vpv43_a_id_more
vpv43_a_id_success:
        move.l  d5,d1
        move.l  d4,d2
        moveq   #0,d0
        bra.s   vpv43_a_read_id_done
vpv43_a_read_id_fail:
        moveq   #1,d0
vpv43_a_read_id_done:
        movem.l (sp)+,d3-d7/a0
        rts

; EBML size/VINT. D0=status, D1=value (FFFFFFFF unknown), D2=len.
vpv43_a_read_size:
        movem.l d3-d7/a0-a3,-(sp)
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_size_done
        lea     vpv43_a_vint_tmp,a2
        move.b  d1,(a2)
        move.l  d1,d3
        move.l  #$00000080,d4
        moveq   #1,d5
vpv43_a_size_find_marker:
        move.l  d3,d6
        and.l   d4,d6
        bne.s   vpv43_a_size_marker_found
        lsr.l   #1,d4
        addq.l  #1,d5
        cmpi.l  #9,d5
        bcs.s   vpv43_a_size_find_marker
        moveq   #1,d0
        bra.w   vpv43_a_size_done
vpv43_a_size_marker_found:
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   vpv43_a_size_all_read
        lea     1(a2),a3
vpv43_a_size_read_more:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_size_fail
        move.b  d1,(a3)+
        subq.l  #1,d7
        bne.s   vpv43_a_size_read_more
vpv43_a_size_all_read:
        move.l  d4,d6
        subq.l  #1,d6
        moveq   #0,d3
        move.b  (a2),d3
        and.l   d6,d3
        cmp.l   d6,d3
        bne.s   vpv43_a_size_not_unknown
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   vpv43_a_size_unknown
        lea     1(a2),a3
vpv43_a_size_unknown_loop:
        cmpi.b  #$FF,(a3)+
        bne.s   vpv43_a_size_not_unknown
        subq.l  #1,d7
        bne.s   vpv43_a_size_unknown_loop
vpv43_a_size_unknown:
        move.l  #$FFFFFFFF,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.w   vpv43_a_size_done
vpv43_a_size_not_unknown:
        cmpi.l  #4,d5
        bls.s   vpv43_a_size_build_short
        tst.l   d3
        bne.w   vpv43_a_size_fail
        move.l  d5,d7
        sub.l   #4,d7
        subq.l  #1,d7
        ble.s   vpv43_a_size_build_last4
        lea     1(a2),a3
vpv43_a_size_high_zero_loop:
        tst.b   (a3)+
        bne.w   vpv43_a_size_fail
        subq.l  #1,d7
        bne.s   vpv43_a_size_high_zero_loop
vpv43_a_size_build_last4:
        move.l  d5,d7
        sub.l   #4,d7
        lea     (a2,d7.l),a3
        moveq   #0,d6
        moveq   #3,d7
vpv43_a_size_last4_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        dbra    d7,vpv43_a_size_last4_loop
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   vpv43_a_size_done
vpv43_a_size_build_short:
        move.l  d3,d6
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   vpv43_a_size_short_done
        lea     1(a2),a3
vpv43_a_size_short_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        subq.l  #1,d7
        bne.s   vpv43_a_size_short_loop
vpv43_a_size_short_done:
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   vpv43_a_size_done
vpv43_a_size_fail:
        moveq   #1,d0
vpv43_a_size_done:
        movem.l (sp)+,d3-d7/a0-a3
        rts

; Unsigned EBML integer payload, <=32 significant bits.
vpv43_a_read_uint:
        movem.l d2-d7,-(sp)
        move.l  d0,d7
        moveq   #0,d6
        tst.l   d7
        beq.s   vpv43_a_uint_ok
        cmpi.l  #8,d7
        bhi.s   vpv43_a_uint_fail
        move.l  d7,d5
        sub.l   #4,d5
        ble.s   vpv43_a_uint_low_part
vpv43_a_uint_high_loop:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_uint_fail
        tst.l   d1
        bne.s   vpv43_a_uint_fail
        subq.l  #1,d5
        bne.s   vpv43_a_uint_high_loop
vpv43_a_uint_low_part:
        move.l  d7,d5
        cmpi.l  #4,d5
        bls.s   vpv43_a_uint_low_count_ok
        moveq   #4,d5
vpv43_a_uint_low_count_ok:
        tst.l   d5
        beq.s   vpv43_a_uint_ok
vpv43_a_uint_low_loop:
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_uint_fail
        lsl.l   #8,d6
        or.l    d1,d6
        subq.l  #1,d5
        bne.s   vpv43_a_uint_low_loop
vpv43_a_uint_ok:
        move.l  d6,d1
        moveq   #0,d0
        bra.s   vpv43_a_uint_done
vpv43_a_uint_fail:
        moveq   #1,d0
vpv43_a_uint_done:
        movem.l (sp)+,d2-d7
        rts

; Parse one Block/SimpleBlock.  Selected unlaced AAC is left unread.
vpv43_a_begin_audio_block:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        cmpi.l  #4,d7
        bcs.w   vpv43_a_block_fail
        jsr     vpv43_a_read_size
        tst.l   d0
        bne.w   vpv43_a_block_fail
        move.l  d1,d6
        move.l  d2,d5
        move.l  d5,d4
        addq.l  #3,d4
        cmp.l   d7,d4
        bhi.w   vpv43_a_block_fail

        ; signed 16-bit block-relative timecode
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_block_fail
        move.l  d1,d3
        lsl.w   #8,d3
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_block_fail
        or.w    d1,d3
        ext.l   d3
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.w   vpv43_a_block_fail
        move.l  d1,d2
        sub.l   d4,d7

        cmp.l   v19_audio_track_num,d6
        beq.s   vpv43_a_block_selected
        move.l  d7,d0
        jsr     vpv43_a_skip_bytes
        tst.l   d0
        bne.s   vpv43_a_block_fail
        moveq   #3,d0
        bra.s   vpv43_a_block_done
vpv43_a_block_selected:
        move.l  d2,d1
        andi.l  #$00000006,d1
        beq.s   vpv43_a_block_unlaced
        move.l  #1,v19_audio_lacing_seen
        move.l  d7,d0
        jsr     vpv43_a_skip_bytes
        tst.l   d0
        bne.s   vpv43_a_block_fail
        moveq   #3,d0
        bra.s   vpv43_a_block_done
vpv43_a_block_unlaced:
        tst.l   d7
        beq.s   vpv43_a_block_fail
        move.l  d7,vpv43_a_payload_len
        move.l  vpv43_a_cluster_timecode,d1
        add.l   d3,d1
        move.l  d1,vpv43_a_current_pts_ticks
        moveq   #0,d0
        bra.s   vpv43_a_block_done
vpv43_a_block_fail:
        moveq   #1,d0
vpv43_a_block_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Find next selected AAC block in the independent Matroska stream.
; D0=0 found, 2 EOF, 1 malformed/unsupported.
vpv43_a_find_audio_block:
        movem.l d1-d7/a0-a3,-(sp)
vpv43_a_find_loop:
        move.l  vpv43_a_blockgroup_end,d1
        beq.s   vpv43_a_find_check_cluster
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv43_a_find_check_cluster
        move.l  vpv43_a_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv43_a_find_check_cluster
        clr.l   vpv43_a_blockgroup_end
vpv43_a_find_check_cluster:
        move.l  vpv43_a_cluster_end,d1
        beq.s   vpv43_a_find_header
        cmpi.l  #$FFFFFFFF,d1
        beq.s   vpv43_a_find_header
        move.l  vpv43_a_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   vpv43_a_find_header
        clr.l   vpv43_a_cluster_active
        clr.l   vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
vpv43_a_find_header:
        jsr     vpv43_a_read_id
        cmpi.l  #2,d0
        beq.w   vpv43_a_find_eof
        tst.l   d0
        bne.w   vpv43_a_find_fail
        move.l  d1,d5
        jsr     vpv43_a_read_size
        tst.l   d0
        bne.w   vpv43_a_find_fail
        move.l  d1,d6
        move.l  #$FFFFFFFF,d7
        cmpi.l  #$FFFFFFFF,d6
        beq.s   vpv43_a_find_end_ready
        move.l  vpv43_a_abs_pos,d7
        add.l   d6,d7
        bcs.w   vpv43_a_find_fail
vpv43_a_find_end_ready:
        cmpi.l  #$1A45DFA3,d5
        beq.w   vpv43_a_find_skip
        cmpi.l  #$18538067,d5
        beq.w   vpv43_a_find_segment
        cmpi.l  #$1F43B675,d5
        beq.w   vpv43_a_find_cluster
        cmpi.l  #$114D9B74,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1549A966,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1654AE6B,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1C53BB6B,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1254C367,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1941A469,d5
        beq.s   vpv43_a_find_segment_meta
        cmpi.l  #$1043A770,d5
        beq.s   vpv43_a_find_segment_meta
        bra.s   vpv43_a_find_cluster_children
vpv43_a_find_segment_meta:
        move.l  vpv43_a_cluster_end,d1
        cmpi.l  #$FFFFFFFF,d1
        bne.w   vpv43_a_find_skip
        clr.l   vpv43_a_cluster_active
        clr.l   vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
        bra.w   vpv43_a_find_skip
vpv43_a_find_cluster_children:
        tst.l   vpv43_a_cluster_active
        beq.w   vpv43_a_find_skip
        cmpi.l  #$000000E7,d5
        beq.w   vpv43_a_find_timecode
        cmpi.l  #$000000A0,d5
        beq.w   vpv43_a_find_blockgroup
        cmpi.l  #$000000A3,d5
        beq.w   vpv43_a_find_block
        cmpi.l  #$000000A1,d5
        bne.w   vpv43_a_find_skip
        tst.l   vpv43_a_blockgroup_end
        beq.w   vpv43_a_find_skip
        bra.w   vpv43_a_find_block
vpv43_a_find_segment:
        move.l  d7,vpv43_a_segment_end
        bra.w   vpv43_a_find_loop
vpv43_a_find_cluster:
        move.l  #1,vpv43_a_cluster_active
        move.l  d7,vpv43_a_cluster_end
        clr.l   vpv43_a_blockgroup_end
        clr.l   vpv43_a_cluster_timecode
        bra.w   vpv43_a_find_loop
vpv43_a_find_blockgroup:
        move.l  d7,vpv43_a_blockgroup_end
        bra.w   vpv43_a_find_loop
vpv43_a_find_timecode:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv43_a_find_fail
        move.l  d6,d0
        jsr     vpv43_a_read_uint
        tst.l   d0
        bne.w   vpv43_a_find_fail
        move.l  d1,vpv43_a_cluster_timecode
        bra.w   vpv43_a_find_loop
vpv43_a_find_block:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv43_a_find_fail
        move.l  d6,d0
        jsr     vpv43_a_begin_audio_block
        tst.l   d0
        beq.s   vpv43_a_find_found
        cmpi.l  #3,d0
        beq.w   vpv43_a_find_loop
        bra.w   vpv43_a_find_fail
vpv43_a_find_skip:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   vpv43_a_find_fail
        move.l  d6,d0
        jsr     vpv43_a_skip_bytes
        tst.l   d0
        bne.w   vpv43_a_find_fail
        bra.w   vpv43_a_find_loop
vpv43_a_find_found:
        moveq   #0,d0
        bra.s   vpv43_a_find_done
vpv43_a_find_eof:
        moveq   #2,d0
        bra.s   vpv43_a_find_done
vpv43_a_find_fail:
        moveq   #1,d0
vpv43_a_find_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Copy current selected AAC payload into v19 rolling ADTS buffer.
vpv43_a_copy_payload:
        movem.l d1-d7/a0,-(sp)
        move.l  d0,d7
        move.l  v19_aac_buf_cur,a0
vpv43_a_copy_loop:
        tst.l   d7
        beq.s   vpv43_a_copy_ok
        jsr     vpv43_a_get_byte
        tst.l   d0
        bne.s   vpv43_a_copy_fail
        move.b  d1,(a0)+
        addq.l  #1,v19_aac_buf_len
        subq.l  #1,d7
        bra.s   vpv43_a_copy_loop
vpv43_a_copy_ok:
        move.l  a0,v19_aac_buf_cur
        moveq   #0,d0
        bra.s   vpv43_a_copy_done
vpv43_a_copy_fail:
        moveq   #1,d0
vpv43_a_copy_done:
        movem.l (sp)+,d1-d7/a0
        rts

; Fill one rolling ADTS window. D0=0 bytes available, 2 true MP3 EOF, 1 fail.
vpv43_fill_adts_buffer:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   v19_aac_buf_len
        move.l  v19_aac_buf_ptr,d0
        beq.w   vpv43_fill_fail
        move.l  d0,v19_aac_buf_cur
        move.l  d0,vpv18_stream_cur
        clr.l   v19_aac_frame_count
        moveq   #0,d7
vpv43_fill_loop:
        ; Leave room for the largest legal ADTS frame before parsing another
        ; block so a selected payload is never stranded half-consumed.
        move.l  v19_aac_buf_len,d0
        cmpi.l  #VPV19_AAC_BUF_SIZE-$00002010,d0
        bcc.w   vpv43_fill_have
        cmpi.l  #VPV43_ADTS_FILL_FRAMES,d7
        bcc.w   vpv43_fill_have
        jsr     vpv43_a_find_audio_block
        tst.l   d0
        beq.s   vpv43_fill_found
        cmpi.l  #2,d0
        beq.s   vpv43_fill_eof
        bra.w   vpv43_fill_fail
vpv43_fill_found:
        tst.l   vpv43_first_audio_pts_found
        bne.s   vpv43_fill_pts_known
        move.l  vpv43_a_current_pts_ticks,d0
        move.l  d0,vpv43_first_audio_pts_ticks
        move.l  #1,vpv43_first_audio_pts_found
vpv43_fill_pts_known:
        move.l  vpv43_a_payload_len,d0
        addq.l  #7,d0
        move.l  v19_aac_buf_len,d1
        add.l   d0,d1
        cmpi.l  #VPV19_AAC_BUF_SIZE,d1
        bhi.w   vpv43_fill_fail
        move.l  vpv43_a_payload_len,d0
        jsr     vpv19_append_adts_header
        tst.l   d0
        bne.w   vpv43_fill_fail
        move.l  vpv43_a_payload_len,d0
        jsr     vpv43_a_copy_payload
        tst.l   d0
        bne.w   vpv43_fill_fail
        addq.l  #1,d7
        addq.l  #1,v19_aac_frame_count
        addq.l  #1,vpv43_a_total_frames
        bra.w   vpv43_fill_loop
vpv43_fill_eof:
        move.l  #1,vpv43_a_source_eof
        tst.l   v19_aac_buf_len
        bne.s   vpv43_fill_have
        moveq   #2,d0
        bra.s   vpv43_fill_done
vpv43_fill_have:
        tst.l   v19_aac_buf_len
        beq.s   vpv43_fill_fail
        move.l  v19_aac_buf_ptr,vpv18_stream_cur
        moveq   #0,d0
        bra.s   vpv43_fill_done
vpv43_fill_fail:
        move.l  #1,vpv43_a_reader_error
        moveq   #1,d0
vpv43_fill_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Allocate bounded streaming state, open independent reader, fill first ADTS window.
vpv43_audio_stream_prepare:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv43_streaming_audio
        clr.l   vpv43_a_source_eof
        clr.l   vpv43_a_total_frames
        clr.l   vpv43_a_reader_error
        clr.l   vpv43_first_audio_pts_ticks
        move.l  #1,vpv43_first_audio_pts_found
        clr.l   vpv43_audio_next_pts_ticks
        clr.l   vpv43_audio_pts_remainder
        clr.l   vpv43_last_sent_samples
        clr.l   vpv43_pts_mode
        clr.l   vpv45_topup_count
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        clr.l   vpv45_prefetch_count
        clr.l   vpv45_prefetch_miss_count
        clr.l   vpv45_prefetch_first_logged
        clr.l   v19_aac_frame_count
        clr.l   v19_aac_buf_len
        clr.l   vpv43_a_io_ptr

        move.l  #$00000010,mhi3_front_stage   ; about to allocate 128 KiB rolling window
        move.l  a4,a6
        move.l  #VPV19_AAC_BUF_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv43_mp3_prepare_fail_alloc
        move.l  d0,mhi3_front_alloc_ptr
        move.l  d0,v19_aac_buf_ptr
        move.l  d0,v19_aac_buf_cur
        move.l  d0,vpv18_stream_cur

        move.l  #$00000020,mhi3_front_stage   ; allocation OK, snapshot queue before read
        jsr     mhi3_front_snapshot
        move.l  v19_aac_buf_ptr,d2
        move.l  #VPV19_AAC_BUF_SIZE,d3
        jsr     mhi3_stream_read
        move.l  d0,mhi3_front_read_ret
        tst.l   d0
        beq.s   vpv43_mp3_prepare_fail_read
        move.l  #$00000030,mhi3_front_stage   ; MHI bytes copied
        ; MP314 compatibility: CPU1 sees the first MPEG frame at offset zero.
        jsr     mhi3_strip_initial_id3v2
        move.l  d0,mhi3_front_id3_ret
        tst.l   d0
        beq.s   vpv43_mp3_prepare_fail_id3
        move.l  #$00000040,mhi3_front_stage   ; valid post-ID3 MP3 bytes ready
        move.l  d0,v19_aac_buf_len
        move.l  v19_aac_buf_ptr,d1
        move.l  d1,vpv18_stream_cur
        add.l   d0,d1
        move.l  d1,v19_aac_buf_cur
        move.l  #1,vpv43_streaming_audio
        move.l  #$00000050,mhi3_front_stage   ; rolling source prepared
        moveq   #0,d0
        bra.s   vpv43_mp3_prepare_done
vpv43_mp3_prepare_fail_read:
        move.l  #$000000E2,mhi3_front_stage
        bra.s   vpv43_mp3_prepare_fail_cleanup
vpv43_mp3_prepare_fail_id3:
        move.l  #$000000E3,mhi3_front_stage
vpv43_mp3_prepare_fail_cleanup:
        jsr     vpv43_audio_stream_cleanup
        bra.s   vpv43_mp3_prepare_fail
vpv43_mp3_prepare_fail_alloc:
        move.l  #$000000E1,mhi3_front_stage
vpv43_mp3_prepare_fail:
        moveq   #1,d0
vpv43_mp3_prepare_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Full independent streaming cleanup. Safe to call repeatedly.
vpv43_audio_stream_cleanup:
        movem.l d0-d2/a0-a1/a6,-(sp)
        bsr     mhi3_stream_return_current
        clr.l   vpv43_streaming_audio
        clr.l   vpv43_a_source_eof
        clr.l   vpv43_a_reader_error
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts


; BerryMP306: top up the rolling ADTS source OUTSIDE the Helix callback.
; VPv43 performed DOS Read()/Matroska parsing recursively from vpv19_read_cb
; while DECOPS_DECODE was active.  Real hardware crashed in that new path.
; The callback is memory-only again; unread ADTS is compacted here and more
; complete AAC blocks are appended before the next decoder call.
; D0=0 OK (including source EOF with buffered bytes), D0=1 parser/I/O failure.
vpv45_topup_adts_buffer:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv43_streaming_audio
        beq.w   vpv45_mp3_topup_ok

        move.l  v19_aac_buf_ptr,d6
        beq.w   vpv45_mp3_topup_fail
        move.l  d6,d5
        add.l   v19_aac_buf_len,d5
        move.l  vpv18_stream_cur,d4
        cmp.l   d6,d4
        bcs.w   vpv45_mp3_topup_fail
        cmp.l   d5,d4
        bhi.w   vpv45_mp3_topup_fail
        sub.l   d4,d5

        cmpi.l  #VPV44_ADTS_TOPUP_THRESHOLD,d5
        bcc.w   vpv45_mp3_topup_ok
        tst.l   vpv43_a_source_eof
        bne.w   vpv45_mp3_topup_ok

        move.l  d4,a1
        move.l  d6,a0
        move.l  d5,d3
        beq.s   vpv45_mp3_compact_done
        cmp.l   a0,a1
        beq.s   vpv45_mp3_compact_done
vpv45_mp3_compact_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   vpv45_mp3_compact_loop
vpv45_mp3_compact_done:
        move.l  d5,v19_aac_buf_len
        move.l  v19_aac_buf_ptr,d0
        move.l  d0,vpv18_stream_cur
        add.l   d5,d0
        move.l  d0,v19_aac_buf_cur

        move.l  #VPV19_AAC_BUF_SIZE,d3
        sub.l   d5,d3
        beq.s   vpv45_mp3_topup_have
        move.l  v19_aac_buf_cur,d2
        jsr     mhi3_stream_read
        tst.l   d0
        beq.s   vpv45_mp3_topup_eof
        add.l   d0,v19_aac_buf_len
        add.l   d0,v19_aac_buf_cur
        bra.s   vpv45_mp3_topup_have
vpv45_mp3_topup_eof:
        move.l  #1,vpv43_a_source_eof
        ; A short test stream may still carry a final ID3v1 TAG. Trim only at
        ; true MHI queue end, exactly like the MP314 physical-EOF fix.
        move.l  v19_aac_buf_len,d0
        cmpi.l  #128,d0
        bcs.s   vpv314_no_id3v1_tail
        move.l  v19_aac_buf_ptr,a0
        adda.l  d0,a0
        suba.l  #128,a0
        cmpi.b  #$54,(a0)
        bne.s   vpv314_no_id3v1_tail
        cmpi.b  #$41,1(a0)
        bne.s   vpv314_no_id3v1_tail
        cmpi.b  #$47,2(a0)
        bne.s   vpv314_no_id3v1_tail
        sub.l   #128,v19_aac_buf_len
        sub.l   #128,v19_aac_buf_cur
        addq.l  #1,vpv314_id3v1_trim_count
vpv314_no_id3v1_tail:
vpv45_mp3_topup_have:
        addq.l  #1,vpv45_topup_count
vpv45_mp3_topup_ok:
        moveq   #0,d0
        bra.s   vpv45_mp3_topup_done
vpv45_mp3_topup_fail:
        move.l  #1,vpv43_a_reader_error
        moveq   #1,d0
vpv45_mp3_topup_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Decoder callbacks over ADTS. BerryMP314 can refill this window indefinitely.
vpv19_read_cb:
        move.l  12(sp),d0              ; requested byte count
        move.l  8(sp),a0               ; destination
        tst.l   vpv43_streaming_audio
        beq.w   vpv19_read_legacy

        movem.l d2-d7/a2-a3,-(sp)
        move.l  d0,d7
        move.l  a0,a3
        moveq   #0,d6                  ; bytes returned this call
vpv43_read_loop:
        tst.l   d7
        beq.w   vpv43_read_done
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        move.l  vpv18_stream_cur,d2
        sub.l   d2,d1                  ; available bytes
        bne.s   vpv43_read_have

        ; BerryMP314: callback is memory-only. Never call DOS/Matroska parsing
        ; recursively from inside Helix DECOPS_DECODE. The outer scheduler
        ; tops this buffer up before each decode call.
        bra.w   vpv43_read_done

vpv43_read_have:
        move.l  d7,d5
        cmp.l   d1,d5
        bls.s   vpv43_read_n_ready
        move.l  d1,d5
vpv43_read_n_ready:
        move.l  vpv18_stream_cur,a1
        move.l  d5,d4
        beq.s   vpv43_read_after_copy
vpv43_read_copy:
        move.b  (a1)+,(a3)+
        subq.l  #1,d4
        bne.s   vpv43_read_copy
vpv43_read_after_copy:
        move.l  a1,vpv18_stream_cur
        sub.l   d5,d7
        add.l   d5,d6
        bra.w   vpv43_read_loop
vpv43_read_done:
        move.l  d6,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

vpv19_read_legacy:
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        sub.l   vpv18_stream_cur,d1
        cmp.l   d1,d0
        bls.s   vpv19_read_count_ok
        move.l  d1,d0
vpv19_read_count_ok:
        tst.l   d0
        beq.s   vpv19_read_done
        move.l  d0,d1
        move.l  vpv18_stream_cur,a1
        move.l  8(sp),a0
vpv19_read_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv19_read_loop
        move.l  a1,vpv18_stream_cur
vpv19_read_done:
        rts

vpv19_seek_cb:
        move.l  12(sp),d1              ; origin
        tst.l   vpv43_streaming_audio
        beq.w   vpv19_seek_legacy

        ; Streaming AAC is intentionally forward-only. Helix may rewind to byte
        ; zero while opening; support exactly that operation plus CUR+0.
        cmpi.l  #0,d1
        beq.s   vpv43_seek_set
        cmpi.l  #1,d1
        beq.s   vpv43_seek_cur
        bra.w   vpv19_seek_fail
vpv43_seek_set:
        tst.l   8(sp)
        bne.w   vpv19_seek_fail
        movem.l d2-d7/a0-a3/a6,-(sp)
        clr.l   vpv43_a_source_eof
        clr.l   vpv43_a_total_frames
        clr.l   vpv43_first_audio_pts_found
        clr.l   vpv43_first_audio_pts_ticks
        jsr     vpv43_audio_reader_reopen
        tst.l   d0
        bne.s   vpv43_seek_set_fail
        jsr     vpv43_fill_adts_buffer
        tst.l   d0
        bne.s   vpv43_seek_set_fail
        moveq   #0,d0
        bra.s   vpv43_seek_set_done
vpv43_seek_set_fail:
        moveq   #-1,d0
vpv43_seek_set_done:
        movem.l (sp)+,d2-d7/a0-a3/a6
        rts
vpv43_seek_cur:
        tst.l   8(sp)
        bne.w   vpv19_seek_fail
        moveq   #0,d0
        rts

vpv19_seek_legacy:
        cmpi.l  #0,d1
        beq.s   vpv19_seek_set
        cmpi.l  #1,d1
        beq.s   vpv19_seek_cur
        cmpi.l  #2,d1
        beq.s   vpv19_seek_end
        bra.s   vpv19_seek_fail
vpv19_seek_set:
        move.l  v19_aac_buf_ptr,a0
        bra.s   vpv19_seek_add
vpv19_seek_cur:
        move.l  vpv18_stream_cur,a0
        bra.s   vpv19_seek_add
vpv19_seek_end:
        move.l  v19_aac_buf_ptr,a0
        adda.l  v19_aac_buf_len,a0
vpv19_seek_add:
        adda.l  8(sp),a0
        move.l  a0,d0
        move.l  v19_aac_buf_ptr,d1
        cmp.l   d1,d0
        bcs.s   vpv19_seek_fail
        add.l   v19_aac_buf_len,d1
        cmp.l   d1,d0
        bhi.s   vpv19_seek_fail
        move.l  a0,vpv18_stream_cur
        moveq   #0,d0
        rts
vpv19_seek_fail:
        moveq   #-1,d0
        rts

; Configure ril.audio_render to the actual PCM format returned by Helix.
; v19 supports mono/stereo 16-bit and uses the decoder's real sample rate.
vpv19_configure_audio_render:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  vpv18_stream_info+DECSTREAM_RATE,d0
        move.l  d0,v19_pcm_rate
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_CHANNELS,d0
        move.l  d0,v19_pcm_channels
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_BITS,d0
        move.l  d0,v19_pcm_bits
        cmpi.l  #16,d0
        bne.w   vpv19_config_fail
        move.l  v19_pcm_channels,d0
        cmpi.l  #1,d0
        bcs.w   vpv19_config_fail
        cmpi.l  #2,d0
        bhi.w   vpv19_config_fail
        add.l   d0,d0
        move.l  d0,v19_pcm_blockalign
        move.l  v19_pcm_channels,d1
        lsl.l   #4,d1                  ; channels * 16 bits/sample
        move.l  v19_pcm_rate,d0
        mulu.w  d1,d0                  ; <= 96 kHz * 32 = 3.072 Mbit/s
        move.l  d0,v19_pcm_bitrate

        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  port_last_handle,vpv01_audio_control
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        move.l  #MMAL_ES_AUDIO,port_fmt_type
        move.l  #MMAL_ENCODING_PCM_SIGNED_LE,port_fmt_encoding
        clr.l   port_fmt_variant
        move.l  v19_pcm_bitrate,d0
        move.l  d0,port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v19_pcm_channels,d0
        move.l  d0,port_video_width
        move.l  v19_pcm_rate,d0
        move.l  d0,port_video_height
        move.l  v19_pcm_bits,d0
        move.l  d0,port_crop_x
        move.l  v19_pcm_blockalign,d0
        move.l  d0,port_crop_y
        clr.l   port_crop_width
        clr.l   port_crop_height
        clr.l   port_fps_num
        clr.l   port_fps_den
        clr.l   port_par_num
        clr.l   port_par_den
        clr.l   port_color_space

        move.l  port_buf_num_min,d0
        tst.l   d0
        bne.s   vpv19_cfg_num_ok
        moveq   #1,d0
vpv19_cfg_num_ok:
        ; BerryMP314: renderer must accept at least two queued PCM buffers so the
        ; next block can already be resident while the current one is playing.
        cmpi.l  #2,d0
        bcc.s   vpv47_cfg_num_ok
        moveq   #2,d0
vpv47_cfg_num_ok:
        move.l  d0,port_buf_num
        ; VPv59: VPv49 decoded batches stay 64 KiB internally, but audio_render
        ; sees only 16-KiB chunks.  Keep the proven two renderer slots; smaller
        ; chunks reduce scheduler/PTS granularity from ~372 ms to ~93 ms at
        ; 44.1-kHz stereo without touching the video loop.
        move.l  #VPV53_AUDIO_CHUNK_BYTES,d0
vpv21_cfg_have_size:
        cmp.l   port_buf_size_min,d0
        bcc.s   vpv19_cfg_size_ok
        move.l  port_buf_size_min,d0
vpv19_cfg_size_ok:
        cmp.l   #VPV21_PCM_MAX_BYTES,d0
        bhi.w   vpv19_config_fail
        move.l  d0,port_buf_size

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_set_input
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  vpv01_audio_input,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        beq.s   vpv19_dest_ok
        move.l  vpv01_audio_control,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        bne.w   vpv19_config_fail
vpv19_dest_ok:
        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv19_config_fail
        tst.l   v12f_local_port
        bne.s   vpv19_enable_second
        jsr     port_enable_current
        bra.s   vpv19_enable_done
vpv19_enable_second:
        move.l  vpv01_audio_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
vpv19_enable_done:
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  vpv01_audio_handle,component_handle
        jsr     component_enable_worker
        tst.l   d0
        bne.w   vpv19_config_fail
        move.l  #1,vpv01_component_enabled
        lea     msg_v19_render_ok,a1
        move.l  #msg_v19_render_ok_end-msg_v19_render_ok,d3
        jsr     print_force
        moveq   #0,d0
        bra.s   vpv19_config_done
vpv19_config_fail:
        lea     msg_v19_render_fail,a1
        move.l  #msg_v19_render_fail_end-msg_v19_render_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv19_config_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

vpv19_audio_test:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v19_test_status
        clr.l   vpv01_test_status
        clr.l   vpv18_seg
        clr.l   vpv18_ops
        clr.l   vpv18_dec_handle
        clr.l   vpv18_pcm_blocks
        clr.l   vpv18_total_samples

        lea     msg_v19_header,a1
        move.l  #msg_v19_header_end-msg_v19_header,d3
        jsr     print_force
        jsr     vpv18_load_module
        tst.l   d0
        bne.w   vpv19_test_fail
        jsr     vpv19_open_module
        tst.l   d0
        bne.w   vpv19_test_fail

        lea     msg_v19_dec_fmt,a1
        move.l  #msg_v19_dec_fmt_end-msg_v19_dec_fmt,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_stream_info+DECSTREAM_RATE,d0
        jsr     print_hex32
        lea     msg_vpv18_info_ch,a1
        move.l  #msg_vpv18_info_ch_end-msg_vpv18_info_ch,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_CHANNELS,d0
        jsr     print_hex32
        lea     msg_vpv18_info_bits,a1
        move.l  #msg_vpv18_info_bits_end-msg_vpv18_info_bits,d3
        jsr     print_force
        moveq   #0,d0
        move.w  vpv18_stream_info+DECSTREAM_BITS,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print

        lea     msg_vpv01_mmal_ready,a1
        move.l  #msg_vpv01_mmal_ready_end-msg_vpv01_mmal_ready,d3
        jsr     print_force
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv19_test_fail
        jsr     vpv19_configure_audio_render
        tst.l   d0
        bne.w   vpv19_test_fail
        jsr     vpv01_prepare_tone
        tst.l   d0
        bne.w   vpv19_test_fail

        lea     msg_v19_play,a1
        move.l  #msg_v19_play_end-msg_v19_play,d3
        jsr     print_force
vpv19_decode_loop:
        jsr     vpv18_decode_block
        tst.l   d0
        bmi.w   vpv19_decode_error
        beq.w   vpv19_decode_eof
        move.l  d0,vpv18_pcm_samples
        add.l   d0,vpv18_total_samples
        move.l  d0,d1
        move.l  v19_pcm_channels,d2
        mulu.w  d2,d1
        lsl.l   #1,d1
        move.l  d1,vpv18_pcm_bytes
        cmpi.l  #VPV01_TONE_BYTES,d1
        bhi.w   vpv19_decode_error
        jsr     vpv18_swap_pcm16
        jsr     vpv18_make_pagelist
        tst.l   d0
        bne.w   vpv19_decode_error
        jsr     vpv18_send_pcm_block
        tst.l   d0
        bne.w   vpv19_decode_error
        jsr     vpv18_wait_pcm_block
        tst.l   d0
        bne.w   vpv19_decode_error
        addq.l  #1,vpv18_pcm_blocks
        bra.w   vpv19_decode_loop
vpv19_decode_eof:
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #20,d1
        jsr     Delay(a6)
        jsr     dma_post_all
        lea     msg_v19_success,a1
        move.l  #msg_v19_success_end-msg_v19_success,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv18_pcm_blocks,d0
        jsr     print_hex32
        lea     msg_vpv18_success_samples,a1
        move.l  #msg_vpv18_success_samples_end-msg_vpv18_success_samples,d3
        jsr     print_force
        move.l  vpv18_total_samples,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        bra.s   vpv19_cleanup
vpv19_decode_error:
        lea     msg_v19_decode_fail,a1
        move.l  #msg_v19_decode_fail_end-msg_v19_decode_fail,d3
        jsr     print_force
vpv19_test_fail:
        move.l  #1,v19_test_status
        move.l  #1,vpv01_test_status
vpv19_cleanup:
        jsr     vpv18_close_module
        jsr     vpv01_cleanup
        jsr     vpv19_free_aac_buffer
        tst.l   vpv01_test_status
        beq.s   vpv19_cleanup_ok
        move.l  #1,v19_test_status
vpv19_cleanup_ok:
        tst.l   v19_test_status
        bne.s   vpv19_done
        lea     msg_v19_done,a1
        move.l  #msg_v19_done_end-msg_v19_done,d3
        jsr     print_force
vpv19_done:
        move.l  v19_test_status,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; ====================================================================
; VPv36 - AUDIO INPUT0 PORT_INFO_SET ISOLATION ON BOTH START PATHS
;
; Stage strategy:
;   1) keep the VPv21T/VPv21U proven AAC predecode + retained PCM path,
;   2) build/enable the hardware-proven HDMI_v41L H264/ISP graph,
;   3) create ril.audio_render on the already-open MMAL service (VPv21U proven),
;   4) query ONLY audio_render CONTROL port 0 via MMAL_PORT_INFO_GET,
;   5) restore the live video globals and run the complete video to EOS.
;
; No audio INPUT query, no PORT_INFO_SET, no audio enable and no PCM transfer.
; Purpose: isolate the first synchronous audio port transaction from all later
; audio configuration work.
; ====================================================================
VPV21_PCM_MAX_BYTES    equ $00010000      ; BerryMP314: full proven 64-KiB audio_render input buffer
VPV21_PCM_PAGE_OFS     equ $00040000      ; same geometry as proven V41L input slot
VPV21_PCM_DMA_SPAN     equ $00041000      ; same proven 256-KiB data + pagelist span
VPV21_PCM_ALLOC_SIZE   equ $00085000      ; BerryMP314: two 0x42000-aligned audio DMA slots + alignment slack
VPV47_AUDIO_SLOTS        equ 2
VPV47_AUDIO_CONTEXT_BASE equ $A0300100
; VPv59: keep VPv49 video/VCHIQ scheduling intact, but slice each 64-KiB
; FAAD batch into 16-KiB (~93 ms @44.1k stereo) renderer buffers.
VPV53_AUDIO_CHUNK_BYTES  equ $00004000
VPV38_PCM_BLOCKS       equ 1
VPV38_PCM_STORE_BYTES   equ $00010000      ; BerryMP314: one full 64-KiB priming/prefetch PCM block

; VPv48 - BerryFAAD03 / BerryCore CPU1 bridge.
; The external module is the BerryFAAD03 FAAD2 2.11.2 build.
VPV48_FAAD_MODULE_MAX  equ $00010000      ; BerryMP314: real module is 59930 bytes; 64 KiB cap avoids wasting FastRAM
VPV48_FAAD_MODULE_SIZE equ VPV48_FAAD_MODULE_MAX ; compatibility name used by old cleanup geometry
VPV48_FAAD_INPUT_SIZE  equ $00020000      ; 128 KiB aligned staging input
VPV48_FAAD_OUT_SIZE    equ $00011000      ; 256-byte metadata + 64 KiB PCM + guard
VPV48_FAAD_WORK_SIZE   equ $00040000      ; 256 KiB persistent FAAD work/heap/stack
VPV48_FAAD_MAIL_SIZE   equ 128
VPV48_FAAD_MOD_ALLOC   equ VPV48_FAAD_MODULE_SIZE+$1000
VPV48_FAAD_IN_ALLOC    equ VPV48_FAAD_INPUT_SIZE+$1000
VPV48_FAAD_OUT_ALLOC   equ VPV48_FAAD_OUT_SIZE+$1000
VPV48_FAAD_WORK_ALLOC  equ VPV48_FAAD_WORK_SIZE+$1000
VPV48_FAAD_MAIL_ALLOC  equ $00002000
VPV48_SCAN_LOW         equ $08000000
VPV48_SCAN_HIGH        equ $10000000
VPV48_MAGIC0           equ $42393942
VPV48_MAGIC1           equ $59393959
VPV48_CMD_LOAD_MODULE  equ 3
VPV48_CMD_CALL_MODULE  equ 4
VPV48_CMD_UNLOAD_MODULE equ 5
VPV48_MODULE_TYPE_CODEC equ 2
VPV307_MP3_CMD_GET_VERSION equ $00000100
VPV307_MP3_API_VERSION     equ $00010000      ; berry_mp3.module API 1.0
VPV307_MP3_VERSION_MAGIC   equ $4D503356      ; 'MP3V'
VPV48_FAAD_OUT_MARKER  equ $4D503331      ; 'MP31'
VPV48_FAAD_BATCH_STATUS equ 4
VPV48_MAIL_MAX_TICKS   equ 500
VPV56_MAIL_FAST_POLLS  equ 512        ; immediate cache-coherent polls before 1 OS-tick fallback
VPV56_MAIL_SPIN        equ 255        ; short CPU-side wait between PreDMA/PostDMA

        section bss,bss
vpv21_pcm_alloc:          ds.l 1
vpv21_pcm_ptr:            ds.l 1
vpv21_pcm_bus:            ds.l 1
vpv21_pcm_pagelist_ptr:   ds.l 1
vpv21_pcm_pagelist_bus:   ds.l 1
; BerryMP314 second proven-size DMA slot. Both slots are page-aligned inside one allocation.
vpv47_pcm1_ptr:            ds.l 1
vpv47_pcm1_bus:            ds.l 1
vpv47_pcm1_pagelist_ptr:   ds.l 1
vpv47_pcm1_pagelist_bus:   ds.l 1
vpv47_slot_len:            ds.l VPV47_AUDIO_SLOTS
vpv47_slot_samples:        ds.l VPV47_AUDIO_SLOTS
vpv47_slot_state:          ds.l VPV47_AUDIO_SLOTS
vpv47_slot_bulk_done:      ds.l VPV47_AUDIO_SLOTS
vpv47_slot_returned:       ds.l VPV47_AUDIO_SLOTS
vpv47_slot_dma_active:     ds.l VPV47_AUDIO_SLOTS
vpv47_tx_slot:             ds.l 1
vpv47_inflight:            ds.l 1
vpv47_audio_lead_ticks:    ds.l 1
vpv47_double_first_logged: ds.l 1
; VPv59 staging cursor. vpv38_pcm_store always contains one complete FAAD batch.
; A new batch may overwrite it only after every byte of the current batch has
; already been copied into one of the two proven DMA slots.
vpv53_stage_offset:        ds.l 1
vpv53_stage_total:         ds.l 1
vpv53_chunk_count:         ds.l 1
vpv53_batch_adopts:        ds.l 1
vpv21_pcm_total_bytes:    ds.l 1
vpv21_pcm_total_samples:  ds.l 1
vpv21_pcm_write_ptr:      ds.l 1
vpv21_audio_dma_len:      ds.l 1
vpv21_audio_dma_active:   ds.l 1
vpv21_audio_returned:     ds.l 1
vpv21_saved_component:    ds.l 1
vpv21_saved_input:        ds.l 1
vpv21_saved_port_qidx:    ds.l 1
vpv21_saved_port_buf_size: ds.l 1
vpv36_queue_saved_component: ds.l 1
vpv36_queue_saved_input:     ds.l 1
vpv36_queue_saved_qidx:      ds.l 1
vpv36_queue_saved_buf_size:  ds.l 1
vpv23_saved_port_qtype:   ds.l 1
vpv21_audio_port_buf_size: ds.l 1
vpv21_audio_prepared:      ds.l 1
; BerryMP314 primes exactly one real Helix block before video starts.
; All following AAC->PCM decode calls happen live inside the common A/V
; dispatcher and write directly into the proven small DMA slot.
vpv38_pcm_block_count:      ds.l 1
vpv38_pcm_store_total:      ds.l 1
vpv38_pcm_block_sizes:      ds.l VPV38_PCM_BLOCKS
vpv38_pcm_store:            ds.b VPV38_PCM_STORE_BYTES
; BerryMP314: live A/V scheduler state. Audio shares the same MMAL/VCHIQ service
; with video, so BULK_TX is serialized globally while MMAL callbacks remain
; fully multiplexed by their buffer contexts.
vpv39_audio_armed:          ds.l 1
vpv39_audio_next_block:     ds.l 1
vpv39_audio_bulk_pending:   ds.l 1
vpv58_bulk_guard_hits:      ds.l 1
vpv39_audio_blocks_done:    ds.l 1
vpv39_audio_all_done:       ds.l 1
vpv39_audio_failed:         ds.l 1
; BerryMP314: live Helix state retained across the H264 playback; one PCM block is prefetched ahead.
vpv41_decoder_live:         ds.l 1
vpv41_audio_eof:            ds.l 1
vpv41_live_decode_blocks:   ds.l 1

; BerryMP314: movie-length-independent AAC reader and PTS scheduler.  Audio uses a
; second DOS file handle plus its own 64-KiB EBML window, so refilling audio
; never disturbs the proven H264 live-demux state.
vpv43_streaming_audio:          ds.l 1
vpv43_a_file_handle:            ds.l 1
vpv43_a_io_ptr:                 ds.l 1
vpv43_a_io_len:                 ds.l 1
vpv43_a_io_pos:                 ds.l 1
vpv43_a_abs_pos:                ds.l 1
vpv43_a_reader_eof:             ds.l 1
vpv43_a_reader_error:           ds.l 1
vpv43_a_segment_end:            ds.l 1
vpv43_a_cluster_active:         ds.l 1
vpv43_a_cluster_end:            ds.l 1
vpv43_a_blockgroup_end:         ds.l 1
vpv43_a_cluster_timecode:       ds.l 1
vpv43_a_payload_len:            ds.l 1
vpv43_a_current_pts_ticks:      ds.l 1
vpv43_a_source_eof:             ds.l 1
vpv43_a_total_frames:           ds.l 1
vpv43_first_audio_pts_found:    ds.l 1
vpv43_first_audio_pts_ticks:    ds.l 1
vpv43_audio_next_pts_ticks:     ds.l 1
vpv43_audio_pts_remainder:      ds.l 1
vpv43_last_sent_samples:        ds.l 1
vpv43_pts_mode:                 ds.l 1
vpv43_video_frame_ticks:        ds.l 1
vpv43_display_pts_ticks:        ds.l 1
vpv43_last_output_frames:       ds.l 1
vpv43_sync_waits:               ds.l 1
vpv43_sync_started:             ds.l 1
vpv45_topup_count:              ds.l 1
; BerryMP314: one-block CPU-side PCM prefetch. While the current DMA buffer is
; playing on VideoCore, Helix decodes the next block into vpv38_pcm_store.
; This removes file I/O + AAC decode from the critical buffer-return gap.
vpv45_prefetch_ready:            ds.l 1
vpv45_prefetch_bytes:            ds.l 1
vpv45_prefetch_samples:          ds.l 1
vpv45_prefetch_count:            ds.l 1
vpv45_prefetch_miss_count:       ds.l 1
vpv45_prefetch_first_logged:     ds.l 1
vpv43_a_vint_tmp:               ds.b 8
vpv306_id3_skip_bytes:          ds.l 1
vpv306_id3_header:              ds.b 10
vpv311_audio_bytes_left:        ds.l 1
vpv311_id3v1_bytes:             ds.l 1
vpv311_id3v1_tail:              ds.b 128
        even

; VPv48 BerryFAAD03 persistent CPU1 bridge state.
vpv48_faad_ready:              ds.l 1
vpv48_faad_module_loaded:      ds.l 1
vpv48_mail_raw:                ds.l 1
vpv48_mail_ptr:                ds.l 1
vpv48_module_raw:              ds.l 1
vpv48_module_ptr:              ds.l 1
vpv48_input_raw:               ds.l 1
vpv48_input_ptr:               ds.l 1
vpv48_output_raw:              ds.l 1
vpv48_output_ptr:              ds.l 1
vpv48_work_raw:                ds.l 1
vpv48_work_ptr:                ds.l 1
vpv48_module_phys:             ds.l 1
vpv48_input_phys:              ds.l 1
vpv48_output_phys:             ds.l 1
vpv48_work_phys:               ds.l 1
vpv48_module_file:             ds.l 1
vpv48_module_actual_size:      ds.l 1
vpv307_module_api_version:    ds.l 1
vpv307_module_version_magic:  ds.l 1
vpv48_sequence:                ds.l 1
vpv48_req_in_phys:             ds.l 1
vpv48_req_in_len:              ds.l 1
vpv48_req_out_phys:            ds.l 1
vpv48_req_out_len:             ds.l 1
vpv48_req_param0:              ds.l 1
vpv48_req_param1:              ds.l 1
vpv48_req_work_phys:           ds.l 1
vpv48_req_work_len:            ds.l 1
vpv48_dma_mail_len:            ds.l 1
vpv48_dma_module_len:          ds.l 1
vpv48_dma_input_len:           ds.l 1
vpv48_dma_output_len:          ds.l 1
vpv48_dma_work_len:            ds.l 1
vpv48_module_dma_active:       ds.b 1
vpv48_input_dma_active:        ds.b 1
vpv48_output_dma_active:       ds.b 1
vpv48_work_dma_active:         ds.b 1
        even
vpv48_last_consumed:           ds.l 1
vpv48_last_pcm_bytes:          ds.l 1
vpv48_last_samples_ch:         ds.l 1
vpv48_last_frames:             ds.l 1
vpv48_last_frame_index:        ds.l 1
vpv48_batch_count:             ds.l 1
vpv48_last_mail_status:        ds.l 1
vpv302_prepare_stage:          ds.l 1
vpv302_prepare_r0:             ds.l 1
vpv302_prepare_r1:             ds.l 1
vpv302_prepare_r2:             ds.l 1
vpv302_prepare_r3:             ds.l 1
vpv302_prepare_saved_status:   ds.l 1
vpv303_map_substage:           ds.l 1
vpv303_output_ptr_diag:        ds.l 1
vpv303_output_rawphys:         ds.l 1
vpv303_output_len_diag:        ds.l 1
vpv303_work_ptr_diag:          ds.l 1
vpv303_work_rawphys:           ds.l 1
vpv303_work_len_diag:          ds.l 1
vpv303_identity_fallbacks:     ds.l 1
vpv56_mail_fast_replies:     ds.l 1
vpv56_mail_slow_fallbacks:   ds.l 1
        even

        section code,code

; Prime one bounded PCM block before MMAL startup. BerryMP314 keeps Helix open and
; refills compressed AAC through a rolling 128-KiB ADTS window during playback.
vpv21_predecode_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv21_pcm_total_bytes
        clr.l   vpv21_pcm_total_samples
        clr.l   vpv21_audio_returned
        clr.l   vpv21_audio_dma_active
        clr.l   vpv38_pcm_block_count
        clr.l   vpv38_pcm_store_total
        clr.l   vpv41_decoder_live
        clr.l   vpv41_audio_eof
        clr.l   vpv41_live_decode_blocks
        clr.l   vpv48_batch_count
        lea     vpv38_pcm_block_sizes,a0
        moveq   #VPV38_PCM_BLOCKS-1,d0
vpv48_clear_sizes:
        clr.l   (a0)+
        dbra    d0,vpv48_clear_sizes

        ; Keep BerryMP314's proven pair of 64-KiB MMAL audio DMA slots unchanged.
        move.l  a4,a6
        move.l  #VPV21_PCM_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   vpv21_predecode_fail
        move.l  d0,vpv21_pcm_alloc
        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,vpv21_pcm_ptr
        move.l  d0,vpv21_pcm_write_ptr
        cmp.l   #$3f000000,d0
        bcc.w   vpv21_predecode_fail_free
        move.l  d0,d1
        add.l   #VPV21_PCM_DMA_SPAN-1,d1
        cmp.l   #$3f000000,d1
        bcc.w   vpv21_predecode_fail_free
        move.l  d0,d1
        or.l    #$c0000000,d1
        move.l  d1,vpv21_pcm_bus
        move.l  d0,d1
        add.l   #VPV21_PCM_PAGE_OFS,d1
        move.l  d1,vpv21_pcm_pagelist_ptr
        or.l    #$c0000000,d1
        move.l  d1,vpv21_pcm_pagelist_bus

        move.l  vpv21_pcm_ptr,d1
        add.l   #$00042000,d1
        move.l  d1,vpv47_pcm1_ptr
        move.l  d1,d2
        or.l    #$c0000000,d2
        move.l  d2,vpv47_pcm1_bus
        add.l   #VPV21_PCM_PAGE_OFS,d1
        move.l  d1,vpv47_pcm1_pagelist_ptr
        or.l    #$c0000000,d1
        move.l  d1,vpv47_pcm1_pagelist_bus

        ; VPv48: install and initialize the BerryFAAD03
        ; module on CPU1. The Matroska/ADTS rolling reader remains BerryMP314 code.
        jsr     vpv48_faad_prepare
        tst.l   d0
        bne.w   vpv21_predecode_fail_decoder

        move.l  v19_aac_buf_ptr,d0
        move.l  d0,vpv18_stream_cur
        jsr     vpv48_faad_decode_batch_store
        tst.l   d0
        bne.w   vpv21_predecode_fail_decoder

        move.l  vpv48_last_pcm_bytes,d0
        tst.l   d0
        beq.w   vpv21_predecode_fail_decoder
        move.l  d0,vpv38_pcm_store_total
        move.l  d0,vpv21_pcm_total_bytes
        lea     vpv38_pcm_block_sizes,a0
        move.l  d0,(a0)
        move.l  #1,vpv38_pcm_block_count
        move.l  vpv48_last_samples_ch,d0
        move.l  d0,vpv21_pcm_total_samples

        ; BerryFAAD03 keeps the proven AAC-LC stereo/PCM16 format, but the
        ; samplerate now comes from FAAD2/ADTS instead of being forced to 48 kHz.
        tst.l   v19_pcm_rate
        beq.w   vpv21_predecode_fail_decoder
        move.l  #2,v19_pcm_channels
        move.l  #16,v19_pcm_bits
        move.l  #4,v19_pcm_blockalign
        move.l  v19_pcm_rate,d0
        lsl.l   #5,d0                  ; stereo PCM16 bitrate = samplerate * 32
        move.l  d0,v19_pcm_bitrate

        move.l  vpv43_first_audio_pts_ticks,d0
        move.l  d0,vpv43_audio_next_pts_ticks
        clr.l   vpv43_audio_pts_remainder
        move.l  v19_pcm_rate,d0
        tst.l   d0
        bne.s   vpv48_predecode_pts_ready
        clr.l   vpv43_pts_mode
vpv48_predecode_pts_ready:

        move.l  #1,vpv41_decoder_live
        move.l  #1,vpv41_live_decode_blocks

        lea     msg_vpv48_predecode_ok,a1
        move.l  #msg_vpv48_predecode_ok_end-msg_vpv48_predecode_ok,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv48_last_pcm_bytes,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv48_last_consumed,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        moveq   #0,d0
        bra.s   vpv21_predecode_done

vpv21_predecode_fail_decoder:
        lea     msg_vpv49_faad_call_fail,a1
        move.l  #msg_vpv49_faad_call_fail_end-msg_vpv49_faad_call_fail,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv48_last_mail_status,d0
        jsr     print_hex32
        lea     msg_vpv49_faad_freqidx,a1
        move.l  #msg_vpv49_faad_freqidx_end-msg_vpv49_faad_freqidx,d3
        jsr     print_force
        move.l  vpv302_prepare_stage,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
vpv21_predecode_fail_free:
        jsr     vpv21_free_pcm
vpv21_predecode_fail:
        lea     msg_vpv21_predecode_fail,a1
        move.l  #msg_vpv21_predecode_fail_end-msg_vpv21_predecode_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv21_predecode_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; BerryMP314: copy the single staged priming PCM block into the proven DMA slot and rebuild
; its one-run VCHIQ pagelist. D0=block index, returns D0=0/1.
vpv38_load_pcm_block:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmp.l   vpv38_pcm_block_count,d7
        bcc.w   vpv38_load_fail

        ; Find block source by summing prior variable block sizes.
        lea     vpv38_pcm_store,a1
        lea     vpv38_pcm_block_sizes,a2
        moveq   #0,d6
vpv38_load_offset_loop:
        cmp.l   d7,d6
        bcc.s   vpv38_load_have_src
        move.l  (a2)+,d1
        adda.l  d1,a1
        addq.l  #1,d6
        bra.s   vpv38_load_offset_loop
vpv38_load_have_src:
        ; A2 currently points to this block's size entry when d7>0; recompute
        ; directly to keep the zero-index case simple and explicit.
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv38_pcm_block_sizes,a2
        adda.l  d0,a2
        move.l  (a2),d5
        tst.l   d5
        beq.s   vpv38_load_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d5
        bhi.s   vpv38_load_fail
        move.l  d5,vpv21_pcm_total_bytes

        ; Copy exact PCM bytes into the already-proven aligned DMA slot.
        move.l  vpv21_pcm_ptr,a0
        move.l  d5,d1
vpv38_copy_loop:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv38_copy_loop

        ; Rebuild compressed contiguous-run pagelist for this exact block size.
        move.l  vpv21_pcm_pagelist_ptr,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  vpv21_pcm_bus,d1
        and.l   #$fffff000,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     store_le32
        moveq   #0,d0
        bra.s   vpv38_load_done
vpv38_load_fail:
        moveq   #1,d0
vpv38_load_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; BerryMP314: decode ONE additional AAC block live into the proven aligned PCM DMA
; slot. Helix reads through BerryMP314's rolling ADTS callback; refills come from an
; independent 64-KiB MKV reader and do not disturb the H264 file state.
; Return D0: 0=PCM ready, 1=MP3 EOF, 2=fail.
vpv41_decode_live_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv41_decoder_live
        beq.w   vpv41_live_eof_return
        move.l  vpv18_ops,d0
        beq.w   vpv41_live_fail
        move.l  vpv18_dec_handle,d0
        beq.w   vpv41_live_fail

        ; BerryMP314: all file I/O and EBML parsing happens outside Helix.
        jsr     vpv45_topup_adts_buffer
        tst.l   d0
        bne.w   vpv41_live_fail

        move.l  vpv18_ops,a0
        move.l  DECOPS_DECODE(a0),a0
        move.l  #VPV43_SYNC_SAMPLES_CH,-(sp)
        move.l  vpv21_pcm_ptr,-(sp)
        move.l  vpv18_dec_handle,-(sp)
        jsr     (a0)
        lea     12(sp),sp
        tst.l   d0
        bmi.w   vpv41_live_fail
        beq.w   vpv41_live_eof

        move.l  d0,d5                  ; samples/channel
        move.l  d5,d1
        move.l  v19_pcm_channels,d6
        cmpi.l  #1,d6
        bcs.w   vpv41_live_fail
        cmpi.l  #2,d6
        bhi.w   vpv41_live_fail
        mulu.w  d6,d1
        lsl.l   #1,d1                  ; signed 16-bit PCM bytes
        tst.l   d1
        beq.w   vpv41_live_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d1
        bhi.w   vpv41_live_fail
        move.l  d1,vpv21_pcm_total_bytes
        add.l   d5,vpv21_pcm_total_samples

        ; Native m68k decoder output is BE; MMAL PCM_SIGNED_LE requires LE.
        move.l  d1,d2
        lsr.l   #1,d2
        move.l  vpv21_pcm_ptr,a0
vpv41_live_swap_loop:
        moveq   #0,d0
        move.w  (a0),d0
        rol.w   #8,d0
        move.w  d0,(a0)+
        subq.l  #1,d2
        bne.s   vpv41_live_swap_loop

        ; Rebuild the compact contiguous VCHIQ pagelist for this exact block.
        move.l  vpv21_pcm_pagelist_ptr,a0
        move.l  d1,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d1,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  vpv21_pcm_bus,d3
        and.l   #$fffff000,d3
        or.l    d0,d3
        lea     8(a0),a0
        move.l  d3,d0
        jsr     store_le32
        addq.l  #1,vpv41_live_decode_blocks
        moveq   #0,d0
        bra.w   vpv41_live_done

vpv41_live_eof:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv18_close_module
        jsr     vpv19_free_aac_buffer
vpv41_live_eof_return:
        moveq   #1,d0
        bra.s   vpv41_live_done

vpv41_live_fail:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv18_close_module
        jsr     vpv19_free_aac_buffer
        moveq   #2,d0
vpv41_live_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; BerryMP314: decode ONE future AAC block into CPU-side vpv38_pcm_store while the
; previous PCM DMA buffer is still owned by VideoCore. No MMAL/VCHIQ transfer
; happens here. Return D0: 0=prefetch ready/already ready, 1=MP3 EOF, 2=fail.
vpv45_prefetch_live_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv45_prefetch_ready
        bne.w   vpv45_prefetch_ok
        tst.l   vpv41_decoder_live
        beq.w   vpv45_prefetch_eof_return
        tst.l   vpv48_faad_ready
        beq.w   vpv45_prefetch_fail

        jsr     vpv48_faad_decode_batch_store
        cmpi.l  #1,d0
        beq.w   vpv45_prefetch_eof
        tst.l   d0
        bne.w   vpv45_prefetch_fail

        move.l  vpv48_last_pcm_bytes,d1
        tst.l   d1
        beq.w   vpv45_prefetch_fail
        cmpi.l  #VPV38_PCM_STORE_BYTES,d1
        bhi.w   vpv45_prefetch_fail
        move.l  d1,vpv45_prefetch_bytes
        move.l  vpv48_last_samples_ch,d5
        tst.l   d5
        beq.w   vpv45_prefetch_fail
        move.l  d5,vpv45_prefetch_samples
        add.l   d5,vpv21_pcm_total_samples

        move.l  #1,vpv45_prefetch_ready
        addq.l  #1,vpv45_prefetch_count
        addq.l  #1,vpv41_live_decode_blocks
        tst.l   vpv45_prefetch_first_logged
        bne.s   vpv45_prefetch_ok
        move.l  #1,vpv45_prefetch_first_logged
        lea     msg_vpv48_prefetch_ok,a1
        move.l  #msg_vpv48_prefetch_ok_end-msg_vpv48_prefetch_ok,d3
        jsr     vpv21n_trace
vpv45_prefetch_ok:
        moveq   #0,d0
        bra.s   vpv45_prefetch_done

vpv45_prefetch_eof:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
vpv45_prefetch_eof_return:
        moveq   #1,d0
        bra.s   vpv45_prefetch_done

vpv45_prefetch_fail:
        clr.l   vpv41_decoder_live
        move.l  #1,vpv41_audio_eof
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
        moveq   #2,d0
vpv45_prefetch_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Copy the already-decoded future PCM block into the proven aligned DMA slot
; and rebuild the one-run pagelist. Return D0=0/1.
vpv45_load_prefetch_pcm:
        movem.l d1-d7/a0-a3,-(sp)
        tst.l   vpv45_prefetch_ready
        beq.w   vpv45_load_prefetch_fail
        move.l  vpv45_prefetch_bytes,d5
        tst.l   d5
        beq.w   vpv45_load_prefetch_fail
        cmpi.l  #VPV21_PCM_MAX_BYTES,d5
        bhi.w   vpv45_load_prefetch_fail
        move.l  d5,vpv21_pcm_total_bytes
        lea     vpv38_pcm_store,a1
        move.l  vpv21_pcm_ptr,a0
        move.l  d5,d1
vpv45_load_prefetch_copy:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv45_load_prefetch_copy

        move.l  vpv21_pcm_pagelist_ptr,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        move.l  vpv21_pcm_bus,d1
        and.l   #$fffff000,d1
        or.l    d0,d1
        lea     8(a0),a0
        move.l  d1,d0
        jsr     store_le32
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        moveq   #0,d0
        bra.s   vpv45_load_prefetch_done
vpv45_load_prefetch_fail:
        moveq   #1,d0
vpv45_load_prefetch_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; BerryMP314 cleanup is idempotent and is also used when video is stopped before
; MP3 EOF. It must run before the PCM DMA allocation is freed.
vpv41_audio_decoder_cleanup:
        movem.l d0-d2/a0-a1/a6,-(sp)
        lea     msg_vpv53_chunk_stats,a1
        move.l  #msg_vpv53_chunk_stats_end-msg_vpv53_chunk_stats,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv53_chunk_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv53_batch_adopts,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        lea     msg_vpv56_mail_stats,a1
        move.l  #msg_vpv56_mail_stats_end-msg_vpv56_mail_stats,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv56_mail_fast_replies,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv56_mail_slow_fallbacks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        lea     msg_vpv58_bulk_guard_stats,a1
        move.l  #msg_vpv58_bulk_guard_stats_end-msg_vpv58_bulk_guard_stats,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv58_bulk_guard_hits,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        lea     msg_vpv45_prefetch_stats,a1
        move.l  #msg_vpv45_prefetch_stats_end-msg_vpv45_prefetch_stats,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv45_prefetch_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv45_prefetch_miss_count,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        clr.l   vpv41_decoder_live
        jsr     vpv48_faad_cleanup
        jsr     vpv19_free_aac_buffer
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

; ====================================================================
; VPv48 - BerryCore / BerryFAAD03 bridge
; ====================================================================
; The mailbox/service ABI is the hardware-confirmed BerryFAAD03 ABI.  The
; external module remains resident for the whole A/V run; compressed AAC is
; staged into an aligned 128-KiB buffer, while output/work follow the same
; CachePreDMA/PostDMA discipline used by berrytestFAAD02.

; D0=allocation bytes. Returns D0=raw allocation, D1=4-KiB-aligned pointer;
; D0=0 on failure. Allocation size is preserved exactly for later FreeMem.
vpv48_alloc_aligned:
        movem.l d2-d3/a1/a6,-(sp)
        move.l  d0,d3
        move.l  4.w,a6
        move.l  #MEMF_PUBLICFASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   vpv48_aa_done
        move.l  d0,d2
        move.l  d0,d1
        add.l   #$00000fff,d1
        and.l   #$fffff000,d1
        cmpi.l  #VPV48_SCAN_LOW,d1
        bcs.s   vpv48_aa_bad
        cmpi.l  #VPV48_SCAN_HIGH,d1
        bcc.s   vpv48_aa_bad
        move.l  d2,d0
        bra.s   vpv48_aa_done
vpv48_aa_bad:
        move.l  d2,a1
        move.l  d3,d0
        jsr     FreeMem(a6)
        moveq   #0,d0
vpv48_aa_done:
        movem.l (sp)+,d2-d3/a1/a6
        rts

vpv48_check_phys:
        cmpi.l  #VPV48_SCAN_LOW,d0
        bcs.s   vpv48_phys_bad
        cmpi.l  #VPV48_SCAN_HIGH,d0
        bcc.s   vpv48_phys_bad
        moveq   #0,d0
        rts
vpv48_phys_bad:
        moveq   #1,d0
        rts

vpv48_setup_mail:
        movem.l d1-d4/a0-a1/a6,-(sp)
        move.l  vpv48_mail_ptr,a0
        move.l  #VPV48_MAGIC0,(a0)
        move.l  #VPV48_MAGIC1,4(a0)
        moveq   #0,d1
        lea     8(a0),a1
        moveq   #29,d2
vpv48_sm_clear:
        move.l  d1,(a1)+
        dbra    d2,vpv48_sm_clear
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  vpv48_mail_ptr,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,d4
        move.l  vpv48_mail_ptr,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
        move.l  vpv48_mail_ptr,d0
        cmp.l   d4,d0
        beq.s   vpv48_sm_ok
        moveq   #1,d0
        bra.s   vpv48_sm_done
vpv48_sm_ok:
        moveq   #0,d0
vpv48_sm_done:
        movem.l (sp)+,d1-d4/a0-a1/a6
        rts

; D0=BerryCore command. Returns D0=0 and D1/D2/D3=result0/1/2.
vpv48_send_request:
        movem.l d4-d7/a0-a3/a6,-(sp)
        move.l  vpv48_mail_ptr,a3
        addq.l  #1,vpv48_sequence
        move.l  vpv48_sequence,12(a3)
        move.l  d0,16(a3)
        clr.l   20(a3)
        move.l  vpv48_req_in_phys,24(a3)
        move.l  vpv48_req_in_len,28(a3)
        move.l  vpv48_req_out_phys,32(a3)
        move.l  vpv48_req_out_len,36(a3)
        move.l  vpv48_req_param0,40(a3)
        move.l  vpv48_req_param1,44(a3)
        move.l  vpv48_req_work_phys,48(a3)
        move.l  vpv48_req_work_len,52(a3)
        clr.l   56(a3)
        clr.l   60(a3)
        clr.l   64(a3)
        move.l  #$ffffffff,68(a3)
        move.l  #$ffffffff,vpv48_last_mail_status
        clr.l   72(a3)
        clr.l   76(a3)
        clr.b   9(a3)
        clr.b   10(a3)
        clr.b   11(a3)
        move.b  #$a5,8(a3)

        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)

        ; VPv59: the old loop always called DOS Delay(1) before the FIRST
        ; mailbox inspection.  That quantized every FAAD batch to at least
        ; one OS tick.  Poll coherently first with a very short bounded spin;
        ; only fall back to Delay(1) if CPU1 really has not answered yet.
        moveq   #0,d7                  ; number of slow 1-tick fallbacks
        move.l  #VPV56_MAIL_FAST_POLLS,d6
vpv48_sr_poll:
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.w  #VPV56_MAIL_SPIN,d4
vpv56_sr_spin:
        dbf     d4,vpv56_sr_spin
        move.l  a3,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)
        cmpi.b  #$5a,9(a3)
        bne.s   vpv48_sr_notyet
        move.l  vpv48_sequence,d5
        cmp.l   76(a3),d5
        bne.s   vpv48_sr_notyet
        move.l  68(a3),vpv48_last_mail_status
        cmpi.b  #1,10(a3)
        bne.s   vpv48_sr_bad
        cmpi.b  #20,11(a3)
        bne.s   vpv48_sr_bad
        tst.l   68(a3)
        bne.s   vpv48_sr_bad
        tst.l   d7
        bne.s   vpv56_sr_reply_counted
        addq.l  #1,vpv56_mail_fast_replies
vpv56_sr_reply_counted:
        move.l  56(a3),d1
        move.l  60(a3),d2
        move.l  64(a3),d3
        moveq   #0,d0
        bra.s   vpv48_sr_done
vpv48_sr_notyet:
        subq.l  #1,d6
        bne.w   vpv48_sr_poll

        ; Rare slow path: preserve the old scheduler-friendly yield and the
        ; old 500-tick timeout, but only AFTER hundreds of immediate polls.
        addq.l  #1,vpv56_mail_slow_fallbacks
        move.l  a5,a6
        moveq   #1,d1
        jsr     Delay(a6)
        addq.l  #1,d7
        cmpi.l  #VPV48_MAIL_MAX_TICKS,d7
        bcc.s   vpv48_sr_timeout
        move.l  #VPV56_MAIL_FAST_POLLS,d6
        bra.w   vpv48_sr_poll
vpv48_sr_timeout:
        moveq   #1,d0
        bra.s   vpv48_sr_done
vpv48_sr_bad:
        moveq   #2,d0
vpv48_sr_done:
        movem.l (sp)+,d4-d7/a0-a3/a6
        rts

vpv48_map_output_work:
        movem.l d1-d3/a0-a1/a6,-(sp)
        clr.l   vpv303_map_substage
        clr.l   vpv303_identity_fallbacks

        ; OUTPUT: CPU1 writes PCM here.  Some Emu68/Exec combinations may
        ; perform the cache operation for direction=0 but return 0 instead of
        ; the identity physical address.  Record everything, and only fall
        ; back to the aligned FastRAM pointer if the requested span stayed
        ; intact and the pointer is inside the already-proven BerryCore window.
        move.l  #$00000001,vpv303_map_substage
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_dma_output_len
        move.l  vpv48_output_ptr,a0
        move.l  a0,vpv303_output_ptr_diag
        lea     vpv48_dma_output_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv303_output_rawphys
        move.l  vpv48_dma_output_len,vpv303_output_len_diag
        move.l  d0,vpv48_output_phys
        move.b  #1,vpv48_output_dma_active
        cmpi.l  #VPV48_FAAD_OUT_SIZE,vpv48_dma_output_len
        bne.w   vpv48_mow_bad
        move.l  vpv48_output_phys,d0
        jsr     vpv48_check_phys
        tst.l   d0
        beq.s   vpv303_out_ok
        tst.l   vpv303_output_rawphys
        bne.w   vpv48_mow_bad
        move.l  vpv48_output_ptr,d0
        jsr     vpv48_check_phys
        tst.l   d0
        bne.w   vpv48_mow_bad
        move.l  vpv48_output_ptr,vpv48_output_phys
        or.l    #1,vpv303_identity_fallbacks
vpv303_out_ok:

        ; WORK: persistent decoder state/heap/stack is also CPU1 writable.
        move.l  #$00000002,vpv303_map_substage
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_dma_work_len
        move.l  vpv48_work_ptr,a0
        move.l  a0,vpv303_work_ptr_diag
        lea     vpv48_dma_work_len,a1
        moveq   #0,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv303_work_rawphys
        move.l  vpv48_dma_work_len,vpv303_work_len_diag
        move.l  d0,vpv48_work_phys
        move.b  #1,vpv48_work_dma_active
        cmpi.l  #VPV48_FAAD_WORK_SIZE,vpv48_dma_work_len
        bne.s   vpv48_mow_bad
        move.l  vpv48_work_phys,d0
        jsr     vpv48_check_phys
        tst.l   d0
        beq.s   vpv303_work_ok
        tst.l   vpv303_work_rawphys
        bne.s   vpv48_mow_bad
        move.l  vpv48_work_ptr,d0
        jsr     vpv48_check_phys
        tst.l   d0
        bne.s   vpv48_mow_bad
        move.l  vpv48_work_ptr,vpv48_work_phys
        or.l    #2,vpv303_identity_fallbacks
vpv303_work_ok:
        move.l  #$00000003,vpv303_map_substage
        moveq   #0,d0
        bra.s   vpv48_mow_done
vpv48_mow_bad:
        moveq   #1,d0
vpv48_mow_done:
        movem.l (sp)+,d1-d3/a0-a1/a6
        rts

vpv48_close_output_work:
        movem.l d0/a0-a1/a6,-(sp)
        move.l  4.w,a6
        tst.b   vpv48_output_dma_active
        beq.s   vpv48_cow_no_out
        move.l  vpv48_output_ptr,a0
        lea     vpv48_dma_output_len,a1
        moveq   #0,d0
        jsr     CachePostDMA(a6)
        clr.b   vpv48_output_dma_active
vpv48_cow_no_out:
        tst.b   vpv48_work_dma_active
        beq.s   vpv48_cow_done
        move.l  vpv48_work_ptr,a0
        lea     vpv48_dma_work_len,a1
        moveq   #0,d0
        jsr     CachePostDMA(a6)
        clr.b   vpv48_work_dma_active
vpv48_cow_done:
        movem.l (sp)+,d0/a0-a1/a6
        rts

; D0=input byte count in aligned vpv48_input_ptr.
vpv48_map_input:
        movem.l d1/a0-a1/a6,-(sp)
        move.l  d0,vpv48_dma_input_len
        move.l  vpv48_input_ptr,a0
        lea     vpv48_dma_input_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv48_input_phys
        move.b  #1,vpv48_input_dma_active
        jsr     vpv48_check_phys
        movem.l (sp)+,d1/a0-a1/a6
        rts

vpv48_close_input:
        movem.l d0/a0-a1/a6,-(sp)
        tst.b   vpv48_input_dma_active
        beq.s   vpv48_ci_done
        move.l  vpv48_input_ptr,a0
        lea     vpv48_dma_input_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePostDMA(a6)
        clr.b   vpv48_input_dma_active
vpv48_ci_done:
        movem.l (sp)+,d0/a0-a1/a6
        rts

vpv48_release_mail:
        movem.l d0/a0-a1/a6,-(sp)
        move.l  vpv48_mail_ptr,a0
        move.l  a0,d0
        beq.s   vpv48_rm_done
        clr.l   (a0)
        clr.l   4(a0)
        clr.l   8(a0)
        move.l  #VPV48_FAAD_MAIL_SIZE,vpv48_dma_mail_len
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  vpv48_mail_ptr,a0
        lea     vpv48_dma_mail_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
vpv48_rm_done:
        movem.l (sp)+,d0/a0-a1/a6
        rts

; Allocate/load/map the external BerryMP314 module, publish the BerryCore
; mailbox, LOAD_MODULE it and run FAAD INIT. D0=0/1.
vpv48_faad_prepare:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv48_faad_ready
        bne.w   vpv48_fp_ok
        clr.l   vpv48_faad_module_loaded
        clr.l   vpv48_sequence
        clr.b   vpv48_module_dma_active
        clr.b   vpv48_input_dma_active
        clr.b   vpv48_output_dma_active
        clr.b   vpv48_work_dma_active
        clr.l   vpv302_prepare_r0
        clr.l   vpv302_prepare_r1
        clr.l   vpv302_prepare_r2
        clr.l   vpv302_prepare_r3
        clr.l   vpv302_prepare_saved_status
        clr.l   vpv303_map_substage
        clr.l   vpv303_output_ptr_diag
        clr.l   vpv303_output_rawphys
        clr.l   vpv303_output_len_diag
        clr.l   vpv303_work_ptr_diag
        clr.l   vpv303_work_rawphys
        clr.l   vpv303_work_len_diag
        clr.l   vpv303_identity_fallbacks
        clr.l   vpv307_module_api_version
        clr.l   vpv307_module_version_magic
        move.l  #$00000001,vpv302_prepare_stage

        move.l  #VPV48_FAAD_MAIL_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_mail_raw
        move.l  d1,vpv48_mail_ptr
        move.l  #$00000002,vpv302_prepare_stage
        move.l  #VPV48_FAAD_MOD_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_module_raw
        move.l  d1,vpv48_module_ptr
        move.l  #$00000003,vpv302_prepare_stage
        move.l  #VPV48_FAAD_IN_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_input_raw
        move.l  d1,vpv48_input_ptr
        move.l  #$00000004,vpv302_prepare_stage
        move.l  #VPV48_FAAD_OUT_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_output_raw
        move.l  d1,vpv48_output_ptr
        move.l  #$00000005,vpv302_prepare_stage
        move.l  #VPV48_FAAD_WORK_ALLOC,d0
        jsr     vpv48_alloc_aligned
        tst.l   d0
        beq.w   vpv48_fp_fail
        move.l  d0,vpv48_work_raw
        move.l  d1,vpv48_work_ptr
        move.l  #$00000010,vpv302_prepare_stage

        ; Read external raw AArch64 module.
        move.l  a5,a6
        lea     vpv48_faad_modulename_progdir,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        bne.s   vpv48_fp_have_module_file
        lea     vpv48_faad_modulename,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   vpv48_fp_fail
vpv48_fp_have_module_file:
        move.l  d0,vpv48_module_file
        move.l  d0,d1
        move.l  vpv48_module_ptr,d2
        move.l  #VPV48_FAAD_MODULE_MAX,d3
        jsr     Read(a6)
        move.l  d0,d7
        move.l  vpv48_module_file,d1
        jsr     Close(a6)
        clr.l   vpv48_module_file
        tst.l   d7
        bmi.w   vpv48_fp_fail
        cmpi.l  #64,d7
        bcs.w   vpv48_fp_fail
        cmpi.l  #VPV48_FAAD_MODULE_MAX,d7
        bhi.w   vpv48_fp_fail
        move.l  d7,vpv48_module_actual_size
        move.l  #$00000011,vpv302_prepare_stage

        ; BerryMP314 stable module metadata lives in the reserved 64-byte
        ; raw-module header.  Validate it on the 68k side BEFORE CPU1 code runs.
        ; The executable AArch64 image beginning at offset $40 remains exactly
        ; byte-identical to the hardware-confirmed MP304/MP306 module.
        move.l  vpv48_module_ptr,a0
        cmpi.l  #VPV307_MP3_API_VERSION,16(a0)
        bne.w   vpv48_fp_fail
        cmpi.l  #VPV307_MP3_VERSION_MAGIC,20(a0)
        bne.w   vpv48_fp_fail
        move.l  16(a0),vpv307_module_api_version
        move.l  20(a0),vpv307_module_version_magic
        move.l  #$00000014,vpv302_prepare_stage
        lea     msg_vpv307_module_version_ok,a1
        move.l  #msg_vpv307_module_version_ok_end-msg_vpv307_module_version_ok,d3
        jsr     print_force

        ; Strip disk-only version metadata before publishing to BerryCore.
        ; This restores bytes $10..$3f to the exact all-zero header used by
        ; the hardware-confirmed MP306 module, so CPU1 receives the proven
        ; 59930-byte image byte-for-byte.
        move.l  vpv48_module_ptr,a0
        lea     16(a0),a1
        moveq   #0,d0
        moveq   #11,d1
vpv308_clear_disk_metadata:
        move.l  d0,(a1)+
        dbra    d1,vpv308_clear_disk_metadata

        ; Publish actual BerryMP314 module bytes for CPU1.
        move.l  d7,vpv48_dma_module_len
        move.l  vpv48_module_ptr,a0
        lea     vpv48_dma_module_len,a1
        moveq   #DMA_ReadFromRAM,d0
        move.l  4.w,a6
        jsr     CachePreDMA(a6)
        move.l  d0,vpv48_module_phys
        move.b  #1,vpv48_module_dma_active
        move.l  vpv48_module_actual_size,d0
        cmp.l   vpv48_dma_module_len,d0
        bne.w   vpv48_fp_fail
        ; MP304 FIX: D0 above contains the module SIZE for the length compare.
        ; Reload the physical module address before validating the BerryCore window.
        move.l  vpv48_module_phys,d0
        jsr     vpv48_check_phys
        tst.l   d0
        bne.w   vpv48_fp_fail

        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv48_fp_fail
        move.l  #$00000012,vpv302_prepare_stage
        jsr     vpv48_setup_mail
        tst.l   d0
        bne.w   vpv48_fp_fail
        move.l  #$00000013,vpv302_prepare_stage

        ; LOAD_MODULE.
        move.l  vpv48_module_phys,vpv48_req_in_phys
        move.l  vpv48_module_actual_size,vpv48_req_in_len
        clr.l   vpv48_req_out_phys
        clr.l   vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        clr.l   vpv48_req_work_phys
        clr.l   vpv48_req_work_len
        move.l  #$00000020,vpv302_prepare_stage
        moveq   #VPV48_CMD_LOAD_MODULE,d0
        jsr     vpv48_send_request
        move.l  d0,vpv302_prepare_r0
        move.l  d1,vpv302_prepare_r1
        move.l  d2,vpv302_prepare_r2
        move.l  d3,vpv302_prepare_r3
        move.l  vpv48_last_mail_status,vpv302_prepare_saved_status
        move.l  #$00000021,vpv302_prepare_stage
        tst.l   d0
        bne.w   vpv48_fp_fail
        cmpi.l  #VPV48_MODULE_TYPE_CODEC,d1
        bne.w   vpv48_fp_fail
        cmp.l   vpv48_module_actual_size,d2
        bne.w   vpv48_fp_fail
        move.l  #1,vpv48_faad_module_loaded

        ; Version/API was already validated from the reserved module header.
        ; No extra CALL_MODULE is made here: go straight to the hardware-confirmed INIT path.

        ; CALL_MODULE param0=0 -> MP3 decoder INIT + persistent state.
        clr.l   vpv48_req_in_phys
        clr.l   vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_req_work_len
        move.l  #$00000030,vpv302_prepare_stage
        moveq   #VPV48_CMD_CALL_MODULE,d0
        jsr     vpv48_send_request
        move.l  d0,vpv302_prepare_r0
        move.l  d1,vpv302_prepare_r1
        move.l  d2,vpv302_prepare_r2
        move.l  d3,vpv302_prepare_r3
        move.l  vpv48_last_mail_status,vpv302_prepare_saved_status
        move.l  #$00000031,vpv302_prepare_stage
        tst.l   d0
        bne.w   vpv48_fp_fail
        cmpi.l  #1,d1
        bne.w   vpv48_fp_fail

        move.l  #1,vpv48_faad_ready
        move.l  #$00000040,vpv302_prepare_stage
        lea     msg_vpv48_faad_ready,a1
        move.l  #msg_vpv48_faad_ready_end-msg_vpv48_faad_ready,d3
        jsr     print_force
vpv48_fp_ok:
        moveq   #0,d0
        bra.w   vpv48_fp_done
vpv48_fp_fail:
        ; BerryMP314: preserve and print the exact prepare failure BEFORE cleanup
        ; can issue UNLOAD_MODULE and overwrite vpv48_last_mail_status.
        lea     msg_vpv302_prep_diag,a1
        move.l  #msg_vpv302_prep_diag_end-msg_vpv302_prep_diag,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  vpv302_prepare_stage,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_r0,a1
        move.l  #msg_vpv302_prep_r0_end-msg_vpv302_prep_r0,d3
        jsr     print_force
        move.l  vpv302_prepare_r0,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_r1,a1
        move.l  #msg_vpv302_prep_r1_end-msg_vpv302_prep_r1,d3
        jsr     print_force
        move.l  vpv302_prepare_r1,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_r2,a1
        move.l  #msg_vpv302_prep_r2_end-msg_vpv302_prep_r2,d3
        jsr     print_force
        move.l  vpv302_prepare_r2,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_r3,a1
        move.l  #msg_vpv302_prep_r3_end-msg_vpv302_prep_r3,d3
        jsr     print_force
        move.l  vpv302_prepare_r3,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_ms,a1
        move.l  #msg_vpv302_prep_ms_end-msg_vpv302_prep_ms,d3
        jsr     print_force
        move.l  vpv302_prepare_saved_status,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_sz,a1
        move.l  #msg_vpv302_prep_sz_end-msg_vpv302_prep_sz,d3
        jsr     print_force
        move.l  vpv48_module_actual_size,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_mp,a1
        move.l  #msg_vpv302_prep_mp_end-msg_vpv302_prep_mp,d3
        jsr     print_force
        move.l  vpv48_module_phys,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_op,a1
        move.l  #msg_vpv302_prep_op_end-msg_vpv302_prep_op,d3
        jsr     print_force
        move.l  vpv48_output_phys,d0
        jsr     print_hex32
        lea     msg_vpv302_prep_wp,a1
        move.l  #msg_vpv302_prep_wp_end-msg_vpv302_prep_wp,d3
        jsr     print_force
        move.l  vpv48_work_phys,d0
        jsr     print_hex32
        lea     msg_vpv303_map_sub,a1
        move.l  #msg_vpv303_map_sub_end-msg_vpv303_map_sub,d3
        jsr     print_force
        move.l  vpv303_map_substage,d0
        jsr     print_hex32
        lea     msg_vpv303_outptr,a1
        move.l  #msg_vpv303_outptr_end-msg_vpv303_outptr,d3
        jsr     print_force
        move.l  vpv303_output_ptr_diag,d0
        jsr     print_hex32
        lea     msg_vpv303_outraw,a1
        move.l  #msg_vpv303_outraw_end-msg_vpv303_outraw,d3
        jsr     print_force
        move.l  vpv303_output_rawphys,d0
        jsr     print_hex32
        lea     msg_vpv303_outlen,a1
        move.l  #msg_vpv303_outlen_end-msg_vpv303_outlen,d3
        jsr     print_force
        move.l  vpv303_output_len_diag,d0
        jsr     print_hex32
        lea     msg_vpv303_workptr,a1
        move.l  #msg_vpv303_workptr_end-msg_vpv303_workptr,d3
        jsr     print_force
        move.l  vpv303_work_ptr_diag,d0
        jsr     print_hex32
        lea     msg_vpv303_workraw,a1
        move.l  #msg_vpv303_workraw_end-msg_vpv303_workraw,d3
        jsr     print_force
        move.l  vpv303_work_rawphys,d0
        jsr     print_hex32
        lea     msg_vpv303_worklen,a1
        move.l  #msg_vpv303_worklen_end-msg_vpv303_worklen,d3
        jsr     print_force
        move.l  vpv303_work_len_diag,d0
        jsr     print_hex32
        lea     msg_vpv303_fallback,a1
        move.l  #msg_vpv303_fallback_end-msg_vpv303_fallback,d3
        jsr     print_force
        move.l  vpv303_identity_fallbacks,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        lea     msg_vpv48_faad_fail,a1
        move.l  #msg_vpv48_faad_fail_end-msg_vpv48_faad_fail,d3
        jsr     print_force
        jsr     vpv48_faad_cleanup
        moveq   #1,d0
vpv48_fp_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Decode one BerryMP314 streaming batch from the unread MP3 rolling window.
; PCM is copied to vpv38_pcm_store and converted BE->LE for MMAL audio_render.
; D0=0 PCM ready, 1 clean MP3 EOF, 2 failure.
vpv48_faad_decode_batch_store:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv48_last_consumed
        clr.l   vpv48_last_pcm_bytes
        clr.l   vpv48_last_samples_ch
        clr.l   vpv48_last_frames
        tst.l   vpv48_faad_ready
        beq.w   vpv48_fdb_fail

        ; Existing BerryMP314 parser compacts/refills the source before CPU1 runs.
        jsr     vpv45_topup_adts_buffer
        tst.l   d0
        bne.w   vpv48_fdb_fail

        move.l  v19_aac_buf_ptr,d6
        move.l  d6,d5
        add.l   v19_aac_buf_len,d5
        move.l  vpv18_stream_cur,d4
        cmp.l   d6,d4
        bcs.w   vpv48_fdb_fail
        cmp.l   d5,d4
        bhi.w   vpv48_fdb_fail
        sub.l   d4,d5                  ; D5 unread bytes
        bne.s   vpv48_fdb_have_input
        tst.l   vpv43_a_source_eof
        bne.w   vpv48_fdb_eof
        bra.w   vpv48_fdb_fail
vpv48_fdb_have_input:
        cmpi.l  #VPV48_FAAD_INPUT_SIZE,d5
        bls.s   vpv48_fdb_size_ok
        move.l  #VPV48_FAAD_INPUT_SIZE,d5
vpv48_fdb_size_ok:

        ; Stage compressed input into the exact aligned geometry proven by
        ; berrytestFAAD02. No CPU1 DMA phase touches BerryMP314's rolling buffer.
        move.l  d4,a1
        move.l  vpv48_input_ptr,a0
        move.l  d5,d3                  ; exact byte count remains in D5
        move.l  d3,d2
        lsr.l   #2,d2                  ; copy bulk as 32-bit longwords
        beq.s   vpv48_fdb_ci_tail
vpv48_fdb_ci_long:
        move.l  (a1)+,(a0)+
        subq.l  #1,d2
        bne.s   vpv48_fdb_ci_long
vpv48_fdb_ci_tail:
        and.l   #3,d3                  ; 0..3 bytes left
        beq.s   vpv48_fdb_copy_input_done
vpv48_fdb_ci_byte:
        move.b  (a1)+,(a0)+
        subq.l  #1,d3
        bne.s   vpv48_fdb_ci_byte
vpv48_fdb_copy_input_done:

        move.l  d5,d0
        jsr     vpv48_map_input
        tst.l   d0
        bne.w   vpv48_fdb_fail

        move.l  vpv48_input_phys,vpv48_req_in_phys
        move.l  d5,vpv48_req_in_len
        move.l  vpv48_output_phys,vpv48_req_out_phys
        move.l  #VPV48_FAAD_OUT_SIZE,vpv48_req_out_len
        move.l  #3,vpv48_req_param0
        clr.l   vpv48_req_param1
        move.l  vpv48_work_phys,vpv48_req_work_phys
        move.l  #VPV48_FAAD_WORK_SIZE,vpv48_req_work_len
        moveq   #VPV48_CMD_CALL_MODULE,d0
        jsr     vpv48_send_request
        move.l  d0,d7
        jsr     vpv48_close_input
        jsr     vpv48_close_output_work
        tst.l   d7
        bne.w   vpv48_fdb_reopen_fail

        move.l  vpv48_output_ptr,a0
        cmpi.l  #VPV48_FAAD_OUT_MARKER,0(a0)
        bne.w   vpv48_fdb_reopen_fail
        cmpi.l  #VPV48_FAAD_BATCH_STATUS,4(a0)
        bne.w   vpv48_fdb_reopen_fail
        move.l  8(a0),d0              ; actual MP3 samplerate from ADTS/ASC
        tst.l   d0
        beq.w   vpv48_fdb_reopen_fail
        cmpi.l  #192000,d0
        bhi.w   vpv48_fdb_reopen_fail
        move.l  d0,v19_pcm_rate
        cmpi.l  #2,12(a0)
        bne.w   vpv48_fdb_reopen_fail
        tst.l   24(a0)                 ; MP3 error
        bne.w   vpv48_fdb_reopen_fail

        move.l  16(a0),d4              ; bytes consumed from staged chunk
        tst.l   d4
        beq.w   vpv48_fdb_reopen_fail
        cmp.l   d5,d4
        bhi.w   vpv48_fdb_reopen_fail
        move.l  d4,vpv48_last_consumed
        move.l  28(a0),vpv48_last_frame_index
        move.l  68(a0),vpv48_last_frames
        move.l  76(a0),d6              ; exact PCM bytes
        move.l  d6,vpv48_last_pcm_bytes
        cmpi.l  #VPV38_PCM_STORE_BYTES,d6
        bhi.w   vpv48_fdb_reopen_fail
        move.l  20(a0),d2              ; total interleaved sample values
        btst    #0,d2
        bne.w   vpv48_fdb_reopen_fail
        lsr.l   #1,d2                  ; stereo -> samples/channel
        move.l  d2,vpv48_last_samples_ch

        ; Advance the old BerryMP314 stream cursor by exactly FAAD's consumed bytes.
        move.l  vpv18_stream_cur,d1
        add.l   d4,d1
        move.l  d1,vpv18_stream_cur

        tst.l   d6
        beq.s   vpv48_fdb_no_pcm
        move.l  20(a0),d1
        lsl.l   #1,d1
        cmp.l   d6,d1
        bne.w   vpv48_fdb_reopen_fail

        ; CPU1/AArch64-BE PCM16 -> VideoCore MMAL PCM_SIGNED_LE.
        lea     256(a0),a1
        lea     vpv38_pcm_store,a2
        move.l  d6,d3
        lsr.l   #1,d3
vpv48_fdb_pcm_loop:
        move.w  (a1)+,d0
        ror.w   #8,d0                  ; AArch64-BE PCM16 -> MMAL little-endian
        move.w  d0,(a2)+
        subq.l  #1,d3
        bne.s   vpv48_fdb_pcm_loop

        addq.l  #1,vpv48_batch_count
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv48_fdb_fail
        moveq   #0,d0
        bra.s   vpv48_fdb_done

vpv48_fdb_no_pcm:
        ; FAAD has a one-frame filterbank priming delay. Normally the first
        ; batch already contains many frames, but handle a short first chunk.
        jsr     vpv48_map_output_work
        tst.l   d0
        bne.w   vpv48_fdb_fail
        move.l  v19_aac_buf_ptr,d1
        add.l   v19_aac_buf_len,d1
        cmp.l   vpv18_stream_cur,d1
        bhi.w   vpv48_faad_decode_batch_store_retry
        tst.l   vpv43_a_source_eof
        bne.s   vpv48_fdb_eof
        bra.w   vpv48_fdb_fail
vpv48_faad_decode_batch_store_retry:
        ; Re-enter through a small tail path instead of recursion.
        movem.l (sp)+,d1-d7/a0-a3/a6
        bra.w   vpv48_faad_decode_batch_store

vpv48_fdb_reopen_fail:
        jsr     vpv48_map_output_work
        ; fall through to failure regardless of reopen result
vpv48_fdb_fail:
        moveq   #2,d0
        bra.s   vpv48_fdb_done
vpv48_fdb_eof:
        moveq   #1,d0
vpv48_fdb_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Idempotent FAAD/BerryCore cleanup. The Matroska audio reader/buffer remains
; owned by vpv19_free_aac_buffer and is deliberately not freed here.
vpv48_faad_cleanup:
        movem.l d0-d7/a0-a3/a6,-(sp)
        clr.l   vpv48_faad_ready
        jsr     vpv48_close_input
        tst.l   vpv48_faad_module_loaded
        beq.s   vpv48_fc_no_unload
        clr.l   vpv48_req_in_phys
        clr.l   vpv48_req_in_len
        clr.l   vpv48_req_out_phys
        clr.l   vpv48_req_out_len
        clr.l   vpv48_req_param0
        clr.l   vpv48_req_param1
        clr.l   vpv48_req_work_phys
        clr.l   vpv48_req_work_len
        moveq   #VPV48_CMD_UNLOAD_MODULE,d0
        jsr     vpv48_send_request
        clr.l   vpv48_faad_module_loaded
vpv48_fc_no_unload:
        jsr     vpv48_close_output_work
        jsr     vpv48_release_mail

        move.l  4.w,a6
        tst.b   vpv48_module_dma_active
        beq.s   vpv48_fc_no_moddma
        move.l  vpv48_module_ptr,a0
        lea     vpv48_dma_module_len,a1
        moveq   #DMA_ReadFromRAM,d0
        jsr     CachePostDMA(a6)
        clr.b   vpv48_module_dma_active
vpv48_fc_no_moddma:

        move.l  vpv48_work_raw,d0
        beq.s   vpv48_fc_no_work
        move.l  d0,a1
        move.l  #VPV48_FAAD_WORK_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_work_raw
        clr.l   vpv48_work_ptr
vpv48_fc_no_work:
        move.l  vpv48_output_raw,d0
        beq.s   vpv48_fc_no_out
        move.l  d0,a1
        move.l  #VPV48_FAAD_OUT_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_output_raw
        clr.l   vpv48_output_ptr
vpv48_fc_no_out:
        move.l  vpv48_input_raw,d0
        beq.s   vpv48_fc_no_in
        move.l  d0,a1
        move.l  #VPV48_FAAD_IN_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_input_raw
        clr.l   vpv48_input_ptr
vpv48_fc_no_in:
        move.l  vpv48_module_raw,d0
        beq.s   vpv48_fc_no_mod
        move.l  d0,a1
        move.l  #VPV48_FAAD_MOD_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_module_raw
        clr.l   vpv48_module_ptr
vpv48_fc_no_mod:
        move.l  vpv48_mail_raw,d0
        beq.s   vpv48_fc_no_mail
        move.l  d0,a1
        move.l  #VPV48_FAAD_MAIL_ALLOC,d0
        jsr     FreeMem(a6)
        clr.l   vpv48_mail_raw
        clr.l   vpv48_mail_ptr
vpv48_fc_no_mail:
        clr.l   vpv48_module_phys
        clr.l   vpv48_input_phys
        clr.l   vpv48_output_phys
        clr.l   vpv48_work_phys
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts

; Create/configure audio_render while the video decoder/ISP path is still
; quiescent. This isolates the synchronous audio PORT_INFO_SET from active
; video-graph traffic. The audio component remains enabled but receives no
; buffer until the video graph has been built and the decoder component enabled.
vpv21_prepare_audio_early:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv21_audio_prepared

        move.l  component_handle,vpv21_saved_component
        move.l  input_port_handle,vpv21_saved_input
        move.l  port_query_index,vpv21_saved_port_qidx
        move.l  port_buf_size,vpv21_saved_port_buf_size

        lea     msg_vpv21_prepare_begin,a1
        move.l  #msg_vpv21_prepare_begin_end-msg_vpv21_prepare_begin,d3
        jsr     print_force
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.s   vpv21_prepare_restore_fail
        jsr     vpv19_configure_audio_render
        tst.l   d0
        bne.s   vpv21_prepare_restore_fail

        move.l  port_buf_size,vpv21_audio_port_buf_size
        move.l  #1,vpv21_audio_prepared
        lea     msg_vpv21_prepare_ok,a1
        move.l  #msg_vpv21_prepare_ok_end-msg_vpv21_prepare_ok,d3
        jsr     print_force
        moveq   #0,d7
        bra.s   vpv21_prepare_restore
vpv21_prepare_restore_fail:
        moveq   #1,d7
vpv21_prepare_restore:
        move.l  vpv21_saved_component,component_handle
        move.l  vpv21_saved_input,input_port_handle
        move.l  vpv21_saved_port_qidx,port_query_index
        move.l  vpv21_saved_port_buf_size,port_buf_size
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Queue the already-configured short PCM block only after the video graph and
; decoder component are active. No PORT_INFO_SET or COMPONENT_CREATE occurs here.
vpv21_queue_audio_prefix:
        movem.l d1-d7/a0-a3/a6,-(sp)
        tst.l   vpv38_pcm_block_count
        beq.w   vpv39_arm_fail
        tst.l   vpv21_audio_prepared
        beq.w   vpv39_arm_fail

        clr.l   vpv39_audio_next_block
        clr.l   vpv39_audio_bulk_pending
        clr.l   vpv39_audio_blocks_done
        clr.l   vpv39_audio_all_done
        clr.l   vpv39_audio_failed
        clr.l   vpv01_bulk_done
        clr.l   vpv21_audio_returned
        clr.l   vpv21_audio_dma_active
        clr.l   vpv43_sync_started
        clr.l   vpv43_last_output_frames
        clr.l   vpv43_sync_waits
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        clr.l   vpv47_tx_slot
        clr.l   vpv47_inflight
        clr.l   vpv47_audio_lead_ticks
        clr.l   vpv47_double_first_logged
        lea     vpv47_slot_len,a0
        moveq   #((VPV47_AUDIO_SLOTS*6)-1),d0
vpv47_clear_slot_state:
        clr.l   (a0)+
        dbra    d0,vpv47_clear_slot_state
        clr.l   vpv53_stage_offset
        move.l  vpv38_pcm_store_total,d0
        move.l  d0,vpv53_stage_total
        clr.l   vpv53_chunk_count
        clr.l   vpv53_batch_adopts
        move.l  #1,vpv39_audio_armed

        lea     msg_vpv21_queue_begin,a1
        move.l  #msg_vpv21_queue_begin_end-msg_vpv21_queue_begin,d3
        jsr     print_force
        lea     msg_vpv43_sync_values,a1
        move.l  #msg_vpv43_sync_values_end-msg_vpv43_sync_values,d3
        jsr     print_force
        move.l  #1,v41l_force_print
        move.l  v10_first_pts_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv43_first_audio_pts_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv43_video_frame_ticks,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv43_pts_mode,d0
        jsr     print_hex32
        jsr     newline
        clr.l   v41l_force_print
        moveq   #0,d0
        bra.s   vpv39_arm_done
vpv39_arm_fail:
        clr.l   vpv39_audio_armed
        move.l  #1,vpv39_audio_failed
        lea     msg_vpv21_queue_fail,a1
        move.l  #msg_vpv21_queue_fail_end-msg_vpv21_queue_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv39_arm_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; Advance the next audio media PTS by the exact decoded sample count of the
; buffer that just completed.  With 1-ms Matroska ticks this is:
;   delta_ticks = (samples * 1000 + remainder) / sample_rate
; The remainder is carried forever, so a two-hour movie does not accumulate
; integer-rounding drift from this scheduler.
vpv43_advance_audio_pts:
        movem.l d0-d4,-(sp)
        tst.l   vpv43_pts_mode
        beq.s   vpv43_advance_done
        move.l  vpv43_last_sent_samples,d0
        beq.s   vpv43_advance_done
        mulu.w  #1000,d0
        add.l   vpv43_audio_pts_remainder,d0
        move.l  v19_pcm_rate,d1
        tst.l   d1
        beq.s   vpv43_advance_disable
        jsr     v10_udiv32
        add.l   d0,vpv43_audio_next_pts_ticks
        move.l  d1,vpv43_audio_pts_remainder
        bra.s   vpv43_advance_done
vpv43_advance_disable:
        clr.l   vpv43_pts_mode
vpv43_advance_done:
        movem.l (sp)+,d0-d4
        rts

; Update a displayed-video media timeline and decide whether the next PCM block
; is due.  Unlike VPv42, audio is no longer sent simply because VCHIQ is idle.
; The first audio block waits until the first decoded frame has actually reached
; the P96 output.  Thereafter the timeline advances from container PTS base +
; DefaultDuration ticks.  Return D0=0 send allowed, D0=1 wait.
vpv43_audio_pts_gate:
        movem.l d1-d7,-(sp)
        tst.l   vpv43_pts_mode
        beq.w   vpv43_gate_allow
        move.l  output_frame_total,d6
        beq.w   vpv43_gate_wait

        tst.l   vpv43_sync_started
        bne.s   vpv43_gate_update
        move.l  v10_first_pts_ticks,d0
        move.l  d0,vpv43_display_pts_ticks
        clr.l   vpv43_last_output_frames
        move.l  #1,vpv43_sync_started

vpv43_gate_update:
        move.l  vpv43_last_output_frames,d5
vpv43_gate_update_loop:
        cmp.l   d6,d5
        bcc.s   vpv43_gate_compare
        tst.l   d5
        beq.s   vpv43_gate_first_frame
        move.l  vpv43_video_frame_ticks,d0
        add.l   d0,vpv43_display_pts_ticks
vpv43_gate_first_frame:
        addq.l  #1,d5
        bra.s   vpv43_gate_update_loop
vpv43_gate_compare:
        move.l  d5,vpv43_last_output_frames
        move.l  vpv43_audio_next_pts_ticks,d0
        move.l  vpv43_display_pts_ticks,d1
        cmp.l   d1,d0
        bhi.s   vpv43_gate_wait
vpv43_gate_allow:
        moveq   #0,d0
        bra.s   vpv43_gate_done
vpv43_gate_wait:
        addq.l  #1,vpv43_sync_waits
        moveq   #1,d0
vpv43_gate_done:
        movem.l (sp)+,d1-d7
        rts


; BerryMP314 live A/V scheduler. Called only while shared VCHIQ RAM is CPU-owned.
; It never waits synchronously: video/MMAL callbacks continue through h19_poll.
; D0=1 means an AUDIO BULK_TX was just published, so the caller must not
; publish a video BULK_TX in the same cycle. D0=0 means video may continue.
; BerryMP314 true double-buffer audio scheduler. VCHIQ BULK_TX remains globally
; serialized, but two independent PCM DMA/MMAL buffers are allowed to remain
; renderer-owned. Once BULK_TX for slot N completes, slot N+1 can be queued
; without waiting for BUFFER_TO_HOST of N. This removes the renderer-empty gap.
;
; D0=1 only when an AUDIO BULK_TX was published in this call.
vpv47_audio_service:
        movem.l d1-d7/a0-a3/a6,-(sp)
        moveq   #0,d7
        tst.l   vpv39_audio_armed
        beq.w   vpv47_service_done
        tst.l   vpv39_audio_failed
        bne.w   vpv47_service_done

        ; Reclaim any slot whose BULK and exact MMAL return are both complete.
        moveq   #0,d6
vpv47_reap_loop:
        cmpi.l  #VPV47_AUDIO_SLOTS,d6
        bcc.w   vpv47_reap_done
        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_state,a0
        adda.l  d5,a0
        tst.l   (a0)
        beq.s   vpv47_reap_next
        lea     vpv47_slot_bulk_done,a1
        adda.l  d5,a1
        tst.l   (a1)
        beq.s   vpv47_reap_next
        lea     vpv47_slot_returned,a1
        adda.l  d5,a1
        tst.l   (a1)
        beq.s   vpv47_reap_next

        ; CachePostDMA exact slot span only after both ownership signals.
        tst.l   d6
        bne.s   vpv47_reap_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   vpv47_reap_have_ptr
vpv47_reap_slot1:
        move.l  vpv47_pcm1_ptr,a0
vpv47_reap_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_state,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_bulk_done,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_returned,a0
        adda.l  d5,a0
        clr.l   (a0)
        lea     vpv47_slot_dma_active,a0
        adda.l  d5,a0
        clr.l   (a0)
        subq.l  #1,vpv47_inflight
        addq.l  #1,vpv39_audio_blocks_done
vpv47_reap_next:
        addq.l  #1,d6
        bra.w   vpv47_reap_loop
vpv47_reap_done:

        ; VPv59: prefetch may overwrite vpv38_pcm_store ONLY after the entire
        ; current FAAD batch has been sliced/copied into DMA slots.  With two
        ; 16-KiB slots this still leaves up to ~186 ms for CPU1 to decode the
        ; following 64-KiB batch while the last two chunks are renderer-owned.
        move.l  vpv53_stage_offset,d0
        cmp.l   vpv53_stage_total,d0
        bcs.s   vpv47_prefetch_done
        tst.l   vpv45_prefetch_ready
        bne.s   vpv47_prefetch_done
        tst.l   vpv41_decoder_live
        beq.s   vpv47_prefetch_done
        jsr     vpv45_prefetch_live_pcm
        cmpi.l  #2,d0
        beq.w   vpv47_service_fail
vpv47_prefetch_done:

        ; Completion is only final after MP3 EOF, all staged PCM bytes were
        ; copied to DMA slots, and both renderer slots have returned.
        tst.l   vpv41_decoder_live
        bne.s   vpv47_maybe_send
        tst.l   vpv41_audio_eof
        beq.s   vpv47_maybe_send
        tst.l   vpv45_prefetch_ready
        bne.s   vpv47_maybe_send
        move.l  vpv53_stage_offset,d0
        cmp.l   vpv53_stage_total,d0
        bcs.s   vpv47_maybe_send
        tst.l   vpv47_inflight
        bne.s   vpv47_maybe_send
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv47_maybe_send
        move.l  #1,vpv39_audio_all_done
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_done,a1
        move.l  #msg_vpv39_live_done_end-msg_vpv39_live_done,d3
        jsr     vpv21n_trace
        bra.w   vpv47_service_done

vpv47_maybe_send:
        tst.l   v15_stop_requested
        bne.w   vpv47_service_done
        tst.l   input_eof_seen
        bne.w   vpv47_service_done
        tst.l   input_bulk_pending
        bne.w   vpv47_service_done
        tst.l   vpv39_audio_bulk_pending
        bne.w   vpv47_service_done

        ; Find a free DMA/MMAL audio slot.
        moveq   #-1,d6
        tst.l   vpv47_slot_state
        beq.s   vpv47_free_slot0
        tst.l   vpv47_slot_state+4
        bne.w   vpv47_service_done
        moveq   #1,d6
        bra.s   vpv47_have_free_slot
vpv47_free_slot0:
        moveq   #0,d6
vpv47_have_free_slot:

        ; PTS gate. First buffer starts exactly on the visible-video timeline.
        ; Once one buffer is resident, allow the next buffer up to one current
        ; PCM-block duration early so audio_render can keep a continuous queue.
        jsr     vpv47_audio_pts_gate
        tst.l   d0
        bne.w   vpv47_service_done

        ; VPv59: the current 64-KiB FAAD batch is consumed as 16-KiB slices.
        ; If it is exhausted, atomically adopt the already-prefetched next batch
        ; (or decode it now as a measurable fallback) before loading a slot.
        move.l  vpv53_stage_offset,d0
        cmp.l   vpv53_stage_total,d0
        bcs.s   vpv53_have_stage_pcm
        tst.l   vpv45_prefetch_ready
        bne.s   vpv53_adopt_prefetch
        tst.l   vpv41_decoder_live
        beq.w   vpv47_service_done
        addq.l  #1,vpv45_prefetch_miss_count
        jsr     vpv45_prefetch_live_pcm
        cmpi.l  #2,d0
        beq.w   vpv47_service_fail
        tst.l   d0
        bne.w   vpv47_service_done
vpv53_adopt_prefetch:
        move.l  vpv45_prefetch_bytes,d0
        tst.l   d0
        beq.w   vpv47_service_fail
        move.l  d0,vpv53_stage_total
        clr.l   vpv53_stage_offset
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
        addq.l  #1,vpv53_batch_adopts
vpv53_have_stage_pcm:
        move.l  d6,d0
        jsr     vpv53_load_chunk_to_slot
        tst.l   d0
        bne.w   vpv47_service_fail
vpv47_source_ready:

        move.l  d6,d0
        jsr     vpv47_send_audio_slot
        tst.l   d0
        bne.w   vpv47_service_fail
        addq.l  #1,vpv39_audio_next_block
        addq.l  #1,vpv53_chunk_count
        addq.l  #1,vpv47_inflight

        ; Advance the media PTS at publish time, not return time: slot N+1 can
        ; now be queued while slot N remains renderer-owned.
        move.l  d6,d5
        lsl.l   #2,d5
        lea     vpv47_slot_samples,a0
        adda.l  d5,a0
        move.l  (a0),vpv43_last_sent_samples
        jsr     vpv47_set_lead_from_samples
        jsr     vpv43_advance_audio_pts

        ; One breadcrumb when the renderer first holds two distinct buffers.
        cmpi.l  #2,vpv47_inflight
        bcs.s   vpv47_no_double_log
        tst.l   vpv47_double_first_logged
        bne.s   vpv47_no_double_log
        move.l  #1,vpv47_double_first_logged
        lea     msg_vpv47_double_ok,a1
        move.l  #msg_vpv47_double_ok_end-msg_vpv47_double_ok,d3
        jsr     vpv21n_trace
vpv47_no_double_log:
        moveq   #1,d7
        bra.s   vpv47_service_done

vpv47_service_fail:
        move.l  #1,vpv39_audio_failed
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_fail,a1
        move.l  #msg_vpv39_live_fail_end-msg_vpv39_live_fail,d3
        jsr     vpv21n_trace
vpv47_service_done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Same visible-video PTS clock as VPv43, but when one audio buffer is already
; queued allow the NEXT PTS one block-duration ahead. This is bounded lead, not
; free-running audio; it exists solely to keep audio_render non-empty.
vpv47_audio_pts_gate:
        movem.l d1-d7,-(sp)
        tst.l   vpv43_pts_mode
        beq.s   vpv47_gate_allow
        move.l  output_frame_total,d6
        beq.s   vpv47_gate_wait
        tst.l   vpv43_sync_started
        bne.s   vpv47_gate_update
        move.l  v10_first_pts_ticks,vpv43_display_pts_ticks
        clr.l   vpv43_last_output_frames
        move.l  #1,vpv43_sync_started
vpv47_gate_update:
        move.l  vpv43_last_output_frames,d5
vpv47_gate_loop:
        cmp.l   d6,d5
        bcc.s   vpv47_gate_compare
        tst.l   d5
        beq.s   vpv47_gate_first
        move.l  vpv43_video_frame_ticks,d0
        add.l   d0,vpv43_display_pts_ticks
vpv47_gate_first:
        addq.l  #1,d5
        bra.s   vpv47_gate_loop
vpv47_gate_compare:
        move.l  d5,vpv43_last_output_frames
        move.l  vpv43_display_pts_ticks,d1
        tst.l   vpv47_inflight
        beq.s   vpv47_gate_no_lead
        add.l   vpv47_audio_lead_ticks,d1
vpv47_gate_no_lead:
        move.l  vpv43_audio_next_pts_ticks,d0
        cmp.l   d1,d0
        bhi.s   vpv47_gate_wait
vpv47_gate_allow:
        moveq   #0,d0
        bra.s   vpv47_gate_done
vpv47_gate_wait:
        addq.l  #1,vpv43_sync_waits
        moveq   #1,d0
vpv47_gate_done:
        movem.l (sp)+,d1-d7
        rts

; Compute one-buffer lead in 1-ms Matroska ticks without touching the carried
; PTS remainder used by the exact long-term clock.
vpv47_set_lead_from_samples:
        movem.l d0-d3,-(sp)
        move.l  vpv43_last_sent_samples,d0
        mulu.w  #1000,d0
        move.l  v19_pcm_rate,d1
        tst.l   d1
        beq.s   vpv47_lead_zero
        jsr     v10_udiv32
        move.l  d0,vpv47_audio_lead_ticks
        bra.s   vpv47_lead_done
vpv47_lead_zero:
        clr.l   vpv47_audio_lead_ticks
vpv47_lead_done:
        movem.l (sp)+,d0-d3
        rts

; VPv59: D0=slot. Copy the next <=16-KiB slice from the current FAAD batch
; in vpv38_pcm_store into one of the two proven DMA slots.  Advance the staging
; cursor only after the copy and pagelist are complete.  Return D0=0/1.
vpv53_load_chunk_to_slot:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv53_load_fail
        move.l  vpv53_stage_total,d4
        move.l  vpv53_stage_offset,d3
        cmp.l   d4,d3
        bcc.w   vpv53_load_fail
        sub.l   d3,d4                  ; remaining bytes
        move.l  #VPV53_AUDIO_CHUNK_BYTES,d5
        cmp.l   d5,d4
        bcc.s   vpv53_chunk_len_ok
        move.l  d4,d5
vpv53_chunk_len_ok:
        tst.l   d5
        beq.w   vpv53_load_fail
        ; PCM16 stereo chunks must end on the decoder block-alignment.
        move.l  v19_pcm_blockalign,d2
        tst.l   d2
        beq.w   vpv53_load_fail
        move.l  d5,d0
        move.l  d2,d1
        jsr     v10_udiv32
        tst.l   d1                     ; remainder must be zero
        bne.w   vpv53_load_fail
        move.l  d0,d6                  ; samples/channel in this chunk

        lea     vpv38_pcm_store,a1
        adda.l  d3,a1
        tst.l   d7
        bne.s   vpv53_load_slot1
        move.l  vpv21_pcm_ptr,a0
        move.l  vpv21_pcm_bus,d3
        move.l  vpv21_pcm_pagelist_ptr,a2
        bra.s   vpv53_load_have_slot
vpv53_load_slot1:
        move.l  vpv47_pcm1_ptr,a0
        move.l  vpv47_pcm1_bus,d3
        move.l  vpv47_pcm1_pagelist_ptr,a2
vpv53_load_have_slot:
        ; MHI04 LIVE VOLUME:
        ; AmiAMP already sends MHIP_VOLUME (0..100) to mhiberry.library.
        ; The old engine stored that byte but never applied it because PCM goes
        ; directly to ril.audio_render/HDMI and bypasses AHI.  Read the shared
        ; handle once per <=16-KiB chunk and attenuate PCM16 little-endian while
        ; copying it into the DMA slot.  100% keeps the proven byte-copy path
        ; bit-identical; 0% uses a fast zero-fill.  Intermediate values use a
        ; Q8 gain (round(volume*256/100)) so no per-sample division is needed.
        moveq   #100,d2
        move.l  mhi3_lib_base,a3
        beq.s   vpv53_volume_percent_ready
        lea     MHI3_B_HANDLE(a3),a3
        cmpi.l  #MHI3_HANDLE_MAGIC,MHI3_H_MAGIC(a3)
        bne.s   vpv53_volume_percent_ready
        moveq   #0,d2
        move.b  MHI3_H_VOLUME(a3),d2
        cmpi.w  #100,d2
        bls.s   vpv53_volume_percent_ready
        moveq   #100,d2
vpv53_volume_percent_ready:
        cmpi.w  #100,d2
        beq.s   vpv53_load_copy_full
        tst.w   d2
        beq.s   vpv53_load_copy_mute

        ; percent -> rounded Q8 gain 0..256
        move.l  d2,d0
        lsl.l   #8,d0
        addi.l  #50,d0
        moveq   #100,d4
        divu.w  d4,d0
        move.w  d0,d2

        ; PCM is signed 16-bit little-endian.  Swap each word into native
        ; 68k order, multiply by Q8 gain, shift back, then store LE again.
        move.l  d5,d1
        lsr.l   #1,d1
vpv53_load_copy_scaled:
        move.w  (a1)+,d0
        ror.w   #8,d0
        ext.l   d0
        muls.w  d2,d0
        asr.l   #8,d0
        ror.w   #8,d0
        move.w  d0,(a0)+
        subq.l  #1,d1
        bne.s   vpv53_load_copy_scaled
        bra.s   vpv53_load_copy_done

vpv53_load_copy_mute:
        move.l  d5,d1
        lsr.l   #1,d1
vpv53_load_zero_loop:
        clr.w   (a0)+
        subq.l  #1,d1
        bne.s   vpv53_load_zero_loop
        bra.s   vpv53_load_copy_done

vpv53_load_copy_full:
        move.l  d5,d1
vpv53_load_copy:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv53_load_copy
vpv53_load_copy_done:

        move.l  a2,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        and.l   #$fffff000,d3
        or.l    d0,d3
        lea     8(a0),a0
        move.l  d3,d0
        jsr     store_le32

        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_len,a0
        adda.l  d0,a0
        move.l  d5,(a0)
        lea     vpv47_slot_samples,a0
        adda.l  d0,a0
        move.l  d6,(a0)
        add.l   d5,vpv53_stage_offset
        moveq   #0,d0
        bra.s   vpv53_load_done
vpv53_load_fail:
        moveq   #1,d0
vpv53_load_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; D0=slot. Copy the priming PCM into that slot, rebuild its pagelist and record
; exact length/sample count.
vpv47_load_priming_to_slot:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv47_load_fail
        lea     vpv38_pcm_block_sizes,a2
        move.l  (a2),d5
        tst.l   d5
        beq.w   vpv47_load_fail
        lea     vpv38_pcm_store,a1
        bra.s   vpv47_load_common

; D0=slot. Consume the one CPU-side prefetched PCM block into that DMA slot.
vpv47_load_prefetch_to_slot:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv47_load_fail
        tst.l   vpv45_prefetch_ready
        beq.w   vpv47_load_fail
        move.l  vpv45_prefetch_bytes,d5
        tst.l   d5
        beq.w   vpv47_load_fail
        lea     vpv38_pcm_store,a1

vpv47_load_common:
        cmpi.l  #VPV21_PCM_MAX_BYTES,d5
        bhi.w   vpv47_load_fail
        tst.l   d7
        bne.s   vpv47_load_slot1
        move.l  vpv21_pcm_ptr,a0
        move.l  vpv21_pcm_bus,d3
        move.l  vpv21_pcm_pagelist_ptr,a2
        bra.s   vpv47_load_have_slot
vpv47_load_slot1:
        move.l  vpv47_pcm1_ptr,a0
        move.l  vpv47_pcm1_bus,d3
        move.l  vpv47_pcm1_pagelist_ptr,a2
vpv47_load_have_slot:
        move.l  d5,d1
vpv47_load_copy:
        move.b  (a1)+,(a0)+
        subq.l  #1,d1
        bne.s   vpv47_load_copy

        move.l  a2,a0
        move.l  d5,d0
        jsr     store_le32
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        move.l  d5,d0
        add.l   #$00000fff,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        subq.l  #1,d0
        and.l   #$00000fff,d0
        and.l   #$fffff000,d3
        or.l    d0,d3
        lea     8(a0),a0
        move.l  d3,d0
        jsr     store_le32

        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_len,a0
        adda.l  d0,a0
        move.l  d5,(a0)
        move.l  d5,d1
        move.l  v19_pcm_blockalign,d2
        tst.l   d2
        beq.s   vpv47_load_fail
        move.l  d1,d0
        move.l  d2,d1
        jsr     v10_udiv32
        move.l  d7,d1
        lsl.l   #2,d1
        lea     vpv47_slot_samples,a0
        adda.l  d1,a0
        move.l  d0,(a0)

        ; Prefetch source is consumed after successful copy. Priming source is
        ; left intact but will only be selected while next_block==0.
        move.l  vpv39_audio_next_block,d0
        cmp.l   vpv38_pcm_block_count,d0
        bcs.s   vpv47_load_ok
        clr.l   vpv45_prefetch_ready
        clr.l   vpv45_prefetch_bytes
        clr.l   vpv45_prefetch_samples
vpv47_load_ok:
        moveq   #0,d0
        bra.s   vpv47_load_done
vpv47_load_fail:
        moveq   #1,d0
vpv47_load_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; D0=slot. Publish one independent MMAL audio buffer + serialized VCHIQ BULK_TX.
vpv47_send_audio_slot:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  d0,d7
        cmpi.l  #VPV47_AUDIO_SLOTS,d7
        bcc.w   vpv47_send_fail
        move.l  d7,d6
        lsl.l   #2,d6
        lea     vpv47_slot_len,a0
        adda.l  d6,a0
        move.l  (a0),d5
        tst.l   d5
        beq.w   vpv47_send_fail

        tst.l   d7
        bne.s   vpv47_send_slot1
        move.l  vpv21_pcm_ptr,a3
        move.l  vpv21_pcm_pagelist_bus,d4
        bra.s   vpv47_send_have_ptr
vpv47_send_slot1:
        move.l  vpv47_pcm1_ptr,a3
        move.l  vpv47_pcm1_pagelist_bus,d4
vpv47_send_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  a3,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   a3,d0
        bne.w   vpv47_send_fail
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        move.l  #1,(a0)

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv47_send_fail
        move.l  a2,a0
        moveq   #79,d3
vpv47_send_clear:
        clr.l   (a0)+
        dbra    d3,vpv47_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV47_AUDIO_CONTEXT_BASE,d0
        add.l   d7,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV47_AUDIO_CONTEXT_BASE,d0
        add.l   d7,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  a3,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  vpv21_audio_port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  d5,d0
        jsr     store_le32
        ; VPv59 diagnostic: keep the host-side media PTS gate/sample clock,
        ; but DO NOT hand absolute timestamps to ril.audio_render.  The older
        ; proven PCM path used MMAL_TIME_UNKNOWN and let queued PCM play
        ; continuously.  This isolates whether per-16KiB MMAL PTS scheduling
        ; is creating the short silences heard on the constant 1-kHz test.
        ; MMAL_TIME_UNKNOWN = 0x8000000000000000, little-endian low/high words.
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        ; Audio decode order equals presentation order; DTS is unknown too.
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     308(a2),a0
        move.l  #8,d0
        jsr     store_le32
        lea     312(a2),a0
        move.l  d4,d0
        jsr     store_le32
        lea     316(a2),a0
        move.l  d5,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d3
        jsr     dma_pre_all
        tst.l   d3
        beq.s   vpv47_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv47_send_no_bell:
        move.l  d7,vpv47_tx_slot
        move.l  #1,vpv39_audio_bulk_pending
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_state,a0
        adda.l  d0,a0
        move.l  #1,(a0)
        lea     vpv47_slot_bulk_done,a0
        adda.l  d0,a0
        clr.l   (a0)
        lea     vpv47_slot_returned,a0
        adda.l  d0,a0
        clr.l   (a0)
        moveq   #0,d0
        bra.s   vpv47_send_done
vpv47_send_fail:
        ; If CachePreDMA succeeded but TX reservation/publication failed,
        ; return CPU ownership before leaving the slot reusable.
        move.l  d7,d0
        cmpi.l  #VPV47_AUDIO_SLOTS,d0
        bcc.s   vpv47_send_fail_done
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        tst.l   (a0)
        beq.s   vpv47_send_fail_done
        tst.l   d7
        bne.s   vpv47_send_fail_slot1
        move.l  vpv21_pcm_ptr,a0
        bra.s   vpv47_send_fail_have_ptr
vpv47_send_fail_slot1:
        move.l  vpv47_pcm1_ptr,a0
vpv47_send_fail_have_ptr:
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        move.l  d7,d0
        lsl.l   #2,d0
        lea     vpv47_slot_dma_active,a0
        adda.l  d0,a0
        clr.l   (a0)
vpv47_send_fail_done:
        moveq   #1,d0
vpv47_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

msg_vpv47_double_ok:
        dc.b "[BerryMP314][AUDIO-DOUBLE] two independent 16KiB MMAL audio chunks queued; AUDIO-ONLY",10
msg_vpv47_double_ok_end:
        even

; Retain VPv46 single-buffer service below as diagnostic/reference, but it is
; no longer called by the H264 streaming dispatcher in BerryMP314.
vpv39_audio_service:
        movem.l d1-d7/a0-a3/a6,-(sp)
        moveq   #0,d7
        tst.l   vpv39_audio_armed
        beq.w   vpv39_service_done
        tst.l   vpv39_audio_failed
        bne.w   vpv39_service_done

        ; BerryMP314: while VideoCore is playing the current DMA block, prepare the
        ; NEXT AAC block in ordinary Fast RAM. This is the key anti-underrun
        ; change: file I/O + Helix decode no longer sit in the renderer gap.
        tst.l   vpv21_audio_dma_active
        beq.s   vpv45_no_prefetch_window
        tst.l   vpv45_prefetch_ready
        bne.s   vpv45_no_prefetch_window
        tst.l   vpv41_decoder_live
        beq.s   vpv45_no_prefetch_window
        jsr     vpv45_prefetch_live_pcm
        cmpi.l  #2,d0
        beq.w   vpv41_service_decode_fail
vpv45_no_prefetch_window:

        ; If the current PCM buffer has BOTH transport completion and the exact
        ; audio BUFFER_TO_HOST callback, ownership is fully back on the 68k.
        tst.l   vpv21_audio_dma_active
        beq.w   vpv39_service_maybe_send
        tst.l   vpv01_bulk_done
        beq.w   vpv39_service_done
        tst.l   vpv21_audio_returned
        beq.w   vpv39_service_done

        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
        clr.l   vpv01_bulk_done
        clr.l   vpv21_audio_returned
        addq.l  #1,vpv39_audio_blocks_done
        addq.l  #1,vpv39_audio_next_block
        jsr     vpv43_advance_audio_pts

        move.l  vpv39_audio_next_block,d0
        cmp.l   vpv38_pcm_block_count,d0
        bcs.s   vpv39_service_maybe_send
        ; BerryMP314 continues past the single priming block by decoding the next
        ; AAC block on demand. Completion is only declared after Helix EOF.
        tst.l   vpv41_decoder_live
        bne.s   vpv39_service_maybe_send
        tst.l   vpv41_audio_eof
        beq.s   vpv39_service_maybe_send
        move.l  #1,vpv39_audio_all_done
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_done,a1
        move.l  #msg_vpv39_live_done_end-msg_vpv39_live_done,d3
        jsr     vpv21n_trace
        bra.w   vpv39_service_done

vpv39_service_maybe_send:
        ; Never start a new audio buffer once a user stop/EOF is in progress.
        ; Any already-published audio buffer is still allowed to return above.
        tst.l   v15_stop_requested
        bne.w   vpv39_service_done
        tst.l   input_eof_seen
        bne.w   vpv39_service_done

        ; One VCHIQ BULK_TX at a time globally. Video can keep owning MMAL
        ; input buffers, but its current BULK transport must be idle here.
        tst.l   input_bulk_pending
        bne.w   vpv39_service_done
        tst.l   vpv39_audio_bulk_pending
        bne.w   vpv39_service_done
        tst.l   vpv21_audio_dma_active
        bne.w   vpv39_service_done

        ; BerryMP314: transport-idle is no longer sufficient.  Only publish PCM
        ; when its media PTS is due against the displayed-video timeline.
        jsr     vpv43_audio_pts_gate
        tst.l   d0
        bne.w   vpv39_service_done

        move.l  vpv39_audio_next_block,d0
        cmp.l   vpv38_pcm_block_count,d0
        bcs.s   vpv41_have_pcm_source

        ; Normal BerryMP314 path: next PCM was decoded while the previous block was
        ; playing. If we missed that window, decode here as a measurable fallback.
        tst.l   vpv45_prefetch_ready
        bne.s   vpv45_have_prefetched_pcm
        tst.l   vpv41_decoder_live
        beq.s   vpv45_no_decoder_for_prefetch
        addq.l  #1,vpv45_prefetch_miss_count
        jsr     vpv45_prefetch_live_pcm
        tst.l   d0
        beq.s   vpv45_have_prefetched_pcm
        cmpi.l  #1,d0
        bne.w   vpv41_service_decode_fail
vpv45_no_decoder_for_prefetch:
        ; Clean MP3 EOF: no more PCM to send.
        move.l  #1,vpv39_audio_all_done
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_done,a1
        move.l  #msg_vpv39_live_done_end-msg_vpv39_live_done,d3
        jsr     vpv21n_trace
        bra.w   vpv39_service_done
vpv45_have_prefetched_pcm:
        moveq   #1,d6                  ; source = CPU-side prefetched PCM
        bra.s   vpv45_expose_audio_globals
vpv41_have_pcm_source:
        moveq   #0,d6                  ; source = initial staged priming PCM

vpv45_expose_audio_globals:
        ; Save all live VIDEO globals. The proven audio constructor still uses
        ; these generic slots internally, so expose audio only for this publish.
        move.l  component_handle,vpv36_queue_saved_component
        move.l  input_port_handle,vpv36_queue_saved_input
        move.l  port_query_index,vpv36_queue_saved_qidx
        move.l  port_buf_size,vpv36_queue_saved_buf_size

        move.l  vpv01_audio_handle,component_handle
        move.l  vpv01_audio_input,input_port_handle
        move.l  vpv21_audio_port_buf_size,port_buf_size

        tst.l   d6
        beq.s   vpv45_load_priming_pcm
        jsr     vpv45_load_prefetch_pcm
        tst.l   d0
        bne.s   vpv39_service_send_fail
        bra.s   vpv41_pcm_is_in_dma
vpv45_load_priming_pcm:
        move.l  vpv39_audio_next_block,d0
        jsr     vpv38_load_pcm_block
        tst.l   d0
        bne.s   vpv39_service_send_fail
vpv41_pcm_is_in_dma:
        ; Remember exact samples/channel represented by this PCM buffer so the
        ; next audio PTS can advance with carried rational remainder.
        move.l  vpv21_pcm_total_bytes,d0
        move.l  v19_pcm_blockalign,d1
        tst.l   d1
        beq.w   vpv39_service_send_fail
        jsr     v10_udiv32
        move.l  d0,vpv43_last_sent_samples
        jsr     vpv21_send_full_pcm
        tst.l   d0
        bne.s   vpv39_service_send_fail
        move.l  #1,vpv39_audio_bulk_pending
        moveq   #1,d7
        bra.s   vpv39_service_restore

vpv41_service_decode_fail:
        move.l  #1,vpv39_audio_failed
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_fail,a1
        move.l  #msg_vpv39_live_fail_end-msg_vpv39_live_fail,d3
        jsr     vpv21n_trace
        bra.w   vpv39_service_done

vpv39_service_send_fail:
        move.l  #1,vpv39_audio_failed
        clr.l   vpv39_audio_armed
        lea     msg_vpv39_live_fail,a1
        move.l  #msg_vpv39_live_fail_end-msg_vpv39_live_fail,d3
        jsr     vpv21n_trace
vpv39_service_restore:
        move.l  vpv36_queue_saved_component,component_handle
        move.l  vpv36_queue_saved_input,input_port_handle
        move.l  vpv36_queue_saved_qidx,port_query_index
        move.l  vpv36_queue_saved_buf_size,port_buf_size
vpv39_service_done:
        move.l  d7,d0
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Publish the one bounded short PCM MMAL input buffer plus VCHIQ BULK_TX.
vpv21_send_full_pcm:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   vpv01_bulk_done
        clr.l   vpv21_audio_returned

        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        cmp.l   vpv21_pcm_ptr,d0
        bne.w   vpv21_send_fail
        move.l  vpv21_audio_dma_len,d1
        cmp.l   #VPV21_PCM_DMA_SPAN,d1
        bcs.w   vpv21_send_fail_post
        move.l  #1,vpv21_audio_dma_active

        move.l  #320,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   vpv21_send_fail_post
        move.l  a2,a0
        moveq   #79,d7
vpv21_send_clear:
        clr.l   (a0)+
        dbra    d7,vpv21_send_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  vpv01_audio_handle,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  vpv01_audio_input,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  #VPV01_BUFFER_CONTEXT,d0
        jsr     store_le32
        lea     76(a2),a0
        move.l  vpv21_pcm_ptr,d0
        jsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     84(a2),a0
        move.l  vpv21_pcm_total_bytes,d0
        jsr     store_le32
        lea     96(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        jsr     store_le32

        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  vpv21_pcm_pagelist_bus,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  vpv21_pcm_total_bytes,d0
        jsr     store_le32

        add.l   #320,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   vpv21_send_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
vpv21_send_no_bell:
        moveq   #0,d0
        bra.s   vpv21_send_done
vpv21_send_fail_post:
        tst.l   vpv21_audio_dma_active
        beq.s   vpv21_send_fail
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
vpv21_send_fail:
        moveq   #1,d0
vpv21_send_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; VPv36: wait until BOTH the PCM BULK transfer and the matching
; audio BUFFER_TO_HOST callback have completed. VPv34 started H264 after
; BULK_TX_DONE alone and left the audio input header outstanding.
; Success returns CPU-owned with no audio buffer still in flight.
vpv21_wait_bulk_only:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #V10_CLEANUP_POLL_COUNT,d7
vpv21_wait_bulk_loop:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   vpv21_wait_bulk_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv21_wait_bulk_loop
        jsr     dma_post_all
        bra.w   vpv21_wait_bulk_fail
vpv21_wait_bulk_have:
        jsr     h26a_map_rx_current
        tst.l   d0
        bne.w   vpv21_wait_bulk_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,d5
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,d6

        ; Same local/remote MMAL service?
        move.l  d5,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   vpv21_wait_bulk_consume
        move.l  d5,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   vpv21_wait_bulk_consume

        move.l  d5,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.s   vpv21_wait_got_bulk
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.s   vpv21_wait_check_data
        bra.w   vpv21_wait_bulk_consume

vpv21_wait_got_bulk:
        cmpi.l  #4,d6
        bcs.w   vpv21_wait_bulk_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   vpv21_pcm_total_bytes,d0
        bne.w   vpv21_wait_bulk_fail
        move.l  #1,vpv01_bulk_done
        bra.s   vpv21_wait_bulk_consume

vpv21_wait_check_data:
        ; VPv36: do NOT start H264 until audio_render has returned the exact
        ; PCM input buffer as well.  VPv34 waited only for BULK_TX_DONE and
        ; left this MMAL callback outstanding while video streaming started.
        cmpi.l  #48,d6
        bcs.s   vpv21_wait_bulk_consume
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.s   vpv21_wait_bulk_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_BUFFER_TO_HOST,d0
        bne.s   vpv21_wait_bulk_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv21_wait_bulk_fail
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   vpv01_audio_input,d0
        bne.s   vpv21_wait_bulk_consume
        lea     44(a2),a0
        jsr     load_le32
        cmp.l   #VPV01_BUFFER_CONTEXT,d0
        bne.s   vpv21_wait_bulk_consume
        move.l  #1,vpv21_audio_returned

vpv21_wait_bulk_consume:
        move.l  d6,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv21_wait_bulk_fail
        tst.l   vpv01_bulk_done
        beq.s   vpv21_wait_bulk_more
        tst.l   vpv21_audio_returned
        bne.s   vpv21_wait_bulk_success
vpv21_wait_bulk_more:
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.w   vpv21_wait_bulk_loop
        jsr     dma_post_all
        bra.s   vpv21_wait_bulk_fail
vpv21_wait_bulk_success:
        tst.l   vpv21_audio_dma_active
        beq.s   vpv21_wait_bulk_success_done
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
vpv21_wait_bulk_success_done:
        lea     msg_vpv35_audio_return_ok,a1
        move.l  #msg_vpv35_audio_return_ok_end-msg_vpv35_audio_return_ok,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        bra.s   vpv21_wait_bulk_done
vpv21_wait_bulk_fail:
        tst.l   vpv21_audio_dma_active
        beq.s   vpv21_wait_bulk_fail_done
        move.l  #VPV21_PCM_DMA_SPAN,vpv21_audio_dma_len
        move.l  vpv21_pcm_ptr,a0
        lea     vpv21_audio_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   vpv21_audio_dma_active
vpv21_wait_bulk_fail_done:
        lea     msg_vpv21_queue_fail,a1
        move.l  #msg_vpv21_queue_fail_end-msg_vpv21_queue_fail,d3
        jsr     print_force
        moveq   #1,d0
vpv21_wait_bulk_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; VPv36: complete audio_render setup AFTER the already-proven PCM PORT_INFO_SET,
; but BEFORE any video input buffers are queued.  Entry has audio globals active.
; Adds only: HDMI destination, INPUT enable, component enable.  No PCM transfer.
; D0=0 success, 1 failure.
vpv35_finish_audio_enable:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   vpv21_audio_prepared

        lea     msg_vpv35_dest_begin,a1
        move.l  #msg_vpv35_dest_begin_end-msg_vpv35_dest_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_input,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        beq.s   vpv35_dest_ok
        move.l  vpv01_audio_control,d0
        jsr     vpv01_set_hdmi_destination
        tst.l   d0
        bne.w   vpv35_finish_fail
vpv35_dest_ok:
        lea     msg_vpv35_dest_ok,a1
        move.l  #msg_vpv35_dest_ok_end-msg_vpv35_dest_ok,d3
        jsr     vpv21n_trace

        ; Refresh INPUT0 snapshot after SET before enabling it.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv35_finish_fail
        move.l  port_last_handle,vpv01_audio_input
        move.l  vpv01_audio_input,input_port_handle

        lea     msg_vpv35_port_enable_begin,a1
        move.l  #msg_vpv35_port_enable_begin_end-msg_vpv35_port_enable_begin,d3
        jsr     vpv21n_trace
        tst.l   v12f_local_port
        bne.s   vpv35_enable_local1
        jsr     port_enable_current
        bra.s   vpv35_enable_done
vpv35_enable_local1:
        move.l  vpv01_audio_input,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
vpv35_enable_done:
        tst.l   d0
        bne.w   vpv35_finish_fail

        ; Verify INPUT0 really reports enabled=1.
        move.l  vpv01_audio_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        tst.l   d0
        bne.w   vpv35_finish_fail
        cmpi.l  #1,port_enabled
        bne.w   vpv35_finish_fail
        lea     msg_vpv35_port_enable_ok,a1
        move.l  #msg_vpv35_port_enable_ok_end-msg_vpv35_port_enable_ok,d3
        jsr     vpv21n_trace

        lea     msg_vpv35_component_enable_begin,a1
        move.l  #msg_vpv35_component_enable_begin_end-msg_vpv35_component_enable_begin,d3
        jsr     vpv21n_trace
        move.l  vpv01_audio_handle,component_handle
        tst.l   v12f_local_port
        bne.s   vpv35_comp_enable_local1
        jsr     component_enable_worker
        bra.s   vpv35_comp_enable_done
vpv35_comp_enable_local1:
        jsr     v9f_component_enable
vpv35_comp_enable_done:
        tst.l   d0
        bne.s   vpv35_finish_fail
        move.l  #1,vpv01_component_enabled
        move.l  port_buf_size,vpv21_audio_port_buf_size
        move.l  #1,vpv21_audio_prepared
        lea     msg_vpv35_component_enable_ok,a1
        move.l  #msg_vpv35_component_enable_ok_end-msg_vpv35_component_enable_ok,d3
        jsr     vpv21n_trace
        moveq   #0,d0
        bra.s   vpv35_finish_done
vpv35_finish_fail:
        clr.l   vpv21_audio_prepared
        lea     msg_vpv35_finish_fail,a1
        move.l  #msg_vpv35_finish_fail_end-msg_vpv35_finish_fail,d3
        jsr     vpv21n_trace
        moveq   #1,d0
vpv35_finish_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

vpv21_free_pcm:
        movem.l d0-d1/a0-a1/a6,-(sp)
        move.l  vpv21_pcm_alloc,d0
        beq.s   vpv21_free_done
        move.l  d0,a1
        ; VPv21T FIX: Exec FreeMem() expects byteSize in D0, not D1.
        ; Previous VPv21 code left the allocation address in D0, causing
        ; Exec to free an absurd pointer-sized byte count and corrupt MemLists.
        move.l  #VPV21_PCM_ALLOC_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   vpv21_pcm_alloc
        clr.l   vpv21_pcm_ptr
        clr.l   vpv21_pcm_bus
        clr.l   vpv21_pcm_pagelist_ptr
        clr.l   vpv21_pcm_pagelist_bus
        clr.l   vpv47_pcm1_ptr
        clr.l   vpv47_pcm1_bus
        clr.l   vpv47_pcm1_pagelist_ptr
        clr.l   vpv47_pcm1_pagelist_bus
        clr.l   vpv21_pcm_total_bytes
        clr.l   vpv21_pcm_total_samples
vpv21_free_done:
        movem.l (sp)+,d0-d1/a0-a1/a6
        rts

        section data,data
msg_vpv35_audio_return_ok:
        dc.b "[BerryMP314][AUDIO-PCM] BULK_TX_DONE + exact audio BUFFER_TO_HOST both received; video starts only now",10
msg_vpv35_audio_return_ok_end:
msg_vpv35_dest_begin:
        dc.b "[BerryMP314][AUDIO-CONFIG] set HDMI destination",10
msg_vpv35_dest_begin_end:
msg_vpv35_dest_ok:
        dc.b "[BerryMP314][AUDIO-CONFIG] HDMI destination: OK",10
msg_vpv35_dest_ok_end:
msg_vpv35_port_enable_begin:
        dc.b "[BerryMP314][AUDIO-CONFIG] enable audio INPUT0",10
msg_vpv35_port_enable_begin_end:
msg_vpv35_port_enable_ok:
        dc.b "[BerryMP314][AUDIO-CONFIG] audio INPUT0 enabled=1: OK",10
msg_vpv35_port_enable_ok_end:
msg_vpv35_component_enable_begin:
        dc.b "[BerryMP314][AUDIO-CONFIG] enable ril.audio_render component",10
msg_vpv35_component_enable_begin_end:
msg_vpv35_component_enable_ok:
        dc.b "[BerryMP314][AUDIO-CONFIG] ril.audio_render COMPONENT_ENABLE: OK",10
msg_vpv35_component_enable_ok_end:
msg_vpv35_finish_fail:
        dc.b "[BerryMP314][AUDIO-CONFIG] configuration step FAILED; audio stays disabled",10
msg_vpv35_finish_fail_end:
msg_vpv35_enable_ok:
        dc.b "[BerryMP314][AUDIO-CONFIG] full renderer configuration proven; arming live A/V scheduler",10
msg_vpv35_enable_ok_end:
msg_vpv35_queue_proven:
        dc.b "[BerryMP314][AUDIO-LIVE] double-buffer scheduler armed; H264 starts and PCM is queued ahead by the common dispatcher",10
msg_vpv35_queue_proven_end:
msg_vpv35_queue_fail_continue:
        dc.b "[BerryMP314][AUDIO-PCM] PCM queue failed; continue video without sound for diagnosis",10
msg_vpv35_queue_fail_continue_end:
msg_vpv35_enable_fail_continue:
        dc.b "[BerryMP314][AUDIO-CONFIG] failed; continue video deliberately",10
msg_vpv35_enable_fail_continue_end:

msg_vpv23_second_create_begin:
        dc.b "[BerryMP314][AUDIO-ISO2] local-1: before ril.audio_render COMPONENT_CREATE",10
msg_vpv23_second_create_begin_end:
msg_vpv23_second_create_ok:
        dc.b "[BerryMP314][AUDIO-ISO2] local-1: ril.audio_render COMPONENT_CREATE returned OK",10
msg_vpv23_second_create_ok_end:
msg_vpv23_second_create_fail:
        dc.b "[BerryMP314][AUDIO-ISO2] local-1: audio isolation failed; aborting before stream",10
msg_vpv23_second_create_fail_end:
msg_vpv23_second_ctrl_begin:
