; ====================================================================
; VPv59 - TRUE AUDIO-ONLY STREAMING DIAGNOSTIC
; Entry: MMAL service open + GET_VERSION complete, shared VCHIQ RAM CPU-owned.
; No H264 component, ISP, video ports, video BULK_TX or video PTS gate exist.
; BerryFAAD03/CPU1 + VPv58-derived 16-KiB two-slot audio scheduler are unchanged.
; ====================================================================
        even
        section bss,bss
vpv59_audio_only_active:      ds.l 1
vpv59_audio_rx_records:       ds.l 1
vpv59_audio_bulk_done_count:  ds.l 1
vpv59_audio_return_count:     ds.l 1
vpv59_audio_bad_count:        ds.l 1
vpv314_audio_yield_count:     ds.l 1
vpv314_id3v1_trim_count:      ds.l 1
        even

        section code,code
vpv59_audio_only_run:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  #1,vpv59_audio_only_active
        clr.l   vpv59_audio_rx_records
        clr.l   vpv59_audio_bulk_done_count
        clr.l   vpv59_audio_return_count
        clr.l   vpv59_audio_bad_count
        clr.l   vpv314_audio_yield_count
        clr.l   vpv314_id3v1_trim_count
        clr.l   input_bulk_pending
        clr.l   input_eof_seen
        clr.l   v15_stop_requested
        clr.l   output_frame_total
        clr.l   vpv43_pts_mode             ; no video clock exists in VPv59
        clr.l   vpv43_sync_started
        clr.l   vpv43_sync_waits

        lea     msg_vpv59_begin,a1
        move.l  #msg_vpv59_begin_end-msg_vpv59_begin,d3
        jsr     print_force

        ; Create ONLY ril.audio_render on the already-open MMAL service.
        jsr     vpv01_create_audio_render
        tst.l   d0
        bne.w   vpv59_audio_fail

        ; VPv60 AUDIO-ONLY FORMAT FIX:
        ; BerryFAAD03 does not use the legacy Helix DECSTREAM_INFO structure.
        ; vpv21_predecode_pcm already contains the authoritative MP3 format in
        ; v19_pcm_rate/channels/bits, but vpv19_configure_audio_render begins by
        ; importing those three values from vpv18_stream_info.  The normal A/V
        ; history happened to populate that legacy structure; true audio-only
        ; does not.  Mirror ONLY the proven MP3 format into DECSTREAM_INFO so
        ; the existing renderer setup remains byte-for-byte otherwise unchanged.
        move.l  v19_pcm_rate,d0
        move.l  d0,vpv18_stream_info+DECSTREAM_RATE
        move.l  v19_pcm_channels,d0
        move.w  d0,vpv18_stream_info+DECSTREAM_CHANNELS
        move.l  v19_pcm_bits,d0
        move.w  d0,vpv18_stream_info+DECSTREAM_BITS

        jsr     vpv19_configure_audio_render
        tst.l   d0
        bne.w   vpv59_audio_fail

        ; vpv19_configure_audio_render enabled the component. Expose the exact
        ; configured chunk size to the proven BerryMP314 scheduler and arm it.
        move.l  port_buf_size,vpv21_audio_port_buf_size
        move.l  #1,vpv21_audio_prepared
        move.l  v12f_local_bits,port_query_index
        jsr     vpv21_queue_audio_prefix
        tst.l   d0
        bne.w   vpv59_audio_fail

        lea     msg_vpv59_armed,a1
        move.l  #msg_vpv59_armed_end-msg_vpv59_armed,d3
        jsr     print_force

        ; First service call queues slot 0 immediately.  The service itself
        ; returns D0=1 when it published a BULK and therefore already handed
        ; shared VCHIQ memory back to VideoCore with dma_pre_all.
        move.l  #POLL_COUNT,d7
        jsr     vpv47_audio_service
        tst.l   vpv39_audio_failed
        bne.w   vpv59_audio_fail_cpu
        tst.l   d0
        bne.s   vpv59_audio_poll
        jsr     dma_pre_all

vpv59_audio_poll:
        ; BerryMP314: audio-only playback no longer burns the 68k in the
        ; legacy VP busy-spin.  Entry to this label always has the shared
        ; VCHIQ region returned to DMA ownership (initial no-publish path,
        ; published BULK path, or no-progress path).  Yield one DOS tick
        ; before re-acquiring it.  Two 16-KiB renderer slots provide ~186 ms
        ; of PCM reserve at 44.1-kHz stereo, so a 20-ms poll cadence is safe
        ; while giving Workbench/other tasks real CPU time.
        move.l  a5,a6
        moveq   #1,d1
        jsr     Delay(a6)
        addq.l  #1,vpv314_audio_yield_count
        jsr     dma_post_all

        ; Ctrl-C stops NEW PCM publication, but already queued renderer slots
        ; are allowed to return before teardown.
        jsr     v15_poll_ctrl_c

vpv59_audio_rx_again:
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bls.w   vpv59_audio_service_step

        ; Map the next non-PADDING record. v12a_rx_map_data also handles slot
        ; padding and recycle boundaries correctly for long audio runs.
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   vpv59_audio_fail_cpu
        move.l  a2,a3
        move.l  a3,a0
        jsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a3),a0
        jsr     load_le32
        move.l  d0,bulk_rx_size
        addq.l  #1,vpv59_audio_rx_records
        move.l  #POLL_COUNT,d7

        ; Ignore unrelated transport records, but always consume them.
        move.l  bulk_rx_msgid,d0
        jsr     v9g_rx_service_match
        tst.l   d0
        bne.w   vpv59_audio_consume

        move.l  bulk_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_BULK_TX_DONE,d0
        beq.w   vpv59_audio_bulk_done
        cmp.l   #VCHIQ_MSG_DATA,d0
        beq.w   vpv59_audio_data
        bra.w   vpv59_audio_consume

vpv59_audio_bulk_done:
        move.l  bulk_rx_size,d0
        cmpi.l  #4,d0
        bcs.w   vpv59_audio_bad
        tst.l   vpv39_audio_bulk_pending
        beq.w   vpv59_audio_bad
        lea     8(a3),a0
        jsr     load_le32
        move.l  d0,d4                    ; actual transferred bytes
        move.l  vpv47_tx_slot,d1
        cmpi.l  #VPV47_AUDIO_SLOTS,d1
        bcc.w   vpv59_audio_bad
        move.l  d1,d2
        lsl.l   #2,d2
        lea     vpv47_slot_len,a0
        adda.l  d2,a0
        cmp.l   (a0),d4
        bne.w   vpv59_audio_bad
        lea     vpv47_slot_bulk_done,a0
        adda.l  d2,a0
        move.l  #1,(a0)
        clr.l   vpv39_audio_bulk_pending
        addq.l  #1,vpv59_audio_bulk_done_count
        bra.w   vpv59_audio_consume

vpv59_audio_data:
        move.l  bulk_rx_size,d0
        cmpi.l  #48,d0
        bcs.w   vpv59_audio_consume
        lea     8(a3),a0
        jsr     load_le32
        cmpi.l  #MMAL_MAGIC,d0
        bne.w   vpv59_audio_consume
        lea     12(a3),a0
        jsr     load_le32
        cmpi.l  #MMAL_BUFFER_TO_HOST,d0
        bne.w   vpv59_audio_consume
        lea     24(a3),a0
        jsr     load_le32
        tst.l   d0
        bne.w   vpv59_audio_bad
        lea     44(a3),a0
        jsr     load_le32
        move.l  d0,d1
        sub.l   #VPV47_AUDIO_CONTEXT_BASE,d1
        cmpi.l  #VPV47_AUDIO_SLOTS,d1
        bcc.w   vpv59_audio_consume       ; other async callback: ignore
        move.l  d1,d2
        lsl.l   #2,d2
        lea     vpv47_slot_returned,a0
        adda.l  d2,a0
        move.l  #1,(a0)
        addq.l  #1,vpv59_audio_return_count
        bra.w   vpv59_audio_consume

vpv59_audio_bad:
        addq.l  #1,vpv59_audio_bad_count
        bra.w   vpv59_audio_fail_cpu

vpv59_audio_consume:
        move.l  bulk_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   vpv59_audio_fail_cpu
        bra.w   vpv59_audio_rx_again

vpv59_audio_service_step:
        ; Same VPv58-derived scheduler, but with vpv43_pts_mode=0, so no video timeline
        ; can delay a chunk. This is the exact isolation test we want.
        jsr     vpv47_audio_service
        tst.l   vpv39_audio_failed
        bne.w   vpv59_audio_fail_cpu

        ; Natural MP3 EOF is declared only after all staged bytes and both
        ; renderer-owned slots have returned. Ctrl-C uses the same ownership gate.
        tst.l   vpv39_audio_all_done
        bne.s   vpv59_audio_finish
        tst.l   v15_stop_requested
        beq.s   vpv59_audio_continue
        tst.l   vpv39_audio_bulk_pending
        bne.s   vpv59_audio_continue
        tst.l   vpv47_inflight
        bne.s   vpv59_audio_continue
        bra.s   vpv59_audio_finish

vpv59_audio_continue:
        ; If vpv47_audio_service published a BULK, shared RAM is already DMA-owned
        ; and this is forward progress: reset the bounded no-progress watchdog.
        tst.l   d0
        beq.s   vpv59_audio_no_publish
        move.l  #POLL_COUNT,d7
        bra.w   vpv59_audio_poll
vpv59_audio_no_publish:
        ; No RX and no new publish this round. Keep the same bounded watchdog
        ; policy as the proven stream dispatcher so a broken renderer cannot hang.
        subq.l  #1,d7
        beq.w   vpv59_audio_timeout
        jsr     dma_pre_all
        bra.w   vpv59_audio_poll

vpv59_audio_timeout:
        lea     msg_vpv59_timeout,a1
        move.l  #msg_vpv59_timeout_end-msg_vpv59_timeout,d3
        jsr     print_force
        bra.w   vpv59_audio_fail_cpu

vpv59_audio_finish:
        ; Renderer has returned every slot. Give its internal HDMI queue a short
        ; drain interval, then tear down only audio_render + this MMAL service.
        jsr     dma_pre_all
        move.l  a5,a6
        move.l  #10,d1
        jsr     Delay(a6)
        jsr     dma_post_all

        lea     msg_vpv59_success,a1
        move.l  #msg_vpv59_success_end-msg_vpv59_success,d3
        jsr     print_force
        jsr     vpv59_audio_print_counters
        jsr     vpv01_cleanup
        clr.l   vpv59_audio_only_active
        moveq   #0,d0
        bra.s   vpv59_audio_done

vpv59_audio_fail_cpu:
        ; Entry is CPU-owned. Best-effort service-owned teardown; no video DMA
        ; allocations exist in this build.
vpv59_audio_fail:
        lea     msg_vpv59_fail,a1
        move.l  #msg_vpv59_fail_end-msg_vpv59_fail,d3
        jsr     print_force
        jsr     vpv59_audio_print_counters
        jsr     vpv01_cleanup
        clr.l   vpv59_audio_only_active
        moveq   #1,d0
vpv59_audio_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

vpv59_audio_print_counters:
        movem.l d0-d7/a0-a3/a6,-(sp)
        lea     msg_vpv59_counts,a1
        move.l  #msg_vpv59_counts_end-msg_vpv59_counts,d3
        jsr     print_force
        move.l  vpv59_audio_rx_records,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv59_audio_bulk_done_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv59_audio_return_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv59_audio_bad_count,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_vpv314_yield_stats,a1
        move.l  #msg_vpv314_yield_stats_end-msg_vpv314_yield_stats,d3
        jsr     print_force
        move.l  vpv314_audio_yield_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv314_id3v1_trim_count,d0
        jsr     print_hex32
        jsr     newline
        lea     msg_vpv59_chunks,a1
        move.l  #msg_vpv59_chunks_end-msg_vpv59_chunks,d3
        jsr     print_force
        move.l  vpv53_chunk_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv53_batch_adopts,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv45_prefetch_count,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print_force
        move.l  vpv45_prefetch_miss_count,d0
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts

        section data,data
msg_vpv59_begin:
        dc.b 10,"[BerryMP314][AUDIO-ONLY] KEIN Video. rohe MP3 -> CPU1 -> PCM16 -> ril.audio_render/HDMI.",10
msg_vpv59_begin_end:
msg_vpv59_armed:
        dc.b "[BerryMP314][AUDIO-ONLY] Renderer + 2x16KiB PCM scheduler aktiv; kein Video-PTS-Gate.",10
msg_vpv59_armed_end:
msg_vpv59_success:
        dc.b "[BerryMP314][AUDIO-ONLY] MP3 EOF/Stop erreicht; alle Audio-DMA/MMAL-Slots sauber zurueck.",10
msg_vpv59_success_end:
msg_vpv59_fail:
        dc.b "[BerryMP314][AUDIO-ONLY] FEHLER im reinen MP3/PCM/audio_render-Pfad.",10
msg_vpv59_fail_end:
msg_vpv59_timeout:
        dc.b "[BerryMP314][AUDIO-ONLY] TIMEOUT: kein VCHIQ/MMAL-Audiofortschritt innerhalb des Poll-Fensters.",10
msg_vpv59_timeout_end:
msg_vpv59_counts:
        dc.b "[BerryMP314][AUDIO-ONLY] rx/bulkdone/returned/bad = 0x"
msg_vpv59_counts_end:
msg_vpv59_chunks:
        dc.b "[BerryMP314][AUDIO-ONLY] chunks/batch-adopts/prefetch/missed = 0x"
msg_vpv59_chunks_end:
msg_vpv59_second_audio:
        dc.b "[BerryMP314][AUDIO-ONLY] Zweitstart: local-1 MMAL-Service bereit; kein Video-Decoder wird erzeugt.",10
msg_vpv59_second_audio_end:
msg_vpv314_yield_stats:
        dc.b "[BerryMP314][COOP] DOS-yields/ID3v1-tail-trims = 0x"
msg_vpv314_yield_stats_end:
        even
